		["thunder ridge"] = {
			name = "Falaises du Tonnerre",
			short = "Les falaises du Tonnerre forment une gorge au nord-ouest de Durotar, au sud-ouest d'Orgrimmar. Elles abritent une forêt d'arbres anciens qui ont poussé en harmonie avec les lézards-tonnerre qui y ont leurs tanières.",
			full = "Les falaises du Tonnerre forment une gorge au nord-ouest de Durotar, au sud-ouest d'Orgrimmar. Elles abritent une forêt d'arbres anciens qui ont poussé en harmonie avec les lézards-tonnerre qui y ont leurs tanières.\n\nCette harmonie se rompit lorsqu'une exploitation forestière humaine commença à dépouiller la crête de ses arbres, rendant les lézards fous. Rexxar, envoyé cueillir de la chatoyante pour Drek'Thar, remarqua le changement chez les bêtes et en porta la nouvelle à Orgrimmar. Drek'Thar et lui revinrent ensemble, découvrirent l'exploitation forestière et furent contraints d'abattre les lézards devenus fous pour éviter le désastre, bien que Rexxar ait ensuite recueilli leurs œufs pour que Drek'Thar les étudie.\n\nJaina Proudmoore, envoyée par Thrall pour découvrir ce qui avait encore troublé la crête, constata que ses arbres avaient été abattus par magie démoniaque, œuvre de la Lame ardente qui cherchait à déstabiliser la région. Une petite bande de ses sectateurs, menée par Fizzle Darkclaw, y avait établi son camp pour semer davantage le chaos, et Orgnil Soulscar réclama la mort de Fizzle, et sa griffe pour en preuve.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Ridge",
		},
		["tiragarde keep"] = {
