		},
		["valley of trials"] = {
			name = "Vallée des épreuves",
			short = "La vallée des Épreuves s'étend, enclavée, au sud de Durotar, une cuvette de terre brûlée où chaque jeune orc commence la vie que la Horde a tracée pour lui.",
			full = "La vallée des Épreuves s'étend, enclavée, au sud de Durotar, une cuvette de terre brûlée où chaque jeune orc commence la vie que la Horde a tracée pour lui. Ceux qui échouent ne sont pas emportés. On les laisse là où ils tombent, à cuire au soleil jusqu'à ce que le désert ait achevé ce que l'épreuve avait commencé.\n\nAu cœur de la vallée se trouve l'Antre, une grotte taillée dans la falaise et pourvue du simple confort d'une vie vouée au service. Des anciens la tiennent, enseignant aux jeunes leur vocation et les soumettant à leurs épreuves.\n\nAu nord, une modeste suite de grottes naturelles restait jadis vide dans les falaises. Quelque chose s'y est glissé depuis. Des démons de la Lame ardente y nichent désormais et se répandent dans la vallée elle-même, et leur présence a donné du poids à de vieilles rumeurs selon lesquelles le Conseil des ombres aurait pris pied dans la région. Les démons sont faibles, mais ils ne restent pas dans leurs grottes, et la souillure qu'ils portent a commencé à se répandre au-delà de la pierre qui la contenait.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Trials",
		},
	},
	-- Mulgore: 18 subzones
	[1412] = {
		["baeldun digsite"] = {
			name = "Site de fouilles de Bael'Dun",
			short = "L'expédition de Bael'dun creusa sa carrière dans la lisière ouest de Mulgore, enfonçant ses pioches dans le flanc de la montagne.",
			full = "L'expédition de Bael'dun creusa sa carrière dans la lisière ouest de Mulgore, enfonçant ses pioches dans le flanc de la montagne. Ces fouilles furent déclarées offense à la Terre-mère, et lorsque les paroles échouèrent à les faire reculer, la tribu Bloodhoof s'empara des outils des envahisseurs et les brisa pour les chasser.\n\nLes nains continuèrent pourtant de creuser, sourds aux avertissements qu'on leur avait donnés, et leur travail inconsidéré attisa la colère des esprits de la terre. La carrière demeure, cicatrice creusée dans le sol de Mulgore.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Digsite",
		},
		["bloodhoof village"] = {
			name = "Village Bloodhoof",
			short = "Le village Bloodhoof se trouve au bord des eaux du lac Taureau-de-pierre, dans les plaines de Mulgore, et porte le nom de la tribu qui y vit.",
			full = "Le village Bloodhoof se trouve au bord des eaux du lac Taureau-de-pierre, dans les plaines de Mulgore, et porte le nom de la tribu qui y vit. C'est ici que les kodos sauvages des plaines sont domptés et dressés jusqu'à ce qu'ils soient assez calmes pour porter un cavalier, et le village est réputé pour ce travail autant que pour tout le reste.\n\nBaine Bloodhoof veille sur le village et assure sa protection. Zarlman Deux-Lunes prend soin de la vie spirituelle de la tribu Bloodhoof ; c'est l'ancien qui parle au nom des ancêtres et de la Terre-mère à ceux qui vivent ici ou ne font que passer.",
			source = "https://warcraft.wiki.gg/wiki/Bloodhoof_Village",
		},
		["brambleblade ravine"] = {
			name = "Ravin de Roncelame",
			short = "Le ravin de Roncelame entaille la lisière nord-est de la mesa de Nuage rouge ; c'est le repaire des hurans Dos-hirsute.",
			full = "Le ravin de Roncelame entaille la lisière nord-est de la mesa de Nuage rouge ; c'est le repaire des hurans Dos-hirsute. Au fond du ravin, dans une grande hutte, demeure leur chef, Brochaigu Mantépine, dont l'autorité a attiré sur lui les attaques des taurens, destinées à briser à la source les raids des hurans.",
			source = "https://warcraft.wiki.gg/wiki/Brambleblade_Ravine",
		},
		["camp narache"] = {
			name = "Camp Narache",
			short = "Le camp Narache se trouve à la lisière nord de la mesa de Nuage rouge, un petit cercle de tentes appartenant à la tribu Hawkwind, au sud de Mulgore.",
			full = "Le camp Narache se trouve à la lisière nord de la mesa de Nuage rouge, un petit cercle de tentes appartenant à la tribu Hawkwind, au sud de Mulgore. Des braves blessés se reposent dans la tente principale, et autour du centre du village, les maîtres de la tribu forment un cercle paisible, rendant hommage à Grand-mère Hawkwind.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Narache",
		},
		["golden plains"] = {
			name = "Les plaines dorées",
			short = "Les plaines dorées, un bassin d'herbes vertes ondoyantes au sud-est de Thunder Bluff, sont chéries au sein de la patrie des taurens et prisées comme terrain de chasse.",
			full = "Les plaines dorées, un bassin d'herbes vertes ondoyantes au sud-est de Thunder Bluff, sont chéries au sein de la patrie des taurens et prisées comme terrain de chasse. De grands troupeaux de kodos s'y rassemblent pour paître, et quelque part dans les herbes, dit-on, la célèbre Arra'chea a élu domicile.",
			source = "https://warcraft.wiki.gg/wiki/Golden_Plains",
		},
		["kodo rock"] = {
			name = "Rocher des kodos",
			short = "Le rocher des kodos se dresse discrètement entre le camp Narache et le ravin de Roncelame ; il est facile de passer devant sans le remarquer si l'on n'y prête pas attention, car on ne peut le voir que de près.",
			full = "Le rocher des kodos se dresse discrètement entre le camp Narache et le ravin de Roncelame ; il est facile de passer devant sans le remarquer si l'on n'y prête pas attention, car on ne peut le voir que de près.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Rock",
		},
		["palemane rock"] = {
			name = "Rocher des crins-pâles",
			short = "Le rocher des Crins-pâles est une grotte profondément creusée dans le flanc des montagnes de l'ouest de Mulgore, repaire des gnolls de la tribu Crins-pâles.",
			full = "Le rocher des Crins-pâles est une grotte profondément creusée dans le flanc des montagnes de l'ouest de Mulgore, repaire des gnolls de la tribu Crins-pâles. Ils occupent à la fois la grotte et un camp à l'extérieur, et ils sont prompts à la violence, s'abattant sur quiconque s'égare trop près de leur territoire.",
			source = "https://warcraft.wiki.gg/wiki/Palemane_Rock",
		},
		["ravaged caravan"] = {
			name = "Caravane dévastée",
			short = "Sur la rive nord-est du lac Taureau-de-pierre se consume l'épave d'une caravane de la KapitalRisk, qui crache encore une fumée noire dans le ciel de Mulgore.",
			full = "Sur la rive nord-est du lac Taureau-de-pierre se consume l'épave d'une caravane de la KapitalRisk, qui crache encore une fumée noire dans le ciel de Mulgore. Elle transportait des provisions pour l'exploitation minière du superviseur Fizsprocket lorsque les taurens, las de voir des gobelins traverser leurs terres, l'attaquèrent.\n\nLes survivants n'ont jamais abandonné l'épave. Ils tiennent toujours le monticule fumant et sa cargaison calcinée, repoussant quiconque s'en approche.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Caravan",
		},
		["red cloud mesa"] = {
			name = "Mesa de Nuage rouge",
			short = "La mesa de Nuage rouge est une étendue de plaines ondulantes au sommet des hautes falaises du sud de Mulgore, réputée pour sa beauté paisible et ouverte.",
			full = "La mesa de Nuage rouge est une étendue de plaines ondulantes au sommet des hautes falaises du sud de Mulgore, réputée pour sa beauté paisible et ouverte. C'est ici que les jeunes taurens font leurs preuves, prenant les armes contre les hurans Dos-hirsute qui tiennent le ravin de Roncelame, au nord-est.\n\nLe camp Narache, établi au nord-ouest de la mesa, est le dernier refuge sûr sur la mesa. Depuis le cimetière à l'ouest du camp, un sentier grimpe jusqu'au sommet de la mesa Fargaze.",
			source = "https://warcraft.wiki.gg/wiki/Red_Cloud_Mesa",
		},
		["red rocks"] = {
			name = "Rochers rouges",
			short = "Le grès rouge des Rochers rouges s'élève au nord-est de Mulgore, un lieu où le monde de Thunder Bluff s'efface pour laisser place à quelque chose de plus paisible.",
			full = "Le grès rouge des Rochers rouges s'élève au nord-est de Mulgore, un lieu où le monde de Thunder Bluff s'efface pour laisser place à quelque chose de plus paisible. C'est ici que les taurens confient leurs morts honorés à la Terre-mère et au Père-ciel par la flamme purificatrice. Tous les taurens tombés n'y sont pas amenés ; seuls les plus valeureux reçoivent ce repos, les guerriers qui ont fondé et défendu Thunder Bluff, ceux qui ont donné leur vie pour leurs tribus et leurs chefs. C'est aussi là que les jeunes braves viennent achever leur passage à l'âge adulte, debout parmi les pierres pour écouter la voix de leurs ancêtres dans le vent.\n\nLe caractère sacré du lieu ne l'a pas protégé. Une bande de hurans Dos-hirsute a forcé l'entrée des Rochers rouges et souillé la terre sainte de sa présence, un acte qui a suscité une profonde colère parmi les taurens de Thunder Bluff, pour qui ce lieu est cher.",
			source = "https://warcraft.wiki.gg/wiki/Red_Rocks",
		},
		["rolling plains"] = {
			name = "Les plaines vallonnées",
			short = "Les plaines vallonnées s'ouvrent au sud du village Bloodhoof et s'étendent jusqu'à la frontière des Tarides. Loups et cougars se déplacent dans les herbes aux côtés des kodos et des hauts-trotteurs.",
			full = "Les plaines vallonnées s'ouvrent au sud du village Bloodhoof et s'étendent jusqu'à la frontière des Tarides. Loups et cougars se déplacent dans les herbes aux côtés des kodos et des hauts-trotteurs.\n\nContrairement au reste de Mulgore, les plaines ne sont pas fermées : des éclaireurs centaures ont trouvé un passage par ici et parcourent des terres où aucun autre centaure ne s'aventure. Dans les confins de l'est, un nid de harpies Furies-des-vents s'est installé.",
			source = "https://warcraft.wiki.gg/wiki/Rolling_Plains",
		},
		["stonebull lake"] = {
			name = "Lac Taureau-de-pierre",
			short = "Le lac Taureau-de-pierre entoure le village Bloodhoof sur trois côtés, long fer à cheval d'eau fraîche. Ses eaux regorgent de poissons, et l'on y lance des lignes durant de longues heures paisibles.",
			full = "Le lac Taureau-de-pierre entoure le village Bloodhoof sur trois côtés, long fer à cheval d'eau fraîche. Ses eaux regorgent de poissons, et l'on y lance des lignes durant de longues heures paisibles. Là où le lac se resserre, un pont enjambe le passage, portant la route qui relie le village Bloodhoof à Thunder Bluff.",
			source = "https://warcraft.wiki.gg/wiki/Stonebull_Lake",
		},
		["thunderhorn water well"] = {
			name = "Puits Thunderhorn",
			short = "Le puits se trouve dans les herbes dégagées de Mulgore, le long de la route du nord entre Thunder Bluff et le village Bloodhoof.",
			full = "Le puits se trouve dans les herbes dégagées de Mulgore, le long de la route du nord entre Thunder Bluff et le village Bloodhoof. La KapitalRisk s'en empara jadis, espérant couper l'eau des taurens, mais ceux-ci la chassèrent et le reprirent.",
			source = "https://warcraft.wiki.gg/wiki/Thunderhorn_Water_Well",
		},
		["venture co mine"] = {
			name = "Mine de la KapitalRisk",
			short = "La mine s'enfonce profondément dans les falaises de l'est de Mulgore, avec trois accès : l'entrée principale à pied, une paroi rocheuse et un petit camp de bûcherons au-delà.",
			full = "La mine s'enfonce profondément dans les falaises de l'est de Mulgore, avec trois accès : l'entrée principale à pied, une paroi rocheuse et un petit camp de bûcherons au-delà. Elle n'a rien à faire là. Les taurens refusèrent à la KapitalRisk le droit d'exploiter des mines sur leur terre natale, et la compagnie se mit tout simplement à creuser malgré tout, plaçant le superviseur Fizsprocket à la tête de l'exploitation, tandis que le conseil consultatif du magnat Razdunk le pressait de s'étendre plus encore, jusqu'à l'exploitation forestière, en envoyant de nouveaux déchiqueteurs et des matériaux bruts pour qu'une scierie se nourrisse du bois de Mulgore.\n\nLes taurens ne laissèrent pas passer l'intrusion. Une caravane de matériel minier qui avançait sous escorte le long de la rive nord du lac Taureau-de-pierre fut repérée par les estafettes, qui l'attaquèrent et brûlèrent ce qu'elles purent, laissant l'épave derrière elles en supposant que le feu avait détruit tout ce qui valait la peine d'être pris. Il n'en était rien. On vit plus tard des récupérateurs de la KapitalRisk fouiller les cendres, ramassant ce que les flammes avaient épargné.\n\nCette découverte désigna la mine pour des représailles, un avertissement porté contre l'exploitation de Fizsprocket pour punir le refus de la compagnie de laisser en paix les terres taurènes.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Mine",
		},
		["wildmane water well"] = {
			name = "Puits Wildmane",
			short = "Le puits Wildmane se dresse au nord de Thunder Bluff ; c'est le plus septentrional des puits sacrés des taurens. Des harpies Furies-des-vents se sont emparées des terres alentour, et le puits, souillé, attend d'être purifié.",
			full = "Le puits Wildmane se dresse au nord de Thunder Bluff ; c'est le plus septentrional des puits sacrés des taurens. Des harpies Furies-des-vents se sont emparées des terres alentour, et le puits, souillé, attend d'être purifié.",
			source = "https://warcraft.wiki.gg/wiki/Wildmane_Water_Well",
		},
		["windfury ridge"] = {
			name = "Crête des Furies-des-vents",
			short = "La crête des Furies-des-vents doit son nom aux harpies qui nichent sur ses hauteurs, de féroces créatures qui fondent sur quiconque s'approche trop près, tuant ou emportant les imprudents.",
			full = "La crête des Furies-des-vents doit son nom aux harpies qui nichent sur ses hauteurs, de féroces créatures qui fondent sur quiconque s'approche trop près, tuant ou emportant les imprudents. Cougars et loups rôdent également dans les collines environnantes.\n\nPourtant, les plumes éclatantes des harpies sont prisées par les taurens de Thunder Bluff, qui s'en parent pour les mariages et les fêtes.",
			source = "https://warcraft.wiki.gg/wiki/Windfury_Ridge",
		},
		["winterhoof water well"] = {
			name = "Puits Winterhoof",
			short = "Le puits Winterhoof se trouve en bordure des plaines vallonnées, au sud de Mulgore. Des années après la troisième guerre, la KapitalRisk s'en empara et empoisonna ses eaux pour couper l'approvisionnement des taurens.",
			full = "Le puits Winterhoof se trouve en bordure des plaines vallonnées, au sud de Mulgore. Des années après la troisième guerre, la KapitalRisk s'en empara et empoisonna ses eaux pour couper l'approvisionnement des taurens. Mull Thunderhorn fabrique des totems pour purifier la souillure, mais le puits n'est pas encore pur.",
			source = "https://warcraft.wiki.gg/wiki/Winterhoof_Water_Well",
		},
	},
	-- Les Tarides: 31 subzones
	[1413] = {
		["agamagor"] = {
			name = "Agama'gor",
			short = "Agama'gor s'étend au nord de la route qui part vers l'ouest depuis le camp Taurajo, un dédale de bois épineux revendiqué par les hurans Dos-hirsute.",
			full = "Agama'gor s'étend au nord de la route qui part vers l'ouest depuis le camp Taurajo, un dédale de bois épineux revendiqué par les hurans Dos-hirsute. Leurs morts laissent derrière eux des éclats de sang séché, des trophées que l'exilé Mangletooth apprécie et contre lesquels il échange ses étranges faveurs.",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "Bael Modan",
			short = "La forteresse de pierre du donjon de Bael'dun s'élève là où se dressait jadis un village des taurens Stonespire.",
			full = "La forteresse de pierre du donjon de Bael'dun s'élève là où se dressait jadis un village des taurens Stonespire. En dessous, des excavateurs nains creusent en direction d'un antique complexe des Titans, un centre de recherche enseveli depuis avant même que les taurens ne foulent cette terre, et dont les reliques gisent encore, pour la plupart, inexplorées dans l'obscurité.\n\nLes nains arrivèrent avec des explosifs, dynamitant une terre que la tribu Stonespire tenait pour sacrée. Les fouilles déchirèrent la terre, et les taurens avec elle : la plus grande partie de la tribu fut tuée ou chassée des terres qu'elle gardait depuis des générations. Leur ancien village est désormais éventré par les machines d'excavation des nains. Gann Stonespire, qui arpente toujours les routes voisines, tenta de régler l'affaire d'un chef à un autre, par la parole plutôt que par le combat. Les nains refusèrent de renoncer aux fouilles. Il passa alors de la diplomatie à la guerre, cherchant toute force capable de les chasser.",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
		["baeldun keep"] = {
			name = "Donjon de Bael'dun",
			short = "Le donjon de Bael'dun domine le site de fouilles de Bael Modan, au sud des Tarides. Le général Twinbraid le commande, tenant le donjon et ses nains face aux taurens et aux orcs des plaines alentour.",
			full = "Le donjon de Bael'dun domine le site de fouilles de Bael Modan, au sud des Tarides. Le général Twinbraid le commande, tenant le donjon et ses nains face aux taurens et aux orcs des plaines alentour.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Keep",
		},
		["blackthorn ridge"] = {
			name = "Crête de Noirépine",
			short = "Les épines envahissent la vallée au nord du kraal de Tranchebauge, tenue par les hurans Tranchecrin. Sur la crête demeure Brine, une chamane. Sous son camp s'étend un bassin d'eau claire et pure au milieu des épines.",
			full = "Les épines envahissent la vallée au nord du kraal de Tranchebauge, tenue par les hurans Tranchecrin. Sur la crête demeure Brine, une chamane. Sous son camp s'étend un bassin d'eau claire et pure au milieu des épines.",
			source = "https://warcraft.wiki.gg/wiki/Blackthorn_Ridge",
		},
		["boulder lode mine"] = {
			name = "Mine des Pierriers",
			short = "La mine des Pierriers se trouve dans les Tarides ; ses tunnels sont étayés de bois orc et ornés de bannières de la Horde, reliques fanées de ceux qui creusèrent les premiers ces puits dans la roche.",
			full = "La mine des Pierriers se trouve dans les Tarides ; ses tunnels sont étayés de bois orc et ornés de bannières de la Horde, reliques fanées de ceux qui creusèrent les premiers ces puits dans la roche. Cette possession n'est plus. La KapitalRisk tient la mine, et les gobelins grouillent dans les galeries où travaillaient autrefois les orcs.\n\nLa nouvelle parvint au maître des quais Dizzywig que l'un des mineurs avait percé un filon et en avait extrait une émeraude géante. Le maître des quais la convoitait au point de promettre une part des bénéfices à quiconque accepterait d'aller l'arracher aux mains de la KapitalRisk.",
			source = "https://warcraft.wiki.gg/wiki/Boulder_Lode_Mine",
		},
		["bramblescar"] = {
			name = "Ronceplaie",
			short = "Les hurans Tranchecrin tiennent Ronceplaie. De l'autre côté de la route, à Agama'gor, se trouvent les Dos-hirsute, et entre les deux tribus il n'y a que la guerre.",
			full = "Les hurans Tranchecrin tiennent Ronceplaie. De l'autre côté de la route, à Agama'gor, se trouvent les Dos-hirsute, et entre les deux tribus il n'y a que la guerre. Qui s'aventure trop près du repaire des Tranchecrin verra les hurans attaquer sans attendre d'être provoqués.",
			source = "https://warcraft.wiki.gg/wiki/Bramblescar",
		},
		["camp taurajo"] = {
			name = "Camp Taurajo",
			short = "Le camp Taurajo se trouve dans les Tarides, près du col de montagne qui mène à Mulgore. Il offre repos et provisions à ceux qui viennent du village Bloodhoof avant qu'ils ne poursuivent leur route vers la patrie des taurens.",
			full = "Le camp Taurajo se trouve dans les Tarides, près du col de montagne qui mène à Mulgore. Il offre repos et provisions à ceux qui viennent du village Bloodhoof avant qu'ils ne poursuivent leur route vers la patrie des taurens.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Taurajo",
		},
		["crossroads"] = {
			name = "La Croisée",
			short = "La Croisée se trouve là où les routes se rejoignent : la piste nord-sud qui descend de la route de l'or, et la longue voie est-ouest qui va de Ratchet jusqu'aux Serres-Rocheuses.",
			full = "La Croisée se trouve là où les routes se rejoignent : la piste nord-sud qui descend de la route de l'or, et la longue voie est-ouest qui va de Ratchet jusqu'aux Serres-Rocheuses. C'est un lieu né de son carrefour plutôt que de ce qu'on y a bâti : peu de logis, pas de grandes murailles, rien que des tentes, des étals et des marchands qui crient plus fort les uns que les autres pour vendre ce qu'ils ont.\n\nPassé la lisière de la colonie s'étend un cimetière, simple et silencieux face au vacarme de la place marchande derrière lui. C'est ici que la Horde vient rendre hommage à ses morts, tout comme la Colline des sentinelles remplit ce rôle pour l'Alliance.",
			source = "https://warcraft.wiki.gg/wiki/Crossroads",
		},
		["dreadmist den"] = {
			name = "Refuge de Brume-funeste",
			short = "Une brume d'un rouge sombre plane éternellement sur le pic de Brume-funeste, le drapant de crépuscule. À l'intérieur, les sectateurs de la Lame ardente tiennent le refuge de Brume-funeste, où ils gardent la Graine démoniaque, un artefact qu'ils chérissent par-dessus tout.",
			full = "Une brume d'un rouge sombre plane éternellement sur le pic de Brume-funeste, le drapant de crépuscule. À l'intérieur, les sectateurs de la Lame ardente tiennent le refuge de Brume-funeste, où ils gardent la Graine démoniaque, un artefact qu'ils chérissent par-dessus tout. La brume elle-même semble protéger leur culte démoniaque des regards extérieurs.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Den",
		},
		["dreadmist peak"] = {
			name = "Pic de Brume-funeste",
			short = "Au nord-ouest de la Croisée, le pic de Brume-funeste s'élève dans les Tarides, son sommet étouffé par un brouillard rouge, vestige d'une antique malédiction démoniaque.",
			full = "Au nord-ouest de la Croisée, le pic de Brume-funeste s'élève dans les Tarides, son sommet étouffé par un brouillard rouge, vestige d'une antique malédiction démoniaque. Les sectateurs de la Lame ardente se sont installés à son sommet, gardant la Graine démoniaque dans le refuge de Brume-funeste, en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Peak",
		},
		["dry hills"] = {
			name = "Les Collines arides",
			short = "Les Collines arides s'élèvent, vertes, contre la poussière des Tarides, contreforts qui grimpent vers les Serres-Rocheuses.",
			full = "Les Collines arides s'élèvent, vertes, contre la poussière des Tarides, contreforts qui grimpent vers les Serres-Rocheuses. Les harpies Ensorçaile tiennent ce territoire, et elles se sont enhardies, s'abattant sur les caravanes le long de la route de l'or, au nord, avant de disparaître de nouveau dans la verdure.",
			source = "https://warcraft.wiki.gg/wiki/Dry_Hills",
		},
		["far watch post"] = {
			name = "Poste de garde extérieur",
			short = "Le poste de garde extérieur se trouve juste à l'ouest du pont qui relie Durotar aux Tarides ; ce n'est guère plus qu'une tour de guet, un terrier orc et une rangée de catapultes, avec un enclos à loups et ses deux péons un peu plus au sud.",
			full = "Le poste de garde extérieur se trouve juste à l'ouest du pont qui relie Durotar aux Tarides ; ce n'est guère plus qu'une tour de guet, un terrier orc et une rangée de catapultes, avec un enclos à loups et ses deux péons un peu plus au sud. Ce n'est pas une affectation confortable, mais elle est nécessaire : on y garde les caravanes en route vers Durotar et l'on y tient la ligne contre l'Alliance comme contre les hurans.",
			source = "https://warcraft.wiki.gg/wiki/Far_Watch_Post",
		},
		["field of giants"] = {
			name = "Champ des Géants",
			short = "Le Champ des Géants s'étend à travers le sud des Tarides, vaste et dégagé, là où des troupeaux de lézards-tonnerre et de kodos se déplacent ensemble en nombre tel que peu d'autres terres peuvent l'égaler.",
			full = "Le Champ des Géants s'étend à travers le sud des Tarides, vaste et dégagé, là où des troupeaux de lézards-tonnerre et de kodos se déplacent ensemble en nombre tel que peu d'autres terres peuvent l'égaler.\n\nLa route de l'or traverse ces plaines par sa branche sud, moins sûre ici qu'au nord. Des tours de guet se dressaient jadis le long de son tracé pour protéger les caravanes de passage ; elles sont vides désormais, abandonnées au vent et aux herbes.\n\nLa Horde n'a pas renoncé à ce territoire, bien que son emprise y soit mince. Sur une crête, à la lisière sud du Champ, vit la chamane Brine, à l'écart de tout camp et de tout carrefour. Non loin de là marche Gann Stonespire, qui nourrit une vieille rancune : sa tribu fut chassée de son village quand des nains vinrent creuser la terre en quête de ruines des Titans, sur des terres voisines de leur foyer. Ces fouilles devinrent Bael Modan, et Gann n'a pas oublié ce qu'elles ont coûté à son peuple.",
			source = "https://warcraft.wiki.gg/wiki/Field_of_Giants",
		},
		["forgotten pools"] = {
			name = "Les Bassins oubliés",
			short = "Les Bassins oubliés se trouvent au nord de la route de l'ouest qui part de la Croisée ; ce sont les plus septentrionales des oasis éparpillées dans le nord des Tarides.",
			full = "Les Bassins oubliés se trouvent au nord de la route de l'ouest qui part de la Croisée ; ce sont les plus septentrionales des oasis éparpillées dans le nord des Tarides. Leurs rives restent vertes, cerclées de champignons chargés que l'on ne trouve nulle part ailleurs, et leurs eaux abritent des poissons déviants sans pareils parmi ceux que l'on pêche ailleurs dans les Tarides.\n\nDes centaures Kolkar parcourent le bord de l'eau, aux côtés des tortues et des animaux sauvages qui s'y abritent.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Pools",
		},
		["fray island"] = {
			name = "Ile de la Dispute",
			short = "L'île de la Dispute, petite et aride, se trouve au large de la côte est des Tarides.",
			full = "L'île de la Dispute, petite et aride, se trouve au large de la côte est des Tarides.\n\nL'île sert de terrain d'entraînement aux guerriers de toutes races et de toutes croyances, réunis là sous l'égide de Klannoc Macleod.",
			source = "https://warcraft.wiki.gg/wiki/Fray_Island",
		},
		["gold road"] = {
			name = "Route de l'or",
			short = "La route de l'or s'étend entre le Rempart de Mor'shan et la Grande Fissure ; au-delà du pont qui marque la traversée, sa portion méridionale est connue sous le nom distinct de route de l'or méridionale.",
			full = "La route de l'or s'étend entre le Rempart de Mor'shan et la Grande Fissure ; au-delà du pont qui marque la traversée, sa portion méridionale est connue sous le nom distinct de route de l'or méridionale.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Road",
		},
		["groldom farm"] = {
			name = "Ferme de Grol'dom",
			short = "La ferme de Grol'dom est l'une des porcheries qui s'implantèrent dans les années qui suivirent la fondation d'Orgrimmar, et ses enclos subissent les raids incessants des pillards Tranchecrin.",
			full = "La ferme de Grol'dom est l'une des porcheries qui s'implantèrent dans les années qui suivirent la fondation d'Orgrimmar, et ses enclos subissent les raids incessants des pillards Tranchecrin.",
			source = "https://warcraft.wiki.gg/wiki/Grol'dom_Farm",
		},
		["lushwater oasis"] = {
			name = "Oasis luxuriante",
			short = "L'eau s'accumule là où la Grande Fissure s'abaisse, et les bêtes sauvages descendent à travers les arbres pour s'y abreuver. Les centaures Kolkar les attendent parmi les racines, chassant les animaux attirés par les bassins.",
			full = "L'eau s'accumule là où la Grande Fissure s'abaisse, et les bêtes sauvages descendent à travers les arbres pour s'y abreuver. Les centaures Kolkar les attendent parmi les racines, chassant les animaux attirés par les bassins.\n\nSous l'oasis se trouve l'entrée des cavernes des Lamentations, un lieu que l'on dit maudit. Ce qui remue en dessous ne remonte pas à la surface, mais son nom plane toujours sur les eaux.\n\nLes poissons d'ici ne ressemblent à aucun de ceux que l'on trouve ailleurs dans les Tarides.",
			source = "https://warcraft.wiki.gg/wiki/Lushwater_Oasis",
		},
		["merchant coast"] = {
			name = "La Côte des marchands",
			short = "La Côte des marchands tient son nom du commerce qui la traverse, économe et incessant, aux mains des gobelins de Ratchet.",
			full = "La Côte des marchands tient son nom du commerce qui la traverse, économe et incessant, aux mains des gobelins de Ratchet.\n\nLa côte sud appartient aux flibustiers des mers du Sud. Parmi eux se trouve le baron de Longrivage, qui vola jadis à Gazlowe une précieuse cargaison et l'enterra avant de pouvoir être capturé, laissant la fortune perdue quelque part le long du rivage.",
			source = "https://warcraft.wiki.gg/wiki/Merchant_Coast",
		},
		["morshan base camp"] = {
			name = "Campement de Mor'shan",
			short = "Le campement de Mor'shan se trouve au sud de la frontière d'Orneval, près du Rempart de Mor'shan ; c'est l'une des plus grandes possessions de la Horde dans les Tarides.",
			full = "Le campement de Mor'shan se trouve au sud de la frontière d'Orneval, près du Rempart de Mor'shan ; c'est l'une des plus grandes possessions de la Horde dans les Tarides. Les voltigeurs Warsong y ont établi leur base, surveillant la route qui mène au nord, vers la forêt disputée au-delà.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Base_Camp",
		},
		["morshan rampart"] = {
			name = "Le Rempart de Mor'shan",
			short = "Le Rempart de Mor'shan se dresse là où la route de l'or quitte les Tarides vers le nord ; il fut élevé comme un mur contre la poussée de l'Alliance venue d'Orneval.",
			full = "Le Rempart de Mor'shan se dresse là où la route de l'or quitte les Tarides vers le nord ; il fut élevé comme un mur contre la poussée de l'Alliance venue d'Orneval. C'est un ouvrage grossier, bâti pour la guerre : des terrassements et des tours de guet destinés à tenir une ligne contre les forces qui descendent du nord.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["raptor grounds"] = {
			name = "Terres des Raptors",
			short = "Les raptors solécaille qui peuplent cette petite vallée ne ressemblent à aucun autre dans les Tarides. Ils font preuve d'une ruse contre nature, construisant des huttes grossières et façonnant des outils avec des griffes qui ne devraient rien connaître de l'artisanat.",
			full = "Les raptors solécaille qui peuplent cette petite vallée ne ressemblent à aucun autre dans les Tarides. Ils font preuve d'une ruse contre nature, construisant des huttes grossières et façonnant des outils avec des griffes qui ne devraient rien connaître de l'artisanat.\n\nPlus étrange encore est leur appétit pour tout ce qui brille ou leur est inconnu, qui les a poussés à attaquer les colonies de la Horde voisines, emportant tout ce qui attire leur regard.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "Ratchet",
			short = "Ratchet se trouve sur la côte est des Tarides, une ville portuaire gobeline qui commerce activement avec Baie-du-Butin et le baron Revilgaz, de l'autre côté de la mer.",
			full = "Ratchet se trouve sur la côte est des Tarides, une ville portuaire gobeline qui commerce activement avec Baie-du-Butin et le baron Revilgaz, de l'autre côté de la mer. Gazlowe la fonda avec l'argent que Thrall lui avait versé pour avoir élevé Orgrimmar, et elle se remplit de contrebandiers et de tous ceux que les endroits respectables avaient refoulés.\n\nCette indifférence faillit lui coûter cher. Le culte de la Lame ardente œuvra en secret pour dresser Orgrimmar et Theramore l'une contre l'autre, provoquant près du port de Ratchet des incidents maritimes que ni l'un ni l'autre camp ne comprit autrement que comme des provocations. Les marins orcs et humains qui avaient partagé ses quais en paix se mirent à se battre dans ses rues, et lorsque le cogneur Muzzlecrank arrêta les capitaines Klatt et Joq, le Fort du Nord y vit la preuve que les orcs se massaient pour la guerre. Ratchet devint le point de ralliement d'une armée de la Horde qui s'apprêtait à marcher contre eux. Ce n'est que lorsque la main de la Lame ardente dans l'affaire fut révélée que Thrall annula le combat avant qu'il ne commence.",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["shrine of the fallen warrior"] = {
			name = "Autel du Guerrier mort",
			short = "Un sentier usé gravit une colline à l'ouest de la Croisée et s'achève devant l'autel d'un guerrier tombé. Aucun nom n'y est gravé, aucune bannière ne le signale.",
			full = "Un sentier usé gravit une colline à l'ouest de la Croisée et s'achève devant l'autel d'un guerrier tombé. Aucun nom n'y est gravé, aucune bannière ne le signale. La colline garde le silence, et le sentier qui y monte est le seul signe que quelqu'un s'en souvient encore.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "La Videfange",
			short = "Le marais des Boues n'a pas toujours été une plaie sur la terre. Il abritait jadis un bassin d'eau d'un bleu cristallin, avant que la KapitalRisk ne vienne y dresser un derrick.",
			full = "Le marais des Boues n'a pas toujours été une plaie sur la terre. Il abritait jadis un bassin d'eau d'un bleu cristallin, avant que la KapitalRisk ne vienne y dresser un derrick. Il n'en reste aujourd'hui qu'un bourbier de déchets industriels, exploité sous l'œil d'un superviseur gobelin qui répond de l'opération devant la Compagnie.\n\nLe derrick a attiré les rivaux autant qu'il a souillé l'eau. Le Syndicat des artisans de Ratchet, pressé par le directeur Riddlevox d'égaler les nouveaux déchiqueteurs de la KapitalRisk, renonça à les surpasser et choisit plutôt d'en voler purement et simplement la conception. Le gobelin Sputtervalve envoya Wizzlecrank s'emparer de l'une des machines dans le marais et la ramener à Ratchet. Wizzlecrank parvint seulement à grimper dans le déchiqueteur avant de découvrir qu'il n'avait pas de clé pour le faire avancer, et resta coincé en territoire ennemi jusqu'à ce que des secours arrivent et que la machine puisse être ramenée au nez et à la barbe des ouvriers de la Compagnie.",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern gold road"] = {
			name = "Route de l'or méridionale",
			short = "La route de l'or méridionale tient son nom des caravanes qui l'empruntent.",
			full = "La route de l'or méridionale tient son nom des caravanes qui l'empruntent. Elle va de la Grande élévation, à la lisière sud des Tarides, jusqu'au pont qui relie les deux moitiés des Tarides, au nord, où elle devient simplement la route de l'or.\n\nDes marchands viennent de loin par ce chemin : de Gadgetzan en Tanaris, d'Auberdine à Sombrivage, de Havrenuit au nord. Tous suivent la même route, attirés par le même commerce qui lui a donné son nom.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "Fleuve Furie-du-Sud",
			short = "La Furie-du-Sud prend sa source haut sur le mont Hyjal, jaillissant d'un lac de montagne en une chute qui dévale dans un fracas de tonnerre jusqu'aux basses terres.",
			full = "La Furie-du-Sud prend sa source haut sur le mont Hyjal, jaillissant d'un lac de montagne en une chute qui dévale dans un fracas de tonnerre jusqu'aux basses terres. De là, elle coule large et rapide, coupant la terre en deux : elle marque l'endroit où Orneval cède la place à Azshara et, plus au sud, celui où finissent les Tarides et où commence Durotar. À son embouchure, le fleuve se jette par une dernière cascade dans la Grande mer, juste au nord-est du port gobelin de Ratchet.\n\nTrois ponts l'enjambent sur toute sa longueur : l'un relie Azshara à Orneval, un autre mène les voyageurs jusqu'à Orgrimmar, et le dernier joint Durotar aux Tarides. Juste au nord du plus occidental d'entre eux, une seule étendue d'eau touche les quatre terres à la fois, le seul endroit où se rejoignent Orneval, Azshara, Durotar et les Tarides.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "L'oasis stagnante",
			short = "L'oasis stagnante est une étendue d'eau verte et immobile entre la Côte des marchands et la route de l'or. Des centaures Kolkar campent sur ses abords, et l'on dit que leur présence et leur vigueur proviennent des eaux stagnantes elles-mêmes.",
			full = "L'oasis stagnante est une étendue d'eau verte et immobile entre la Côte des marchands et la route de l'or. Des centaures Kolkar campent sur ses abords, et l'on dit que leur présence et leur vigueur proviennent des eaux stagnantes elles-mêmes. Les kodos qui errent ici sont affaiblis et solitaires, bien différents des grands troupeaux du Champ des Géants, au sud, et constituent des proies bien plus faciles. Des poissons déviants nagent sous la surface, prisés une fois cuisinés, tandis que des gueules d'acier de l'oasis rôdent à leurs côtés dans l'eau trouble.",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "Colline des épines",
			short = "La colline des Épines se dresse sur le versant nord d'un sommet, entre la Croisée et Durotar, et ses pentes grouillent de hurans de la tribu Tranchecrin.",
			full = "La colline des Épines se dresse sur le versant nord d'un sommet, entre la Croisée et Durotar, et ses pentes grouillent de hurans de la tribu Tranchecrin. Depuis ces hauteurs, ils ont attaqué les caravanes de la Horde qui traversaient la région, s'attirant la colère de ceux qui gardent les routes en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "L'Escalier des marées",
			short = "L'Escalier des marées s'élève au-dessus de la Côte des marchands en une série de larges terrasses de pierre, empilées comme l'escalier d'un géant tourné vers les flots.",
			full = "L'Escalier des marées s'élève au-dessus de la Côte des marchands en une série de larges terrasses de pierre, empilées comme l'escalier d'un géant tourné vers les flots. Islen Waterseer et Mahren Skyseer, deux taurens, se tiennent sur ces corniches, lançant leurs lignes dans le ressac et parlant avec les esprits qui demeurent dans les eaux en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "Cavernes des lamentations",
			short = "Les cavernes des Lamentations tiennent leur nom du son même des lieux : la vapeur qui jaillit des fissures de la roche, portée à travers les ténèbres en longs cris lugubres.",
			full = "Les cavernes des Lamentations tiennent leur nom du son même des lieux : la vapeur qui jaillit des fissures de la roche, portée à travers les ténèbres en longs cris lugubres.\n\nC'est le druide elfe de la nuit Naralex qui les découvrit, et qui leur donna leur raison d'être. Sous la savane couraient des cours d'eau qui refaisaient surface ailleurs, formant les oasis éparses des Tarides, et Naralex croyait qu'en reliant ces eaux au Rêve d'émeraude lui-même, il pourrait déverser cette vitalité verdoyante sur la terre desséchée au-dessus. Il conduisit ses disciples dans les cavernes et s'installa en méditation, s'offrant comme un canal entre le Rêve et le monde éveillé.\n\nC'est le Cauchemar d'émeraude qui s'empara de lui. Naralex ne put s'éveiller. À travers son corps endormi et ouvert, la corruption du Cauchemar se déversa dans les cavernes, souillant les eaux, déformant la faune en étranges créatures perverties et poussant la plupart de ses disciples à la folie ; ceux qui restèrent devinrent les druides du Croc.\n\nNaralex y dort encore, et les druides du Croc tiennent les cavernes contre quiconque voudrait l'éveiller.",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- Montagnes d'Alterac: 5 subzones
	[1416] = {
		["dalaran"] = {
			name = "Dalaran",
			short = "Dalaran s'éleva comme une cité de mages, fondée après les guerres des Trolls par les sorciers de l'empire d'Arathor, et devint une nation à part entière.",
			full = "Dalaran s'éleva comme une cité de mages, fondée après les guerres des Trolls par les sorciers de l'empire d'Arathor, et devint une nation à part entière. Son peuple n'obéissait à aucune couronne, hormis celle du Kirin Tor, ce cercle d'élite réunissant les plus puissants lanceurs de sorts du monde, gouverné par le Conseil des Six. En son cœur se dressait la Citadelle pourpre, sanctuaire et refuge de ceux qui étudiaient les arcanes, et aucune cité hors des terres elfiques de Quel'Thalas ne concentrait une telle puissance magique. Même les mages hauts-elfes de Quel'Thalas, malgré leur orgueil, s'inclinaient devant la souveraineté du Kirin Tor.\n\nCette souveraineté fut brisée par le feu. Lorsque le Fléau s'abattit sur Dalaran, son peuple fut chassé de son propre royaume, et Archimonde en personne réduisit la cité en ruine, dispersant les membres survivants du Kirin Tor à travers Azeroth.\n\nLes survivants ne laissèrent pas leur cité morte. Ils revinrent dans les décombres et entreprirent de la rebâtir, dressant un immense dôme de magie pour protéger son cœur brisé de nouveaux dommages.",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "Clos de Dandred",
			short = "Une petite ferme et un manoir se dressent à la lisière ouest des Hauteurs, là où la terre rejoint le Rivage brumeux et où un port s'ouvre sur le lac Lordamere.",
			full = "Une petite ferme et un manoir se dressent à la lisière ouest des Hauteurs, là où la terre rejoint le Rivage brumeux et où un port s'ouvre sur le lac Lordamere.\n\nC'est ici que vit Aliden, et avec lui sa maîtresse Elysa. Elle porte un collier qui appartenait jadis à Taretha Foxton.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["lordamere internment camp"] = {
			name = "Camp d'internement de Lordamere",
			short = "Le camp d'internement de Lordamere se trouve sur une colline dominant le cratère de Dalaran ; c'est le seul camp d'internement jamais élevé dans les montagnes d'Alterac, gardé par les forces de Dalaran.",
			full = "Le camp d'internement de Lordamere se trouve sur une colline dominant le cratère de Dalaran ; c'est le seul camp d'internement jamais élevé dans les montagnes d'Alterac, gardé par les forces de Dalaran.\n\nC'est ici qu'en route vers Dalaran, le prince Arthas Menethil et dame Jaina Proudmoore se glissèrent un jour, à la faveur de la nuit, entre les patrouilles et les tours de guet pour observer les orcs qui y étaient détenus. Ce qu'ils virent les divisa. Jaina regarda les femelles orques et leurs petits, et sentit sa certitude vaciller pour laisser place au doute et au remords. Arthas n'éprouva rien de tel, et soutint que les camps étaient nécessaires malgré tout. Nul ne les vit. Ils repartirent comme ils étaient venus, emportant avec eux leur désaccord.\n\nLa gardienne Belamoore commande aujourd'hui la garnison, étudiant les artefacts de pierre de sang que lui ont apportés Kegan Darkmar et ses compagnons.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["ruins of alterac"] = {
			name = "Ruines d'Alterac",
			short = "Des murs brisés escaladent les pentes des montagnes d'Alterac là où se dressait jadis une cité, avec son palais à demi debout, son église et son hôtel de ville effondrés sur eux-mêmes, et sa porte bâtie à la manière de celle de Stormwind.",
			full = "Des murs brisés escaladent les pentes des montagnes d'Alterac là où se dressait jadis une cité, avec son palais à demi debout, son église et son hôtel de ville effondrés sur eux-mêmes, et sa porte bâtie à la manière de celle de Stormwind.\n\nSa ruine vint de son propre roi. Pendant la deuxième guerre, le roi Aiden Perenolde trahit les siens, liant son sort à la Horde orque contre ses frères humains. On trouva des soldats d'Alterac combattant aux côtés des orcs, et un camp de prisonniers près de la cité détenait des citoyens de Dalaran. Lorsque la vérité éclata, les autres royaumes humains marchèrent sur Alterac en représailles. Le peuple s'enfuit ou fut chassé de ses foyers, et le roi Terenas Menethil II de Lordaeron plaça la cité sous la loi martiale, déposant Perenolde et le jetant aux fers.\n\nLa cité ne se releva jamais. Les ogres Cassecrête, menés par Mug'thol, s'installèrent dans les rues et le palais vides, tandis que les restes épars de l'ancien peuple d'Alterac tenaient les villages alentour. Des chariots à viande renversés gisent encore près du rempart nord et de la porte, et les cimetières à l'intérieur comme au-delà des murs, la ferme ensevelie sous la neige et les balistes fracassées parmi les décombres demeurent tels qu'on les a laissés.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "Les Hauteurs",
			short = "Les Hauteurs nourrissaient jadis un royaume. Leurs collines étaient le grenier d'Alterac, blé et pâturages pour l'ancienne nation.",
			full = "Les Hauteurs nourrissaient jadis un royaume. Leurs collines étaient le grenier d'Alterac, blé et pâturages pour l'ancienne nation.\n\nCette nation s'est brisée. Les Hauteurs ne sont passées à aucune couronne, mais au Syndicat, qui ne tient nulle part dans les montagnes aussi fermement qu'ici. Le baron Vardus commande parmi leurs camps, seigneur des terres restantes d'un royaume brisé.\n\nDans les confins les plus occidentaux se dresse le Clos de Dandred, un nom qui a survécu à ce qu'il a jamais pu signifier.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
	-- Hautes-terres d'Arathi: 19 subzones
	[1417] = {
		["boulderfist hall"] = {
			name = "Hall Rochepoing",
			short = "Le hall Rochepoing se dresse au sud des Hautes-terres d'Arathi, près du viaduc de Thandol et du village Witherbark, un tertre de pierre fortifié par des mains d'ogres.",
			full = "Le hall Rochepoing se dresse au sud des Hautes-terres d'Arathi, près du viaduc de Thandol et du village Witherbark, un tertre de pierre fortifié par des mains d'ogres. Dans la grande caverne en son cœur règne Kor'gresh Coldrage, chef du clan Rochepoing.\n\nLes ogres se sont depuis répandus dans les collines environnantes, renforçant encore leurs défenses.",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Hall",
		},
		["bouldergor"] = {
			name = "Boulder'gor",
			short = "Au nord du donjon de Stromgarde, la colline de Boulder'gor s'élève, accidentée et rugueuse. Les ogres Rochepoing y tiennent leur tertre, et des trolls des forêts Witherbark traînent à leurs côtés sur ses pentes.",
			full = "Au nord du donjon de Stromgarde, la colline de Boulder'gor s'élève, accidentée et rugueuse. Les ogres Rochepoing y tiennent leur tertre, et des trolls des forêts Witherbark traînent à leurs côtés sur ses pentes. Sur le versant est se dresse le Cercle des éléments, et juste au sud de la colline se trouvent deux fermes.",
			source = "https://warcraft.wiki.gg/wiki/Boulder'gor",
		},
		["circle of east binding"] = {
			name = "Cercle de lien oriental",
			short = "La pierre de Lien orientale veille sur les confins est des Hautes-terres d'Arathi, près de Trépas-d'Orgrim, marquant l'un des cercles de lien éparpillés dans la région.",
			full = "La pierre de Lien orientale veille sur les confins est des Hautes-terres d'Arathi, près de Trépas-d'Orgrim, marquant l'un des cercles de lien éparpillés dans la région. Des élémentaires d'eau gardent toujours la pierre, liés au lieu comme s'ils s'acquittaient d'une vieille tâche inachevée.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_East_Binding",
		},
		["circle of inner binding"] = {
			name = "Cercle de lien intérieur",
			short = "Le cercle de lien intérieur se dresse au sud des Hautes-terres d'Arathi, près du donjon de Stromgarde, gardé par des élémentaires de terre. Ici repose la pierre de Lien intérieure, la plus puissante des pierres.",
			full = "Le cercle de lien intérieur se dresse au sud des Hautes-terres d'Arathi, près du donjon de Stromgarde, gardé par des élémentaires de terre. Ici repose la pierre de Lien intérieure, la plus puissante des pierres.\n\nC'est par son éclat que Myzrael trouva le moyen de parler aux mortels.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Inner_Binding",
		},
		["circle of outer binding"] = {
			name = "Cercle de lien extérieur",
			short = "Le cercle de lien extérieur se trouve près du Refuge de l'Ornière, dans les Hautes-terres d'Arathi. En son centre se dresse la pierre de Lien extérieure, toujours gardée par des élémentaires d'air.",
			full = "Le cercle de lien extérieur se trouve près du Refuge de l'Ornière, dans les Hautes-terres d'Arathi. En son centre se dresse la pierre de Lien extérieure, toujours gardée par des élémentaires d'air.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Outer_Binding",
		},
		["circle of west binding"] = {
			name = "Cercle de lien occidental",
			short = "Le cercle de lien occidental se dresse à l'ouest des Hautes-terres d'Arathi, près du mur de Thoradin. Là repose la pierre de Lien occidentale, gardée par des élémentaires de feu qui ne la quittent jamais des yeux.",
			full = "Le cercle de lien occidental se dresse à l'ouest des Hautes-terres d'Arathi, près du mur de Thoradin. Là repose la pierre de Lien occidentale, gardée par des élémentaires de feu qui ne la quittent jamais des yeux.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_West_Binding",
		},
		["dabyries farmstead"] = {
			name = "Ferme des Dabyrie",
			short = "Dans le nord des Hautes-terres d'Arathi se trouve la ferme des Dabyrie, tenue par Kenata Dabyrie et ses enfants Fardel et Marcel, citoyens de Stromgarde fidèles à l'Alliance.",
			full = "Dans le nord des Hautes-terres d'Arathi se trouve la ferme des Dabyrie, tenue par Kenata Dabyrie et ses enfants Fardel et Marcel, citoyens de Stromgarde fidèles à l'Alliance. Une milice veille sur les champs, car la famille a des ennemis.",
			source = "https://warcraft.wiki.gg/wiki/Dabyrie's_Farmstead",
		},
		["drowned reef"] = {
			name = "Le récif englouti",
			short = "Sous la baie, au large de la côte sud des Hautes-terres d'Arathi, gît une cité elfique engloutie, antique et en ruine. Elle n'est plus vide : les nagas Daggerspine l'ont revendiquée, sous le règne du prince Nazjak.",
			full = "Sous la baie, au large de la côte sud des Hautes-terres d'Arathi, gît une cité elfique engloutie, antique et en ruine. Elle n'est plus vide : les nagas Daggerspine l'ont revendiquée, sous le règne du prince Nazjak.\n\nLe récif qui la surplombe a englouti bien des navires, parmi lesquels la Folie de la vierge et l'Esprit des Pins argentés. On dit que les Daggerspine peuvent retourner les marées mêmes de la baie, attirant sur les rochers les équipages qui croient avoir trouvé un havre sûr dans la crique de Faldir.",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "Gorge des Sèches-moustaches",
			short = "La gorge des Sèches-moustaches entaille les montagnes de l'est des Hautes-terres d'Arathi, au nord-est de Trépas-d'Orgrim. À son extrémité se trouve une grotte, repaire des kobolds Sèches-moustaches, alliés aux géants qui partagent ces hautes terres.",
			full = "La gorge des Sèches-moustaches entaille les montagnes de l'est des Hautes-terres d'Arathi, au nord-est de Trépas-d'Orgrim. À son extrémité se trouve une grotte, repaire des kobolds Sèches-moustaches, alliés aux géants qui partagent ces hautes terres.\n\nTout au fond, au-delà des galeries, repose un éclat de pierre dans lequel est emprisonnée une part de l'essence de la princesse Myzrael. Les kobolds le gardent farouchement, ainsi que les particules amassées dans les profondeurs de la grotte, bien qu'aucun d'eux ne semble savoir ce que renferme vraiment cet éclat.",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["faldirs cove"] = {
			name = "La Crique de Faldir",
			short = "La crique de Faldir tient son nom de Faldir, qui aurait marqué cet endroit lorsque lui et ses fidèles prirent la mer.",
			full = "La crique de Faldir tient son nom de Faldir, qui aurait marqué cet endroit lorsque lui et ses fidèles prirent la mer.\n\nBien plus tard, les Écumeurs des Flots noirs vinrent y chercher un trésor elfique qui reposerait dans les eaux voisines. Les capitaines Steelgut et O'Breen menèrent trois navires dans la crique, mais une étrange marée se leva contre eux, soulevée par les nagas qui gardaient des ruines englouties sous le récif, et deux des trois navires sombrèrent. Seul le Noir messager atteignit le rivage, et son équipage se retrouva prisonnier de la baie, incapable de repartir tant que les nagas n'auraient pas été chassés et que les journaux de navigation n'auraient pas été récupérés dans les épaves.\n\nPlus tard, deux ingénieurs gnomes, le docteur Draxlegauge et le professeur Phizzlethorpe, construisirent un appareil pour chercher les gemmes elfiques qui seraient calcifiées dans les pierres du récif englouti.\n\nLa crique porte encore les cicatrices de cette histoire noyée : récif, épave et ruine, qui parlent tous de navires qui n'auraient jamais dû sombrer, et d'un trésor que la mer n'a pas rendu.",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["goshek farm"] = {
			name = "Ferme de Go'Shek",
			short = "La ferme de Go'Shek se trouve à l'est des Hautes-terres d'Arathi, près du village Witherbark.",
			full = "La ferme de Go'Shek se trouve à l'est des Hautes-terres d'Arathi, près du village Witherbark. Après la troisième guerre, des Réprouvés et des orcs venus de Trépas-d'Orgrim s'emparèrent de la ferme pour leurs propres desseins : les orcs y puisaient des provisions, les Réprouvés transformèrent ses champs et ses dépendances en terrain d'essai pour une alchimie plus sombre.\n\nLes agents de l'Alliance Quae et Kinelory vinrent enquêter sur ce qui se passait ici. Avec de l'aide, ils abattirent un messager réprouvé en route pour Moulin-de-Tarren avant qu'il ne puisse remettre son message, et fouillèrent la ferme elle-même, où ils découvrirent les notes d'un certain apothicaire Jorell. Ses recherches indiquaient que quelque chose de nouveau et de terrible prenait forme : une autre peste en préparation.\n\nLes grunts de Trépas-d'Orgrim tiennent désormais la ferme.",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "Trépas-d'Orgrim",
			short = "Le sol de Trépas-d'Orgrim se souvient de ce qu'il fut jadis. Après la deuxième guerre, l'Alliance de Lordaeron y construisit l'un de ses plus grands camps d'internement, parquant les orcs capturés derrière ses murs.",
			full = "Le sol de Trépas-d'Orgrim se souvient de ce qu'il fut jadis. Après la deuxième guerre, l'Alliance de Lordaeron y construisit l'un de ses plus grands camps d'internement, parquant les orcs capturés derrière ses murs. Il ne resta pas une prison. Le chef de guerre Thrall et Orgrim Marteau du Destin menèrent la Horde contre le camp pour libérer leur peuple, et dans le chaos de cette libération, alors que Thrall couvrait la retraite, un chevalier lancé à la charge planta une lance dans le dos d'Orgrim avec une telle force qu'elle perça son armure de part en part. Doomhammer mourut là, sur la terre qu'il était venu libérer.\n\nAprès la troisième guerre, la Horde revint dans les ruines et y établit une base avancée, qu'elle nomma en l'honneur du chef de guerre tombé en la prenant. Elle devint plus qu'un avant-poste : un refuge pour ceux qui pensaient n'avoir plus leur place dans le monde, avec ses huttes des esprits, ses écuries, sa forge et sa grande salle dressées là où s'élevaient jadis les murs du camp d'internement.",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["northfold manor"] = {
			name = "Manoir de Nordclos",
			short = "Après la chute de Stromgarde, le manoir de Nordclos passa aux mains du Syndicat, qui en fit un avant-poste dans les Hautes-terres d'Arathi.",
			full = "Après la chute de Stromgarde, le manoir de Nordclos passa aux mains du Syndicat, qui en fit un avant-poste dans les Hautes-terres d'Arathi.\n\nC'est ici que vint le chaman troll Tor'gan, attiré par quelque chose d'anormal dans l'air. En remontant sa trace jusqu'au manoir, il découvrit les vestiges d'une invocation démoniaque encore accrochés aux lieux, et à mesure qu'il approchait, son propre sang se mit à bouillir d'une rage qui n'était pas entièrement la sienne. Sur le sol, il trouva une amulette de pierre de sang servant à invoquer des démons, bien que celle-ci ait été vidée de son pouvoir. Soupçonnant que les manigances du Syndicat allaient plus loin que le simple brigandage, il chercha d'autres amulettes semblables pour découvrir la vérité sur leurs intentions.",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "Refuge de l'Ornière",
			short = "Lorsque la capitale de Stromgarde tomba en ruine pendant la troisième guerre, la plupart de ses habitants s'enfuirent vers le sud, dans les Hautes-terres d'Arathi. Mais les restes de l'armée de Stromgarde refusèrent de les suivre.",
			full = "Lorsque la capitale de Stromgarde tomba en ruine pendant la troisième guerre, la plupart de ses habitants s'enfuirent vers le sud, dans les Hautes-terres d'Arathi. Mais les restes de l'armée de Stromgarde refusèrent de les suivre. Ils restèrent, déterminés à reconquérir ce qui avait été perdu, et c'est ici, au Refuge de l'Ornière, qu'ils livrèrent leur combat.\n\nL'avant-poste devint le siège de la guerre de l'Alliance dans les Hautes-terres, ses soldats résolus à reprendre le donjon de Stromgarde et à s'assurer toutes les ressources possibles pour la cause de l'Alliance. Cette détermination sans partage laissait peu de place à autre chose. Lorsque le viaduc de Thandol subit un violent assaut des Sombrefer et que ses nains demandèrent de l'aide pour reprendre Dun Modr et le viaduc lui-même, la capitaine Nials ne put épargner personne. Stromgarde était tombée, dit-elle, et tant qu'elle ne serait pas reprise, chaque épée et chaque main du Refuge de l'Ornière appartenaient à cette seule cause. L'honneur et le devoir les liaient aux Hautes-terres, dit-elle au messager, et Longbraid le Macabre devrait se débrouiller sans eux.",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["stromgarde keep"] = {
			name = "Donjon de Stromgarde",
			short = "Stromgarde était jadis Strom, berceau du premier royaume humain, capitale de l'empire d'Arathor.",
			full = "Stromgarde était jadis Strom, berceau du premier royaume humain, capitale de l'empire d'Arathor. Lorsque la Horde orque vint dans les Royaumes de l'est, elle demeurait une puissance au sein de l'Alliance de Lordaeron, son nom resté fier même après la deuxième guerre.\n\nLa cité fut mise à sac après la troisième guerre et laissée en ruine. Elle est aujourd'hui divisée en trois : le donjon intérieur, tenu par le Syndicat ; le quartier des mages en ruine, envahi par les ogres Rochepoing aidés des trolls Witherbark ; et le dernier quartier, toujours tenu par l'armée de Stromgarde, d'où le prince Galen Trollemort commande ce qui reste de son peuple.",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "Viaduc de Thandol",
			short = "Deux grandes arches de pierre enjambent le gouffre entre les Paluns et les Hautes-terres d'Arathi ; élevées par des mains naines, elles sont gardées depuis trois générations par la lignée des Anvilmar.",
			full = "Deux grandes arches de pierre enjambent le gouffre entre les Paluns et les Hautes-terres d'Arathi ; élevées par des mains naines, elles sont gardées depuis trois générations par la lignée des Anvilmar. Elles furent bâties après la guerre des Trois clans, lorsqu'Ironforge voulut rester fidèle à ses cousins Marteau-hardi du Nid-de-l'Aigle, et les ponts devinrent à la fois une route et un symbole entre les deux royaumes nains, portant un commerce qui les enrichit l'un et l'autre.\n\nLes ponts pouvaient supporter le poids d'armées entières, et servirent jadis de principale route commerciale entre nains et humains. C'est ici qu'Anduin Lothar chassa de Lordaeron les derniers restes de l'ancienne Horde et les repoussa vers Khaz Modan, les forçant à traverser le viaduc dans la défaite.\n\nAujourd'hui, le viaduc porte des cicatrices. Un complot des Sombrefer, ourdi par Kam Deepfury et Balgaras l'Immonde, a lourdement endommagé les ponts, et les forces naines luttent pour tenir ce qu'il en reste et reprendre la ville voisine de Dun Modr. De nombreux nains sont morts dans les combats, parmi lesquels Sully Balloo, Ebenezer Rustlocke et le frère de Longbraid le Macabre.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "Mur de Thoradin",
			short = "Le roi Thoradin éleva ce mur pour contenir les trolls amani, au temps où Strom était jeune et où Arathor venait tout juste de conquérir la contrée pour l'humanité.",
			full = "Le roi Thoradin éleva ce mur pour contenir les trolls amani, au temps où Strom était jeune et où Arathor venait tout juste de conquérir la contrée pour l'humanité. Des générations durant, il se dressa en sentinelle inébranlable, une ligne destinée à protéger l'humanité des incursions des trolls.\n\nDes siècles plus tard, le mur est toujours debout, mais gravement endommagé, ses pierres brisées et sa longue veille réduite à l'état de ruine.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "La Tour d'Arathor",
			short = "La Tour d'Arathor se dresse dans le quartier des mages du donjon de Stromgarde ; elle porte le nom de l'ancien empire d'Arathor, dont le royaume tient sa lignée.",
			full = "La Tour d'Arathor se dresse dans le quartier des mages du donjon de Stromgarde ; elle porte le nom de l'ancien empire d'Arathor, dont le royaume tient sa lignée.\n\nL'archimage Trelane étudiait jadis entre ses murs, et il y bâtit une défense tissée dans la tour elle-même, en sommeil jusqu'à ce qu'une gemme enchantée l'éveille. Lorsque le Syndicat et les ogres Rochepoing se refermèrent sur Stromgarde, Trelane tenta de tenir la tour grâce à sa création, mais cela ne suffit pas. Il s'enfuit de la cité, et la tour tomba avec elle. Les ogres Rochepoing s'approprièrent le quartier, et le mage ogre Ruul Onestone vint s'installer dans ses salles.\n\nTrelane ne cessa jamais de penser à ce qu'il y avait laissé : son phylactère, son orbe, une agate de braise travaillée de sa propre main. Il se tourna vers son ancien apprenti, l'archimage Malin, pour les récupérer auprès des ogres qui tenaient désormais la tour. On rapporta à Malin que les biens du vieux maître avaient été retrouvés, cachés dans des coffres au sein des salles qu'il appelait jadis les siennes.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["witherbark village"] = {
			name = "Village Witherbark",
			short = "Le village Witherbark s'étend autour d'un petit lac au sud-est des Hautes-terres d'Arathi ; c'est le foyer des trolls de la tribu Witherbark. Derrière le village se trouve une grande caverne où l'on trouve le plus souvent les chefs de la tribu.",
			full = "Le village Witherbark s'étend autour d'un petit lac au sud-est des Hautes-terres d'Arathi ; c'est le foyer des trolls de la tribu Witherbark. Derrière le village se trouve une grande caverne où l'on trouve le plus souvent les chefs de la tribu.\n\nLes Witherbark ont fait cause commune avec les ogres Rochepoing voisins, une alliance tournée contre Stromgarde et Trépas-d'Orgrim. Ensemble, trolls et ogres tiennent une partie de Stromgarde même, arrachée à ses anciens maîtres.\n\nCette force a fait des Witherbark un peuple marqué, traqué à la fois par l'Alliance et par la Horde, qui souhaitaient les voir disparaître. Parmi ceux qui se dressèrent contre ce règlement de comptes, Nimar le Pourfendeur fut désigné comme le plus dangereux, un combattant qui, dans la mort, emporta nombre de ses ennemis avec lui.",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
	-- Terres ingrates: 17 subzones
	[1418] = {
		["agmonds end"] = {
			name = "Fin d'Agmond",
			short = "Le site de fouilles du centre-sud des Terres ingrates porte le nom du nain qui y mourut.",
			full = "Le site de fouilles du centre-sud des Terres ingrates porte le nom du nain qui y mourut. Agmond vint briser la pierre et trouva les troggs qui avaient déjà revendiqué le terrain ; ils l'achevèrent sur place, et le site leur fut abandonné.",
			source = "https://warcraft.wiki.gg/wiki/Agmond's_End",
		},
		["angor fortress"] = {
			name = "Forteresse d'Angor",
			short = "Les nains Sombrefer tiennent la forteresse d'Angor, leur siège dans les Terres ingrates, d'où ils dirigent leurs fouilles vers Uldaman.",
			full = "Les nains Sombrefer tiennent la forteresse d'Angor, leur siège dans les Terres ingrates, d'où ils dirigent leurs fouilles vers Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Angor_Fortress",
		},
		["apocryphans rest"] = {
			name = "Repos d'Apocryphan",
			short = "Les ossements du Repos d'Apocryphan s'étalent à travers les Terres ingrates, au sud de Kargath : le squelette d'un dragon tombé, laissé à blanchir dans la chaleur sèche.",
			full = "Les ossements du Repos d'Apocryphan s'étalent à travers les Terres ingrates, au sud de Kargath : le squelette d'un dragon tombé, laissé à blanchir dans la chaleur sèche. Des busards nichent et chassent désormais parmi ses côtes, les seuls à revendiquer la grande carcasse comme demeure.",
			source = "https://warcraft.wiki.gg/wiki/Apocryphan's_Rest",
		},
		["camp boff"] = {
			name = "Camp Boff",
			short = "Le camp Boff est le camp sud-est des ogres Dustbelcher, l'un des quatre avec les camps Cagg, Kosh et Wurg. Peu d'ogres le gardent.",
			full = "Le camp Boff est le camp sud-est des ogres Dustbelcher, l'un des quatre avec les camps Cagg, Kosh et Wurg. Peu d'ogres le gardent.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Boff",
		},
		["camp cagg"] = {
			name = "Camp Cagg",
			short = "Le camp Cagg est l'un des foyers des ogres Dustbelcher, un nom qu'il partage avec trois autres camps disséminés non loin.",
			full = "Le camp Cagg est l'un des foyers des ogres Dustbelcher, un nom qu'il partage avec trois autres camps disséminés non loin.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Cagg",
		},
		["camp kosh"] = {
			name = "Camp Kosh",
			short = "Le camp Kosh se trouve à la lisière nord du territoire Dustbelcher, surveillant les routes stériles qui serpentent vers Kargath et descendent vers la gorge des Vents brûlants.",
			full = "Le camp Kosh se trouve à la lisière nord du territoire Dustbelcher, surveillant les routes stériles qui serpentent vers Kargath et descendent vers la gorge des Vents brûlants. Les caravanes qui traversent les Terres ingrates redoutent ce tronçon, car les ogres de Kosh s'abattent sur elles pour s'emparer de tout ce qu'elles transportent.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Kosh",
		},
		["camp wurg"] = {
			name = "Camp Wurg",
			short = "Le camp Wurg est l'un des foyers des ogres Dustbelcher, parents des ogres des camps Cagg, Boff et Kosh.",
			full = "Le camp Wurg est l'un des foyers des ogres Dustbelcher, parents des ogres des camps Cagg, Boff et Kosh.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Wurg",
		},
		["dustbelch grotto"] = {
			name = "Grotte de Crache-poussière",
			short = "Au sud-ouest des Terres ingrates s'élève un grand tertre de terre et de pierre, creusé et revendiqué par les ogres Dustbelcher.",
			full = "Au sud-ouest des Terres ingrates s'élève un grand tertre de terre et de pierre, creusé et revendiqué par les ogres Dustbelcher. La grotte de Crache-poussière est leur demeure, un dédale de tunnels et de salles où le clan a établi son repaire au milieu de la terre craquelée et brûlée par le soleil qui l'entoure.",
			source = "https://warcraft.wiki.gg/wiki/Dustbelch_Grotto",
		},
		["dustbowl"] = {
			name = "Vallée de la poussière",
			short = "La vallée de la Poussière s'étend entre Kargath et la vallée des Crocs, une étendue de terre aride et craquelée au nord-ouest des Terres ingrates. Coyotes et busards la parcourent, et des élémentaires de roche remuent parmi les pierres.",
			full = "La vallée de la Poussière s'étend entre Kargath et la vallée des Crocs, une étendue de terre aride et craquelée au nord-ouest des Terres ingrates. Coyotes et busards la parcourent, et des élémentaires de roche remuent parmi les pierres. Il n'y pousse guère que des cactus et quelques arbres obstinés. Le camp Wurg se dresse au milieu de ce désert.",
			source = "https://warcraft.wiki.gg/wiki/Dustbowl",
		},
		["dustwind gulch"] = {
			name = "Goulet de la Bourrasque",
			short = "Les vents récurent le goulet de la Bourrasque jusqu'à ce que rien de tendre n'y reste debout, seulement la pierre et les os secs du ravin. Il s'étend à l'ouest du ravin de Lethlor, une entaille de terre stérile dans les Terres ingrates où la poussière ne retombe jamais longtemps.",
			full = "Les vents récurent le goulet de la Bourrasque jusqu'à ce que rien de tendre n'y reste debout, seulement la pierre et les os secs du ravin. Il s'étend à l'ouest du ravin de Lethlor, une entaille de terre stérile dans les Terres ingrates où la poussière ne retombe jamais longtemps.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
		},
		["hammertoes digsite"] = {
			name = "Site de fouilles d'Hammertoe",
			short = "Le site de fouilles d'Hammertoe se trouve au nord des Terres ingrates ; ses tranchées sont désormais désertées par les mineurs qui y travaillaient autrefois.",
			full = "Le site de fouilles d'Hammertoe se trouve au nord des Terres ingrates ; ses tranchées sont désormais désertées par les mineurs qui y travaillaient autrefois. Hammertoe lui-même a abandonné le site, et à sa place, une bande de Sombrefer s'y est installée, probablement la même force qui a pénétré dans Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["kargath"] = {
			name = "Kargath",
			short = "Kargath se dresse seule en Khaz Modan, l'unique avant-poste que la Horde tienne dans cette contrée, et porte le nom de Kargath Bladefist, chef du clan de la Main brisée.",
			full = "Kargath se dresse seule en Khaz Modan, l'unique avant-poste que la Horde tienne dans cette contrée, et porte le nom de Kargath Bladefist, chef du clan de la Main brisée.\n\nSur l'ordre du chef de guerre Thrall en personne, le corps expéditionnaire de Kargath sillonne sans relâche les rudes Terres ingrates. Son véritable but est d'ouvrir une route à travers la gorge des Vents brûlants jusqu'au mont Blackrock, afin que la Horde puisse frapper Rend Blackhand, chef de guerre de la Horde noire, dans sa propre forteresse. Cette route traverse des terres que les nains Sombrefer considèrent comme les leurs, si bien que la Horde s'est de nouveau retrouvée en guerre contre eux, non par dessein, mais par la simple nécessité de traverser ces terres.\n\nL'autre valeur de Kargath est plus évidente : c'est la charnière entre le nord et le sud, le point où la route venant de Trépas-d'Orgrim et d'Undercity rejoint celle qui descend vers Grom'gol, Baie-du-Butin et Stonard.",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "Ravin de Lethlor",
			short = "Le ravin de Lethlor entaille, large et escarpé, l'est des Terres ingrates, et son fond est hanté par les dragonnets et les drakes du vol draconique noir.",
			full = "Le ravin de Lethlor entaille, large et escarpé, l'est des Terres ingrates, et son fond est hanté par les dragonnets et les drakes du vol draconique noir. Des obélisques cristallins se dressent çà et là dans le ravin, étranges et délibérés au milieu de la roche et du feu des dragons.",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "La Terrasse des faiseurs",
			short = "Devant l'entrée d'Uldaman, la terre a été décapée en larges entailles délibérées, une cicatrice de fouilles laissée à ciel ouvert.",
			full = "Devant l'entrée d'Uldaman, la terre a été décapée en larges entailles délibérées, une cicatrice de fouilles laissée à ciel ouvert. Les nains Sombrefer tiennent désormais la Terrasse, surveillant les fouilles et la route qui descend vers les lieux enfouis en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "Vallée des mirages",
			short = "La vallée des Mirages s'étend à l'est de la grotte de Crache-poussière, dans les Terres ingrates. Il n'en reste guère qu'une étendue de no man's land, revendiquée seulement par des busards géants, des patriarches traqueurs des crêtes et des coyotes des rochers enragés.",
			full = "La vallée des Mirages s'étend à l'est de la grotte de Crache-poussière, dans les Terres ingrates. Il n'en reste guère qu'une étendue de no man's land, revendiquée seulement par des busards géants, des patriarches traqueurs des crêtes et des coyotes des rochers enragés.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["uldaman"] = {
			name = "Uldaman",
			short = "Au plus profond des montagnes de Khaz Modan se trouve Uldaman, une vaste et antique chambre forte élevée par les gardiens titans en des âges depuis longtemps révolus.",
			full = "Au plus profond des montagnes de Khaz Modan se trouve Uldaman, une vaste et antique chambre forte élevée par les gardiens titans en des âges depuis longtemps révolus. Des nains d'Ironforge y creusèrent jadis, taillant dans ses salles ensevelies avant la troisième guerre, mais la chambre forte est depuis tombée aux mains des troggs et des Sombrefer, qui creusent désormais sa pierre en quête des richesses terrestres qu'elle recèle encore.\n\nUldaman reste riche des vestiges de cet âge forgé par les Titans, et ceux qui osent affronter ses profondeurs y trouvent encore des artefacts enfouis, lentement mis au jour par les archéologues et les aventuriers de la Ligue des Explorateurs qui continuent de fouiller la ruine.",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["valley of fangs"] = {
			name = "Vallée des crocs",
			short = "La vallée des Crocs s'étire, étroite, entre deux murailles de pierre dans les Terres ingrates, revendiquée par les loups et les cougars dont les crocs lui donnent son nom.",
			full = "La vallée des Crocs s'étire, étroite, entre deux murailles de pierre dans les Terres ingrates, revendiquée par les loups et les cougars dont les crocs lui donnent son nom.\n\nMartek l'Exilé y campe, chassé de l'endroit auquel il appartenait jadis, aux côtés de Rigglefuzz et de Jazzrik.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
		},
	},
	-- Terres foudroyées: 7 subzones
	[1419] = {
		["dark portal"] = {
			name = "La Porte des ténèbres",
			short = "La création de la Porte fut une trahison dès le premier coup. Gul'dan et le mage humain Medivh, ce dernier possédé par le titan noir Sargeras, ouvrirent ensemble la faille.",
			full = "La création de la Porte fut une trahison dès le premier coup. Gul'dan et le mage humain Medivh, ce dernier possédé par le titan noir Sargeras, ouvrirent ensemble la faille. Sur Draenor, les tailleurs de pierre orcs qui en bâtirent le cadre de pierre furent assassinés par des démonistes pour amorcer le sceau final, et presque tous les prisonniers draeneï encore détenus par la Horde furent amenés à sa base et vidés de leur vie en un seul instant, afin de donner à Gul'dan le pouvoir de relier les deux mondes. Par cette porte, la Horde se déversa sur Stormwind et déclencha la première guerre, et dans la guerre qui suivit, elle déversa sans fin orcs et ogres sur Azeroth, tandis que les marais alentour se changeaient en ce désert rouge sang que l'on appela plus tard les Terres foudroyées.\n\nÀ la fin de la guerre, l'archimage Khadgar et ses compagnons mages détruisirent la structure du côté d'Azeroth pour couper la retraite de la Horde, une explosion si violente qu'elle détruisit aussi le cadre sur Draenor. Khadgar éleva ensuite le Rempart-du-Néant pour monter la garde sur la ruine, mais la déchirure entre les mondes ne fut jamais vraiment refermée, et des démons la franchiraient de nouveau dans les années suivantes.",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul post"] = {
			name = "Poste Cognepeur",
			short = "Le poste Cognepeur est un tertre élevé par le clan ogre Cognepeur, venu de Draenor jusqu'à Azeroth et qui ne s'est jamais beaucoup éloigné de la Porte des ténèbres.",
			full = "Le poste Cognepeur est un tertre élevé par le clan ogre Cognepeur, venu de Draenor jusqu'à Azeroth et qui ne s'est jamais beaucoup éloigné de la Porte des ténèbres. Ils tiennent toujours ce terrain.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["garrison armory"] = {
			name = "Armurerie de la garnison",
			short = "Dans le sol meurtri des Terres foudroyées, des mineurs de l'Alliance exploitent l'armurerie de la garnison, arrachant des minerais à la terre pour le Rempart-du-Néant.",
			full = "Dans le sol meurtri des Terres foudroyées, des mineurs de l'Alliance exploitent l'armurerie de la garnison, arrachant des minerais à la terre pour le Rempart-du-Néant. Ce qu'ils récoltent est expédié à Stormwind, et en retour, la forteresse reçoit les autres provisions dont elle a besoin pour tenir dans ce lieu flétri.",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["nethergarde keep"] = {
			name = "Rempart-du-Néant",
			short = "Le Rempart-du-Néant se dresse sur un haut promontoire au-dessus de la seule route qui mène aux Terres foudroyées, ses murs élevés pour surveiller une cicatrice du monde que nul ne voulait voir se rouvrir.",
			full = "Le Rempart-du-Néant se dresse sur un haut promontoire au-dessus de la seule route qui mène aux Terres foudroyées, ses murs élevés pour surveiller une cicatrice du monde que nul ne voulait voir se rouvrir.\n\nL'archimage Khadgar en demanda la construction dans les années qui suivirent la deuxième guerre, lorsque la première Porte des ténèbres gisait brisée et que les terres natales des orcs, au-delà, s'étaient flétries jusqu'à la ruine. L'Alliance de Lordaeron la finança, certains royaumes plus volontiers que d'autres, et la guilde des Maçons l'éleva sous la direction d'Edwin VanCleef. Le Kirin Tor y tint ensuite garnison, s'efforçant de contenir la souillure qui s'échappait de la blessure de la Porte et menaçait de se répandre sur les terres au-delà.\n\nKhadgar en resta le maître jusqu'à ce que les clans de Ner'zhul reforgent la Porte des ténèbres depuis Draenor et assiègent la forteresse. Khadgar et ses compagnons Turalyon, Danath Trollemort, Alleria Coursevent et Kurdran Marteau-hardi menèrent l'Alliance à travers la Porte pour y briser la Horde, puis restèrent de l'autre côté pour la sceller, afin que la ruine de Draenor ne les suive pas jusque chez eux. Pendant vingt ans, la Porte resta silencieuse.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["rise of the defiler"] = {
			name = "Cime du Souilleur",
			short = "La cime du Souilleur se dresse au milieu des Terres foudroyées, une étendue escarpée de montagne brisée. Ici demeure le grand démon Razelikh, dont la seule présence suffit à donner son nom au lieu.",
			full = "La cime du Souilleur se dresse au milieu des Terres foudroyées, une étendue escarpée de montagne brisée. Ici demeure le grand démon Razelikh, dont la seule présence suffit à donner son nom au lieu.",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["serpents coil"] = {
			name = "Anneaux du serpent",
			short = "Les Anneaux du serpent sont un réseau de grottes sinueuses à l'est des Terres foudroyées, dont l'entrée est marquée par des structures orques calcinées, vestiges de la deuxième guerre.",
			full = "Les Anneaux du serpent sont un réseau de grottes sinueuses à l'est des Terres foudroyées, dont l'entrée est marquée par des structures orques calcinées, vestiges de la deuxième guerre. Longtemps après la fin de cette guerre, les grottes devinrent le repaire de quelque chose de plus sombre : des sectateurs voués au culte de Kirith le Damné.\n\nDans ce labyrinthe vint l'archimage Allistarj, qui y mit ses liges d'ombre à l'œuvre. Près de l'entrée, un coffre renferme une amulette portant son nom.",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["tainted scar"] = {
			name = "La Balafre impure",
			short = "La Balafre impure faisait jadis partie du Noir Marécage, avant que la corruption de la Porte des ténèbres ne s'y répande et ne laisse le sol sec, sans arbres et rouge comme le sang.",
			full = "La Balafre impure faisait jadis partie du Noir Marécage, avant que la corruption de la Porte des ténèbres ne s'y répande et ne laisse le sol sec, sans arbres et rouge comme le sang. Aucune eau n'y coule plus. Des bêtes démoniaques rôdent sur une terre qui ne se souvient plus de ce qui y poussait.\n\nAprès la bataille du mont Hyjal, le seigneur ered'ruin Kazzak retira dans la Balafre ce qui restait des forces de la Légion ardente sur Azeroth, et en fit son domaine. Il plaça son lieutenant Razelikh le Souilleur à sa tête, le chargeant de tenir la terre. Kazzak lui-même y resta ensuite, sa seule présence suffisant à marquer la Balafre comme territoire de la Légion, des années après que la bataille d'Hyjal eut été livrée et gagnée ailleurs.\n\nUn vieux démoniste humain, Daio le Décrépit, vint à la Balafre bien plus tard et s'installa près de son autel. Là, parmi les démons que la terre engendrait déjà, il pratiquait ses rituels sans être dérangé et prenait de jeunes recrues, leur enseignant les arts infernaux en un lieu déjà livré à la gangrène.",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- Clairières de Tirisfal: 28 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "Crypte de la famille Agamand",
			short = "Au nord des moulins d'Agamand, les morts de la famille Agamand reposaient jadis dans cette crypte. Le capitaine Dargol, un serviteur du Fléau, s'empara des lieux et réveilla chaque cadavre et chaque esprit qui s'y trouvait.",
			full = "Au nord des moulins d'Agamand, les morts de la famille Agamand reposaient jadis dans cette crypte. Le capitaine Dargol, un serviteur du Fléau, s'empara des lieux et réveilla chaque cadavre et chaque esprit qui s'y trouvait. Désormais, la poussière flotte, épaisse, dans les sombres couloirs, et les morts vengeurs frappent quiconque entre sans y être invité.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "Moulins d'Agamand",
			short = "Les moulins d'Agamand tournaient jadis pour l'une des familles les plus riches de Tirisfal. Lorsque le Fléau arriva dans le nord, Gregor Agamand refusa de fuir.",
			full = "Les moulins d'Agamand tournaient jadis pour l'une des familles les plus riches de Tirisfal. Lorsque le Fléau arriva dans le nord, Gregor Agamand refusa de fuir. Il fortifia les moulins, les approvisionna en prévision d'un siège et convainquit les propres ouvriers de la famille de rester et de combattre à leurs côtés.\n\nIls auraient dû tenir. Ils ne tinrent pas, car la trahison vint de l'intérieur des murs. Devlin, le cadet des fils Agamand, se retourna contre son propre sang et aida le Fléau, et la garnison ne put tenir la ligne face aux assauts qui suivirent. Avec le temps, la peste emporta de toute façon le reste de la famille, et les Agamand morts en défendant leur foyer s'y relevèrent en morts sans esprit.\n\nLes moulins se dressent toujours sur les hauteurs du nord de Tirisfal, et la famille qui les bâtit sert désormais l'armée même qui l'a brisée.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "Ferme des Balnir",
			short = "La ferme des Balnir se trouve au nord-est de la capitale en ruine ; ses clôtures sont brisées et ses écuries vides, hormis les créatures du Fléau qui y errent.",
			full = "La ferme des Balnir se trouve au nord-est de la capitale en ruine ; ses clôtures sont brisées et ses écuries vides, hormis les créatures du Fléau qui y errent.\n\nLa famille Balnir exploitait jadis cette terre, élevant les grands chevaux blancs que montait la maison royale de Lordaeron. Le jour où la capitale tomba, le Fléau vint à la ferme et tua toute la famille, ne laissant derrière lui que leur terre hantée.\n\nLes gueules-de-loup que l'on cultivait jadis dans le jardin de la ferme y poussent toujours à l'état sauvage, et la rumeur est parvenue aux vivants que la corruption des Maleterres pourrait s'y être insinuée. Les créatures du Fléau qui se faufilent au-delà de la Barricade se rassemblent en nombre autour de la ferme en ruine.",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["brightwater lake"] = {
			name = "Lac Etincelant",
			short = "Le lac Étincelant s'étend au nord-est de Brill ; ses eaux entourent en leur centre une grande île où se dresse désormais la Retraite de Gunther.",
			full = "Le lac Étincelant s'étend au nord-est de Brill ; ses eaux entourent en leur centre une grande île où se dresse désormais la Retraite de Gunther.",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "Brill",
			short = "Brill était jadis une ville ordinaire du royaume de Lordaeron, tenue par la famille Barov, où les Agamand possédaient aussi leur propre manoir.",
			full = "Brill était jadis une ville ordinaire du royaume de Lordaeron, tenue par la famille Barov, où les Agamand possédaient aussi leur propre manoir. Son caractère ordinaire prit fin le jour où Kel'Thuzad y vint. Encore vivant à l'époque, le nécromancien choisit Brill pour y tester en premier la peste de la non-mort, et le succès de cette contamination fut si total qu'il l'enhardit à presser le roi-liche de lancer prématurément l'invasion de Lordaeron. Les morts des clairières de Tirisfal étaient plus nombreux que la terre ne pouvait en ensevelir dignement ; le grand cimetière hors des murs de Brill est la réponse à ce surplus. Les propres défenseurs de la ville ne purent la tenir, et les rares survivants s'enfuirent pour rejoindre le prince Arthas Menethil, qui traquait la source de la corruption balayant le nord.\n\nBrill ne resta pas silencieuse. Des années plus tard, les Réprouvés la revendiquèrent, et le magistrat Sevren gouverne désormais ce que la peste avait jadis pris. De vieilles rancunes y persistent aussi : Coleman Farthing, jadis au service de la famille Agamand, cherche toujours leurs restes, des ossements réclamés non par pitié mais par vengeance pour une mort dont il les tient pour responsables.",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "Hôtel de ville de Brill",
			short = "L'hôtel de ville est l'édifice le plus imposant de Brill. Depuis sa tribune, le magistrat Sevren parle au nom de la ville, assignant leurs tâches aux morts de Tirisfal.",
			full = "L'hôtel de ville est l'édifice le plus imposant de Brill. Depuis sa tribune, le magistrat Sevren parle au nom de la ville, assignant leurs tâches aux morts de Tirisfal. Rares sont les salles de ce genre qui se trouvent, comme celle-ci, aux mains des Réprouvés, signe de la fermeté avec laquelle Brill leur appartient.",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "La Barricade",
			short = "La Barricade se dresse là où les clairières de Tirisfal rejoignent les Maleterres de l'ouest ; c'est la ligne que les Réprouvés tiennent contre le Fléau qui se masse toujours à l'est.",
			full = "La Barricade se dresse là où les clairières de Tirisfal rejoignent les Maleterres de l'ouest ; c'est la ligne que les Réprouvés tiennent contre le Fléau qui se masse toujours à l'est. Ici, les défenseurs réprouvés et l'Aube d'argent ont mis de côté leurs différends face à cet ennemi commun, surveillant ensemble la frontière et envoyant des combattants vers l'est pour frapper les serviteurs du roi-liche.\n\nContrairement au reste de Tirisfal, cette étendue ne ressemble en rien aux clairières : une brume pestilentielle la recouvre, teintant le ciel du même gris-jaune maladif que les Maleterres de l'ouest au-delà.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["cold hearth manor"] = {
			name = "Manoir du Foyer froid",
			short = "Le manoir du Foyer froid devait jadis son nom à la chaleur de son âtre et à la richesse de ses champs. La peste de la non-mort y mit fin.",
			full = "Le manoir du Foyer froid devait jadis son nom à la chaleur de son âtre et à la richesse de ses champs. La peste de la non-mort y mit fin. Tous ceux qui y vivaient ou y travaillaient moururent de la maladie, et la terre généreuse devint stérile, ses rangs envahis par des morts sans esprit du Fléau qui s'y traînent encore.\n\nLes Réprouvés ont pris la ferme pour eux et y commercent avec les voyageurs de la route voisine.",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "Avant-poste des Croisés",
			short = "Une tour d'observation s'élève dans les collines de l'est des clairières de Tirisfal, tenue par la Croisade écarlate.",
			full = "Une tour d'observation s'élève dans les collines de l'est des clairières de Tirisfal, tenue par la Croisade écarlate. De ses hauteurs, les croisés surveillent la route qui descend vers le sud à travers les clairières, prêts à prendre à revers toute force qui oserait marcher sur le Monastère écarlate au-delà. Le capitaine Vachon y commande.",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["deathknell"] = {
			name = "Le Glas",
			short = "Le Glas se niche dans une vallée étroite et bien gardée, et c'est ici que les Réprouvés fraîchement relevés ouvrent pour la première fois les yeux sur le monde qui leur a été donné.",
			full = "Le Glas se niche dans une vallée étroite et bien gardée, et c'est ici que les Réprouvés fraîchement relevés ouvrent pour la première fois les yeux sur le monde qui leur a été donné.\n\nContrairement aux autres possessions des morts-vivants rebelles de la reine banshee, qui ont conservé les noms qu'elles portaient du temps où c'étaient des villes vivantes, le Glas reçut un nom entièrement nouveau, adapté à ce qui s'y passe plutôt qu'à ce qui s'y dressait autrefois. Nul ne se souvient aujourd'hui pourquoi.\n\nIci, survivre est un combat de chaque jour, et l'or est la chose la plus rare qui soit. Au nord-ouest du village se trouve une mine riche en métal, mais elle a été envahie par les araignées, et les morts du Glas y retournent encore et encore pour tenter de la nettoyer, afin que le minerai qu'elle renferme puisse enfin être exploité. Des gardes noirs d'élite veillent aux abords de la vallée, seul rempart entre les fragiles nouveaux morts et le Fléau ou la Croisade écarlate, qui les tueraient une seconde fois.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["faols rest"] = {
			name = "Repos de Faol",
			short = "Au sud-ouest du Monastère écarlate, à l'est des clairières de Tirisfal, se trouve un lopin de terre jadis entretenu par des endeuillés : le Repos de Faol, la tombe de l'archevêque Alonsus Faol.",
			full = "Au sud-ouest du Monastère écarlate, à l'est des clairières de Tirisfal, se trouve un lopin de terre jadis entretenu par des endeuillés : le Repos de Faol, la tombe de l'archevêque Alonsus Faol.\n\nFaol était vénéré de son vivant, et sa mort, survenue quelque temps avant l'arrivée du Fléau, attira des endeuillés en ce lieu.\n\nPlus personne ne vient visiter la tombe qu'il a laissée. Les endeuillés qui venaient jadis ont disparu, et le lopin, laissé à l'abandon, est presque oublié.",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "Taverne des Pendus",
			short = "La taverne des Pendus se trouve à Brill, et son nom est l'écho sinistre de la ville qu'elle sert.",
			full = "La taverne des Pendus se trouve à Brill, et son nom est l'écho sinistre de la ville qu'elle sert. Sous son plancher, les caves ne renferment aucun tonneau digne de ce nom : on y garde un zélote écarlate capturé et un montagnard nain, prisonniers des Réprouvés.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "Antre de Garren",
			short = "L'antre de Garren était jadis une ferme prospère du nord des clairières de Tirisfal, aux champs vastes et aux silos pleins. La peste de la non-mort y mit fin.",
			full = "L'antre de Garren était jadis une ferme prospère du nord des clairières de Tirisfal, aux champs vastes et aux silos pleins. La peste de la non-mort y mit fin. Lorsque le Fléau déferla sur Lordaeron, Garren et sa famille furent massacrés chez eux, et la terre elle-même devint grise et sans vie autour de leur demeure en ruine.\n\nCe qui tient encore debout fut revendiqué par les gnolls Poil-putride, menés par Œil-de-ver, qui s'approprièrent la ferme et la grange et attaquaient sans hésiter quiconque s'approchait trop près.\n\nLa ferme ne s'en est jamais remise. Elle reste abandonnée, ses champs vides, sa famille disparue, et seuls les gnolls sont là pour dire qui la tient désormais.",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["gunthers retreat"] = {
			name = "Retraite de Gunther",
			short = "Sur une île du lac Étincelant se dresse la Retraite de Gunther, revendiquée par la liche réprouvée Gunther Arcanus et ses serviteurs zombies.",
			full = "Sur une île du lac Étincelant se dresse la Retraite de Gunther, revendiquée par la liche réprouvée Gunther Arcanus et ses serviteurs zombies. Au large de sa rive sud-ouest, sur un îlot nu et sans nom, se trouve un étrange repère connu seulement sous le nom de Table de dîner de Lillith.",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "Grottes des Tisse-nuit",
			short = "Les grottes des Tisse-nuit forment une petite vallée traversée par une vieille mine d'or, l'une et l'autre revendiquées par les araignées. Les jeunes errent dans le creux à ciel ouvert, tandis que les araignées Tisse-nuit adultes tiennent les tunnels plus sombres de la mine.",
			full = "Les grottes des Tisse-nuit forment une petite vallée traversée par une vieille mine d'or, l'une et l'autre revendiquées par les araignées. Les jeunes errent dans le creux à ciel ouvert, tandis que les araignées Tisse-nuit adultes tiennent les tunnels plus sombres de la mine.\n\nLes Réprouvés fraîchement relevés viennent ici éprouver ce dont leur corps est encore capable, abattant les jeunes araignées à l'extérieur avant d'oser affronter la mine elle-même.\n\nDans son recoin le plus profond se tient la matriarche Tisse-nuit, mère de l'essaim qui grouille au-dessus d'elle.",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "Vallée des cauchemars",
			short = "À l'ouest de la tour de guet écarlate, dans les clairières de Tirisfal, s'étend une vallée tombée en ruine. Ses arbres se sont flétris, et la faune qui vivait autrefois parmi eux a été dévorée par des chiens noirs et d'énormes chauves-souris vampires.",
			full = "À l'ouest de la tour de guet écarlate, dans les clairières de Tirisfal, s'étend une vallée tombée en ruine. Ses arbres se sont flétris, et la faune qui vivait autrefois parmi eux a été dévorée par des chiens noirs et d'énormes chauves-souris vampires. Parmi ces chasseurs vole Ressan l'Aiguillonneur, une rare chauve-souris blanche qui ne ressemble à aucune autre.",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "La Côte nord",
			short = "La Côte nord s'étend là où les clairières de Tirisfal rejoignent la Grande mer, livrée désormais aux murlocs et aux créatures des eaux.",
			full = "La Côte nord s'étend là où les clairières de Tirisfal rejoignent la Grande mer, livrée désormais aux murlocs et aux créatures des eaux. Depuis la peste de la non-mort, le rivage est devenu sombre et froid, et la marée laisse des créatures marines mortes pourrir au bord de l'eau.",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["ruins of lordaeron"] = {
			name = "Ruines de Lordaeron",
			short = "Au-dessus de la cité enfouie, le palais de Lordaeron se dresse toujours, ses salles ouvertes au ciel, ses jardins en ruine. C'est ici que mourut le grand royaume de l'Alliance, et c'est ici que ses fantômes ne sont jamais tout à fait partis.",
			full = "Au-dessus de la cité enfouie, le palais de Lordaeron se dresse toujours, ses salles ouvertes au ciel, ses jardins en ruine. C'est ici que mourut le grand royaume de l'Alliance, et c'est ici que ses fantômes ne sont jamais tout à fait partis.\n\nCe fut Arthas Menethil qui y mit fin. Le prince rentra chez lui à la tête d'une armée levée contre son propre peuple, accueilli à ces portes par les cloches et les acclamations avant que quiconque ne comprenne ce qu'il était devenu. Il trouva son père, le roi Terenas, qui l'attendait dans la salle du trône, et le tua sur place. Debout au-dessus du corps, il prononça des paroles qui résonnent encore dans cette salle pour qui s'y attarde : le royaume tomberait, et de ses cendres s'élèverait un ordre nouveau qui ébranlerait le monde. Ce n'était pas une vaine fanfaronnade. En quelques jours, la cité et son peuple furent massacrés, et Lordaeron appartint au Fléau.\n\nOn dit qu'en arpentant encore la cour, on peut entendre ce dont la pierre se souvient : des voix étouffées, le tintement des cloches de bienvenue, un murmure venu de la salle du trône qui ne s'éteint jamais tout à fait. Ceux qui voient au-delà du voile affirment que les habitants de Lordaeron y marchent encore, ignorant que leur royaume n'est plus.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet monastery"] = {
			name = "Monastère écarlate",
			short = "Sous la Croisade, le vieux monastère devint caserne et prison. L'inquisitrice Whitemane et Renault Mograine y établirent leur siège, et sa chapelle devint un lieu de jugement autant que de prière.",
			full = "Sous la Croisade, le vieux monastère devint caserne et prison. L'inquisitrice Whitemane et Renault Mograine y établirent leur siège, et sa chapelle devint un lieu de jugement autant que de prière.\n\nAvant d'être une forteresse, le vieux monastère était une cathédrale de l'Église de la Lumière sacrée, remplie de bibliothèques où s'entraînaient les paladins. Alexandros Mograine lui-même y passa des mois dans sa jeunesse, à prier et à étudier avant même de porter une lame.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet watch post"] = {
			name = "Poste de garde de la Croisade",
			short = "Le poste de garde de la Croisade veille sur l'approche que le Monastère écarlate ne peut défendre seul. Le capitaine Melrache y commande, tenant le poste contre quiconque voudrait frapper sans être vu le flanc exposé du monastère.",
			full = "Le poste de garde de la Croisade veille sur l'approche que le Monastère écarlate ne peut défendre seul. Le capitaine Melrache y commande, tenant le poste contre quiconque voudrait frapper sans être vu le flanc exposé du monastère.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["shadow grave"] = {
			name = "Tombeau des ombres",
			short = "Le Tombeau des ombres se dresse au sommet de la pente, parmi les tombes du Glas, haut dans les montagnes de Tirisfal. Un sentier usé serpente depuis son entrée jusqu'au Glas, en contrebas.",
			full = "Le Tombeau des ombres se dresse au sommet de la pente, parmi les tombes du Glas, haut dans les montagnes de Tirisfal. Un sentier usé serpente depuis son entrée jusqu'au Glas, en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["solliden farmstead"] = {
			name = "Ferme des Solliden",
			short = "Les champs de citrouilles des Solliden sont l'une des rares parcelles de Tirisfal où l'ancienne vie n'a pas été engloutie par la peste ou la non-mort.",
			full = "Les champs de citrouilles des Solliden sont l'une des rares parcelles de Tirisfal où l'ancienne vie n'a pas été engloutie par la peste ou la non-mort. Tandis que la campagne alentour est tombée aux mains du Fléau, puis des Réprouvés qui en sont issus, les fermiers d'ici travaillent toujours leurs rangs, protégés par la Croisade écarlate depuis la palissade écarlate voisine.\n\nCette protection a fait des Solliden une singularité. Les fermiers ne font confiance à personne qui ne soit pas écarlate, repoussant les Réprouvés comme des abominations nées de la peste qui a failli les emporter, et se méfiant aussi de l'Alliance, dont les bannières pourraient les entraîner dans une guerre à laquelle ils ont échappé jusqu'ici en restant petits et oubliés.\n\nC'est cette quiétude que les Réprouvés ne peuvent laisser en paix. Le garde noir Simmer surveille la ferme non pour ce qu'elle est aujourd'hui, mais pour ce qu'elle pourrait devenir : de paisibles fermiers aujourd'hui, des métayers armés de l'Alliance demain, une tête de pont sur une terre que les Réprouvés entendent garder.",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "Etang immobile",
			short = "Avant la peste, l'étang Immobile était un lieu où les vivants pouvaient être jeunes.",
			full = "Avant la peste, l'étang Immobile était un lieu où les vivants pouvaient être jeunes. Les familles des clairières venaient pique-niquer sur ses berges, et les enfants trop petits pour braver les eaux plus profondes du lac Étincelant y apprenaient à nager.\n\nCette eau est grise désormais. Les poissons sous la surface ne sont plus que des arêtes qui nagent encore, comme si personne ne leur avait dit de s'arrêter. Des morts-vivants errants et des bêtes sauvages longent la rive, et le chien noir Bayne rôde au bord de l'eau, se nourrissant de tout ce qui est assez imprudent pour s'attarder.\n\nLorsque les Réprouvés commencèrent à relever Brill de ses ruines, des guerriers écarlates s'étaient mis à patrouiller sur la rive de l'étang Immobile.",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "Terrasse de la quiétude",
			short = "Juste au nord du Monastère écarlate s'étend une terre que la peste n'a jamais touchée. Des haies vertes y poussent, et une fontaine y coule, claire plutôt que stagnante, contrairement au reste des clairières de Tirisfal.",
			full = "Juste au nord du Monastère écarlate s'étend une terre que la peste n'a jamais touchée. Des haies vertes y poussent, et une fontaine y coule, claire plutôt que stagnante, contrairement au reste des clairières de Tirisfal. La Croisade écarlate l'entretient, gardant en vie cette petite terrasse comme la preuve que quelque chose de pur peut encore subsister au milieu de la flétrissure.",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["venomweb vale"] = {
			name = "Vallée de Tissevenin",
			short = "La vallée de Tissevenin était jadis verte, peuplée de cerfs et de lapins, avant de devenir ce qu'elle est aujourd'hui : une vallée envahie d'araignées venimeuses, menées par la rare et mortelle Sri'skulk, dont les toiles ont remplacé l'herbe et donné son nom à la vallée.",
			full = "La vallée de Tissevenin était jadis verte, peuplée de cerfs et de lapins, avant de devenir ce qu'elle est aujourd'hui : une vallée envahie d'araignées venimeuses, menées par la rare et mortelle Sri'skulk, dont les toiles ont remplacé l'herbe et donné son nom à la vallée. Des chiens noirs rôdent au nord, près du campement écarlate tenu par le lieutenant Sanders.",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["whispering gardens"] = {
			name = "Jardins des murmures",
			short = "Sur la colline au sud du Monastère écarlate, une bataille fut jadis livrée entre les hommes qui allaient devenir la Croisade écarlate et une armée du Fléau.",
			full = "Sur la colline au sud du Monastère écarlate, une bataille fut jadis livrée entre les hommes qui allaient devenir la Croisade écarlate et une armée du Fléau. Beaucoup tombèrent des deux côtés. Au crépuscule, leurs esprits s'attardent encore, murmurant comme de faibles chuchotements parmi les pierres silencieuses du jardin.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "Rivage des murmures",
			short = "Le Rivage des murmures s'étend à l'ouest des clairières de Tirisfal, au nord de la ferme des Solliden. Les pêcheurs appréciaient jadis ses eaux calmes et ses prises régulières.",
			full = "Le Rivage des murmures s'étend à l'ouest des clairières de Tirisfal, au nord de la ferme des Solliden. Les pêcheurs appréciaient jadis ses eaux calmes et ses prises régulières.\n\nCette abondance a disparu. Les murlocs ont envahi le rivage, s'abattant sur quiconque s'en approche, et l'eau est devenue froide et sombre.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- Forêt des Pins argentés: 22 subzones
	[1421] = {
		["ambermill"] = {
			name = "Moulin-de-l'Ambre",
			short = "Moulin-de-l'Ambre n'était jadis qu'un bourg sans importance, où l'on débitait du bois au sud-ouest du lac Lordamere, dans la forêt des Pins argentés.",
			full = "Moulin-de-l'Ambre n'était jadis qu'un bourg sans importance, où l'on débitait du bois au sud-ouest du lac Lordamere, dans la forêt des Pins argentés.\n\nLe Fléau et la Légion ardente changèrent la valeur de la ville. Le Kirin Tor de Dalaran, qui se reconstruisait après sa propre ruine, occupa la ville, et pour un temps Moulin-de-l'Ambre devint ce qu'elle n'avait jamais été : un véritable foyer de résistance humaine dans la forêt des Pins argentés, soutenu par la sorcellerie de Dalaran.\n\nLes Réprouvés ne laissent pas cela sans surveillance. Leurs traqueurs noirs ont appris, grâce à un prisonnier, que les sorciers y conservent des documents concernant l'état de Dalaran elle-même. Les moulins, les écuries et l'hôtel de ville restent aux mains du Kirin Tor, tandis que des espions agissent contre eux depuis l'ombre de la forêt.",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["berens peril"] = {
			name = "Péril de Beren",
			short = "Dans les collines au sud-ouest de Moulin-de-l'Ambre se trouve le Péril de Beren.",
			full = "Dans les collines au sud-ouest de Moulin-de-l'Ambre se trouve le Péril de Beren. Des années après la troisième guerre, des éclaireurs réprouvés apprirent au prêtre des ombres Allister que des morts-vivants s'y étaient rassemblés en secret, se massant pour frapper le Sépulcre. Ces morts-vivants servaient le nécromancien Thule Serres-de-corbeau, qui avait choisi ce lieu pour réunir ses serviteurs à l'abri des regards, assez près pour menacer le Sépulcre, assez loin de la route pour passer inaperçu.",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "Les îles de l'aube",
			short = "Les îles de l'Aube s'élevaient jadis, douces et basses, des eaux cristallines du lac Lordamere, îlots paisibles que rien ne troublait. La peste de la non-mort changea cela.",
			full = "Les îles de l'Aube s'élevaient jadis, douces et basses, des eaux cristallines du lac Lordamere, îlots paisibles que rien ne troublait. La peste de la non-mort changea cela. Leurs arbres tombèrent malades, et murlocs et bêtes des tourbières envahirent les îlots. Les bêtes des tourbières ont disparu désormais, mais les murlocs Ailerons noirs se sont multipliés sans entrave et tiennent aujourd'hui les îles tout entières.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "Le Champ des morts",
			short = "Le Champ des morts s'étend, abandonné, au nord de la forêt des Pins argentés, ses champs pourris et ses premiers occupants oubliés.",
			full = "Le Champ des morts s'étend, abandonné, au nord de la forêt des Pins argentés, ses champs pourris et ses premiers occupants oubliés. Ce que l'on sait, c'est qui s'en est emparé depuis : les gnolls Poil-putride, liés au service du Fléau, qui ont fait de la ferme en ruine leur base, et dont le nombre croissant laisse penser qu'un assaut s'y prépare encore.\n\nLes Réprouvés ont frappé la ferme à plusieurs reprises, espérant briser les gnolls avant qu'ils ne puissent bouger. Chaque tentative a échoué. Chaque fois que les Poils-putrides sont menacés, une banshee répond à leur appel, un esprit nommé Cinglenuit qui commande les gnolls comme les siens, surgissant de nulle part pour les défendre.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "Le bac délabré",
			short = "Le bac délabré transportait jadis les marchandises jusqu'à l'île de Fenris, où un seigneur et sa famille avaient leur manoir, et qui payaient au passeur quelques pièces par traversée.",
			full = "Le bac délabré transportait jadis les marchandises jusqu'à l'île de Fenris, où un seigneur et sa famille avaient leur manoir, et qui payaient au passeur quelques pièces par traversée.\n\nPuis le Fléau s'abattit sur Lordaeron. Le passeur fut tué à son poste, et son bac mis en pièces.\n\nDésormais, goules, guerriers squelettes et gnolls Poil-putride hantent les quais en ruine, et la traversée est abandonnée, dangereuse pour tous sauf les plus forts.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["deep elem mine"] = {
			name = "Mine du gouffre d'Elem",
			short = "La mine du gouffre d'Elem se trouve dans la forêt des Pins argentés. Arugal y laissa se répandre sa magie, et des worgens firent de la mine leur tanière, menés par Grimson le Pâle, jadis contremaître des lieux.",
			full = "La mine du gouffre d'Elem se trouve dans la forêt des Pins argentés. Arugal y laissa se répandre sa magie, et des worgens firent de la mine leur tanière, menés par Grimson le Pâle, jadis contremaître des lieux.\n\nDalar Dawnweaver réclamait la mort de Grimson, afin que les Réprouvés puissent s'approprier la mine au nom de Varimathras.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "Ile de Fenris",
			short = "L'île de Fenris se trouve au milieu du lac Lordamere, fragment d'un anneau brisé de terre ferme qu'elle partage avec les îles de l'Aube, et on la rattache, de façon assez lâche, à la forêt des Pins argentés.",
			full = "L'île de Fenris se trouve au milieu du lac Lordamere, fragment d'un anneau brisé de terre ferme qu'elle partage avec les îles de l'Aube, et on la rattache, de façon assez lâche, à la forêt des Pins argentés.\n\nAvant la troisième guerre, l'île abritait le donjon de Fenris, un avant-poste militaire de Lordaeron. Lorsque le Fléau déferla sur la contrée, le donjon tomba. Ses occupants s'enfuirent ou furent tués sur place, et l'île resta vide.\n\nDans ce vide arrivèrent les gnolls Poil-putride, qui firent du donjon abandonné leur tanière. Leur maître était Thule Serres-de-corbeau, réputé pour sa perfidie même parmi les gnolls, qui règne sur les Poils-putrides et, à travers eux, sur toute l'île de Fenris, tenant le donjon qu'il a revendiqué ainsi que le bac délabré voisin.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "Donjon de Fenris",
			short = "Le donjon de Fenris se dresse au centre du lac Lordamere, sur l'île de Fenris, dans la forêt des Pins argentés ; il abritait jadis une part importante de l'armée de Lordaeron.",
			full = "Le donjon de Fenris se dresse au centre du lac Lordamere, sur l'île de Fenris, dans la forêt des Pins argentés ; il abritait jadis une part importante de l'armée de Lordaeron.\n\nLorsque le Fléau déferla sur la contrée, le donjon tomba avec elle. Dans la ruine arriva Thule Serres-de-corbeau, un jeune mage autrefois membre du Kirin Tor, qui se rallia au Fléau et plia les gnolls de l'île à sa volonté, les forgeant en tribu Poil-putride. Avec cette tribu derrière lui, il se rendit maître du donjon de Fenris, et les Poils-putrides s'abattent sur quiconque approche de leur maître.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["greymane wall"] = {
			name = "Le mur de Greymane",
			short = "Le roi Genn Greymane éleva son mur avant la troisième guerre, las de voir l'or de Gilnéas dépensé pour les camps d'internement orcs et épuisé par les querelles qui divisaient les rois de l'Alliance de Lordaeron.",
			full = "Le roi Genn Greymane éleva son mur avant la troisième guerre, las de voir l'or de Gilnéas dépensé pour les camps d'internement orcs et épuisé par les querelles qui divisaient les rois de l'Alliance de Lordaeron. Il replia son royaume sur lui-même, coupant Gilnéas de Lordaeron et du monde au-delà des montagnes.\n\nLe mur tint face à la peste de la non-mort, mais à un prix. Tandis que le Fléau déferlait sur Lordaeron, des réfugiés s'enfuirent vers le sud et campèrent devant les portes, et pendant des années les portes ne s'ouvrirent pas. Les réfugiés périrent là, sans réponse.",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "Le lopin d'Ivar",
			short = "Le lopin d'Ivar était jadis une ferme enviable, aux rangs chargés de citrouilles, à la maison pleine d'ouvriers qui travaillaient les champs pour un homme nommé Ivar.",
			full = "Le lopin d'Ivar était jadis une ferme enviable, aux rangs chargés de citrouilles, à la maison pleine d'ouvriers qui travaillaient les champs pour un homme nommé Ivar. C'était une belle existence, jusqu'à ce que la peste de la non-mort s'abatte sur Lordaeron et la lui arrache.\n\nIvar ne se contenta pas de mourir. Il se releva, et sa famille aussi, et chacun des ouvriers qui avaient travaillé sa terre, tous changés en goules pourrissantes qui s'abattent désormais sur quiconque approche. Ivar lui-même se releva sous une forme pire encore, dont on se souvient aujourd'hui sous le nom d'Ivar l'Infect.\n\nTrois traqueurs noirs envoyés vers le nord pour évaluer le danger furent surpris ici par les goules, et Ivar l'Infect blessa l'un d'eux, Quinn Yorick, avant que Quinn et sa parente Rane ne se barricadent dans la vieille maison d'Ivar.",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "Lac Lordamere",
			short = "Le lac Lordamere s'étend à l'ombre des royaumes qui peuplaient jadis ses rives.",
			full = "Le lac Lordamere s'étend à l'ombre des royaumes qui peuplaient jadis ses rives. Lordaeron s'élevait sur sa rive nord, et c'est très probablement de cette grande cité, elle-même nommée d'après le vieux Lordain, que le lac tient son nom. Dalaran et Alterac, elles aussi, prospéraient autour de ses eaux au temps où l'Alliance de Lordaeron unissait les royaumes humains.\n\nCette époque est révolue, et ce qui en reste est une frontière. Le lac s'étend désormais entre les possessions réprouvées des clairières de Tirisfal et de la forêt des Pins argentés d'un côté, et les montagnes d'Alterac disputées de l'autre, séparant les morts des vivants.\n\nEn son cœur se trouve l'île de Fenris, dont le donjon est tenu par les gnolls Poil-putride de Thule Serres-de-corbeau.\n\nÀ l'est de l'île de Fenris, parmi les petites îles de l'Aube, les murlocs Ailerons noirs ont établi leur domaine et les ont entièrement envahies.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "Verger de Malden",
			short = "Les arbres du verger de Malden sont devenus sombres et persistants, et leurs fruits pendent sans être cueillis, saison après saison. Malden lui-même a disparu depuis longtemps, chassé de chez lui lorsque le Fléau s'abattit sur Lordaeron.",
			full = "Les arbres du verger de Malden sont devenus sombres et persistants, et leurs fruits pendent sans être cueillis, saison après saison. Malden lui-même a disparu depuis longtemps, chassé de chez lui lorsque le Fléau s'abattit sur Lordaeron.\n\nLe verger appartient désormais aux worgs, qui ont établi leurs tanières en nombre parmi les arbres et autour de l'unique petite chaumière encore debout. C'est là que s'aventura le traqueur noir Erland McKree, envoyé en éclaireur dans le verger lors d'une reconnaissance du nord de la forêt. Les worgs le traquèrent avant qu'il n'ait pu aller bien loin, et il se barricada dans la chaumière abandonnée, où il resta coincé des jours durant, jusqu'à ce que d'autres agents réprouvés l'aident à rejoindre ses compagnons qui l'attendaient.",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides hollow"] = {
			name = "Creux de la côte nord",
			short = "Le Creux de la côte nord se trouve juste au nord du Sépulcre, dans la forêt des Pins argentés. C'est l'un des nombreux repaires des worgens Ragelune, serviteurs de l'archimage Arugal.",
			full = "Le Creux de la côte nord se trouve juste au nord du Sépulcre, dans la forêt des Pins argentés. C'est l'un des nombreux repaires des worgens Ragelune, serviteurs de l'archimage Arugal. Ils y dressent de grossiers campements, ne contenant que le strict nécessaire à la survie, un abri suffisant pour des créatures qui vivent par la dent et par la force.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "La côte nord",
			short = "Le rivage nord-ouest de la forêt des Pins argentés, là où la plage rencontre la froide Grande mer, porte le nom de Côte nord.",
			full = "Le rivage nord-ouest de la forêt des Pins argentés, là où la plage rencontre la froide Grande mer, porte le nom de Côte nord. À demi englouti dans les hauts-fonds gît un navire brisé de la Horde, sa coque enfoncée dans le ressac, la marque la plus visible de cette portion de côte.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "Ferme des Olsen",
			short = "La ferme des Olsen se dressait jadis au bord des routes commerciales qui traversent la forêt des Pins argentés, une ferme en activité dont les champs nourrissaient le trafic de passage.",
			full = "La ferme des Olsen se dressait jadis au bord des routes commerciales qui traversent la forêt des Pins argentés, une ferme en activité dont les champs nourrissaient le trafic de passage.\n\nLa troisième guerre y mit fin. En quelques années, la ferme tomba en ruine.",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood village"] = {
			name = "Bois-du-Bûcher",
			short = "Bois-du-Bûcher se trouve à la lisière de la forêt des Pins argentés, un groupe d'humains qui survécurent à la première venue du Fléau pendant la troisième guerre.",
			full = "Bois-du-Bûcher se trouve à la lisière de la forêt des Pins argentés, un groupe d'humains qui survécurent à la première venue du Fléau pendant la troisième guerre. Au nord se dresse un donjon jadis tenu par le baron d'Argelaine, gardé par le paladin commandant Springvale et la Main d'argent. d'Argelaine et ses hommes furent massacrés par les worgens de l'archimage Arugal, qui s'empara du donjon et le rebaptisa donjon d'Ombrecroc. De là, Arugal tourna sa folie contre Bois-du-Bûcher même, maudissant ses habitants de sorte que chaque nuit ils deviennent des worgens Ragelune écumants, qui déchirent quiconque croise leur chemin, pour se réveiller humains à l'aube.\n\nMalgré cela, le village ouvre encore ses portes aux voyageurs le jour, ses habitants liés à la malédiction qu'Arugal leur a infligée, sans qu'on en voie la fin.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "Le Sépulcre",
			short = "Le Sépulcre domine la côte de Lordaeron, dans les collines de l'ouest de la forêt des Pins argentés, là où une route traversait jadis un simple cimetière, dont les cryptes ne marquaient rien de plus qu'un lieu de repos pour les morts.",
			full = "Le Sépulcre domine la côte de Lordaeron, dans les collines de l'ouest de la forêt des Pins argentés, là où une route traversait jadis un simple cimetière, dont les cryptes ne marquaient rien de plus qu'un lieu de repos pour les morts.\n\nAprès la troisième guerre, les Réprouvés s'emparèrent du vieux cimetière et le transformèrent en base d'opérations, changeant un lieu bâti pour les morts en un lieu au service des non-morts.\n\nCe choix naquit de la nécessité. Les worgens rôdaient au sud, le Fléau tenait encore du terrain à l'est, et le Kirin Tor observait depuis le sud-est. Encerclés presque de toutes parts, les Réprouvés trouvèrent dans le Sépulcre l'un des rares endroits des Pins argentés où la Horde pouvait se tenir en sécurité.",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "Donjon d'Ombrecroc",
			short = "Le donjon d'Ombrecroc se dresse sur un haut promontoire au-dessus de Bois-du-Bûcher. Il appartenait jadis au baron d'Argelaine, un seigneur de Gilnéas, jusqu'à ce que le Fléau s'abatte sur Lordaeron et que l'archimage royal Arugal cherche un moyen de l'arrêter.",
			full = "Le donjon d'Ombrecroc se dresse sur un haut promontoire au-dessus de Bois-du-Bûcher. Il appartenait jadis au baron d'Argelaine, un seigneur de Gilnéas, jusqu'à ce que le Fléau s'abatte sur Lordaeron et que l'archimage royal Arugal cherche un moyen de l'arrêter. S'appuyant sur les recherches du mage Ur, avec la bénédiction du roi Genn Greymane mais contre l'avis du Kirin Tor, Arugal invoqua les worgens. Ils repoussèrent la marée des morts-vivants, puis se retournèrent contre Gilnéas elle-même, ravageant le mur de Greymane avant de se répandre librement dans les Pins argentés. Ils fondirent sur le donjon et tuèrent le baron d'Argelaine et sa maisonnée.\n\nArugal, brisé par ce qu'il avait déchaîné, ne s'enfuit pas. Il appela les worgens ses enfants, s'empara du donjon et le rebaptisa Ombrecroc. Communiant avec un maître qu'il servait au sein du culte du Loup, il répandit la malédiction à travers la forêt, jusqu'à ce que Bois-du-Bûcher lui-même soit transformé, ses habitants humains le jour et bêtes la nuit, gouvernés par un conseil qui ne répondait qu'à lui.",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "Le Rivage rayonnant",
			short = "Le Rivage rayonnant longe le lac Lordamere, depuis la capitale de Lordaeron au nord jusqu'aux collines accidentées qui séparent la forêt des Pins argentés des montagnes d'Alterac.",
			full = "Le Rivage rayonnant longe le lac Lordamere, depuis la capitale de Lordaeron au nord jusqu'aux collines accidentées qui séparent la forêt des Pins argentés des montagnes d'Alterac.\n\nLa tribu de murlocs Ailerons noirs a couvert le rivage de ses colonies, et les voyageurs qui ne connaissent pas la côte ont appris à le craindre. Feu l'apothicaire Berard, dans son journal, évoquait un objet rare que l'on pouvait obtenir des Ailerons noirs, une tumeur durcie, et supposait qu'on pourrait l'utiliser pour élaborer une nouvelle peste.",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "Le Grouillement",
			short = "La mine appelée les Ténèbres grouillantes a été revendiquée par les araignées Toile-grouillante, dont les toiles recouvrent les étais brisés et les outils rouillés.",
			full = "La mine appelée les Ténèbres grouillantes a été revendiquée par les araignées Toile-grouillante, dont les toiles recouvrent les étais brisés et les outils rouillés. Tout au fond se cache la matriarche Toile-grouillante, une araignée devenue monstrueuse, qui règne sur l'essaim depuis des ténèbres qu'elle ne quitte jamais. Au-dehors, la rare Krethis la Tisse-ombre rôde parfois seule parmi les rochers.\n\nDes cocons jonchent le sol, emprisonnant worgens, worgs et ours, ainsi que des orcs traînés depuis une épave échouée sur le rivage, à l'ouest.",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "La côte sud",
			short = "La Côte sud longe le littoral sud-ouest de la forêt des Pins argentés, là où la terre rencontre la Grande mer.",
			full = "La Côte sud longe le littoral sud-ouest de la forêt des Pins argentés, là où la terre rencontre la Grande mer.",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "Champ de Valgan",
			short = "Le champ de Valgan se trouve parmi les fermes désolées du nord de la forêt des Pins argentés, à l'ouest du Rivage rayonnant et au nord d'une petite rivière.",
			full = "Le champ de Valgan se trouve parmi les fermes désolées du nord de la forêt des Pins argentés, à l'ouest du Rivage rayonnant et au nord d'une petite rivière. Il tient son nom d'un fermier qui fut tué ou chassé de ses terres lorsque le Fléau déferla sur les Pins argentés. À ses plus beaux jours, la ferme offrait une vue sur le lac Lordamere digne du nom qu'elle portait jadis.\n\nLa ferme est vide désormais, ruine de ce qu'elle fut, même si l'on peut parfois y apercevoir Cinglenuit.",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
	-- Maleterres de l'ouest: 18 subzones
	[1422] = {
		["bulwark"] = {
			name = "La Barricade",
			short = "La Barricade se dresse là où les clairières de Tirisfal rejoignent les Maleterres de l'ouest ; c'est la ligne que les Réprouvés tiennent contre le Fléau qui se masse toujours à l'est.",
			full = "La Barricade se dresse là où les clairières de Tirisfal rejoignent les Maleterres de l'ouest ; c'est la ligne que les Réprouvés tiennent contre le Fléau qui se masse toujours à l'est. Ici, les défenseurs réprouvés et l'Aube d'argent ont mis de côté leurs différends face à cet ennemi commun, surveillant ensemble la frontière et envoyant des combattants vers l'est pour frapper les serviteurs du roi-liche.\n\nContrairement au reste de Tirisfal, cette étendue ne ressemble en rien aux clairières : une brume pestilentielle la recouvre, teintant le ciel du même gris-jaune maladif que les Maleterres de l'ouest au-delà.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "Caer Darrow",
			short = "Sur l'île du lac Darrowmere se dressait une forteresse élevée jadis par des mains humaines, qui abritait une antique pierre runique des hauts-elfes.",
			full = "Sur l'île du lac Darrowmere se dressait une forteresse élevée jadis par des mains humaines, qui abritait une antique pierre runique des hauts-elfes. Pendant la deuxième guerre, la Horde envahit l'île et mit le donjon à sac, brisant la pierre runique pour forger les autels des tempêtes, grâce auxquels Gul'dan insuffla la magie aux ogres de sa Horde.\n\nLe donjon fut reconstruit et devint le siège de la maison Barov. À mesure que les années menaient à la guerre, les Barov craignirent de perdre ce que des décennies leur avaient permis de bâtir, et passèrent un marché avec Kel'Thuzad, maître du culte des Damnés. Sous le manoir, les catacombes devinrent la Scholomance, une école de nécromancie, et les propres serviteurs de la famille furent livrés comme sujets d'expérience pour une peste de la non-mort. En moins de six mois, la maladie se déchaîna et tua tous les habitants de l'île. Ses victimes ne se contentèrent pas de mourir : elles se relevèrent en fantômes, condamnées à revivre leurs derniers instants, et hantent aujourd'hui encore les salles en ruine de Caer Darrow.",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["chillwind camp"] = {
			name = "Camp du Noroît",
			short = "Le camp du Noroît se trouve à la porte sud des Maleterres de l'ouest, là où les montagnes d'Alterac cèdent la place à une terre empoisonnée. C'est le dernier endroit où un voyageur de l'Alliance peut se tenir en disant encore que la terre est saine.",
			full = "Le camp du Noroît se trouve à la porte sud des Maleterres de l'ouest, là où les montagnes d'Alterac cèdent la place à une terre empoisonnée. C'est le dernier endroit où un voyageur de l'Alliance peut se tenir en disant encore que la terre est saine.\n\nUn petit contingent de l'Aube d'argent le tient, avec seulement une poignée de soldats et de spécialistes. Ce que le camp n'a pas en nombre, il le compense par l'audace : ses membres mènent une guérilla contre la place forte du Fléau à Andorhal et contre les chaudrons de peste qui ensemencent la terre de mort, comptant sur des mercenaires prêts à frapper puis à disparaître plutôt qu'à tenir un terrain qu'ils ne peuvent garder.\n\nDe jeunes chevaliers prometteurs de la Main d'argent y furent envoyés par le seigneur Grayson Shadowbreaker pour se tenir aux côtés du commandant Ashlam Valorfist contre le Fléau dans la région.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons tears"] = {
			name = "Larmes de Dalson",
			short = "Le verger des Dalson portait jadis des fruits pour la famille qui lui avait donné son nom. Aujourd'hui, les arbres se dressent dans les Maleterres de l'ouest sous un nom qui évoque le chagrin plutôt que la récolte : les Larmes de Dalson.",
			full = "Le verger des Dalson portait jadis des fruits pour la famille qui lui avait donné son nom. Aujourd'hui, les arbres se dressent dans les Maleterres de l'ouest sous un nom qui évoque le chagrin plutôt que la récolte : les Larmes de Dalson.\n\nLe Fléau s'empara de la ferme et en fit une plaie dans la terre. En son centre, il installa un grand chaudron qui ne s'est jamais arrêté depuis, crachant la maladie dans l'air, sous la garde du seigneur du chaudron Malvinious et des morts flétris qui le servent.\n\nLes Dalson ne sont jamais partis. Mme Dalson arpente toujours la propriété, squelette errant qui fouille la terre qu'elle cultivait de son vivant. Son mari ne mourut pas à ses côtés. On l'enferma dans les latrines et on l'y laissa, et ce qu'il devint dans ces ténèbres verrouillées n'était plus un homme, mais une goule.",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "Lac Darrowmere",
			short = "Les eaux du Darrowmere gardent encore le souvenir de la deuxième guerre, lorsque le lac était couvert de voiles.",
			full = "Les eaux du Darrowmere gardent encore le souvenir de la deuxième guerre, lorsque le lac était couvert de voiles. La plupart des navires qui y mouillaient battaient pavillon de la flotte des Portvaillant, et avant l'incendie de Quel'Thalas, le grand amiral en envoya un certain nombre à travers ces eaux pour transporter Turalyon, Alleria Coursevent et leur armée vers Stratholme. Turalyon envisagea de poursuivre jusqu'à Quel'Thalas même, mais Alleria l'avertit que les elfes ne laisseraient jamais des navires humains remonter leur fleuve, et la flotte se tourna donc vers Stratholme. C'est au cours de cette même guerre que Zul'jin et sa bande furent repoussés sur les rives du lac, et que le seigneur de guerre troll fut fait prisonnier.\n\nAu centre du lac se dresse la ville insulaire de Caer Darrow, déserte aujourd'hui, jadis tenue par la maison Barov. Sous les pierres de la ville se trouve la Scholomance, où le culte des Damnés œuvre parmi ses morts-vivants, des ténèbres tapies sous le calme noyé de l'île.",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "Champ de Felstone",
			short = "Le champ de Felstone nourrissait jadis les vivants. Cela prit fin lorsque le Fléau s'en empara et ne le laissa plus jamais redevenir une ferme.",
			full = "Le champ de Felstone nourrissait jadis les vivants. Cela prit fin lorsque le Fléau s'en empara et ne le laissa plus jamais redevenir une ferme.\n\nAu cœur du champ, le Fléau installa un grand chaudron, qui n'a jamais cessé son œuvre depuis. Une vapeur chargée de maladie s'en déverse sans répit. Le seigneur du chaudron Bilegueule monte la garde à ses côtés, avec des sorciers squelettes, des écorcheurs squelettes et des goules écumantes, afin que rien de vivant ne puisse s'en approcher et en repartir indemne.\n\nDans l'angle nord-est, la vieille maison est toujours debout, et Janice Felstone y demeure encore, s'attardant sur une terre qui portait autrefois les récoltes de sa famille.",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "La Flétrissure de Gahrron",
			short = "La ferme située à la lisière est des Maleterres de l'ouest appartenait jadis à Del Gahrron, et à ses plus beaux jours on l'appelait l'Éveil de Gahrron, un lieu de semailles et de croissance.",
			full = "La ferme située à la lisière est des Maleterres de l'ouest appartenait jadis à Del Gahrron, et à ses plus beaux jours on l'appelait l'Éveil de Gahrron, un lieu de semailles et de croissance. Plus rien n'y pousse désormais. Le Fléau s'empara des champs et installa un grand chaudron en leur centre, et ce chaudron ne cesse jamais son œuvre, crachant dans l'air une vapeur chargée de maladie, jusqu'à ce que le sol lui-même semble dépérir. Le seigneur du chaudron Irâme monte la garde avec d'autres officiers du Fléau, et les vapeurs ont fait surgir des choses qui ne devraient pas marcher : des visions obsédantes qui dérivent entre les rangs en ruine, des morts gémissantes et des âmes en peine affamées qui n'obéissent à aucun maître sinon à leur faim.",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "Hearthglen",
			short = "Hearthglen se dresse au nord d'Andorhal, ses murs refermés sur un donjon, une tour de mage, un moulin et une mine, image même de l'ordre dans une région livrée à la ruine.",
			full = "Hearthglen se dresse au nord d'Andorhal, ses murs refermés sur un donjon, une tour de mage, un moulin et une mine, image même de l'ordre dans une région livrée à la ruine. Pendant des années, elle maintint cet ordre sous Tirion Fordring, seigneur de Mardenholde, jusqu'à ce qu'il porte secours à l'orc Eitrigg et soit banni pour trahison. Avec le temps, son fils Taelan prit sa place comme seigneur de Mardenholde.\n\nHearthglen abrita plus tard les restes de l'ordre de la Main d'argent, qui répondirent à l'offre de refuge de Taelan après la chute de la capitale. Depuis ses murs, les paladins remportèrent des victoires dans les années qui suivirent, jusqu'à ce que l'ordre se dévoie en Croisade écarlate et s'approprie la ville.",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["mardenholde keep"] = {
			name = "Donjon de Mardenholde",
			short = "Le donjon de Mardenholde se dresse au cœur de Hearthglen depuis bien avant le souvenir de la plupart de ceux qui arpentent ses salles, et ses murs sont restés intacts même aux jours les plus sombres de l'invasion orque de Lordaeron.",
			full = "Le donjon de Mardenholde se dresse au cœur de Hearthglen depuis bien avant le souvenir de la plupart de ceux qui arpentent ses salles, et ses murs sont restés intacts même aux jours les plus sombres de l'invasion orque de Lordaeron. Pendant des années, il fut le siège de Tirion Fordring, et là, dans une salle du conseil dominée par une grande table de chêne et une carte qui représentait Hearthglen jusqu'à son moindre chemin, le paladin s'entretenait avec ses conseillers des affaires du royaume. Accusé de trahison pour avoir aidé l'orc Eitrigg, Tirion fut excommunié et banni, et Mardenholde revint avec le temps à son propre fils, Taelan.\n\nAprès que le Fléau eut ravagé Lordaeron, Taelan offrit aux chevaliers survivants de la Main d'argent un foyer à Hearthglen. C'est entre ces murs que parvint la nouvelle de la mort d'Alexandros Mograine, et les soupçons de trahison divisèrent l'ordre : Maxwell Tyrosus emmena ses fidèles fonder l'Aube d'argent, tandis que ceux qui restèrent prirent le nom de Croisade écarlate, et Mardenholde devint leur place forte, Taelan étant élevé au rang de généralissime.",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["northridge lumber camp"] = {
			name = "Camp de bûcherons de la Crête du nord",
			short = "Le camp de bûcherons de la Crête du nord se trouve au nord des Maleterres de l'ouest, près de Hearthglen, ses collines mises à nu par les coupes de bois de la Croisade écarlate.",
			full = "Le camp de bûcherons de la Crête du nord se trouve au nord des Maleterres de l'ouest, près de Hearthglen, ses collines mises à nu par les coupes de bois de la Croisade écarlate. La Croisade exploite la scierie pour son bois, une ressource que l'Alliance comme la Horde ont des raisons de vouloir gâcher.\n\nAvant la troisième guerre, la scierie appartenait à la famille de Nathaniel Dumah, qui travailla la terre jusqu'à ce que la guerre et la peste l'en chassent. La famille de Mickey Levine y travailla aussi autrefois.",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["ruins of andorhal"] = {
			name = "Ruines d'Andorhal",
			short = "Andorhal gît en ruine au cœur des Maleterres de l'ouest, ses maisons brisées et éparpillées sur un terrain découvert.",
			full = "Andorhal gît en ruine au cœur des Maleterres de l'ouest, ses maisons brisées et éparpillées sur un terrain découvert. Ce qui en reste est tenu par Araj l'Invocateur, une liche d'une puissance considérable, et par les morts qui le servent : des goules qui se traînent entre les pierres effondrées, des squelettes montant la garde là où se tenaient autrefois des gardes, des banshees dont les cris portent au-dessus des ruines, et des abominations qui avancent pesamment parmi les débris des maisons.\n\nAraj demeure au centre de tout cela, régnant sur une cité qui ne s'est jamais relevée.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "Scholomance",
			short = "Sur une hauteur dominant la cité abandonnée de Caer Darrow se dresse le manoir qui fut jadis le siège de la maison Barov, une famille dont l'influence s'étendait de Caer Darrow à Brill, à Southshore et jusqu'à Moulin-de-Tarren.",
			full = "Sur une hauteur dominant la cité abandonnée de Caer Darrow se dresse le manoir qui fut jadis le siège de la maison Barov, une famille dont l'influence s'étendait de Caer Darrow à Brill, à Southshore et jusqu'à Moulin-de-Tarren. Pendant des décennies, ils régnèrent dans le confort, mais à mesure que les années menaient à la guerre, les Barov devinrent amers et avides, refusant de laisser la mort mettre fin à ce qu'ils avaient bâti. Ils passèrent donc un marché avec Kel'Thuzad, maître du culte des Damnés, afin de conserver leur fortune et leurs terres au-delà d'une vie mortelle.\n\nEn six mois, le donjon avait pourri pour devenir tout autre chose. Les acolytes du culte y étudiaient l'art du nécromancien, tandis que les propres serviteurs de la famille étaient livrés comme sujets d'expérience vivants pour une peste de la non-mort. Avant qu'Uther le Porteur de Lumière ne puisse effectuer une visite prévue au manoir, une maladie engendrée dans ses salles se déchaîna sur Caer Darrow même. Elle ne laissa personne en vie et condamna ses victimes à errer ensuite sous forme de fantômes.\n\nLes Barov eux-mêmes se relevèrent en morts-vivants, toujours liés aux salles qu'ils avaient vendues. Désormais, le nécromancien mortel Sombre maître Gandling en est le directeur, ayant succédé à Araj l'Invocateur, qui avait lui-même succédé à Kel'Thuzad.",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["sorrow hill"] = {
			name = "Colline des chagrins",
			short = "La colline des Chagrins servait Andorhal en des jours plus doux ; les morts de la ville, riches ou pauvres, y reposaient sous des cryptes et de simples pierres.",
			full = "La colline des Chagrins servait Andorhal en des jours plus doux ; les morts de la ville, riches ou pauvres, y reposaient sous des cryptes et de simples pierres. Cette paix prit fin lorsque vint la peste de la non-mort. Tandis que le Fléau se jetait encore et encore contre Andorhal, la colline se remplit plus vite qu'elle ne pouvait contenir ; des tombes hâtives et anonymes marquent encore le sol là où tombèrent les défenseurs. Avec le temps, les survivants cessèrent tout à fait d'enterrer leurs morts, trop effrayés que la peste ne relève leurs proches contre eux, et creusèrent une fosse commune au sud du cimetière pour y brûler les corps.\n\nLe dernier geste de la ville fut le plus triste. Lorsqu'Arthas abattit le seigneur Uther, les derniers habitants d'Andorhal élevèrent un grand tombeau au sommet de la colline et y déposèrent le corps meurtri du paladin avant d'abandonner leur foyer pour de bon. Certains disent que la colline tient son nom de cette seule tombe.\n\nLes chaudrons de peste voisins n'épargnèrent pas les morts de la colline. Soldats et habitants se relevèrent de leurs tombes, montant la garde sur les sépultures qu'ils avaient jadis remplies.",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["thondroril river"] = {
			name = "La Thondroril",
			short = "La Thondroril sépare les Maleterres de l'ouest et de l'est. Elle prend sa source loin au nord, près du tunnel de Tisse-terreur, et coule vers le sud jusqu'à se jeter dans le lac Darrowmere, pour continuer au-delà sous le nom de rivière Darrowmere.",
			full = "La Thondroril sépare les Maleterres de l'ouest et de l'est. Elle prend sa source loin au nord, près du tunnel de Tisse-terreur, et coule vers le sud jusqu'à se jeter dans le lac Darrowmere, pour continuer au-delà sous le nom de rivière Darrowmere.\n\nSes berges appartiennent à la flétrissure. Asticots et chauves-souris vampires grouillent sur le sol humide, ours de la peste et araignées rôdent dans les hauts-fonds, et des gueules d'acier guettent là où le courant ralentit.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "Tombeau d'Uther",
			short = "Le tombeau d'Uther se dresse sur la colline des Chagrins, seul endroit des Maleterres de l'ouest où la Lumière résiste encore au dépérissement de la terre.",
			full = "Le tombeau d'Uther se dresse sur la colline des Chagrins, seul endroit des Maleterres de l'ouest où la Lumière résiste encore au dépérissement de la terre.\n\nUther le Porteur de Lumière défendit jadis Andorhal contre le Fléau, aux côtés du sage Truthbearer et de Ballador le Radieux, avec les chevaliers de la Main d'argent derrière lui. Ce fut Arthas Menethil qui mit fin à cette résistance, lançant son armée de morts-vivants contre la cité et abattant Truthbearer, Ballador et Uther lui-même.\n\nCe qu'Arthas laissa derrière lui, les propres soldats d'Uther le recueillirent. Ils portèrent son corps au sud des ruines d'Andorhal et élevèrent un tombeau au-dessus. Sa stèle le montre tel qu'il était de son vivant, un tome de la Lumière dans une main et son marteau de guerre dans l'autre, avec des mots gravés en langue commune sur la pierre commémorative placée devant.\n\nLe grand prêtre Thel'danis veille toujours sur le tombeau, dont il est le gardien et le protecteur. La tombe est sacrée pour ceux qui suivent la Lumière, l'un des rares endroits des Maleterres où une telle dévotion a encore un sens.",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "La grotte des Pleurs",
			short = "La grotte des Pleurs se trouve à l'ouest de la Thondroril, ses cavités peuplées de bêtes des tourbières et de limons nés de la terre pestiférée. Des béhémoths pourrissants et des horreurs en décomposition se traînent dans l'obscurité.",
			full = "La grotte des Pleurs se trouve à l'ouest de la Thondroril, ses cavités peuplées de bêtes des tourbières et de limons nés de la terre pestiférée. Des béhémoths pourrissants et des horreurs en décomposition se traînent dans l'obscurité. Plus profond encore, un élémentaire appelé la Gangue ferait de rares apparitions, une chose étrange et troublante à entrevoir.",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "Le Repaire putride",
			short = "Le Repaire putride était jadis une terre agricole, cultivée pour nourrir les vivants. Cette vocation a disparu.",
			full = "Le Repaire putride était jadis une terre agricole, cultivée pour nourrir les vivants. Cette vocation a disparu. Le Fléau s'empara des champs et installa en leur centre un grand chaudron qui n'a jamais cessé son œuvre depuis : un flot constant de vapeur chargée de maladie qui roule sur les sillons où poussaient jadis les récoltes.\n\nLe chaudron n'est pas laissé sans garde. Le seigneur du chaudron Razarch veille sur lui, entouré de goules pourrissantes, de goules glaciales et de zombies fétides, liés au lieu comme ses gardiens.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- Maleterres de l'est: 28 subzones
	[1423] = {
		["blackwood lake"] = {
			name = "Lac de Noirbois",
			short = "Les eaux du lac de Noirbois sont viciées, infestées d'élémentaires d'eau corrompus qui ondulent dans l'eau trouble. Les vieilles annales de Darrowshire affirment que le fond du lac renferme la tête de Horgus le Ravageur, engloutie quelque part dans ces ténèbres.",
			full = "Les eaux du lac de Noirbois sont viciées, infestées d'élémentaires d'eau corrompus qui ondulent dans l'eau trouble. Les vieilles annales de Darrowshire affirment que le fond du lac renferme la tête de Horgus le Ravageur, engloutie quelque part dans ces ténèbres.\n\nAvant la peste, une ville nommée Noirbois se dressait ici, patrie du grand maréchal Othmar Garithos. Il n'en reste plus rien, hormis le lac qui porte son nom.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
		},
		["browman mill"] = {
			name = "Scierie de Browman",
			short = "Stephen Browman débitait jadis du bois à la scierie au nord de la chapelle de l'Espoir de Lumière. Le Fléau le tua comme tous ceux que la peste toucha, puis le releva en goule liée à son service.",
			full = "Stephen Browman débitait jadis du bois à la scierie au nord de la chapelle de l'Espoir de Lumière. Le Fléau le tua comme tous ceux que la peste toucha, puis le releva en goule liée à son service. Il n'est jamais parti. Il monte désormais la garde entre les murs qui lui appartenaient autrefois.\n\nLa scierie grouille de squelettes, de banshees et d'abominations, plus garnison que ruine, et rien en elle n'invite à s'attarder.",
			source = "https://warcraft.wiki.gg/wiki/Browman_Mill",
		},
		["corins crossing"] = {
			name = "La Croisée de Corin",
			short = "La Croisée de Corin se trouve là où se rejoignent les routes d'Andorhal, de Darrowshire, de Stratholme et de la Main de Tyr, entre la Balafre infecte et le lac Mereldar.",
			full = "La Croisée de Corin se trouve là où se rejoignent les routes d'Andorhal, de Darrowshire, de Stratholme et de la Main de Tyr, entre la Balafre infecte et le lac Mereldar. Jadis simple bourg de carrefour, elle possédait un hôtel de ville et une forge.\n\nDésormais, le Fléau emplit entièrement ses rues, et parmi les morts se déplacent des choses que l'on ne peut voir du tout : des serviteurs invisibles, qui percent le camouflage comme s'il n'existait pas. Aucun chemin discret ne traverse la Croisée de Corin.",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "Tour de garde de la couronne",
			short = "La tour de garde de la Couronne veille sur les Maleterres de l'est ; c'est l'une de leurs tours d'observation. L'invasion de Lordaeron par le Fléau ravagea la région, et la tour en porte encore les cicatrices, repère silencieux des terres mortes.",
			full = "La tour de garde de la Couronne veille sur les Maleterres de l'est ; c'est l'une de leurs tours d'observation. L'invasion de Lordaeron par le Fléau ravagea la région, et la tour en porte encore les cicatrices, repère silencieux des terres mortes.",
			source = "https://warcraft.wiki.gg/wiki/Crown_Guard_Tower",
		},
		["darrowshire"] = {
			name = "Darrowshire",
			short = "Darrowshire était jadis un village à part entière, jusqu'à ce que la troisième guerre amène le Fléau à ses portes. Un seigneur goule nommé Horgus le Ravageur mena l'assaut, aux côtés du chevalier de la mort Marduk Noirétang.",
			full = "Darrowshire était jadis un village à part entière, jusqu'à ce que la troisième guerre amène le Fléau à ses portes. Un seigneur goule nommé Horgus le Ravageur mena l'assaut, aux côtés du chevalier de la mort Marduk Noirétang. Les défenseurs du village résistèrent d'abord avec un certain succès, mais le vent tourna, et à la fin, tous furent massacrés.\n\nLeur mort ne fut pas leur fin. Les tombés se relevèrent en goules, liés au service du Fléau même qui les avait tués, leurs esprits prisonniers de la chair pourrissante qui avait été la leur.\n\nDarrowshire elle-même se dresse aujourd'hui silencieuse et brisée, vide de tout sauf de fantômes et de souvenirs.",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
		["eastwall gate"] = {
			name = "Porte du Mur d'est",
			short = "La porte du Mur d'est est l'entrée latérale de Stratholme ; elle s'ouvre directement sur la place des Anciens, près de la chapelle d'Alonsus où se tient Aurius.",
			full = "La porte du Mur d'est est l'entrée latérale de Stratholme ; elle s'ouvre directement sur la place des Anciens, près de la chapelle d'Alonsus où se tient Aurius.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Gate",
		},
		["eastwall tower"] = {
			name = "Tour du Mur d'est",
			short = "La tour du Mur d'est se dresse dans les Maleterres de l'est, une tour d'observation qui veillait jadis sur la contrée pour Lordaeron. Le Fléau déferla sur le royaume, et la tour en porte encore les cicatrices, veillant sur des terres mortes.",
			full = "La tour du Mur d'est se dresse dans les Maleterres de l'est, une tour d'observation qui veillait jadis sur la contrée pour Lordaeron. Le Fléau déferla sur le royaume, et la tour en porte encore les cicatrices, veillant sur des terres mortes.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Tower",
		},
		["fungal vale"] = {
			name = "La Vallée des fongus",
			short = "Au nord de la ferme des Marris et de la tour de garde de la Couronne s'étend le val Fongique, une terre devenue d'un violet sombre sous une brume trouble.",
			full = "Au nord de la ferme des Marris et de la tour de garde de la Couronne s'étend le val Fongique, une terre devenue d'un violet sombre sous une brume trouble. C'est ici que la peste de la non-mort a le plus profondément pris racine, et le Fléau comme le culte des Damnés circulent librement dans la corruption, tenant ce creux comme leur bien propre.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Vale",
		},
		["infectis scar"] = {
			name = "La Balafre infecte",
			short = "Près de la Croisée de Corin, l'épée runique du chevalier de la mort Marduk Noirétang se brisa contre le bouclier d'un capitaine nain. Il en garda la poignée et jeta la lame brisée, la jugeant sans valeur.",
			full = "Près de la Croisée de Corin, l'épée runique du chevalier de la mort Marduk Noirétang se brisa contre le bouclier d'un capitaine nain. Il en garda la poignée et jeta la lame brisée, la jugeant sans valeur. Mais elle s'enfonça dans la terre, et le sol s'ouvrit sous elle, s'emplissant d'eau noire.\n\nCe qui en reste est contre nature de part en part, contrairement à la Balafre pestilentielle voisine, qui n'est qu'une simple gorge naturelle.",
			source = "https://warcraft.wiki.gg/wiki/Infectis_Scar",
		},
		["lake mereldar"] = {
			name = "Lac Mereldar",
			short = "Les eaux du lac Mereldar, au sud de la Croisée de Corin, sont chargées de peste, et des élémentaires d'eau corrompus se meuvent sous leur surface.",
			full = "Les eaux du lac Mereldar, au sud de la Croisée de Corin, sont chargées de peste, et des élémentaires d'eau corrompus se meuvent sous leur surface. Sur sa rive se dressent les ruines d'une vieille maison, ainsi qu'une cabane et un bac qui servaient une ferme aujourd'hui abandonnée.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mereldar",
		},
		["lights hope chapel"] = {
			name = "Chapelle de l'Espoir de Lumière",
			short = "Au pied des montagnes à l'est des Maleterres se dresse une chapelle bien plus ancienne que la ruine qui l'entoure, l'un des lieux saints les plus anciens et les plus vénérés que l'Église de la Lumière sacrée ait jamais élevés.",
			full = "Au pied des montagnes à l'est des Maleterres se dresse une chapelle bien plus ancienne que la ruine qui l'entoure, l'un des lieux saints les plus anciens et les plus vénérés que l'Église de la Lumière sacrée ait jamais élevés.\n\nLes paladins qui refusaient de suivre la voie que prenait la Croisade écarlate se retirèrent plutôt dans les Maleterres de l'est et firent de cette chapelle leur base, prenant le nom d'Aube d'argent. Le seigneur Raymond George les mena d'abord ; à sa mort, le seigneur Maxwell Tyrosus prit sa place. Contrairement à la Croisade écarlate, ils ne repoussaient personne en raison de sa race.\n\nBien que l'Aube d'argent se tienne à l'écart de la Croisade écarlate, la chapelle reste un terrain neutre où les deux se rencontrent encore pour parlementer.",
			source = "https://warcraft.wiki.gg/wiki/Light's_Hope_Chapel",
		},
		["marris stead"] = {
			name = "La ferme des Marris",
			short = "La ferme des Marris se dresse sur une crête basse au-dessus de la route principale de la région ; elle appartenait jadis à Nathanos Marris.",
			full = "La ferme des Marris se dresse sur une crête basse au-dessus de la route principale de la région ; elle appartenait jadis à Nathanos Marris. Son cousin Stephon y vécut un temps, et l'on savait que Sylvanas Windrunner rendait visite à Nathanos sous son toit.\n\nLibéré par la reine banshee après qu'elle eut relevé les Réprouvés à Undercity, Nathanos revint dans le foyer qu'il avait perdu et en refit le sien sur son ordre. De là, il enrôla des soldats de la Horde dans la lutte contre le Fléau et la Croisade écarlate qui infestent encore les Maleterres, et il rassembla des reliques de la bataille de Darrowshire, qu'il gardait à la ferme pour des raisons qu'il ne confia à personne.",
			source = "https://warcraft.wiki.gg/wiki/Marris_Stead",
		},
		["mazraalor"] = {
			name = "Mazra'Alor",
			short = "Au cœur de Zul'Mashar s'élève Mazra'Alor, une ziggourat de pierres empilées qui domine les terres en ruine alentour.",
			full = "Au cœur de Zul'Mashar s'élève Mazra'Alor, une ziggourat de pierres empilées qui domine les terres en ruine alentour. La tribu Mossflayer la tient toujours, et ses chasseurs des ombres montent la garde du haut de ses sommets sur le campement troll en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Mazra'Alor",
		},
		["northdale"] = {
			name = "Valnord",
			short = "Valnord est une ville en ruine au nord de la chapelle de l'Espoir de Lumière, aux confins de Quel'Thalas. C'est ici que Taelan Fordring renia l'ordre de la Main d'argent pour la Croisade écarlate.",
			full = "Valnord est une ville en ruine au nord de la chapelle de l'Espoir de Lumière, aux confins de Quel'Thalas. C'est ici que Taelan Fordring renia l'ordre de la Main d'argent pour la Croisade écarlate.\n\nDes banshees et des guetteurs invisibles hantent désormais les décombres. Le lac voisin abrite des élémentaires d'eau corrompus. Rien de vivant n'y subsiste.",
			source = "https://warcraft.wiki.gg/wiki/Northdale",
		},
		["northpass tower"] = {
			name = "Tour du Col du nord",
			short = "La tour du Col du nord est la plus septentrionale des tours de guet des Maleterres de l'est ; elle marque la route vers les Terres fantômes de Quel'Thalas.",
			full = "La tour du Col du nord est la plus septentrionale des tours de guet des Maleterres de l'est ; elle marque la route vers les Terres fantômes de Quel'Thalas. Le Fléau déferla sur Lordaeron, et la tour en porte encore les cicatrices.",
			source = "https://warcraft.wiki.gg/wiki/Northpass_Tower",
		},
		["noxious glade"] = {
			name = "La Clairière nocive",
			short = "La Clairière nocive se trouve au sommet d'une colline au nord de la chapelle de l'Espoir de Lumière, plus souillée par la flétrissure que le reste des Maleterres alentour.",
			full = "La Clairière nocive se trouve au sommet d'une colline au nord de la chapelle de l'Espoir de Lumière, plus souillée par la flétrissure que le reste des Maleterres alentour. L'air y est épais et d'un vert maladif, et le sol a pris une teinte violet sombre là où rien de vert ne peut pousser.\n\nLe Fléau a fait de la clairière son domaine : un chaudron de peste, un abattoir et quelques ziggourats se dressent sur le sol empoisonné, et les créatures du Fléau s'y déplacent en nombre.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
		},
		["pestilent scar"] = {
			name = "Balafre pestilentielle",
			short = "La Balafre pestilentielle est une gorge profonde dans les Maleterres de l'est flétries, probablement un lac qui s'assécha lorsque frappa la peste de la non-mort.",
			full = "La Balafre pestilentielle est une gorge profonde dans les Maleterres de l'est flétries, probablement un lac qui s'assécha lorsque frappa la peste de la non-mort. Elle est aujourd'hui presque à sec, une plaie dans la terre, dont les profondeurs abritent des limons nés de l'ancienne corruption.",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "Pestebois",
			short = "Les arbres au sud de Stratholme se dressaient jadis verts et paisibles, un bois assez semblable à la forêt d'Elwynn, avec un petit village niché près de l'arche de pierre à sa lisière.",
			full = "Les arbres au sud de Stratholme se dressaient jadis verts et paisibles, un bois assez semblable à la forêt d'Elwynn, avec un petit village niché près de l'arche de pierre à sa lisière. C'est ici que le sergent Morigan, un soldat de Lordaeron né dans ce village, remarqua le premier les effets néfastes du grain empoisonné d'Andorhal sur la terre, lorsque Kel'Thuzad commença son œuvre. Son avertissement vint trop tard pour le royaume, et la route même qu'il surveillait fut celle qu'emprunta plus tard le prince Arthas en chemin vers Stratholme.\n\nCe qui resta ensuite n'était plus une forêt. Le sol lui-même devint spongieux sous les pas, et champignons et vesses-de-loup enflèrent jusqu'à la taille d'arbres, dominant ce qui restait de l'ancien bois. Ils exhalent un gaz brun sombre assez semblable aux vapeurs qui s'élèvent des chaudrons de peste du Fléau, bien que nul ne puisse dire avec certitude si le champignon pousse simplement sur une terre empoisonnée ou si le Fléau le cultive pour propager davantage sa maladie. C'est de cette transformation que le bois tient son nouveau nom.",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["quellithien lodge"] = {
			name = "Gîte de Quel'Lithien",
			short = "Le gîte de Quel'Lithien était un camp des Pérégrins près de Quel'Thalas, un lieu chaleureux et accueillant. C'est ainsi que Lor'themar Theron s'en souvenait de ses propres visites, chaleureusement accueilli par des compatriotes qui y avaient leur foyer.",
			full = "Le gîte de Quel'Lithien était un camp des Pérégrins près de Quel'Thalas, un lieu chaleureux et accueillant. C'est ainsi que Lor'themar Theron s'en souvenait de ses propres visites, chaleureusement accueilli par des compatriotes qui y avaient leur foyer. Le gîte abritait jadis un certain nombre de documents elfiques, dont certains concernaient la famille royale et le général des forestiers de Lune-d'argent. À l'époque de la deuxième guerre, Renthar Hawkspear y menait les chasseurs.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["scarlet base camp"] = {
			name = "Camp de la Croisade",
			short = "Sur la rive est du lac Mereldar, non loin du bastion religieux de la Main de Tyr, le camp de la Croisade se dresse derrière ses barricades, ses défenses renforcées contre tout ce qui pourrait venir.",
			full = "Sur la rive est du lac Mereldar, non loin du bastion religieux de la Main de Tyr, le camp de la Croisade se dresse derrière ses barricades, ses défenses renforcées contre tout ce qui pourrait venir.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "La Basilique écarlate",
			short = "La Basilique écarlate se dresse à la Main de Tyr ; c'est le haut lieu de la foi de la Croisade écarlate, lié à l'abbaye voisine et au lointain Monastère écarlate des clairières de Tirisfal.",
			full = "La Basilique écarlate se dresse à la Main de Tyr ; c'est le haut lieu de la foi de la Croisade écarlate, lié à l'abbaye voisine et au lointain Monastère écarlate des clairières de Tirisfal. Le grand maître Valdelmar la tient, d'une dévotion absolue à la cause de la Croisade.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["stratholme"] = {
			name = "Stratholme",
			short = "La ruine de Stratholme commença par du grain. Des cargaisons venues d'Andorhal, secrètement contaminées par le culte des Damnés, furent transformées en pain et mangées par une population qui ne sut jamais qu'elle se mourait.",
			full = "La ruine de Stratholme commença par du grain. Des cargaisons venues d'Andorhal, secrètement contaminées par le culte des Damnés, furent transformées en pain et mangées par une population qui ne sut jamais qu'elle se mourait. Le prince Arthas Menethil arriva avec Uther le Porteur de Lumière et Jaina Proudmoore et trouva la peste déjà bien installée. Convaincu que la seule miséricorde qui restait était une mort nette plutôt qu'une lente transformation en mort-vivant, Arthas ordonna que la cité soit livrée aux flammes. Uther et Jaina refusèrent et retirèrent leurs hommes. Pas Arthas. Le feu balaya les rues, et presque toutes les âmes de Stratholme périrent avant que le seigneur de l'effroi Mal'Ganis, qu'Arthas était venu tuer, ne s'échappe en riant, laissant le prince brûler ce qui restait.\n\nCela ne suffit pas. Les morts se relevèrent malgré tout, et la cité devint la capitale du Fléau en Lordaeron, gouvernée d'abord par la liche Kel'Thuzad, puis par le chevalier de la mort baron Rivendare.\n\nStratholme brûle encore.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["terrordale"] = {
			name = "Val-Terreur",
			short = "Val-Terreur se trouve à la lisière de Pestebois, ses rues vidées et livrées au Fléau et aux animaux pestiférés. Seuls le marchand Augustus le Touché et le chasseur de fantômes Egan s'attardent encore parmi les ruines.",
			full = "Val-Terreur se trouve à la lisière de Pestebois, ses rues vidées et livrées au Fléau et aux animaux pestiférés. Seuls le marchand Augustus le Touché et le chasseur de fantômes Egan s'attardent encore parmi les ruines.\n\nLa ville est hantée. Des esprits arpentent ses ruelles, et en certains endroits, Val-Terreur elle-même semble vaciller, le monde physique ployant sous le poids du royaume qui s'étend au-delà, comme si le sol se souvenait d'un ancien tourment qu'il ne peut relâcher.\n\nC'est cette agitation qui attira le seigneur Grayson Shadowbreaker, qui vit dans ces esprits une épreuve de choix pour les paladins cherchant à se montrer dignes du jugement et du sacrifice, une étape vers l'obtention des destriers réservés aux plus méritants. Ce que furent ces esprits de leur vivant n'est consigné nulle part ; on sait seulement que leur tourment était assez réel pour déformer la ville autour d'eux.",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "Tunnel de Tisse-terreur",
			short = "Le tunnel perce la montagne au nord-ouest de Val-Terreur et court vers le sud jusqu'à rejoindre la Thondroril.",
			full = "Le tunnel perce la montagne au nord-ouest de Val-Terreur et court vers le sud jusqu'à rejoindre la Thondroril. Des démons des cryptes nérubiens encombrent entièrement le passage, et parmi eux rôde quelque chose de pire : un surveillant nérubien, bien plus mortel que ses congénères.\n\nÀ l'embouchure du tunnel, près de la rivière, Tirion Fordring monte la garde, faisant face aux ténèbres du passage depuis la lumière du dehors.",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thondroril river"] = {
			name = "La Thondroril",
			short = "La Thondroril sépare les Maleterres de l'ouest et de l'est. Elle prend sa source loin au nord, près du tunnel de Tisse-terreur, et coule vers le sud jusqu'à se jeter dans le lac Darrowmere, pour continuer au-delà sous le nom de rivière Darrowmere.",
			full = "La Thondroril sépare les Maleterres de l'ouest et de l'est. Elle prend sa source loin au nord, près du tunnel de Tisse-terreur, et coule vers le sud jusqu'à se jeter dans le lac Darrowmere, pour continuer au-delà sous le nom de rivière Darrowmere.\n\nSes berges appartiennent à la flétrissure. Asticots et chauves-souris vampires grouillent sur le sol humide, ours de la peste et araignées rôdent dans les hauts-fonds, et des gueules d'acier guettent là où le courant ralentit.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "Main de Tyr",
			short = "La Main de Tyr est une cité humaine fortifiée, l'un des derniers bastions des vivants face au Fléau dans la région.",
			full = "La Main de Tyr est une cité humaine fortifiée, l'un des derniers bastions des vivants face au Fléau dans la région. Ses environs sont en bien meilleur état que le reste des Maleterres, même si les arbres et la végétation y pourrissent encore.\n\nLa cité compte parmi les lieux saints les plus anciens et les plus vénérés de l'Église de la Lumière, bâtie presque entièrement d'églises et couronnée par la Basilique écarlate et l'abbaye fortifiée.\n\nLorsque le Fléau arriva et que la Sylve de l'Est devint les Maleterres, la Main de Tyr ne tomba pas. Sous le grand maître Valdelmar, elle résista aux assauts quotidiens, protégée d'abord par les chevaliers de la Main d'argent, puis par la Croisade écarlate, envoyant provisions et renforts vers d'autres possessions écarlates, tandis que des messagers apportaient chaque jour des rapports de Stratholme, contraints de se frayer un chemin à travers des routes infestées par la peste.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["undercroft"] = {
			name = "Le caveau de Zaeldarr",
			short = "Le caveau de Zaeldarr est une crypte au sud-ouest des Maleterres de l'est, repaire de trolls morts-vivants menés par Zaeldarr le Banni, un troll redoutable relevé d'entre les morts.",
			full = "Le caveau de Zaeldarr est une crypte au sud-ouest des Maleterres de l'est, repaire de trolls morts-vivants menés par Zaeldarr le Banni, un troll redoutable relevé d'entre les morts. De là, il pille la fosse funéraire de l'Aube d'argent à la chapelle de l'Espoir de Lumière, volant des corps pour son propre usage.",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "Zul'Mashar",
			short = "Zul'Mashar était jadis la capitale de la tribu Mossflayer, des trolls des forêts du nord-est des Maleterres de l'est.",
			full = "Zul'Mashar était jadis la capitale de la tribu Mossflayer, des trolls des forêts du nord-est des Maleterres de l'est. De longues guerres contre les humains de Lordaeron laissèrent les terres de la tribu dans le chaos, et la peste de la non-mort qui suivit acheva de les ruiner. La cité qui régnait jadis ici n'est plus que l'ombre de sa gloire passée.\n\nSa ziggourat, Mazra'Alor, se dresse toujours au cœur de la cité, tenue aujourd'hui par le seigneur de guerre Thresh'jin et Zul'Brin Warpbranch. Mais le propre peuple des Mossflayer est secrètement transformé par la peste, et Zul'Mashar risque de ne plus devenir qu'un bastion des morts-vivants.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- Contreforts d'Hillsbrad: 29 subzones
	[1424] = {
		["azurelode mine"] = {
			name = "Mine d'Azurelode",
			short = "La mine d'Azurelode se trouve dans la partie sud-ouest des contreforts d'Hillsbrad ; sa colline faisait jadis partie de Gilnéas, avant que le mur de Greymane ne s'élève et ne coupe le royaume du monde.",
			full = "La mine d'Azurelode se trouve dans la partie sud-ouest des contreforts d'Hillsbrad ; sa colline faisait jadis partie de Gilnéas, avant que le mur de Greymane ne s'élève et ne coupe le royaume du monde.\n\nLa mine appartient à l'Alliance ; des mineurs y travaillent sous la surveillance de gardes, et son fer alimente les arsenaux de l'Alliance.",
			source = "https://warcraft.wiki.gg/wiki/Azurelode_Mine",
		},
		["chillwind point"] = {
			name = "Pointe du Noroît",
			short = "La pointe du Noroît tient son nom du vent glacial qui descend des Maleterres de l'ouest et s'engouffre dans le ravin en contrebas. L'éminence est couronnée d'une antique ruine trolle, tout ce qui reste de ceux qui l'élevèrent.",
			full = "La pointe du Noroît tient son nom du vent glacial qui descend des Maleterres de l'ouest et s'engouffre dans le ravin en contrebas. L'éminence est couronnée d'une antique ruine trolle, tout ce qui reste de ceux qui l'élevèrent. Le col appartenait jadis au royaume de Lordaeron. Le troll de la jungle Bath'rah la Vigie des vents se tient désormais dans la ruine.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Point",
		},
		["corrahns dagger"] = {
			name = "Dague de Corrahn",
			short = "La dague de Corrahn est le deuxième des quatre doigts d'Hillsbrad. Le Syndicat tient cette colline.",
			full = "La dague de Corrahn est le deuxième des quatre doigts d'Hillsbrad. Le Syndicat tient cette colline.",
			source = "https://warcraft.wiki.gg/wiki/Corrahn's_Dagger",
		},
		["crushridge hold"] = {
			name = "Bastion Cassecrête",
			short = "Le bastion Cassecrête s'élève près des ruines d'Alterac, une grotte creusée dans un tertre de terre.",
			full = "Le bastion Cassecrête s'élève près des ruines d'Alterac, une grotte creusée dans un tertre de terre. Tout autour, les ogres Cassecrête ont dressé leurs campements, nombreux et brutaux, tenant les pentes qui dominent la cité en ruine en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Crushridge_Hold",
		},
		["darrow hill"] = {
			name = "Colline de Darrow",
			short = "La colline de Darrow se trouve au nord des contreforts d'Hillsbrad, au pied de l'Avancée.",
			full = "La colline de Darrow se trouve au nord des contreforts d'Hillsbrad, au pied de l'Avancée. Pumas et cerfs parcourent ses champs dégagés, et dans les cavernes des contreforts, des yétis ont établi leur tanière, parmi les veines de granit d'Alterac qui traversent la roche.",
			source = "https://warcraft.wiki.gg/wiki/Darrow_Hill",
		},
		["dun garok"] = {
			name = "Dun Garok",
			short = "Dun Garok se dresse dans les collines des contreforts d'Hillsbrad, un fort nain sous le commandement du capitaine Ironhill.",
			full = "Dun Garok se dresse dans les collines des contreforts d'Hillsbrad, un fort nain sous le commandement du capitaine Ironhill. Sa garnison protège les humains d'Hillsbrad et veille sur la mine d'Azurelode, une présence que les Réprouvés ne peuvent souffrir ; ils ont offert de l'or à quiconque se glisserait dans le fort pour passer ses nains au fil de l'épée.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Garok",
		},
		["durnholde keep"] = {
			name = "Donjon de Durnholde",
			short = "Le donjon de Durnholde se dresse, brisé, à l'est de Moulin-de-Tarren, ses casernes et sa tour de mage effondrées sur elles-mêmes, son arène silencieuse.",
			full = "Le donjon de Durnholde se dresse, brisé, à l'est de Moulin-de-Tarren, ses casernes et sa tour de mage effondrées sur elles-mêmes, son arène silencieuse. Il fut jadis le siège du réseau de camps d'internement orcs établi après la deuxième guerre, gouverné par le lieutenant général Aedelas Blackmoore, un ivrogne imbu de lui-même qui se servait du camp pour son propre avancement.\n\nC'est Blackmoore qui trouva un nourrisson orc parmi les corps de ses parents assassinés et le ramena au donjon, le nommant Thrall. L'enfant y fut élevé et instruit, allaité par une humaine dont la fille, Taretha Foxton, se lia d'amitié avec lui. Pendant des années, Blackmoore le battit et le fit combattre dans l'arène, tirant parti de sa force pour gravir les échelons. Taretha lui écrivait en secret, et il lui répondait, jusqu'au jour où il lui annonça qu'il comptait s'évader. Elle créa la diversion qui lui permit de s'échapper, le rejoignit au-delà des murs et lui donna des provisions avant son départ.\n\nIl revint bel et bien, des années plus tard, à la tête des orcs libres qu'il avait rassemblés. Thrall assiégea Durnholde, tua Blackmoore en combat singulier et fit appel à l'esprit de la Terre pour raser entièrement la forteresse. Ce qu'il en reste a depuis attiré le Syndicat, qui revendique ces ruines comme les siennes.",
			source = "https://warcraft.wiki.gg/wiki/Durnholde_Keep",
		},
		["eastern strand"] = {
			name = "Rivage oriental",
			short = "Le Rivage oriental longe la côte sud-est des contreforts d'Hillsbrad, et son pendant s'étend plus à l'ouest sur ce même littoral.",
			full = "Le Rivage oriental longe la côte sud-est des contreforts d'Hillsbrad, et son pendant s'étend plus à l'ouest sur ce même littoral. Cette bande de sable appartient aux nagas Daggerspine, qui tiennent les plages et les eaux peu profondes au-delà.",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Strand",
		},
		["gallows corner"] = {
			name = "Fourche du gibet",
			short = "À la fourche du Gibet, là où les routes se rejoignent dans les montagnes d'Alterac près des salles en ruine d'Alterac, une tour d'observation se dresse, brisée et vide.",
			full = "À la fourche du Gibet, là où les routes se rejoignent dans les montagnes d'Alterac près des salles en ruine d'Alterac, une tour d'observation se dresse, brisée et vide. Les ogres Cassecrête tiennent désormais le carrefour, rôdant parmi les pierres autour des restes de la tour, et rien d'autre n'y bouge.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_Corner",
		},
		["gavins naze"] = {
			name = "Promontoire de Gavin",
			short = "Le promontoire de Gavin est la dernière des quatre collines d'Hillsbrad, et la mieux gardée.",
			full = "Le promontoire de Gavin est la dernière des quatre collines d'Hillsbrad, et la mieux gardée.\n\nDes pumas parcourent cette colline, parmi lesquels Araga, reconnaissable à son pelage peu commun.",
			source = "https://warcraft.wiki.gg/wiki/Gavin's_Naze",
		},
		["growless cave"] = {
			name = "Caverne stérile",
			short = "Dans les montagnes d'Alterac, une caverne abrite des yétis des montagnes, et l'on trouve souvent Skhowl juste devant son entrée.",
			full = "Dans les montagnes d'Alterac, une caverne abrite des yétis des montagnes, et l'on trouve souvent Skhowl juste devant son entrée. Tout au fond se dresse la Flamme d'Uzel, un bûcher élevé par l'humain Helcular pour le rituel qui devait faire de lui une liche. La viande qu'on y brûle attire à l'entrée le puissant yéti Gueule-glacée.",
			source = "https://warcraft.wiki.gg/wiki/Growless_Cave",
		},
		["headland"] = {
			name = "L'Avancée",
			short = "L'Avancée est l'un des doigts de terre qui s'étendent à travers Hillsbrad.",
			full = "L'Avancée est l'un des doigts de terre qui s'étendent à travers Hillsbrad.\n\nSur la falaise, Araga se repose ici parmi ses petits.",
			source = "https://warcraft.wiki.gg/wiki/Headland",
		},
		["hillsbrad fields"] = {
			name = "Champs d'Hillsbrad",
			short = "Les champs d'Hillsbrad s'étendent, fertiles et cultivés, à l'ouest des contreforts d'Hillsbrad, nourrissant Southshore ainsi que la ville d'Hillsbrad.",
			full = "Les champs d'Hillsbrad s'étendent, fertiles et cultivés, à l'ouest des contreforts d'Hillsbrad, nourrissant Southshore ainsi que la ville d'Hillsbrad. Vergers de pommiers, carrés de citrouilles et bétail en pâture couvrent la contrée, et les habitants de la ville travaillent toujours à la mine d'Azurelode.\n\nAu début de la deuxième guerre, Doomhammer tourna ses armées contre Hillsbrad et la fit détruire de manière atroce, pour servir d'avertissement aux royaumes humains. Elle fut reconstruite après la guerre et reste peuplée aujourd'hui, l'un des rares recoins de l'ancien Lordaeron qui ne fut ni laissé en ruine ni englouti par la Croisade écarlate ; ses gardes portent encore le tabard de leur royaume, et le magistrat Burnside gouverne depuis l'hôtel de ville avec le conseil d'Hillsbrad et le greffier Horrace Whitesteed à ses côtés.\n\nAujourd'hui, les champs sont de nouveau menacés, cette fois par les forces de la grande exécutrice Darthalia à Moulin-de-Tarren. Paysans et fermiers subissent les raids, mais beaucoup ripostent contre les morts-vivants en tendant leurs propres embuscades, armés par le forgeron Verringtan et ses apprentis.",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Fields",
		},
		["misty shore"] = {
			name = "Rivage brumeux",
			short = "Le Rivage brumeux longe le lac Lordamere, entre le Clos de Dandred et Dalaran. Des tortues se meuvent lentement dans ses hauts-fonds.",
			full = "Le Rivage brumeux longe le lac Lordamere, entre le Clos de Dandred et Dalaran. Des tortues se meuvent lentement dans ses hauts-fonds.\n\nDeux membres de la Croisade écarlate tiennent ce rivage et s'abattent sur quiconque s'approche trop près, comme si la terre elle-même avait besoin d'être gardée.\n\nDe l'autre côté de l'eau, on aperçoit les îles de l'Aube, et le donjon de Fenris qui se dessine, menaçant, à travers la brume.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Shore",
		},
		["nethander stead"] = {
			name = "Ferme des Nethander",
			short = "La ferme des Nethander se trouve juste à l'est de Southshore ; ses champs, abandonnés depuis longtemps, sont envahis par les gnolls Fangemufle, le seul endroit où l'on trouve leur tribu.",
			full = "La ferme des Nethander se trouve juste à l'est de Southshore ; ses champs, abandonnés depuis longtemps, sont envahis par les gnolls Fangemufle, le seul endroit où l'on trouve leur tribu. De grands champignons blancs appelés fleurs de fangemufle y poussent à l'état sauvage ; l'apothicaire Lydon les recherchait jadis pour son mortel élixir d'agonie.",
			source = "https://warcraft.wiki.gg/wiki/Nethander_Stead",
		},
		["purgation isle"] = {
			name = "Ile de la purification",
			short = "Une spirale de pierre s'élève au sud du rivage d'Hillsbrad, couronnée d'un cimetière et des restes brisés d'une tour d'observation. Avant la première guerre, l'île de la Purification appartenait à Kul Tiras.",
			full = "Une spirale de pierre s'élève au sud du rivage d'Hillsbrad, couronnée d'un cimetière et des restes brisés d'une tour d'observation. Avant la première guerre, l'île de la Purification appartenait à Kul Tiras.\n\nCe qui s'est passé ensuite est incertain, mais les morts n'y reposent pas. Des dizaines d'esprits arpentent l'île, humains et nains, paladins et prêtres, moines et mages, âmes condamnées liées à ses pierres.",
			source = "https://warcraft.wiki.gg/wiki/Purgation_Isle",
		},
		["ravenholdt manor"] = {
			name = "Manoir de Ravenholdt",
			short = "Le manoir de Ravenholdt se tient à l'écart du monde, et c'est voulu.",
			full = "Le manoir de Ravenholdt se tient à l'écart du monde, et c'est voulu. On ne l'atteint que par un sentier étroit et tortueux qui monte depuis un plateau au nord-ouest du donjon de Durnholde, serpentant à travers les montagnes et une petite grotte avant de déboucher sur le domaine ; le manoir n'est pas un lieu sur lequel on tombe par hasard. Les étrangers n'y sont pas les bienvenus, et ceux qui servent le seigneur Jorach Ravenholdt veillent à ce qu'il en soit ainsi.\n\nLe manoir est sa propriété, coiffé de toits orange à l'ancienne mode d'Alterac, dont le royaume tenait cette terre avant la première guerre.\n\nDepuis, le Syndicat erre dans cette partie des hautes terres, et Ravenholdt s'est dressé contre ce fléau derrière son sentier caché et ses portes gardées.",
			source = "https://warcraft.wiki.gg/wiki/Ravenholdt_Manor",
		},
		["slaughter hollow"] = {
			name = "Creux du massacre",
			short = "Au plus profond des montagnes d'Alterac, les ogres Cassecrête ont élu domicile dans le Creux du massacre, un tertre enfoncé dans les collines.",
			full = "Au plus profond des montagnes d'Alterac, les ogres Cassecrête ont élu domicile dans le Creux du massacre, un tertre enfoncé dans les collines. On ne sait guère plus de ce lieu que les ogres qui le tiennent, mais son nom seul dit ce qui attend quiconque s'en approche trop.",
			source = "https://warcraft.wiki.gg/wiki/Slaughter_Hollow",
		},
		["soferas naze"] = {
			name = "Promontoire de Sofera",
			short = "Le promontoire de Sofera est l'un des quatre doigts d'Hillsbrad. Le Syndicat tient la colline et surveille les terres en contrebas.",
			full = "Le promontoire de Sofera est l'un des quatre doigts d'Hillsbrad. Le Syndicat tient la colline et surveille les terres en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Sofera's_Naze",
		},
		["southpoint tower"] = {
			name = "Tour de la Pointe du Midi",
			short = "La tour de la Pointe du Midi se dresse à l'extrême ouest des contreforts d'Hillsbrad, juste au sud de la route qui mène à la forêt des Pins argentés.",
			full = "La tour de la Pointe du Midi se dresse à l'extrême ouest des contreforts d'Hillsbrad, juste au sud de la route qui mène à la forêt des Pins argentés. La maçonnerie est vieille et fissurée, un poste d'observation laissé à l'abandon, bien que la tour elle-même n'ait jamais été abattue lors des combats qui ont traversé la région. Non loin, sans nom, une autre tour se dresse entre Moulin-de-Tarren et Southshore, elle aussi épargnée par la destruction qui a balayé le reste des contreforts.",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Tower",
		},
		["strahnbrad"] = {
			name = "Strahnbrad",
			short = "Strahnbrad se trouve sur les contreforts nord-est des montagnes d'Alterac ; son hôtel de ville et sa forge sont désormais vides.",
			full = "Strahnbrad se trouve sur les contreforts nord-est des montagnes d'Alterac ; son hôtel de ville et sa forge sont désormais vides. Elle appartenait jadis au royaume d'Alterac, et après la deuxième guerre, elle passa aux mains de Lordaeron.\n\nLa ruine de la ville commença peu avant la troisième guerre, lorsque des orcs Blackrock s'abattirent sur elle pour s'emparer d'esclaves à sacrifier à la Légion ardente. Strahnbrad n'avait qu'une poignée de fantassins pour la défendre, mais la nouvelle parvint à temps aux chevaliers de la Main d'argent. Uther le Porteur de Lumière partit en avant pour tenter d'intercepter l'attaque, tandis que le prince Arthas Menethil était envoyé tenir la ville elle-même. Arthas n'arriva pas à temps. Dean, Joe, Mike, Scott et bien d'autres furent tués avant qu'il n'atteigne Strahnbrad, et les défenseurs restants se joignirent à lui pour mettre les orcs en déroute et tuer le maître des esclaves qui avait mené le raid. L'Alliance remporta la victoire, mais le peuple de Strahnbrad avait déjà disparu.\n\nLe Syndicat s'empara plus tard de la ville en ruine, s'en servant comme place forte pour conquérir les montagnes d'Alterac, et retint l'orc Gol'dir prisonnier dans l'une de ses cellules, le faisant travailler comme esclave pour porter et creuser.",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "Moulin-de-Tarren",
			short = "Moulin-de-Tarren était jadis une simple ville de Lordaeron, au milieu des prairies au pied des montagnes d'Alterac.",
			full = "Moulin-de-Tarren était jadis une simple ville de Lordaeron, au milieu des prairies au pied des montagnes d'Alterac. Au début de la deuxième guerre, des archers hauts-elfes de Lune-d'argent, envoyés vers le sud pour constater par eux-mêmes la menace orque, tombèrent dans une embuscade près de la ville et furent traînés jusqu'à un camp de prisonniers voisin. Le roi Terenas envoya des soldats de l'Alliance les libérer, et le sauvetage réussit. C'est ce succès qui poussa le Conseil de Lune-d'argent à joindre les armées de Quel'Thalas à l'Alliance de Lordaeron.\n\nMoulin-de-Tarren ne resta pas aux mains des humains. Les Réprouvés s'en emparèrent avec le temps et la laissèrent comme ils ont laissé leurs autres possessions : une église, quelques maisons éparses, des vergers pourris, tout debout mais rien d'intact. D'ici, les Réprouvés mènent leur guerre contre les forces de l'Alliance de Southshore et de Dun Garok, et le terrain entre Moulin-de-Tarren et Southshore est devenu tristement célèbre pour les escarmouches incessantes entre les deux villes, aucune ne parvenant à briser l'autre.",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
		},
		["thoradins wall"] = {
			name = "Mur de Thoradin",
			short = "Le roi Thoradin éleva ce mur pour contenir les trolls amani, au temps où Strom était jeune et où Arathor venait tout juste de conquérir la contrée pour l'humanité.",
			full = "Le roi Thoradin éleva ce mur pour contenir les trolls amani, au temps où Strom était jeune et où Arathor venait tout juste de conquérir la contrée pour l'humanité. Des générations durant, il se dressa en sentinelle inébranlable, une ligne qu'aucune horde trolle ne pouvait franchir.\n\nDes siècles plus tard, il est toujours debout, mais gravement endommagé, ses pierres brisées et sa longue veille réduite à l'état de ruine.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["western strand"] = {
			name = "Rivage occidental",
			short = "Le Rivage occidental se trouve sur la côte sud-ouest des contreforts d'Hillsbrad. Les murlocs Aileron déchiré ont établi de petits camps le long de ses berges, et Andy Murgole patrouille ces eaux, surveillant la côte où ils vivent.",
			full = "Le Rivage occidental se trouve sur la côte sud-ouest des contreforts d'Hillsbrad. Les murlocs Aileron déchiré ont établi de petits camps le long de ses berges, et Andy Murgole patrouille ces eaux, surveillant la côte où ils vivent.",
			source = "https://warcraft.wiki.gg/wiki/Western_Strand",
		},
	},
	-- Les Hinterlands: 20 subzones
	[1425] = {
		["aerie peak"] = {
			name = "Nid-de-l'Aigle",
			short = "Les nains Marteau-hardi n'ont pas choisi les Hinterlands en premier.",
			full = "Les nains Marteau-hardi n'ont pas choisi les Hinterlands en premier. Leur foyer était Grim Batol, au plus profond de la montagne, jusqu'à ce que la guerre des Trois clans prenne fin et que les nains, à leur retour, trouvent leur forteresse empoisonnée par la mort de Modgud. Grim Batol ne pouvait plus être habitée. Les Marteau-hardi rebâtirent donc ici, au sommet de la montagne plutôt qu'en son sein, refusant, après les horreurs des combats dans les tunnels contre les nains Sombrefer, de s'enfouir de nouveau dans la pierre. Le Nid s'ouvre sur le ciel à cause de cette guerre.\n\nC'est d'ici que Kurdran Marteau-hardi mena ses chevaucheurs de gryphon contre les forces orques envoyées frapper les Hinterlands pour faire diversion, tandis que la véritable armée de la Horde marchait sur Quel'Thalas. Les forces d'Anduin Lothar vinrent à son aide et contribuèrent à chasser les orcs et les trolls des forêts des terres des Marteau-hardi, et en reconnaissance, Kurdran engagea son clan auprès de l'Alliance.\n\nFalstad Marteau-hardi, devenu haut-thane lorsque Kurdran ne revint pas, règne toujours sur le Nid. Les trolls des forêts des Hinterlands, qui voient dans les Marteau-hardi des squatteurs installés sur une terre ancestrale, attaquent toujours les aires des gryphons, tandis que les hauts-elfes de Quel'Danil demeurent les alliés des nains face à ce même ennemi.",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
		},
		["agolwatha"] = {
			name = "Agol'watha",
			short = "Les pierres d'Agol'watha sont plus anciennes que les trolls qui les tinrent en dernier pour sacrées ; elles furent élevées en temple de l'empire Amani avant la chute de cet empire.",
			full = "Les pierres d'Agol'watha sont plus anciennes que les trolls qui les tinrent en dernier pour sacrées ; elles furent élevées en temple de l'empire Amani avant la chute de cet empire. Les trolls Vilebranch qui vinrent ensuite revendiquèrent la ruine. Aujourd'hui, le temple a été envahi par des vases animées qui emplissent ses cours brisées.",
			source = "https://warcraft.wiki.gg/wiki/Agol'watha",
		},
		["altar of zul"] = {
			name = "L'Autel de Zul",
			short = "L'autel de Zul s'élève dans les Hinterlands, dressé par les trolls des forêts Vilebranch pour leurs anciens rites. Qiaga la Gardienne veille au sommet des pierres, gardienne du pouvoir que l'autel détient encore.",
			full = "L'autel de Zul s'élève dans les Hinterlands, dressé par les trolls des forêts Vilebranch pour leurs anciens rites. Qiaga la Gardienne veille au sommet des pierres, gardienne du pouvoir que l'autel détient encore.",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Zul",
		},
		["bogens ledge"] = {
			name = "Escarpement de Bogen",
			short = "L'escarpement de Bogen est une grotte au sud-ouest des Hinterlands.",
			full = "L'escarpement de Bogen est une grotte au sud-ouest des Hinterlands.",
			source = "https://warcraft.wiki.gg/wiki/Bogen's_Ledge",
		},
		["creeping ruin"] = {
			name = "La Ruine aux rampants",
			short = "La Ruine aux rampants gît, brisée, dans les Hinterlands, faite de pierres jadis façonnées par des mains de trolls des forêts. Des limons rampent désormais dans ses salles effondrées, suintant entre les vieilles pierres trolles là où marchaient autrefois les trolls.",
			full = "La Ruine aux rampants gît, brisée, dans les Hinterlands, faite de pierres jadis façonnées par des mains de trolls des forêts. Des limons rampent désormais dans ses salles effondrées, suintant entre les vieilles pierres trolles là où marchaient autrefois les trolls.",
			source = "https://warcraft.wiki.gg/wiki/Creeping_Ruin",
		},
		["featherbeards hovel"] = {
			name = "Taudis de Featherbeard",
			short = "Près du Nid-de-l'Aigle se dresse une petite maison qui appartenait jadis à un certain Featherbeard. Elle n'abrite ni garnison ni trésor.",
			full = "Près du Nid-de-l'Aigle se dresse une petite maison qui appartenait jadis à un certain Featherbeard. Elle n'abrite ni garnison ni trésor. Elle n'a plus d'autre raison d'être que de se tenir là où elle s'est toujours tenue, vide de la vie qui l'emplissait autrefois.",
			source = "https://warcraft.wiki.gg/wiki/Featherbeard's_Hovel",
		},
		["hiriwatha"] = {
			name = "Hiri'watha",
			short = "Les trolls Witherbark tiennent Hiri'watha, un village situé au sud du gîte de Quel'Danil dans les Hinterlands, au cœur de la forêt qu'ils revendiquent comme la leur.",
			full = "Les trolls Witherbark tiennent Hiri'watha, un village situé au sud du gîte de Quel'Danil dans les Hinterlands, au cœur de la forêt qu'ils revendiquent comme la leur.",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
		},
		["jinthaalor"] = {
			name = "Jintha'Alor",
			short = "Jintha'Alor s'élève en terrasses au-dessus des Hinterlands ; c'est la plus grande des cités des trolls des forêts après Zul'Aman.",
			full = "Jintha'Alor s'élève en terrasses au-dessus des Hinterlands ; c'est la plus grande des cités des trolls des forêts après Zul'Aman. Elle fut élevée au temps de l'empire Amani et tient son nom de Jintha, l'un des anciens chefs des Amani.\n\nLa cité appartient à la tribu Vilebranch, qui a fait de ses hauteurs une forteresse du sacrifice. La vile prêtresse Maléficia y règne au service d'Hakkar l'Écorcheur d'âmes, et les Vilebranch s'en prennent sans pitié à la tribu plus faible des Revantusk pour nourrir la faim de leur dieu. L'Ancien Torntusk des Revantusk fut enlevé lors d'un de ces raids et est toujours retenu captif dans la cité ; son capitaine de la garde, le chasseur Malkhor, fut capturé lors de la même attaque et exécuté, et ses restes jetés aux loups et aux limons gardés entre les murs.\n\nLe clan Marteau-hardi et la tribu Revantusk, unis par une même rancune envers les Vilebranch, assiègent ensemble la cité, cherchant à mettre fin à ses raids et à venger leurs morts.",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["overlook cliffs"] = {
			name = "Les Hauts-Surplombs",
			short = "Les Hauts-Surplombs marquent l'endroit où les Hinterlands cessent d'être des montagnes pour devenir le ciel.",
			full = "Les Hauts-Surplombs marquent l'endroit où les Hinterlands cessent d'être des montagnes pour devenir le ciel. Le grand fleuve qui serpente à travers la région se rassemble ici et se déverse par-dessus le bord en une unique et immense cascade, tombant jusqu'au rivage en contrebas.\n\nLes falaises sont abruptes et bien plus hautes qu'elles n'en ont l'air. Nombre de ceux qui s'avancèrent jusqu'au bord sous-estimèrent la chute et trouvèrent la mort.",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
		},
		["plaguemist ravine"] = {
			name = "Ravin de Pestebrume",
			short = "Une brume flotte là où la muraille montagneuse s'ouvre à l'ouest du gîte de Quel'Danil, marquant le ravin qui file vers le nord en direction de Caer Darrow. Rien ne vit dans ce passage.",
			full = "Une brume flotte là où la muraille montagneuse s'ouvre à l'ouest du gîte de Quel'Danil, marquant le ravin qui file vers le nord en direction de Caer Darrow. Rien ne vit dans ce passage. Aucun oiseau ne le traverse, aucune bête ne gîte dans sa roche.\n\nLes Hinterlands alentour restent verts et sains, mais le ravin exhale autre chose, une brume qui n'appartient pas à la forêt. C'est pourquoi le lieu porte aujourd'hui le nom qui est le sien : Pestebrume, un nom donné pour ce brouillard maladif qui souille ce seul chemin tandis que le reste de la contrée demeure intact.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "Gîte de Quel'Danil",
			short = "Le gîte de Quel'Danil est l'un des derniers véritables rassemblements de hauts-elfes, le plus grand des deux seuls établissements de ce genre qui subsistent en Lordaeron.",
			full = "Le gîte de Quel'Danil est l'un des derniers véritables rassemblements de hauts-elfes, le plus grand des deux seuls établissements de ce genre qui subsistent en Lordaeron. Après la troisième guerre, il devint un lieu de correspondance, ses ambassadeurs tendant la main aux autres peuples de l'Alliance. Cette ouverture valut aux elfes de Highvale une alliance avec les nains Marteau-hardi, et leur attira la haine des trolls Revantusk, qui voulaient voir les elfes massacrés et leurs archives brûlées. Les documents survécurent : registres des décès, des naissances, des saisons, et de chaque traité que les elfes avaient conclu.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "Village des Revantusk",
			short = "Le village des Revantusk se dresse sur la côte des Hinterlands, dernier foyer d'une tribu de trolls des forêts qui choisit la loyauté plutôt que la survie.",
			full = "Le village des Revantusk se dresse sur la côte des Hinterlands, dernier foyer d'une tribu de trolls des forêts qui choisit la loyauté plutôt que la survie.\n\nLorsque l'ancienne Horde fut brisée pendant la deuxième guerre, les geôliers des orcs se retournèrent contre leurs anciens alliés, et les tribus de trolls des forêts à travers le pays abandonnèrent la Horde sans hésiter. Pas les Revantusk. Ils n'étaient pas assez nombreux pour libérer les orcs captifs, qui de toute façon montraient peu d'envie d'être libérés, mais leur loyauté persistante les désigna comme cible aux autres trolls, qui ne voulaient plus rien avoir à faire avec les orcs. Chassés de leurs terres, les Revantusk s'enfuirent sur la côte des Hinterlands, espérant que l'isolement les protégerait, et y bâtirent leur village.\n\nLa nouvelle finit par leur parvenir que Thrall avait refondé la Horde et ramené son peuple aux voies chamaniques de ses ancêtres. Les Revantusk envoyèrent leurs coureurs les plus rapides le trouver, et de cette rencontre naquit un pacte d'amitié entre la tribu et la nouvelle Horde. Les autres trolls des forêts ne l'ont jamais pardonné, traitant les Revantusk de faibles et de traîtres, tandis que les Revantusk désignent comme les vrais traîtres tous ceux qui ont déserté la Horde.",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "Seradane",
			short = "Au nord-est des Hinterlands se trouve Seradane, où un grand portail circulaire s'ouvre sur le Rêve d'émeraude. La forêt appartient au vol draconique vert, venu garder le seuil que les siens tiennent pour sacré.",
			full = "Au nord-est des Hinterlands se trouve Seradane, où un grand portail circulaire s'ouvre sur le Rêve d'émeraude. La forêt appartient au vol draconique vert, venu garder le seuil que les siens tiennent pour sacré. Les drakes Rothos et Dreamtracker ont élu domicile parmi ces arbres.\n\nLa plupart de ceux qui gardent les bois sont des drakônides, nés du pouvoir du vol. Ils se déplacent par groupes de trois, un oracle verdoyant flanqué de gardes-ramures et de gardiens des arbres, patrouillant les sentiers enchevêtrés en une veille permanente sur la voie qui mène au Rêve.",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
		["shadraalor"] = {
			name = "Shadra'Alor",
			short = "Dans les Hinterlands se dresse Shadra'Alor, un site élevé par les trolls des forêts de l'empire Amani. Ici, le loa Shadra pouvait être appelé et invoqué ; c'était un lieu réservé à ce seul dessein.",
			full = "Dans les Hinterlands se dresse Shadra'Alor, un site élevé par les trolls des forêts de l'empire Amani. Ici, le loa Shadra pouvait être appelé et invoqué ; c'était un lieu réservé à ce seul dessein.",
			source = "https://warcraft.wiki.gg/wiki/Shadra'Alor",
		},
		["shaolwatha"] = {
			name = "Shaol'watha",
			short = "Shaol'watha est une ruine des trolls des forêts Vilebranch au nord-est des Hinterlands. C'était jadis un temple.",
			full = "Shaol'watha est une ruine des trolls des forêts Vilebranch au nord-est des Hinterlands. C'était jadis un temple.",
			source = "https://warcraft.wiki.gg/wiki/Shaol'watha",
		},
		["shindiggers camp"] = {
			name = "Camp de Shindigger",
			short = "Rhapsody Croquejarret, un nain qui aime la boisson, tient son petit camp dans les Hinterlands aux côtés du haut-elfe Gilveradin Sunchaser, un étrange duo qui occupe ce coin tranquille.",
			full = "Rhapsody Croquejarret, un nain qui aime la boisson, tient son petit camp dans les Hinterlands aux côtés du haut-elfe Gilveradin Sunchaser, un étrange duo qui occupe ce coin tranquille.",
			source = "https://warcraft.wiki.gg/wiki/Shindigger's_Camp",
		},
		["skulk rock"] = {
			name = "Rocher de l'Affût",
			short = "Le Rocher de l'Affût est une ruine des trolls des forêts envahie par les limons. Une grotte en dessous est l'un des rares endroits où poussent encore des champignons fantômes.",
			full = "Le Rocher de l'Affût est une ruine des trolls des forêts envahie par les limons. Une grotte en dessous est l'un des rares endroits où poussent encore des champignons fantômes.\n\nPendant la deuxième guerre, l'ancienne Horde fit du rocher sa base, jusqu'à ce que l'Alliance de Lordaeron l'en chasse.",
			source = "https://warcraft.wiki.gg/wiki/Skulk_Rock",
		},
		["valorwind lake"] = {
			name = "Lac Vent-vaillant",
			short = "Le lac Vent-vaillant s'étend, paisible, au nord-est de Shadra'Alor, ses eaux en apparence sans rien de remarquable.",
			full = "Le lac Vent-vaillant s'étend, paisible, au nord-est de Shadra'Alor, ses eaux en apparence sans rien de remarquable. Pourtant, sur ses rives pousse quelque chose que l'on ne connaît nulle part ailleurs au monde : le tragan violet, un mystérieux champignon qui garde ses secrets pour lui.",
			source = "https://warcraft.wiki.gg/wiki/Valorwind_Lake",
		},
		["wildhammer keep"] = {
			name = "Donjon des Wildhammer",
			short = "Le donjon des Wildhammer s'élève au cœur du Nid-de-l'Aigle ; c'est le siège des nains Marteau-hardi qui le tiennent. Ses salles sont ouvertes aux voyageurs qui atteignent le sommet.",
			full = "Le donjon des Wildhammer s'élève au cœur du Nid-de-l'Aigle ; c'est le siège des nains Marteau-hardi qui le tiennent. Ses salles sont ouvertes aux voyageurs qui atteignent le sommet.",
			source = "https://warcraft.wiki.gg/wiki/Wildhammer_Keep",
		},
		["zunwatha"] = {
			name = "Zun'watha",
			short = "Les pierres de Zun'watha abritaient jadis, et abritent encore, les trolls Witherbark des Hinterlands.",
			full = "Les pierres de Zun'watha abritaient jadis, et abritent encore, les trolls Witherbark des Hinterlands. Parmi les ruines qu'ils ont laissées debout, on aperçoit de temps à autre un oiseau de haine de Zul'arek, qui marche là où vivent encore les Witherbark.",
			source = "https://warcraft.wiki.gg/wiki/Zun'watha",
		},
	},
	-- Dun Morogh: 25 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "Ferme des Amberstill",
			short = "La ferme des Amberstill se trouve en retrait de la route du Loch Modan, au nord de la carrière de Gol'Bolar ; les nains de la famille Amberstill y élèvent leurs troupeaux malgré le froid de Dun Morogh.",
			full = "La ferme des Amberstill se trouve en retrait de la route du Loch Modan, au nord de la carrière de Gol'Bolar ; les nains de la famille Amberstill y élèvent leurs troupeaux malgré le froid de Dun Morogh. Rudra Amberstill y élève des béliers réputés, tandis que la jeune Yarlyn garde ses lapins des neiges dans ses jambes.\n\nLes troupeaux ne sont pas à l'abri. Un wendigo nommé Vagash s'est mis à traquer les bêtes de la ferme, et les Amberstill ont dû défendre ce qu'ils élèvent contre sa faim.",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "Anvilmar",
			short = "Dans la vallée des Frigères se dresse Anvilmar, une salle bâtie autour d'une grande forge. Ce fut le premier véritable établissement que les nains élevèrent dans ces confins du nord, un lieu de rassemblement avant que tout autre ne prenne forme.",
			full = "Dans la vallée des Frigères se dresse Anvilmar, une salle bâtie autour d'une grande forge. Ce fut le premier véritable établissement que les nains élevèrent dans ces confins du nord, un lieu de rassemblement avant que tout autre ne prenne forme. La forge en son cœur brûle toujours, bien qu'aucun forgeron n'y enseigne plus son art.",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["brewnall village"] = {
			name = "Brassetout",
			short = "Brassetout se trouve dans la vallée de la Bise, près de Gnomeregan ; c'est le foyer de la famille Barleybrew. Les Barleybrew se sont voués à une seule quête : perfectionner l'art nain de la brasserie.",
			full = "Brassetout se trouve dans la vallée de la Bise, près de Gnomeregan ; c'est le foyer de la famille Barleybrew. Les Barleybrew se sont voués à une seule quête : perfectionner l'art nain de la brasserie. Ils envoient leurs jeunes hors du village pour le protéger des bêtes sauvages et chercher des ingrédients rares pour la bière ultime.",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "Vallée de la bise",
			short = "La vallée de la Bise s'étend d'est en ouest entre Gnomeregan et Kharanos, son chemin bien connu des jeunes nains et gnomes qui y passent.",
			full = "La vallée de la Bise s'étend d'est en ouest entre Gnomeregan et Kharanos, son chemin bien connu des jeunes nains et gnomes qui y passent. Mais la vallée s'incurve aussi vers le nord et vers le sud, et là, la neige raconte une autre histoire : de larges taches de sang s'étalent sur le blanc, et des carcasses d'animaux déchiquetées gisent à l'abandon. Rares sont ceux qui empruntent volontiers cet embranchement. Ceux qui le font partent chasser les bêtes responsables, espérant mettre fin à leur menace sur les terres naines, et beaucoup ne reviennent pas. Au fond de l'une des grottes se terre un wendigo, la créature la plus responsable du sang dans la neige.",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "Passe des Frigères",
			short = "La passe des Frigères est l'étroite issue de la vallée des Frigères, le dernier tronçon qu'un nain doit franchir avant d'atteindre Kharanos et les routes plus larges de Dun Morogh.",
			full = "La passe des Frigères est l'étroite issue de la vallée des Frigères, le dernier tronçon qu'un nain doit franchir avant d'atteindre Kharanos et les routes plus larges de Dun Morogh. Les troggs ont envahi la passe, et les voyageurs n'ont que deux options : la traverser en courant aussi vite que leurs jambes le permettent, ou se tailler un chemin sanglant à travers les envahisseurs.\n\nFendrig Redbeard mena jadis douze autres mineurs dans la passe pour enquêter sur l'infestation. Tout au fond, il fut coincé sous un éboulement. Les autres rebroussèrent chemin pour le dégager, mais leurs efforts firent s'effondrer la passe autour d'eux. Douze mineurs moururent. Seul Fendrig, tiré des décombres, survécut.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "Vallée des Frigères",
			short = "La neige recouvre épaisse la vallée des Frigères, enclavée de toutes parts, dont la seule issue est l'étroit tunnel de la passe des Frigères, au nord-est.",
			full = "La neige recouvre épaisse la vallée des Frigères, enclavée de toutes parts, dont la seule issue est l'étroit tunnel de la passe des Frigères, au nord-est. Ce passage est infesté de pillards troggs, des brutes qui rendent depuis longtemps dangereuse la traversée vers Kharanos et Ironforge pour quiconque voyage seul.\n\nAu-delà de la passe, la route grimpe vers l'est, puis vers le nord à travers Kharanos, avant de serpenter dans les montagnes jusqu'aux portes d'Ironforge elle-même.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["frostmane hold"] = {
			name = "Repaire des Frostmane",
			short = "Le repaire des Frostmane se dresse à la lisière ouest des montagnes glacées de Dun Morogh, au sud de Gnomeregan, un ensemble de bâtiments épars reliés à un réseau de grottes creusé dans le flanc de la montagne.",
			full = "Le repaire des Frostmane se dresse à la lisière ouest des montagnes glacées de Dun Morogh, au sud de Gnomeregan, un ensemble de bâtiments épars reliés à un réseau de grottes creusé dans le flanc de la montagne. C'est le camp de base des trolls des glaces Frostmane, qui tiennent le terrain avec des chasseurs de têtes et des écorcheurs gardant chaque approche.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["gates of ironforge"] = {
			name = "Portes d'Ironforge",
			short = "Les portes d'Ironforge s'élèvent là où la grande rampe de Dun Morogh monte à la rencontre de la montagne, visibles à des lieues à travers les neiges bien avant qu'un voyageur ne les atteigne.",
			full = "Les portes d'Ironforge s'élèvent là où la grande rampe de Dun Morogh monte à la rencontre de la montagne, visibles à des lieues à travers les neiges bien avant qu'un voyageur ne les atteigne. Elles marquent le seuil entre les terres naines à ciel ouvert et Ironforge proprement dite.\n\nEn les franchissant, on passe sous le regard d'une immense statue élevée au haut roi Modimus Anvilmar, placée pour veiller juste derrière l'entrée, afin que nul n'entre dans la cité sans passer d'abord sous ses yeux.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "Gnomeregan",
			short = "Gnomeregan est la capitale souterraine du royaume gnome du même nom, témoignage de fer forgé du génie, de l'ambition et de l'ingéniosité des gnomes.",
			full = "Gnomeregan est la capitale souterraine du royaume gnome du même nom, témoignage de fer forgé du génie, de l'ambition et de l'ingéniosité des gnomes.\n\nPendant la troisième guerre, une invasion de troggs causa sa chute. Les troggs avaient été tirés de leur sommeil par le bouleversement des sites des Titans, et envahirent la cité par en dessous. Dans une tentative désespérée pour tuer les envahisseurs, le Grand Bricoleur Gelbin Mekkatorque, sur les conseils de son conseiller Sicco Thermaplugg, ordonna à son peuple d'ouvrir les valves de pression de leurs gigantesques machines broyeuses et de libérer une radiation toxique dans tout Gnomeregan. Si le gaz tua certains troggs, il ne fit qu'en renforcer d'autres, et près de quatre-vingts pour cent du peuple gnome périt en quelques jours. Les survivants s'enfuirent sous la protection d'Ironforge. D'autres furent changés en gnomes lépreux, horribles, sans esprit et malfaisants, qui hantent encore les tunnels en ruine.\n\nRendu fou par la radiation lui-même, Thermaplugg se proclama roi de Gnomeregan et prit le contrôle de la cité empoisonnée, menant une armée de troggs et de gnomes lépreux à travers ses salles et ses ateliers dévastés.",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "Carrière de Gol'Bolar",
			short = "La carrière de Gol'Bolar est creusée au sud-est de Dun Morogh, un camp minier interrompu par ce qui remonta en rampant de ses profondeurs.",
			full = "La carrière de Gol'Bolar est creusée au sud-est de Dun Morogh, un camp minier interrompu par ce qui remonta en rampant de ses profondeurs. Les nains ouvrirent l'excavation en quête de ce que recelait la montagne, mais les fouilles réveillèrent des troggs, qui surgirent en masse des profondeurs de la mine et envahirent les fosses et les tunnels creusés par les mineurs.\n\nLe camp qui subsiste est une tête de pont, non une victoire : les nains tiennent la surface, tandis que la mine en dessous reste perdue aux mains des troggs.",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["grizzled den"] = {
			name = "L'antre Gris",
			short = "Un vaste réseau de grottes s'ouvre au sud-ouest de Kharanos, s'enfonçant profondément dans la glace de Dun Morogh. Les wendigos y ont établi leur tanière, des bêtes hirsutes au souffle glacé qui se regroupent contre tout intrus.",
			full = "Un vaste réseau de grottes s'ouvre au sud-ouest de Kharanos, s'enfonçant profondément dans la glace de Dun Morogh. Les wendigos y ont établi leur tanière, des bêtes hirsutes au souffle glacé qui se regroupent contre tout intrus. Leurs crinières sont prisées pour les housses de siège, mais rares sont ceux qui vont les chercher et en ressortent sans combat, car les wendigos ne se dispersent pas : ils serrent les rangs et repoussent les intrus à coups de griffes et de souffle gelé.",
			source = "https://warcraft.wiki.gg/wiki/Grizzled_Den",
		},
		["helms bed lake"] = {
			name = "Lac du Lit d'Helm",
			short = "Le lac du Lit d'Helm reste gelé la majeure partie de l'année, sa surface prise dans une glace assez épaisse pour qu'on la traverse sans danger. Un seul trou y est maintenu ouvert, percé pour que l'on puisse encore puiser de l'eau douce sous le gel.",
			full = "Le lac du Lit d'Helm reste gelé la majeure partie de l'année, sa surface prise dans une glace assez épaisse pour qu'on la traverse sans danger. Un seul trou y est maintenu ouvert, percé pour que l'on puisse encore puiser de l'eau douce sous le gel.\n\nLa sécurité s'arrête au rivage. Loups et autres créatures sauvages parcourent les berges, et des troggs égarés hantent les rochers alentour. Au sud du lac se dresse un bâtiment abandonné dont se sont emparés des nains Sombrefer, qui attaquent quiconque s'en approche trop.",
			source = "https://warcraft.wiki.gg/wiki/Helm's_Bed_Lake",
		},
		["iceflow lake"] = {
			name = "Lac glacial",
			short = "Le lac glacial gèle dur dans le froid de Dun Morogh, mais les nains de Brassetout y maintiennent un trou percé dans la glace, pour puiser de l'eau douce et pêcher sous la surface gelée.",
			full = "Le lac glacial gèle dur dans le froid de Dun Morogh, mais les nains de Brassetout y maintiennent un trou percé dans la glace, pour puiser de l'eau douce et pêcher sous la surface gelée.\n\nVers le centre du lac s'élèvent deux îles qu'il vaut mieux laisser tranquilles. Une meute de loups affamés les a revendiquées, menée par un worg nommé Timber, et leur présence laisse les îles vides de tout sauf des bêtes qui les tiennent.",
			source = "https://warcraft.wiki.gg/wiki/Iceflow_Lake",
		},
		["ironbands compound"] = {
			name = "Base d'Ironband",
			short = "Au sud du lac du Lit d'Helm, la base d'Ironband sert de point d'appui aux nains Sombrefer, qui attaquent quiconque s'en approche trop. Le lieu appartenait jadis à Sturgy Ironband, avant de tomber aux mains des Sombrefer.",
			full = "Au sud du lac du Lit d'Helm, la base d'Ironband sert de point d'appui aux nains Sombrefer, qui attaquent quiconque s'en approche trop. Le lieu appartenait jadis à Sturgy Ironband, avant de tomber aux mains des Sombrefer.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Compound",
		},
		["kharanos"] = {
			name = "Kharanos",
			short = "Kharanos se niche parmi les sommets de Dun Morogh, ses rues cernées de terres sauvages et hivernales qui ne laissent jamais ses habitants s'amollir.",
			full = "Kharanos se niche parmi les sommets de Dun Morogh, ses rues cernées de terres sauvages et hivernales qui ne laissent jamais ses habitants s'amollir. Une forge brûle en son cœur, un atelier gnome cliquette sans relâche, et la distillerie Thunderbrew sert certaines des meilleures bières qui soient, mais la ville n'a jamais pu se reposer sur son charme. À l'ouest s'étend une caverne infestée de wendigos, et au nord-ouest, les trolls Frostmane tiennent la Crête scintillante, observant la ville en contrebas.\n\nCette surveillance tourna un jour à la guerre, lorsqu'un troll Frostmane géant s'abattit sur Kharanos et faillit anéantir tous les nains qui y vivaient. Là où les défenseurs de la ville faiblirent, un nain tint bon. Lazlo Grindwidget affronta le troll et l'abattit seul, et pour cela la ville le proclama héros, un titre qui l'a suivi depuis dans des rues qui se souviennent combien elles furent près du silence.",
			source = "https://warcraft.wiki.gg/wiki/Kharanos",
		},
		["misty pine refuge"] = {
			name = "Refuge de Brumepins",
			short = "Le refuge de Brumepins s'étend, paisible, au centre de Dun Morogh, une clairière abritée parmi les pins chargés de neige.",
			full = "Le refuge de Brumepins s'étend, paisible, au centre de Dun Morogh, une clairière abritée parmi les pins chargés de neige.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",
		},
		["north gate outpost"] = {
			name = "Avant-poste de la porte Nord",
			short = "L'avant-poste de la porte Nord est établi sur le passage de la porte Nord, l'étroit chemin à travers les montagnes qui relie Dun Morogh au Loch Modan ; c'est la plus au nord-est des places fortes naines de ces hautes terres.",
			full = "L'avant-poste de la porte Nord est établi sur le passage de la porte Nord, l'étroit chemin à travers les montagnes qui relie Dun Morogh au Loch Modan ; c'est la plus au nord-est des places fortes naines de ces hautes terres.\n\nLes montagnards en garnison passent leurs journées à repousser la faune qui descend des sommets alentour. Certains, partis chasser les bêtes les plus dangereuses, ne sont jamais revenus, et l'on a fouillé les montagnes en quête de nouvelles d'eux, sans grand résultat.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Outpost",
		},
		["north gate pass"] = {
			name = "Passage de la porte Nord",
			short = "Le passage traverse les hautes montagnes, descendant de Dun Morogh vers le Loch Modan.",
			full = "Le passage traverse les hautes montagnes, descendant de Dun Morogh vers le Loch Modan. C'est la route la plus courte entre les deux, et les voyageurs en route vers les terres au-delà du Loch l'empruntent plus que toute autre.\n\nL'avant-poste de la porte Nord monte la garde ici, tenant le passage.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["shimmer ridge"] = {
			name = "Crête scintillante",
			short = "La Crête scintillante s'élève au nord de Dun Morogh, tenue par des trolls Frostmane qui y ont deux camps reliés par un pont, où ils cultivent la chatoyante et dressent des sangliers parmi les rochers.",
			full = "La Crête scintillante s'élève au nord de Dun Morogh, tenue par des trolls Frostmane qui y ont deux camps reliés par un pont, où ils cultivent la chatoyante et dressent des sangliers parmi les rochers.",
			source = "https://warcraft.wiki.gg/wiki/Shimmer_Ridge",
		},
		["south gate outpost"] = {
			name = "Avant-poste de la porte Sud",
			short = "L'avant-poste de la porte Sud se trouve là où le passage se resserre entre Dun Morogh et le Loch Modan, un goulet de pierre tenu par des montagnards nains.",
			full = "L'avant-poste de la porte Sud se trouve là où le passage se resserre entre Dun Morogh et le Loch Modan, un goulet de pierre tenu par des montagnards nains. Leur tâche est plus tranquille que celle de leurs frères de la porte Nord : ils ont repoussé la faune qui menaçait autrefois le passage, et la route qui le traverse reste ouverte et sûre pour ceux qui vont à Thelsamar ou en reviennent.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "Passage de la porte Sud",
			short = "Le passage de la porte Sud traverse les montagnes, reliant les hautes neiges de Dun Morogh aux vallées plus basses du Loch Modan. C'est le chemin le plus court pour descendre à Thelsamar, usé par les voyageurs qui vont d'une terre à l'autre.",
			full = "Le passage de la porte Sud traverse les montagnes, reliant les hautes neiges de Dun Morogh aux vallées plus basses du Loch Modan. C'est le chemin le plus court pour descendre à Thelsamar, usé par les voyageurs qui vont d'une terre à l'autre.\n\nIci se dresse l'avant-poste de la porte Sud, un poste de garde chargé de surveiller le passage.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["steelgrills depot"] = {
			name = "Dépôt de Steelgrill",
			short = "Le dépôt de Steelgrill se trouve à l'est de Kharanos, un petit camp de mineurs et d'ingénieurs qui travaillent le sol gelé de Dun Morogh.",
			full = "Le dépôt de Steelgrill se trouve à l'est de Kharanos, un petit camp de mineurs et d'ingénieurs qui travaillent le sol gelé de Dun Morogh.",
			source = "https://warcraft.wiki.gg/wiki/Steelgrill's_Depot",
		},
		["thunderbrew distillery"] = {
			name = "Distillerie Thunderbrew",
			short = "La distillerie Thunderbrew se dresse à Kharanos, son nom connu bien au-delà de la ville naine pour la qualité de sa bière. Belm l'aubergiste tient l'établissement, offrant repos et boisson à ceux qui passent.",
			full = "La distillerie Thunderbrew se dresse à Kharanos, son nom connu bien au-delà de la ville naine pour la qualité de sa bière. Belm l'aubergiste tient l'établissement, offrant repos et boisson à ceux qui passent.",
			source = "https://warcraft.wiki.gg/wiki/Thunderbrew_Distillery",
		},
		["tundrid hills"] = {
			name = "Les Collines de Tundrid",
			short = "Les collines de Tundrid s'étendent au sud de la carrière de Gol'Bolar, une étendue balayée par le vent où peu voyagent sans une lame à la main.",
			full = "Les collines de Tundrid s'étendent au sud de la carrière de Gol'Bolar, une étendue balayée par le vent où peu voyagent sans une lame à la main. Loups et autres bêtes sauvages rôdent sur les pentes, et ceux qui traversent les collines pour couper entre la vallée des Frigères et l'est de Dun Morogh le font en sachant que la route passant par Kharanos aurait été plus sûre.\n\nLes trolls Frostmane ont établi un camp dans la vallée, tenant ce terrain à portée de vue de la carrière des nains.",
			source = "https://warcraft.wiki.gg/wiki/Tundrid_Hills",
		},
	},
	-- Gorge des Vents brûlants: 11 subzones
	[1427] = {
		["blackchar cave"] = {
			name = "Caverne de Noircharbon",
			short = "La caverne de Noircharbon est scellée près du mont Blackrock, sa pierre sombre silencieuse et coupée du monde extérieur.",
			full = "La caverne de Noircharbon est scellée près du mont Blackrock, sa pierre sombre silencieuse et coupée du monde extérieur.",
			source = "https://warcraft.wiki.gg/wiki/Blackchar_Cave",
		},
		["blackrock mountain"] = {
			name = "Mont Blackrock",
			short = "Le mont Blackrock n'est pas né d'un feu ordinaire.",
			full = "Le mont Blackrock n'est pas né d'un feu ordinaire. Lorsque les armées Bronzebeard et Marteau-hardi marchèrent pour anéantir le clan Sombrefer pendant la guerre des Trois clans, le thane-sorcier Thaurissan plongea la main dans le cœur en fusion du monde et en arracha la puissance pour en faire une arme. Ce qui lui répondit fut Ragnaros. La renaissance du seigneur du Feu déchira les montagnes, noya les terres alentour sous le feu et poussa les deux rois à faire faire demi-tour à leurs armées plutôt que de l'affronter. Là où s'était dressé le royaume Sombrefer fumait désormais un volcan, avec les Steppes ardentes au sud et la gorge des Vents brûlants au nord. Ragnaros se retira au cœur de la montagne et asservit les nains Sombrefer survivants pour qu'ils creusent la cité d'Ombreforge sous leur propre foyer en ruine.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["cauldron"] = {
			name = "Le Chaudron",
			short = "Le Chaudron est une vaste excavation creusée au centre de la gorge des Vents brûlants, fortifiée par les nains Sombrefer quelque temps après qu'ils eurent invoqué Ragnaros.",
			full = "Le Chaudron est une vaste excavation creusée au centre de la gorge des Vents brûlants, fortifiée par les nains Sombrefer quelque temps après qu'ils eurent invoqué Ragnaros. Les grandes machines dont ils se servirent pour l'ouvrir en bordent encore le pourtour. En contrebas, des élémentaires de feu et de magma se meuvent dans les crevasses fissurées et rougeoyantes.\n\nLes esclaves capturés par les Sombrefer y travaillent sans fin, brisés par le labeur et la chaleur écrasante. Ils ne distinguent plus l'ami du geôlier, et accueillent quiconque entre avec la même violence aveugle que n'importe quel surveillant.",
			source = "https://warcraft.wiki.gg/wiki/Cauldron",
		},
		["dustfire valley"] = {
			name = "Vallée des Escarbilles",
			short = "La vallée des Escarbilles traverse la gorge des Vents brûlants, une terre balayée par les vents qui mène au nord jusqu'aux portes du passage de Formepierre, et au-delà à la vallée des Rois, dans le Loch Modan.",
			full = "La vallée des Escarbilles traverse la gorge des Vents brûlants, une terre balayée par les vents qui mène au nord jusqu'aux portes du passage de Formepierre, et au-delà à la vallée des Rois, dans le Loch Modan.",
			source = "https://warcraft.wiki.gg/wiki/Dustfire_Valley",
		},
		["firewatch ridge"] = {
			name = "Crête de Guet-du-feu",
			short = "La crête de Guet-du-feu est le principal camp des nains Sombrefer dans la gorge des Vents brûlants, dominant la grande excavation du Chaudron.",
			full = "La crête de Guet-du-feu est le principal camp des nains Sombrefer dans la gorge des Vents brûlants, dominant la grande excavation du Chaudron. Les nains Sombrefer tiennent les pentes avec des golems mécaniques et des araignées de feu géantes, faisant de la crête un lieu dangereux à fouler.",
			source = "https://warcraft.wiki.gg/wiki/Firewatch_Ridge",
		},
		["grimesilt dig site"] = {
			name = "Site de fouilles de Grimesilt",
			short = "Des nains d'Ironforge creusaient jadis ici, jusqu'à ce que les nains Sombrefer viennent s'emparer du site. Il reste aux mains des Sombrefer.",
			full = "Des nains d'Ironforge creusaient jadis ici, jusqu'à ce que les nains Sombrefer viennent s'emparer du site. Il reste aux mains des Sombrefer.",
			source = "https://warcraft.wiki.gg/wiki/Grimesilt_Dig_Site",
		},
		["sea of cinders"] = {
			name = "La Mer de braises",
			short = "La Mer de braises s'étend, plate et dégagée, dans le sud de la gorge des Vents brûlants, juste au nord du mont Blackrock. Rien n'y pousse.",
			full = "La Mer de braises s'étend, plate et dégagée, dans le sud de la gorge des Vents brûlants, juste au nord du mont Blackrock. Rien n'y pousse. Le sol fume encore, et la cendre s'élève sans cesse dans le vent, dérivant sur l'étendue stérile. Le feu et le vent n'ont laissé derrière eux qu'une terre désolée, et la combustion ne s'est jamais arrêtée.",
			source = "https://warcraft.wiki.gg/wiki/Sea_of_Cinders",
		},
		["slag pit"] = {
			name = "La Fosse aux scories",
			short = "La Fosse aux scories s'enfonce profondément dans l'excavation du Chaudron, dans la gorge des Vents brûlants, travaillée par des esclaves sous la cruauté des nains Sombrefer.",
			full = "La Fosse aux scories s'enfonce profondément dans l'excavation du Chaudron, dans la gorge des Vents brûlants, travaillée par des esclaves sous la cruauté des nains Sombrefer. Esclavagistes et contremaîtres pressent le labeur, et même les ouvriers soumis se retournent contre quiconque frappe leurs surveillants. Les Sombrefer répondent à toute ingérence dans leurs mines par une hostilité ouverte, et dans les ténèbres plus profondes de la fosse, des incendosaures voraces nichent parmi les galeries.",
			source = "https://warcraft.wiki.gg/wiki/Slag_Pit",
		},
		["stonewrought pass"] = {
			name = "Passage de Formepierre",
			short = "Le tunnel appelé passage de Formepierre traverse les montagnes, reliant la gorge des Vents brûlants à la vallée des Rois, dans le Loch Modan, à l'extrémité nord de la vallée des Escarbilles.",
			full = "Le tunnel appelé passage de Formepierre traverse les montagnes, reliant la gorge des Vents brûlants à la vallée des Rois, dans le Loch Modan, à l'extrémité nord de la vallée des Escarbilles. C'est l'œuvre de Franclorn Forgebusier, qui éleva aussi le barrage de Formepierre et bien d'autres ouvrages de maçonnerie naine à travers les Royaumes de l'est.\n\nLa porte du Loch Modan est tenue fermée par la montagnarde Pebblebitty, qui en barre le passage à tous sauf à ceux qui ont fait leurs preuves contre Margol l'Enragé.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Pass",
		},
		["tanner camp"] = {
			name = "Camp de Tanner",
			short = "Sarah Tanner, maîtresse du travail du cuir élémentaire, tient une tente solitaire dans la gorge des Vents brûlants. Derrière elle, un long passage serpente dans la montagne et s'achève là où attend le lézard-tonnerre Margol l'Enragé.",
			full = "Sarah Tanner, maîtresse du travail du cuir élémentaire, tient une tente solitaire dans la gorge des Vents brûlants. Derrière elle, un long passage serpente dans la montagne et s'achève là où attend le lézard-tonnerre Margol l'Enragé.",
			source = "https://warcraft.wiki.gg/wiki/Tanner_Camp",
		},
		["thorium point"] = {
			name = "Halte du Thorium",
			short = "Dans le nord calciné de la gorge des Vents brûlants se dresse la Halte du Thorium, une petite ville neutre tenue par la Confrérie du Thorium, peuplée surtout de nains Sombrefer fidèles à la Confrérie plutôt qu'aux sombres puissances qui dorment sous les montagnes.",
			full = "Dans le nord calciné de la gorge des Vents brûlants se dresse la Halte du Thorium, une petite ville neutre tenue par la Confrérie du Thorium, peuplée surtout de nains Sombrefer fidèles à la Confrérie plutôt qu'aux sombres puissances qui dorment sous les montagnes. Une forge et une enclume y sont toujours prêtes, entretenues au milieu de la cendre et de la chaleur, où l'on façonne encore le métal malgré ce qu'est devenue la gorge.",
			source = "https://warcraft.wiki.gg/wiki/Thorium_Point",
		},
	},
	-- Steppes ardentes: 11 subzones
	[1428] = {
		["blackrock mountain"] = {
			name = "Mont Blackrock",
			short = "Le mont Blackrock n'est pas né d'un feu ordinaire.",
			full = "Le mont Blackrock n'est pas né d'un feu ordinaire. Lorsque les armées Bronzebeard et Marteau-hardi marchèrent pour anéantir le clan Sombrefer pendant la guerre des Trois clans, le thane-sorcier Thaurissan plongea la main dans le cœur en fusion du monde et en arracha la puissance pour en faire une arme. Ce qui lui répondit fut Ragnaros. La renaissance du seigneur du Feu déchira les montagnes, noya les terres alentour sous le feu et poussa les deux rois à faire faire demi-tour à leurs armées plutôt que de l'affronter. Là où s'était dressé le royaume Sombrefer fumait désormais un volcan, avec les Steppes ardentes au sud et la gorge des Vents brûlants au nord. Ragnaros se retira au cœur de la montagne et asservit les nains Sombrefer survivants pour qu'ils creusent la cité d'Ombreforge sous leur propre foyer en ruine.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["blackrock pass"] = {
			name = "Défilé des Blackrock",
			short = "Le défilé des Blackrock est le seuil entre deux mondes. D'un côté s'étendent les Carmines, vertes et paisibles. De l'autre attendent les Steppes ardentes, calcinées et déformées au point d'en être méconnaissables.",
			full = "Le défilé des Blackrock est le seuil entre deux mondes. D'un côté s'étendent les Carmines, vertes et paisibles. De l'autre attendent les Steppes ardentes, calcinées et déformées au point d'en être méconnaissables. Une porte se dresse à la frontière, marquant clairement la limite.\n\nLa franchir, c'est laisser la sécurité derrière soi d'un seul pas. Ceux qui s'y aventurent sans préparation trouvent le changement brutal : les créatures au-delà sont bien plus cruelles que tout ce qui remue dans les montagnes derrière eux.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
		},
		["blackrock stronghold"] = {
			name = "Bastion des Blackrock",
			short = "Le bastion s'élève à la lisière des Steppes ardentes, tout contre l'ombre du pic Blackrock, une forteresse de pierre noire tenue par le clan Blackrock.",
			full = "Le bastion s'élève à la lisière des Steppes ardentes, tout contre l'ombre du pic Blackrock, une forteresse de pierre noire tenue par le clan Blackrock. Hors de ses murs, dans les champs d'Honneur, les guerriers du clan et leurs alliés se rassemblent et s'exercent, tenus au pas par le fouet et la voix des sergents Blackrock.\n\nLe commandement du bastion revient au général Thorg'izog, qui discipline les troupes rassemblées dans les champs et veille à ce que ses ordres soient exécutés sans discussion.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Stronghold",
		},
		["dracodar"] = {
			name = "Draco'dar",
			short = "Les collines de Draco'dar sont noircies et calcinées, livrées entièrement au vol draconique noir. Les siens s'y déplacent librement, si nombreux que nul ne devrait s'y aventurer sans prudence ni compagnie.",
			full = "Les collines de Draco'dar sont noircies et calcinées, livrées entièrement au vol draconique noir. Les siens s'y déplacent librement, si nombreux que nul ne devrait s'y aventurer sans prudence ni compagnie.",
			source = "https://warcraft.wiki.gg/wiki/Draco'dar",
		},
		["dreadmaul rock"] = {
			name = "Rocher des Cognepeurs",
			short = "Le rocher des Cognepeurs est une place forte faite de sentiers de pierre et de tertres d'ogres creusés, siège du clan Brûlentrailles.",
			full = "Le rocher des Cognepeurs est une place forte faite de sentiers de pierre et de tertres d'ogres creusés, siège du clan Brûlentrailles. Depuis ses hauteurs et ses tunnels, les Brûlentrailles lancent leurs raids vers le sud, dans les Carmines, se servant du rocher comme base avant de se replier dans ses profondeurs.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Rock",
		},
		["flame crest"] = {
			name = "Corniche des flammes",
			short = "La Corniche des flammes se dresse sur un affleurement dénudé des Steppes ardentes, accessible seulement par un pont grossier. Dans la petite grotte à l'arrière vit Kibler, qui garde un perroquet bavard.",
			full = "La Corniche des flammes se dresse sur un affleurement dénudé des Steppes ardentes, accessible seulement par un pont grossier. Dans la petite grotte à l'arrière vit Kibler, qui garde un perroquet bavard.",
			source = "https://warcraft.wiki.gg/wiki/Flame_Crest",
		},
		["morgans vigil"] = {
			name = "Veille de Morgan",
			short = "La Veille de Morgan gît en ruine dans le sud-est des Steppes ardentes, ses maisons réduites en cendres et sa tour de mage effondrée en décombres.",
			full = "La Veille de Morgan gît en ruine dans le sud-est des Steppes ardentes, ses maisons réduites en cendres et sa tour de mage effondrée en décombres. Des tentes se dressent parmi les débris, abritant ceux qui restent.\n\nDepuis ces tentes, l'Alliance surveille le Mont Blackrock, frappant le danger au plus près de sa source.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Vigil",
		},
		["pillar of ash"] = {
			name = "Le Pilier de cendres",
			short = "Une haute tour de pierre calcinée s'élève à l'extrémité orientale de Black Tooth Hovel, sa surface noircie comme si le feu lui-même l'avait gravie avant de s'arrêter.",
			full = "Une haute tour de pierre calcinée s'élève à l'extrémité orientale de Black Tooth Hovel, sa surface noircie comme si le feu lui-même l'avait gravie avant de s'arrêter. Rien ne pousse à proximité, et rien d'autre ici ne s'élève aussi haut.",
			source = "https://warcraft.wiki.gg/wiki/Pillar_of_Ash",
		},
		["ruins of thaurissan"] = {
			name = "Ruines de Thaurissan",
			short = "Jadis, ces étendues de cendres des Steppes ardentes étaient verdoyantes, et la cité qui s'y dressait portait le nom de son fondateur : la cité de Thaurissan, capitale du clan Sombrefer, exilé d'Ironforge et mené vers le sud par le thane-sorcier Thaurissan pendant la guerre des Trois clans.",
			full = "Jadis, ces étendues de cendres des Steppes ardentes étaient verdoyantes, et la cité qui s'y dressait portait le nom de son fondateur : la cité de Thaurissan, capitale du clan Sombrefer, exilé d'Ironforge et mené vers le sud par le thane-sorcier Thaurissan pendant la guerre des Trois clans.\n\nLes Sombrefer perdaient cette guerre. Leur armée venait d'être brisée contre les places fortes des deux autres clans lorsque Thaurissan, désespéré de renverser le cours des choses, rassembla sept de ses nains les plus fidèles et appela les puissances endormies sous la terre pour obtenir un serviteur qui lui rendrait la victoire. Ce qui répondit ne fut pas un serviteur, mais Ragnaros, seigneur élémentaire du Feu, et sa venue fendit les montagnes d'un volcan qui réduisit la vallée en cendres. La cité fut anéantie, et les Sombrefer survivants furent asservis au seigneur du Feu. Abandonnant les ruines, ils bâtirent un nouveau foyer sous le Mont Blackrock, et des cendres de Thaurissan s'élevèrent le Pic Blackrock et une nouvelle nation Sombrefer.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Thaurissan",
		},
		["slither rock"] = {
			name = "Roc sinueux",
			short = "Le Roc sinueux est une petite grotte cachée au-delà du Chemin de l'Aile de la terreur, à l'extrême nord-est des Steppes ardentes.",
			full = "Le Roc sinueux est une petite grotte cachée au-delà du Chemin de l'Aile de la terreur, à l'extrême nord-est des Steppes ardentes. Elle abrite le draconide noir Cyrus Therepentous, qui aide volontiers contre un ennemi commun, mais jamais sans commentaires grossiers et méprisants.",
			source = "https://warcraft.wiki.gg/wiki/Slither_Rock",
		},
		["terror wing path"] = {
			name = "Chemin de l'Aile de la terreur",
			short = "Le Chemin de l'Aile de la terreur est une vallée de l'est des Steppes ardentes, entièrement livrée au vol draconique noir. Dragonnets et dragons nichent parmi ses rochers et ses cendres.",
			full = "Le Chemin de l'Aile de la terreur est une vallée de l'est des Steppes ardentes, entièrement livrée au vol draconique noir. Dragonnets et dragons nichent parmi ses rochers et ses cendres.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Wing_Path",
		},
	},
	-- Forêt d'Elwynn: 23 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "Champ de potirons des Brackwell",
			short = "Dans le sud-est de la forêt d'Elwynn se trouve une ferme qui appartenait jadis à la famille Brackwell. Ce qu'il advint d'eux, nul ne saurait le dire.",
			full = "Dans le sud-est de la forêt d'Elwynn se trouve une ferme qui appartenait jadis à la famille Brackwell. Ce qu'il advint d'eux, nul ne saurait le dire. La Confrérie défias s'empara des lieux, et les Brackwell disparurent tout simplement de leurs champs et de leurs clôtures.\n\nD'eux, un seul souvenir demeure : une truie primée nommée Princesse, devenue énorme à force de dérober des légumes en se faufilant nuit après nuit jusqu'à la ferme voisine des Stonefield, bien avant l'arrivée des bandits.",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "Lac de Cristal",
			short = "Le lac de Cristal s'étend à l'est de Goldshire, ses eaux grouillantes de murlocs qui font de la rive un lieu peu sûr pour les imprudents. Une ferme humaine veille sur l'eau depuis la rive sud.",
			full = "Le lac de Cristal s'étend à l'est de Goldshire, ses eaux grouillantes de murlocs qui font de la rive un lieu peu sûr pour les imprudents. Une ferme humaine veille sur l'eau depuis la rive sud.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "Camp de bûcherons du Val d'est",
			short = "Les camps de scierie du Val d'est sont disséminés dans l'est d'Elwynn, leurs logements tendus entre les fosses de sciage, et le travail n'y cesse jamais vraiment.",
			full = "Les camps de scierie du Val d'est sont disséminés dans l'est d'Elwynn, leurs logements tendus entre les fosses de sciage, et le travail n'y cesse jamais vraiment. Les commandes de bois arrivent plus vite que les délais ne le permettent, et les bûcherons triment sous la pression constante d'acheteurs qui attendent le bois de Stormwind.\n\nLe maréchal Haggard, qui commandait jadis la garde de Stormwind, s'est retiré de ce commandement il y a quelques années et a choisi de passer ses dernières années dans un manoir au sein du camp plutôt que dans la cité qu'il avait défendue. Ceya Northbrooke a elle aussi grandi ici.\n\nLa forêt presse de tous côtés, et sa sauvagerie n'est pas une mince affaire. Loups et ours ont harcelé les bûcherons, dispersant les équipes et menaçant d'enterrer complètement les délais du camp. Le problème devint si grave que la garde de Stormwind dut faire appel à une aide extérieure pour éclaircir les rangs des bêtes.",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "Mine de la crête aux échos",
			short = "Les tunnels de la Mine de la crête aux échos s'étendent dans le nord-ouest de la vallée de Northshire.",
			full = "Les tunnels de la Mine de la crête aux échos s'étendent dans le nord-ouest de la vallée de Northshire. Des kobolds envahirent les puits et s'en emparèrent, au grand dam des humains qui vivaient à proximité, et le maréchal McBride ne put qu'envoyer des hommes réduire leur nombre, encore et encore.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "Mine de Fargodeep",
			short = "La Mine de Fargodeep fut jadis exploitée pour l'or de Stormwind, ses puits creusés profondément dans la terre de la forêt d'Elwynn. Elle est aujourd'hui abandonnée, ses tunnels revendiqués par un clan de kobolds.",
			full = "La Mine de Fargodeep fut jadis exploitée pour l'or de Stormwind, ses puits creusés profondément dans la terre de la forêt d'Elwynn. Elle est aujourd'hui abandonnée, ses tunnels revendiqués par un clan de kobolds. Les mines inférieures, les profondeurs situées sous les galeries principales, s'enfoncent plus loin encore dans l'obscurité.\n\nLe maréchal Dughan, qui veille à la sécurité d'Elwynn, fit renforcer les patrouilles alentour une fois la présence des kobolds confirmée. Parmi les kobolds rôde Goldtooth, qui détient un collier volé à Tatie Bernice Stonefield, un souvenir qu'elle n'a pas perdu l'espoir de revoir.",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "La Lisière",
			short = "La Lisière s'étend au sud-ouest de Stormwind, une langue de bois entre le Verger du lac Miroir, la rivière Nazfériti et un ruisseau plus petit qui coule vers la Marche de l'Ouest.",
			full = "La Lisière s'étend au sud-ouest de Stormwind, une langue de bois entre le Verger du lac Miroir, la rivière Nazfériti et un ruisseau plus petit qui coule vers la Marche de l'Ouest. Des sangliers fouillent ses sous-bois, et des filons de cuivre courent le long des berges. La forêt appartient à une bande de gnolls, et parmi eux se tient un individu qui n'est pas une simple bête de meute. Hogger parcourt les bois parmi les gnolls inférieurs, et il n'a rien d'un vulgaire cabot.",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "Goldshire",
			short = "Goldshire se trouve au cœur de la forêt d'Elwynn, ses champs en vue de Northshire, ses routes menant vers Stormwind, la Marche de l'Ouest et les Carmines.",
			full = "Goldshire se trouve au cœur de la forêt d'Elwynn, ses champs en vue de Northshire, ses routes menant vers Stormwind, la Marche de l'Ouest et les Carmines. Le bourg se développa dans les années qui suivirent la fondation de Stormwind, lorsque les habitants du royaume se répandirent de la capitale vers la campagne environnante.\n\nL'heure la plus sombre du bourg survint pendant la première guerre, lorsque le chef de guerre Blackhand lança la Horde contre le lien vital qui unissait le donjon de Stormwind à son peuple. Goldshire et Ruisselune étaient les deux dernières villes entre les orcs et la capitale, et lorsqu'elles tombèrent, la route du donjon fut ouverte. Goldshire ne se releva qu'après la deuxième guerre, lorsque l'Alliance de Lordaeron la rebâtit, le commandant suprême Turalyon veillant en personne au retour des citoyens dispersés de Stormwind.\n\nCe qui reste aujourd'hui est plus paisible : l'auberge de la Fierté du lion se dresse au centre du bourg, son âtre et sa bière attirant les voyageurs de toutes les routes qui s'y croisent. Le maréchal Dughan, de la garde de Stormwind, veille toujours sur le bourg, conscient de ce qu'il en a coûté autrefois de le perdre.",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["heroes vigil"] = {
			name = "Veillée des héros",
			short = "Un cercle de pierres dressées entoure le petit îlot du lac du Cairn, centré sur la Pierre du souvenir.",
			full = "Un cercle de pierres dressées entoure le petit îlot du lac du Cairn, centré sur la Pierre du souvenir. Il honore les morts de la première guerre, lorsque les orcs saccagèrent Goldshire et les terres alentour et les livrèrent aux flammes.\n\nDes sorciers renégats tiennent désormais l'île. Parmi les pierres gît le corps de Henze Faulk, laissé là où il est tombé.",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
		},
		["jasperlode mine"] = {
			name = "Mine de Jasperlode",
			short = "La Mine de Jasperlode alimentait jadis les forges de Stormwind, l'un des sites de la forêt d'Elwynn qui fournissaient le minerai brut dont la cité avait besoin pour ses guerres.",
			full = "La Mine de Jasperlode alimentait jadis les forges de Stormwind, l'un des sites de la forêt d'Elwynn qui fournissaient le minerai brut dont la cité avait besoin pour ses guerres. Ce travail est désormais terminé. Des kobolds ont envahi les tunnels, et l'armée de Stormwind, dispersée par des menaces plus graves, n'a pas d'hommes à consacrer à les en déloger.\n\nLes kobolds ne sont pas le seul danger en dessous. Dans les recoins les plus profonds de la mine, une colonie d'araignées des mines s'est installée, et pour elles les kobolds ne sont pas des envahisseurs à craindre mais des proies à chasser. Leur reine, Mother Fang, couve dans l'obscurité et ne tolère aucune intrusion dans son nid.",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
		},
		["jerods landing"] = {
			name = "Le Débarcadère de Jerod",
			short = "Le Débarcadère de Jerod est un ponton sur la rive de la forêt d'Elwynn, au bord de la rivière Nazfériti.",
			full = "Le Débarcadère de Jerod est un ponton sur la rive de la forêt d'Elwynn, au bord de la rivière Nazfériti. La Confrérie défias le tient, et le chef des docks et ses hommes s'en servent pour faire passer en contrebande des marchandises volées depuis les Carmines jusqu'à la tour de Klaven, dans la Marche de l'Ouest.",
			source = "https://warcraft.wiki.gg/wiki/Jerod's_Landing",
		},
		["maclure vineyards"] = {
			name = "Les Vignes des Maclure",
			short = "Les Vignes des Maclure s'étendent dans le sud de la forêt d'Elwynn, entretenues par la famille Maclure sur de longs rangs de vignes et de terre.",
			full = "Les Vignes des Maclure s'étendent dans le sud de la forêt d'Elwynn, entretenues par la famille Maclure sur de longs rangs de vignes et de terre. Les Maclure entretiennent une âpre rivalité avec la famille Stonefield voisine, échangeant l'inimitié aussi librement qu'ils n'échangent rien d'autre. Pourtant, un enfant des Maclure et un enfant des Stonefield sont tombés amoureux l'un de l'autre, au mépris de tout ce que défendent leurs familles, et certains espèrent qu'un tel amour pourrait réparer ce que des générations de rancœur n'ont pu guérir.",
			source = "https://warcraft.wiki.gg/wiki/Maclure_Vineyards",
		},
		["mirror lake"] = {
			name = "Lac Miroir",
			short = "Le lac Miroir s'étend, petit et paisible, dans l'ouest de la forêt d'Elwynn, sa cascade étincelant à côté d'un verger voisin, le genre d'endroit qui semble fait pour la baignade ou la pêche.",
			full = "Le lac Miroir s'étend, petit et paisible, dans l'ouest de la forêt d'Elwynn, sa cascade étincelant à côté d'un verger voisin, le genre d'endroit qui semble fait pour la baignade ou la pêche. Ce n'est plus si simple. Des bandits défias ont investi les bois alentour, et ce qui devrait être un lieu de repos est devenu un lieu à traverser avec prudence.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake",
		},
		["mirror lake orchard"] = {
			name = "Verger du lac Miroir",
			short = "Le Verger du lac Miroir s'étend sur les rives sud du lac Miroir, ses rangées d'arbres et une chaumière solitaire se dressant parmi les champs de l'ouest de la forêt d'Elwynn.",
			full = "Le Verger du lac Miroir s'étend sur les rives sud du lac Miroir, ses rangées d'arbres et une chaumière solitaire se dressant parmi les champs de l'ouest de la forêt d'Elwynn. Des bandits défias tinrent jadis le verger et la chaumière voisine, s'appropriant les lieux, et nul ne saurait dire avec certitude s'ils en chassèrent les véritables propriétaires.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake_Orchard",
		},
		["northshire abbey"] = {
			name = "Abbaye de Northshire",
			short = "L'abbaye de Northshire repose dans la vallée qui porte son nom, sur les contreforts de la forêt d'Elwynn, son grand hall, sa salle d'armes et son aile de bibliothèque se dressant là où les clercs de l'Église de la Lumière sacrée s'établirent pour la première fois après être venus du Lordaeron vers le sud.",
			full = "L'abbaye de Northshire repose dans la vallée qui porte son nom, sur les contreforts de la forêt d'Elwynn, son grand hall, sa salle d'armes et son aile de bibliothèque se dressant là où les clercs de l'Église de la Lumière sacrée s'établirent pour la première fois après être venus du Lordaeron vers le sud. C'est d'ici que l'ordre sacré des clercs de Northshire apporta à Stormwind son réconfort et sa sagesse, et c'est entre ces murs que Medivh, le Gardien de Tirisfal, fut soigné pendant les longues années de son coma.\n\nL'abbaye ne sortit pas indemne de la première guerre. Son abbé prêta les clercs de Northshire à la défense de Stormwind, et peu après que la demi-orque Garona y eut été amenée captive, les orcs envahirent Northshire et la réduisirent en ruine. Des réfugiés s'enfuirent vers Lordaeron, non sans avoir arraché aux décombres des ouvrages sacrés, des textes qui enseigneraient plus tard aux mages de Dalaran l'art de l'invisibilité.\n\nLes terres en ruine ne restèrent pas vides. Le clan du Marteau du crépuscule de Cho'gall fit du site son quartier général pendant la deuxième guerre, jusqu'à ce que l'Alliance reprenne la forêt d'Elwynn et que l'archevêque Alonsus Faol rebâtisse l'abbaye pierre par pierre, fondant en ses murs la Confrérie de Northshire.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "Vallée de Northshire",
			short = "La vallée de Northshire est fermée de tous côtés sauf un, ses montagnes infranchissables, son unique passage vers le sud barré par d'épais murs de pierre et une porte gardée.",
			full = "La vallée de Northshire est fermée de tous côtés sauf un, ses montagnes infranchissables, son unique passage vers le sud barré par d'épais murs de pierre et une porte gardée. Une rivière traverse son calme, serpentant vers le lac de Cristal, passant devant l'abbaye et les rangs de vignes qui donnent au lieu son air de paix.\n\nCette paix ne fut pas toujours si assurée. Pendant la deuxième guerre, l'abbaye de Northshire servit de quartier général au clan du Marteau du crépuscule de Cho'gall, dévoué à la cause de Gul'dan, et ses murs abritèrent des conseils de guerre orcs plutôt que des novices et des fermiers.\n\nDésormais, le maréchal McBride commande la garnison de l'abbaye et répond de la sécurité de tout Northshire, bien que la vallée ne soit pas entièrement paisible, même sous sa garde. Des loups affluent du Bois de la Pénombre en un nombre que nul ne sait expliquer, et des kobolds creusent leurs galeries dans la Mine de la crête aux échos.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire vineyards"] = {
			name = "Vignes de Northshire",
			short = "Les vignes s'étendent à l'est de l'abbaye, jadis entretenues pour leur récolte avant que la Confrérie défias ne s'empare de la terre.",
			full = "Les vignes s'étendent à l'est de l'abbaye, jadis entretenues pour leur récolte avant que la Confrérie défias ne s'empare de la terre. Garrick Padfoot menait les agents qui la tenaient, se servant des rangs comme d'un point d'appui pour les sbires de la Confrérie, qui emportèrent avec eux les biens volés de Milly Osworth.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
		},
		["ridgepoint tower"] = {
			name = "Tour de la Crête",
			short = "La Tour de la Crête surveille la frontière de la forêt d'Elwynn, l'une des tours d'observation de la garde de Stormwind.",
			full = "La Tour de la Crête surveille la frontière de la forêt d'Elwynn, l'une des tours d'observation de la garde de Stormwind. Ses sentinelles tournent les yeux vers les Carmines, où se rassemblent gnolls et orcs, vers le Bois de la Pénombre, où les morts ne restent pas enterrés, et vers les camps défias voisins. La garnison est bien défendue contre les trois.",
			source = "https://warcraft.wiki.gg/wiki/Ridgepoint_Tower",
		},
		["stone cairn lake"] = {
			name = "Lac du Cairn",
			short = "Le lac du Cairn tire son nom de la Veillée des héros, le cairn élevé sur l'île en son centre à la mémoire des morts de la première guerre contre les orcs, lorsque tant d'hommes tombèrent qu'aucune tombe ne pouvait à elle seule contenir leur souvenir.",
			full = "Le lac du Cairn tire son nom de la Veillée des héros, le cairn élevé sur l'île en son centre à la mémoire des morts de la première guerre contre les orcs, lorsque tant d'hommes tombèrent qu'aucune tombe ne pouvait à elle seule contenir leur souvenir. C'était jadis un lieu de pèlerinage paisible.\n\nCette paix a disparu. Des sorciers renégats se sont emparés de l'île, et le cairn destiné au deuil se dresse désormais derrière eux. Le long des rives sud, une tribu de murlocs a élevé ses propres habitations grossières, indifférente au monument de l'autre côté de l'eau.",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
		},
		["stonefield farm"] = {
			name = "La ferme des Stonefield",
			short = "La ferme des Stonefield se trouve dans le sud de la forêt d'Elwynn, exploitée par la famille Stonefield, qui entretient une âpre rivalité avec les Maclure voisins.",
			full = "La ferme des Stonefield se trouve dans le sud de la forêt d'Elwynn, exploitée par la famille Stonefield, qui entretient une âpre rivalité avec les Maclure voisins. Pourtant, un enfant de chaque maison est tombé amoureux, défiant la vieille rancune entre leurs familles. Certains espèrent que cette idylle pourrait réussir là où des années de querelles ont échoué, et réparer ce que la discorde a brisé.",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
		},
		["thunder falls"] = {
			name = "Chutes du Tonnerre",
			short = "Le sentier qui monte depuis la cascade du lac Miroir grimpe, raide et étroit, dans les montagnes avant de déboucher sur les Chutes du Tonnerre, un ravin qui se distingue des autres de la forêt d'Elwynn par ses chutes d'eau à ses deux extrémités.",
			full = "Le sentier qui monte depuis la cascade du lac Miroir grimpe, raide et étroit, dans les montagnes avant de déboucher sur les Chutes du Tonnerre, un ravin qui se distingue des autres de la forêt d'Elwynn par ses chutes d'eau à ses deux extrémités. Une troisième cascade dévale des falaises du nord, alimentant le ravin par le haut. Au pied de la hauteur se dresse une petite chaumière rustique, dont l'enclume et le feu restent allumés, avec un petit ponton et une barque posés sur la rivière à côté de la maison. Des bandits rôdent près de la chaumière. La rivière poursuit sa course par une seconde cascade près de la lisière de la Marche de l'Ouest. On dit que les perches violettes qui nagent dans ces eaux ne se trouvent nulle part aussi facilement qu'ici.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "Tour d'Azora",
			short = "La Tour d'Azora s'élève au milieu des champs du centre de la forêt d'Elwynn, demeure d'une compagnie de serviteurs gnomes qui obéissent à l'archimage Theocritus.",
			full = "La Tour d'Azora s'élève au milieu des champs du centre de la forêt d'Elwynn, demeure d'une compagnie de serviteurs gnomes qui obéissent à l'archimage Theocritus.\n\nAu loin, dans les Carmines, se dresse sa rivale, la Tour d'Ilgalar, gouvernée par le sorcier Morganth. Les deux tours ne se sont jamais fait ouvertement la guerre, mais elles s'observent sans cesse par des moyens magiques, chacune attendant de prendre l'autre en défaut.\n\nLa magie propre de la tour déborde dans les champs alentour, et tout ce qui s'attarde trop près risque d'en être touché et changé en quelque chose de plus étrange qu'auparavant. Les serviteurs protègent leur tour contre ce petit tracas constant, un œil toujours tourné vers les Carmines.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "Garnison du ruisseau de l'ouest",
			short = "La Garnison du ruisseau de l'ouest se dresse à la lisière ouest de la forêt d'Elwynn, là où les arbres cèdent la place à la campagne plus pauvre de la Marche de l'Ouest, et elle a toujours été une affectation solitaire pour la garde de Stormwind.",
			full = "La Garnison du ruisseau de l'ouest se dresse à la lisière ouest de la forêt d'Elwynn, là où les arbres cèdent la place à la campagne plus pauvre de la Marche de l'Ouest, et elle a toujours été une affectation solitaire pour la garde de Stormwind.\n\nSes années les plus dures vinrent tandis que la corruption de Dame Katrana Prestor pesait lourdement sur le royaume et que l'essentiel de l'armée de Stormwind était engagé ailleurs. Faute de soldats disponibles, gnolls et voleurs venus de la Marche de l'Ouest pressaient chaque saison davantage les bois, et la garnison parvenait à peine à garder les routes sûres.\n\nParmi les gnolls, le chef Riverpaw Hogger devint un nom redouté. Il déjoua toutes les tentatives faites pour le capturer, et des avis de recherche à son nom sont encore affichés, non satisfaits, à la porte de la garnison.",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
	-- Défilé de Deuillevent: 9 subzones
	[1430] = {
		["aridens camp"] = {
			name = "Camp d'Ariden",
			short = "Le camp gît abandonné au nord de la route qui traverse le défilé de Deuillevent, un éparpillement de foyers froids et de couchages vides sous les arbres toujours sombres.",
			full = "Le camp gît abandonné au nord de la route qui traverse le défilé de Deuillevent, un éparpillement de foyers froids et de couchages vides sous les arbres toujours sombres. Ariden menait jadis les Cavaliers noirs depuis cet endroit, où il établit son camp avant d'être maudit, et d'où il tenta d'écouler de faux artefacts qui, prétendait-il, avaient appartenu à Medivh. Il ne reste aujourd'hui que le campement lui-même.",
			source = "https://warcraft.wiki.gg/wiki/Ariden's_Camp",
		},
		["deadmans crossing"] = {
			name = "Croisée de l'homme mort",
			short = "Un arbre de pendu se dresse à la croisée, deux cadavres se balançant encore à ses branches. À côté, un poteau indicateur porte deux avertissements : « Faites demi-tour ! » et « Vous qui entrez ici, abandonnez toute espérance. »",
			full = "Un arbre de pendu se dresse à la croisée, deux cadavres se balançant encore à ses branches. À côté, un poteau indicateur porte deux avertissements : « Faites demi-tour ! » et « Vous qui entrez ici, abandonnez toute espérance. »\n\nIci, la route de l'ouest mène vers le Bois de la Pénombre, la route de l'est vers le Marais des Chagrins, et la route du sud dans le défilé de Deuillevent, où se dresse Karazhan. Le gibet et l'avertissement furent dressés pour quiconque serait tenté de quitter la croisée pour s'engager dans le défilé au-delà.",
			source = "https://warcraft.wiki.gg/wiki/Deadman's_Crossing",
		},
		["deadwind ravine"] = {
			name = "Ravin de Deuillevent",
			short = "Le ravin taille une brèche escarpée à travers les montagnes, sa route occidentale longeant le niveau supérieur en direction de Karazhan, dont la silhouette attend, menaçante, à l'autre bout.",
			full = "Le ravin taille une brèche escarpée à travers les montagnes, sa route occidentale longeant le niveau supérieur en direction de Karazhan, dont la silhouette attend, menaçante, à l'autre bout. Au bout du ravin se trouve le pont sud, le dernier passage avant la tour elle-même.",
			source = "https://warcraft.wiki.gg/wiki/Deadwind_Ravine",
		},
		["groshgok compound"] = {
			name = "Base des Grosh'gok",
			short = "Les ogres de Deuillevent revendiquent la Base des Grosh'gok comme leur domaine, un tertre de terre et de pierre élevé dans l'Étau.",
			full = "Les ogres de Deuillevent revendiquent la Base des Grosh'gok comme leur domaine, un tertre de terre et de pierre élevé dans l'Étau. Des grottes qui criblent cette portion de terre, celle-ci est la plus au sud, et aucune autre ne l'égale en taille.",
			source = "https://warcraft.wiki.gg/wiki/Grosh'gok_Compound",
		},
		["karazhan"] = {
			name = "Karazhan",
			short = "Karazhan se dresse, abandonnée, dans le sud du défilé de Deuillevent, bâtie sur un nexus de lignes telluriques. La tour est surtout connue pour son dernier occupant, Medivh, le dernier Gardien de Tirisfal.",
			full = "Karazhan se dresse, abandonnée, dans le sud du défilé de Deuillevent, bâtie sur un nexus de lignes telluriques. La tour est surtout connue pour son dernier occupant, Medivh, le dernier Gardien de Tirisfal. Après que Medivh eut été tué par Khadgar, Anduin Lothar et Garona, la tour se ferma au monde. Mais depuis peu, Karazhan s'agite de nouveau : une présence maléfique s'en est emparée, ses salles grouillent d'esprits et de démons, et l'ombre de Medivh s'y attarde encore, son pouvoir si grand que sa magie résonne toujours dans la tour.\n\nIl est impossible de poser les yeux sur Karazhan sans songer à la sombre saga de son maître. Comme il sied à son titre, le dernier Gardien de Tirisfal avait amassé une vaste collection d'écrits et d'artefacts, surpassant même celle du Kirin Tor. La tour est immense et dangereuse, ses salles hantées de fantômes.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan",
		},
		["masters cellar"] = {
			name = "La cave du maître",
			short = "Sous le village en ruine au sud de Karazhan, où vivaient jadis les serviteurs de la tour, le sol s'ouvre sur des caves qui n'appartiennent plus aux vivants.",
			full = "Sous le village en ruine au sud de Karazhan, où vivaient jadis les serviteurs de la tour, le sol s'ouvre sur des caves qui n'appartiennent plus aux vivants. Deux entrées y mènent. L'une s'ouvre sur une vaste cave à vin, ses casiers et ses tonneaux depuis longtemps abandonnés aux morts. L'autre plonge dans une seconde cave dont le sol s'est entièrement effondré, s'écroulant dans un réseau de grottes qui s'étend loin sous terre.\n\nLes deux grouillent d'âmes sans repos : des intendants non-morts qui semblent encore entretenir une maison sans maître, des âmes damnées, des ombres qui ne trouvent pas la paix, des spectres dont les gémissements montent à travers la pierre brisée. Quel que fût le service qui les liait à Karazhan de leur vivant, il s'est mué en quelque chose qui ne les laisse pas partir dans la mort.\n\nSeule la cave à vin renferme quelque chose qui se distingue parmi les morts. Le réseau de grottes inférieur, silencieux et noyé d'obscurité, ne recèle rien d'autre que d'autres morts sans repos, rien de nommé, rien que quiconque ait jugé digne de mémoire.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Cellar",
		},
		["morgans plot"] = {
			name = "Le lopin de Morgan",
			short = "Une petite église délabrée se dresse derrière Karazhan, son cimetière et sa crypte plongés dans la pénombre du défilé de Deuillevent.",
			full = "Une petite église délabrée se dresse derrière Karazhan, son cimetière et sa crypte plongés dans la pénombre du défilé de Deuillevent. La chapelle abrite depuis longtemps des choses qui ne reposent pas en paix, et quelque chose d'autre patrouille encore sur la colline juste en contrebas.\n\nQu'un lieu destiné aux morts échoue si souvent à les garder en dit long sur ce qui se trouve derrière lui.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Plot",
		},
		["sleeping gorge"] = {
			name = "Gorge endormie",
			short = "La Gorge endormie entaille l'est du défilé de Deuillevent, un petit gouffre que les voyageurs empruntant l'accès sud de Karazhan doivent traverser avant que le chemin ne tourne vers l'est, dans l'Étau.",
			full = "La Gorge endormie entaille l'est du défilé de Deuillevent, un petit gouffre que les voyageurs empruntant l'accès sud de Karazhan doivent traverser avant que le chemin ne tourne vers l'est, dans l'Étau.",
			source = "https://warcraft.wiki.gg/wiki/Sleeping_Gorge",
		},
		["vice"] = {
			name = "L'Etau",
			short = "L'Étau s'étend le long de la portion sud de la route de Karazhan, là où les ogres de Deuillevent ont élevé leurs tertres et leurs camps parmi les escarpements.",
			full = "L'Étau s'étend le long de la portion sud de la route de Karazhan, là où les ogres de Deuillevent ont élevé leurs tertres et leurs camps parmi les escarpements. C'est une étendue désolée, où ne vivent guère que des esprits sans repos et les vautours qui tournoient au-dessus d'eux. Pourquoi les ogres ont choisi de s'enraciner ici, en un lieu si vide et si peu favorable, nul de ceux qui l'ont contemplé ne le sait.",
			source = "https://warcraft.wiki.gg/wiki/Vice",
		},
	},
	-- Bois de la Pénombre: 17 subzones
	[1431] = {
		["addles stead"] = {
			name = "Ferme des Addle",
			short = "La Ferme des Addle gît abandonnée parmi les champs du sud-ouest du Bois de la Pénombre, l'une des nombreuses fermes laissées à pourrir lorsque les ténèbres s'étendirent sur la terre.",
			full = "La Ferme des Addle gît abandonnée parmi les champs du sud-ouest du Bois de la Pénombre, l'une des nombreuses fermes laissées à pourrir lorsque les ténèbres s'étendirent sur la terre. La grange est vide, la ferme silencieuse, et seuls s'y attardent désormais des esprits désespérés, que l'on dit être les ombres de membres défunts de la Confrérie défias qui revendiquèrent jadis les lieux.\n\nLes Défias prirent entièrement la Ferme des Addle, rampant dans le champ envahi d'herbes, se cachant dans la grange, rôdant dans les pièces de la ferme.",
			source = "https://warcraft.wiki.gg/wiki/Addle's_Stead",
		},
		["beggars haunt"] = {
			name = "Repaire des mendiants",
			short = "La tour appelée le Repaire des mendiants se dresse, abandonnée, au-dessus de la route qui mène au défilé de Deuillevent, au nord-est du Manoir Mistmantle.",
			full = "La tour appelée le Repaire des mendiants se dresse, abandonnée, au-dessus de la route qui mène au défilé de Deuillevent, au nord-est du Manoir Mistmantle. Élevée comme poste d'observation pour la garde de Stormwind, elle sert désormais les Réprouvés, dont le traqueur noir Zraedus et l'apothicaire Faustin mènent des expériences entre ses murs.\n\nUn sentier descend jusqu'à un petit bassin alimenté par une cascade, où une tombe anonyme repose sous deux grandes statues sculptées comme celles de la Porte des ténèbres. Près de la tour se trouve un autre petit cimetière, qui abrite la tombe d'un soldat inconnu.",
			source = "https://warcraft.wiki.gg/wiki/Beggar's_Haunt",
		},
		["brightwood grove"] = {
			name = "Bosquet de Clairbois",
			short = "Le Bosquet de Clairbois se trouve juste à l'ouest de Darkshire, ses quelques bâtiments depuis longtemps tombés en ruine.",
			full = "Le Bosquet de Clairbois se trouve juste à l'ouest de Darkshire, ses quelques bâtiments depuis longtemps tombés en ruine. Ce qui reste du lieu appartient désormais aux worgens Plaie-de-nuit, qui rôdent en meutes dans les champs obscurs, dressant des camps grossiers parmi les décombres et se jetant sur quiconque s'approche de trop près.",
			source = "https://warcraft.wiki.gg/wiki/Brightwood_Grove",
		},
		["darkened bank"] = {
			name = "La Rive sombre",
			short = "La Rive sombre longe le rivage nord du Bois de la Pénombre, de la lisière ouest de la région jusqu'au pont qui la relie aux Carmines, à l'est.",
			full = "La Rive sombre longe le rivage nord du Bois de la Pénombre, de la lisière ouest de la région jusqu'au pont qui la relie aux Carmines, à l'est. À son extrémité ouest se trouve un petit camp où les réfugiés Sven Yorgen et Lars ont trouvé abri, repoussés jusqu'au bord de l'eau par ce qui a rendu le reste du Bois de la Pénombre trop dangereux à tenir.",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "Darkshire",
			short = "Darkshire n'a pas toujours porté ce nom. Il s'éleva il y a longtemps sous le nom de Grand Hamlet, un petit bourg forestier qui grandit à mesure que les habitants de Stormwind se répandaient sur les terres voisines.",
			full = "Darkshire n'a pas toujours porté ce nom. Il s'éleva il y a longtemps sous le nom de Grand Hamlet, un petit bourg forestier qui grandit à mesure que les habitants de Stormwind se répandaient sur les terres voisines. Mais la terre elle-même ne se remit jamais de ce qui s'était passé à Karazhan. Lorsque le Gardien Medivh fut tué dans sa tour, l'énergie gangrenée libérée par sa mort s'insinua dans la forêt environnante, la changeant en ce lieu épineux et privé de lumière qu'elle est restée. Clairbois devint le Bois de la Pénombre, et Grand Hamlet prit le nom plus juste de Darkshire.\n\nLa milice du bourg, les Veilleurs, existe parce que Stormwind l'a abandonné. Lorsque les manigances de Dame Katrana Prestor à Stormwind vidèrent la forêt des garnisons du royaume, les habitants prirent les armes plutôt que d'attendre des soldats qui ne viendraient jamais. Formée et entraînée entièrement par les gens de la forêt, elle défend depuis les routes contre les loups, les cadavres ambulants et pire encore, sans autre armée à appeler qu'elle-même.",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["dawning wood catacombs"] = {
			name = "Catacombes du Bois-de-l'Aube",
			short = "Sous le Cimetière de Colline-aux-Corbeaux, la terre s'ouvre sur les Catacombes du Bois-de-l'Aube, un dédale de tunnels qui serpentent assez profondément pour que peu de ceux qui y entrent seuls en ressortent.",
			full = "Sous le Cimetière de Colline-aux-Corbeaux, la terre s'ouvre sur les Catacombes du Bois-de-l'Aube, un dédale de tunnels qui serpentent assez profondément pour que peu de ceux qui y entrent seuls en ressortent. Deux chemins y descendent. Le passage oriental s'ouvre sur un repaire de goules, malades et féroces. Le passage occidental s'ouvre sur une salle de squelettes, montant la garde sur les tombeaux des morts qu'ils furent jadis.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "La masure lugubre",
			short = "Colline à la lisière nord du Cimetière de Colline-aux-Corbeaux, la masure lugubre est enveloppée d'une obscurité plus dense que l'ombre des arbres alentour.",
			full = "Colline à la lisière nord du Cimetière de Colline-aux-Corbeaux, la masure lugubre est enveloppée d'une obscurité plus dense que l'ombre des arbres alentour. Ici se dresse la demeure de Morbent Fel, un nécromancien qui plie les morts-vivants de la forêt à sa volonté par une magie arcanique maléfique. Seule une arme d'une grande puissance pourrait espérer l'arrêter.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "La Rive silencieuse",
			short = "La Rive silencieuse longe la rivière occidentale du Bois de la Pénombre, depuis l'endroit où se rejoignent la Marche de l'Ouest, la forêt d'Elwynn et le Bois de la Pénombre, vers le sud en direction de la vallée de Strangleronce.",
			full = "La Rive silencieuse longe la rivière occidentale du Bois de la Pénombre, depuis l'endroit où se rejoignent la Marche de l'Ouest, la forêt d'Elwynn et le Bois de la Pénombre, vers le sud en direction de la vallée de Strangleronce. Un pont couvert franchit ici la rivière, reliant le Bois de la Pénombre à la Marche de l'Ouest.\n\nÀ l'angle nord de la rive, les frères Lars et Sven Yorgen tiennent un camp.\n\nLoups et araignées parcourent la rive parmi les arbres.",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "Manoir Mistmantle",
			short = "Le Manoir Mistmantle se dresse dans le nord-est du Bois de la Pénombre, son domaine pourri, ses jardins en ruine.",
			full = "Le Manoir Mistmantle se dresse dans le nord-est du Bois de la Pénombre, son domaine pourri, ses jardins en ruine. Ce fut jadis la demeure de Stalvan Mistmantle, un maître d'école et précepteur devenu agent des morts-vivants, qui a laissé des goules errer sur la propriété à sa place. Au milieu de la corruption, une seule chose pousse encore : une fleur unique appelée la Larme de Tilloa, seul signe de vie dans un jardin par ailleurs livré à la pourriture.",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "Colline-aux-Corbeaux",
			short = "Les maisons de Colline-aux-Corbeaux sont vides, dans l'ouest du Bois de la Pénombre, livrées à la pourriture et à l'obscurité. Quelques âmes s'y accrochèrent malgré tout : La Tremblotte, et Bliztik, un gobelin qui se cachait à un étage supérieur.",
			full = "Les maisons de Colline-aux-Corbeaux sont vides, dans l'ouest du Bois de la Pénombre, livrées à la pourriture et à l'obscurité. Quelques âmes s'y accrochèrent malgré tout : La Tremblotte, et Bliztik, un gobelin qui se cachait à un étage supérieur.\n\nLe bourg est hanté par les Invisibles, invisibles pas seulement de nom, qui se déplacent dans ses pièces vides.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "Cimetière de Colline-aux-Corbeaux",
			short = "Le Cimetière de Colline-aux-Corbeaux s'étend au nord du bourg dont il tire son nom, ayant largement dépassé ses anciennes limites depuis que la corruption s'est emparée du Bois de la Pénombre.",
			full = "Le Cimetière de Colline-aux-Corbeaux s'étend au nord du bourg dont il tire son nom, ayant largement dépassé ses anciennes limites depuis que la corruption s'est emparée du Bois de la Pénombre. Des morts-vivants errent désormais parmi les pierres, et des araignées énormes et des bandes de pilleurs de tombes s'affairent sur les tombes sans être dérangés, chassant quiconque tombe sur leurs affaires.\n\nDans l'angle nord-ouest du cimetière se dresse la masure lugubre, demeure du nécromancien Morbent Fel, dont les sombres travaux agitent les morts du cimetière.\n\nCe nom, Ladimore, marque le plus ancien chagrin du cimetière. Morgan Ladimore revint de la troisième guerre pour trouver sa femme et ses enfants déjà enterrés ici. Le chagrin le brisa ; il assassina trois des gardiens du cimetière sur leurs tombes. Désormais, le mort-vivant Mor'Ladim patrouille dans le cimetière, et la mort vient, rapide et invisible, pour quiconque il surprend sans méfiance parmi les pierres tombales.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "Destin de Roland",
			short = "Le Destin de Roland est une mine du sud-est du Bois de la Pénombre, à l'est du Verger pourri.",
			full = "Le Destin de Roland est une mine du sud-est du Bois de la Pénombre, à l'est du Verger pourri. La prêtresse elfe de la nuit Velinde Starsong porta la Faux d'Elune dans ces collines avant de disparaître, et la relique fut perdue dans la mine. L'homme surnommé La Tremblotte l'y trouva, et sa découverte attira davantage de worgens sur le Bois de la Pénombre et Darkshire.\n\nLa mine appartient désormais à Gutspill et Nefaru, de la meute Plaie-de-nuit, dont les worgens rôdent jusqu'au Verger pourri.",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "Le verger pourrissant",
			short = "Le verger s'étend dans le sud du Bois de la Pénombre, ses arbres noircis par la pourriture, ses bâtiments tombés en ruine entre la ferme des Yorgen et le Cimetière des jardins paisibles.",
			full = "Le verger s'étend dans le sud du Bois de la Pénombre, ses arbres noircis par la pourriture, ses bâtiments tombés en ruine entre la ferme des Yorgen et le Cimetière des jardins paisibles.\n\nLes worgens de la meute Plaie-de-nuit en ont fait leur domaine. Des tisseurs d'ombre pratiquent leur magie parmi les bâtiments en ruine, tandis que des traqueurs attendent, invisibles, dans l'obscurité entre les arbres.\n\nSe tenir ici aujourd'hui, c'est se tenir en un lieu qui a cessé d'être une ferme pour devenir un terrain de chasse.",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["tranquil gardens cemetery"] = {
			name = "Cimetière des jardins paisibles",
			short = "Le Cimetière des jardins paisibles s'étend au sud-est de Darkshire, et son nom est aujourd'hui une plaisanterie amère.",
			full = "Le Cimetière des jardins paisibles s'étend au sud-est de Darkshire, et son nom est aujourd'hui une plaisanterie amère. Les morts n'y reposent pas, bien qu'ils soient plus faibles que les morts-vivants rencontrés ailleurs dans le Bois de la Pénombre, errant parmi les pierres tombales et l'église en ruine au cœur du cimetière. La goule démente hante ce terrain, tantôt dans l'église délabrée, tantôt parmi les tombes. Juste au nord se trouve la maison de Mary l'aveugle.",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "Bosquet du crépuscule",
			short = "Un grand arbre sans nom se dresse au cœur du Bosquet du Crépuscule, au plus profond du Bois de la Pénombre, à côté d'un puits de lune et d'un ancien belvédère elfe de la nuit.",
			full = "Un grand arbre sans nom se dresse au cœur du Bosquet du Crépuscule, au plus profond du Bois de la Pénombre, à côté d'un puits de lune et d'un ancien belvédère elfe de la nuit. Sous ses ramures se trouve l'un des quatre seuls portails menant au Rêve d'émeraude, frère de ceux cachés en Féralas, dans les Hinterlands et en Orneval.\n\nLe portail du bosquet ne resta pas sans garde. Quatre grands dragons, jadis fiers lieutenants d'Ysera, l'Aspect des rêves, y veillaient, protecteurs choisis du Rêve. Mais le Cauchemar d'émeraude les corrompit à leur tour, changeant les gardiens en destructeurs qui ne voulaient que la mort, et il revint à l'Alliance comme à la Horde de prendre les armes contre ces dragons mêmes qui avaient jadis monté la garde en ce lieu.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "Tertre des ogres Vul'Gol",
			short = "Le sud du Bois de la Pénombre s'enfonce dans une petite cuvette où la route bifurque vers la vallée de Strangleronce, et où se dressaient des fermes avant l'arrivée des ogres.",
			full = "Le sud du Bois de la Pénombre s'enfonce dans une petite cuvette où la route bifurque vers la vallée de Strangleronce, et où se dressaient des fermes avant l'arrivée des ogres. Les ogres Poing-brisé la tiennent désormais, et elle tire son nom de leur chef, Zzarc'Vul, qui règne sur le tertre depuis l'intérieur.\n\nLes fermes en ruine sont le seul signe que des gens vivaient ici avant que les ogres ne s'approprient la cuvette. Quel que fût le sort de ces familles, les ogres n'ont laissé derrière eux que des murs effondrés.\n\nLes Veilleurs n'y engagent pas leurs propres hommes, jugeant la menace ici moins urgente que d'autres qui pèsent sur le Bois de la Pénombre, et c'est donc à des étrangers qu'il revient de réduire le nombre des ogres lorsque c'est nécessaire. Parmi le butin des ogres se trouvait une caisse d'outils et d'herbes volée au nécromancien Abercrombie, emportée dans le tertre après qu'ils l'eurent submergé. Et Zzarc'Vul lui-même porte un monocle qu'un chercheur convoita jadis pour ses propres études, petite coquetterie chez une créature brutale.",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "La ferme des Yorgen",
			short = "La ferme des Yorgen gît abandonnée dans le sud du Bois de la Pénombre, ses champs livrés à la pourriture. Sven Yorgen travaillait jadis cette terre, mais se tient désormais dans un petit camp sur la Rive sombre.",
			full = "La ferme des Yorgen gît abandonnée dans le sud du Bois de la Pénombre, ses champs livrés à la pourriture. Sven Yorgen travaillait jadis cette terre, mais se tient désormais dans un petit camp sur la Rive sombre. La ferme elle-même est depuis tombée aux mains de la Confrérie défias, dont les assassins se déplacent invisibles dans les champs, ne frappant que lorsqu'il est trop tard.",
			source = "https://warcraft.wiki.gg/wiki/Yorgen_Farmstead",
		},
	},
	-- Loch Modan: 16 subzones
	[1432] = {
		["algaz station"] = {
			name = "Poste d'Algaz",
			short = "Le Poste d'Algaz se trouve à l'est du Passage de la porte Nord, et tire son nom de Dun Algaz, au nord.",
			full = "Le Poste d'Algaz se trouve à l'est du Passage de la porte Nord, et tire son nom de Dun Algaz, au nord. Des montagnards nains y montent la garde, parmi lesquels le montagnard Stormpike, et l'armurier Gothor Brumn entretient leur équipement.",
			source = "https://warcraft.wiki.gg/wiki/Algaz_Station",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "Le tunnel de Dun Algaz est plus ancien que la querelle qui divisa les nains. Lorsque la guerre des Trois clans chassa les Marteau-hardi d'Ironforge, c'est par ce col qu'ils battirent en retraite.",
			full = "Le tunnel de Dun Algaz est plus ancien que la querelle qui divisa les nains. Lorsque la guerre des Trois clans chassa les Marteau-hardi d'Ironforge, c'est par ce col qu'ils battirent en retraite.\n\nIl vit aussi passer la retraite de la Horde. Repoussés de Dun Modr, les orcs se replièrent vers le sud à travers la vallée de Thandol et se retranchèrent dans l'avant-poste d'ici, et Anduin Lothar, voulant les chasser entièrement de Khaz Modan, envoya ses forces raser la place forte. L'assaut échoua. Les orcs tinrent bon, et Dun Algaz devint le dernier territoire que la Horde conserva dans la région, un point d'appui dont on ne put la déloger.\n\nLes montagnards nains qui surveillaient ce col se tenaient surtout sur les collines qui le dominent, mais le clan Gueule-de-dragon envahit leur poste et les repoussa jusqu'au tunnel supérieur, où ils tiennent toujours. Le col inférieur perdu, la route entre les terres natales des nains et le Port de Menethil est devenue bien plus dangereuse.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["farstrider lodge"] = {
			name = "Le pavillon des Pérégrins",
			short = "Le Pavillon des Pérégrins se dresse dans le sud-est du Loch Modan, son architecture indubitablement haut-elfe, bien qu'un seul membre de cette race demeure encore entre ses murs.",
			full = "Le Pavillon des Pérégrins se dresse dans le sud-est du Loch Modan, son architecture indubitablement haut-elfe, bien qu'un seul membre de cette race demeure encore entre ses murs. Humains et nains s'y sont depuis installés, parmi lesquels des chasseurs, vivant entre des murs élevés par des mains depuis longtemps parties de ce lieu.",
			source = "https://warcraft.wiki.gg/wiki/Farstrider_Lodge",
		},
		["grizzlepaw ridge"] = {
			name = "Falaise de Vieillegriffe",
			short = "La Falaise de Vieillegriffe s'élève au sud de Thelsamar, peuplée d'ours qui ont fait des hauteurs leur domaine.",
			full = "La Falaise de Vieillegriffe s'élève au sud de Thelsamar, peuplée d'ours qui ont fait des hauteurs leur domaine. Le plus redoutable d'entre eux est Ol' Sooty, un ours d'une taille et d'un caractère effrayants, qui descend de sa tanière jusqu'au fond de la vallée, prompt à bondir sur quiconque a le malheur de l'irriter.\n\nGorick Guzzledraught se tient lui aussi sur la falaise.",
			source = "https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",
		},
		["ironbands excavation site"] = {
			name = "Excavations d'Ironband",
			short = "Les Excavations d'Ironband, dans le sud-est du Loch Modan, sont un site de fouilles nain ouvert par le prospecteur Ironband à la recherche de ce que les anciens avaient enfoui.",
			full = "Les Excavations d'Ironband, dans le sud-est du Loch Modan, sont un site de fouilles nain ouvert par le prospecteur Ironband à la recherche de ce que les anciens avaient enfoui. Mais la terre livra plus que des reliques : des troggs, plus grands et plus instables que ceux rencontrés sur les autres chantiers nains, surgirent des profondeurs et envahirent le site, chassant les prospecteurs et les mineurs qui l'avaient ouvert.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Excavation_Site",
		},
		["loch"] = {
			name = "Le Loch",
			short = "Le Loch occupe le cœur du Loch Modan, la plus grande étendue d'eau de tout Khaz Modan, et la troisième en taille du monde connu, derrière seulement le Lordamere et le Darrowmere.",
			full = "Le Loch occupe le cœur du Loch Modan, la plus grande étendue d'eau de tout Khaz Modan, et la troisième en taille du monde connu, derrière seulement le Lordamere et le Darrowmere.",
			source = "https://warcraft.wiki.gg/wiki/The_Loch",
		},
		["mogrosh stronghold"] = {
			name = "Bastion des Mo'grosh",
			short = "Les grottes du Bastion des Mo'grosh s'étendent dans le nord-est du Loch Modan, repaire d'une tribu d'ogres dont les cogne-ténèbres et les plieurs de terre n'obéissent qu'aux leurs.",
			full = "Les grottes du Bastion des Mo'grosh s'étendent dans le nord-est du Loch Modan, repaire d'une tribu d'ogres dont les cogne-ténèbres et les plieurs de terre n'obéissent qu'aux leurs.",
			source = "https://warcraft.wiki.gg/wiki/Mo'grosh_Stronghold",
		},
		["north gate pass"] = {
			name = "Passage de la porte Nord",
			short = "Le col traverse les hautes montagnes, descendant de Dun Morogh vers le Loch Modan.",
			full = "Le col traverse les hautes montagnes, descendant de Dun Morogh vers le Loch Modan. C'est la route la plus courte entre les deux, et les voyageurs en partance pour les terres au-delà du Loch passent par ici plus que par tout autre chemin.\n\nL'Avant-poste de la porte Nord monte la garde en ce lieu, tenant le passage.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["silver stream mine"] = {
			name = "Mine du Ru d'argent",
			short = "La Mine du Ru d'argent regorgeait jadis d'argent, et pendant des générations les nains d'Ironforge tirèrent richesse de ses filons.",
			full = "La Mine du Ru d'argent regorgeait jadis d'argent, et pendant des générations les nains d'Ironforge tirèrent richesse de ses filons. Lorsque le minerai s'épuisa, la Ligue des Mineurs transforma les tunnels en dépôt plutôt que de les abandonner.\n\nLa mine recèle encore une chose qui vaut d'être prise : les gemmes chargées de la faille, que l'on ne trouve nulle part ailleurs, prisées pour la confection des robes de mage.\n\nMais les nains ne tiennent plus ces tunnels. Des kobolds rats des tunnels ont envahi la mine, cherchant à s'approprier ses dernières ressources.",
			source = "https://warcraft.wiki.gg/wiki/Silver_Stream_Mine",
		},
		["south gate pass"] = {
			name = "Passage de la porte Sud",
			short = "Le Passage de la porte Sud traverse les montagnes, reliant les hautes neiges de Dun Morogh aux vallées plus basses du Loch Modan. C'est le chemin le plus court pour descendre à Thelsamar, usé par les voyageurs qui vont d'une terre à l'autre.",
			full = "Le Passage de la porte Sud traverse les montagnes, reliant les hautes neiges de Dun Morogh aux vallées plus basses du Loch Modan. C'est le chemin le plus court pour descendre à Thelsamar, usé par les voyageurs qui vont d'une terre à l'autre.\n\nIci se dresse l'Avant-poste de la porte Sud, un poste de garde chargé de surveiller le col.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["stonesplinter valley"] = {
			name = "Vallée des Brisepierre",
			short = "La Vallée des Brisepierre s'enfonce parmi les montagnes du sud-ouest du Loch Modan. Autrefois intacte, elle appartient désormais aux troggs Brisepierre, qui ont envahi son fond et ses pentes.",
			full = "La Vallée des Brisepierre s'enfonce parmi les montagnes du sud-ouest du Loch Modan. Autrefois intacte, elle appartient désormais aux troggs Brisepierre, qui ont envahi son fond et ses pentes. Les nains du Loch Modan les tiennent pour de la vermine à éliminer. Au plus profond de la vallée demeure Grawmug, le chef autour duquel se rallient les troggs.",
			source = "https://warcraft.wiki.gg/wiki/Stonesplinter_Valley",
		},
		["stonewrought dam"] = {
			name = "Barrage de Formepierre",
			short = "Le Barrage de Formepierre s'élève à l'est du col de Dun Algaz, le long de la lisière nord du Loch Modan.",
			full = "Le Barrage de Formepierre s'élève à l'est du col de Dun Algaz, le long de la lisière nord du Loch Modan.\n\nSon bâtisseur était un nain Sombrefer. Franclorn Forgewright, architecte de ce clan, conçut la méthode de la pierre façonnée grâce à laquelle le barrage fut élevé, bien que peu de ceux qui le traversent sachent qu'une main Sombrefer l'a bâti.\n\nLe barrage retient le Loch, qui a ainsi plus que doublé de taille, et les inondations qu'il provoqua donnèrent naissance aux marécages au-delà, une terre autrefois presque entièrement immergée.\n\nLe clan Sombrefer s'en prit au barrage, et Ironforge répondit en renforçant sa garde. L'ingénieur en chef Hinderweir VII en a désormais la charge.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Dam",
		},
		["stoutlager inn"] = {
			name = "Auberge de la Fortebière",
			short = "L'Auberge de la Fortebière se trouve à Thelsamar, son âtre rarement froid. Nains et voyageurs s'y retrouvent pour boire et échanger des nouvelles du Loch, et peu d'endroits de la région voient passer leur porte une foule aussi constante.",
			full = "L'Auberge de la Fortebière se trouve à Thelsamar, son âtre rarement froid. Nains et voyageurs s'y retrouvent pour boire et échanger des nouvelles du Loch, et peu d'endroits de la région voient passer leur porte une foule aussi constante.",
			source = "https://warcraft.wiki.gg/wiki/Stoutlager_Inn",
		},
		["thelsamar"] = {
			name = "Thelsamar",
			short = "Thelsamar se trouve sur la rive ouest du Loch Modan, au nord de la Falaise de Vieillegriffe et au nord-est de la Vallée des Brisepierre. Une route passe juste à l'ouest du bourg, montant à travers les cols vers Dun Morogh et les Paluns.",
			full = "Thelsamar se trouve sur la rive ouest du Loch Modan, au nord de la Falaise de Vieillegriffe et au nord-est de la Vallée des Brisepierre. Une route passe juste à l'ouest du bourg, montant à travers les cols vers Dun Morogh et les Paluns. Des griffons nichent à son perchoir, et son auberge abrite les voyageurs qui traversent les hautes terres.",
			source = "https://warcraft.wiki.gg/wiki/Thelsamar",
		},
		["valley of kings"] = {
			name = "Vallée des rois",
			short = "La Vallée des rois s'étend dans le sud-ouest du Loch Modan, là où la terre verdoyante se resserre vers la porte qui descend vers la Gorge des Vents brûlants, toute noircie.",
			full = "La Vallée des rois s'étend dans le sud-ouest du Loch Modan, là où la terre verdoyante se resserre vers la porte qui descend vers la Gorge des Vents brûlants, toute noircie. Cette porte est verrouillée et gardée, sous l'œil de la montagnarde Pebblebitty, qui n'accorde le passage qu'à ceux qui s'en montrent dignes.\n\nCe qui attire le regard ici, ce sont les deux grandes statues qui dominent le col : Madoran Bronzebeard et Khardros Marteau-hardi, taillés dans la pierre pour veiller sur la route du sud. À la mort des deux rois, ce furent leurs fils qui élevèrent ensemble les statues, unissant Bronzebeard et Marteau-hardi dans la pierre comme leurs pères l'avaient été dans la vie. Les terres du sud, au-delà, avaient été réduites en feu et en cendres par Ragnaros, et les statues font directement face à cette ruine : un avertissement pour quiconque voudrait s'en prendre aux royaumes nains, et un rappel du prix que les Sombrefer payèrent pour ce qu'ils avaient fait.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Kings",
		},
	},
	-- Les Carmines: 16 subzones
	[1433] = {
		["althers mill"] = {
			name = "Scierie d'Alther",
			short = "La scierie au nord-est de Lakeshire est vide, sa roue arrêtée depuis longtemps. Ce n'était guère plus qu'une halte sur la route du Donjon de Guet-de-pierre, et ses ruines abritent araignées, busards et quelque orc égaré.",
			full = "La scierie au nord-est de Lakeshire est vide, sa roue arrêtée depuis longtemps. Ce n'était guère plus qu'une halte sur la route du Donjon de Guet-de-pierre, et ses ruines abritent araignées, busards et quelque orc égaré.",
			source = "https://warcraft.wiki.gg/wiki/Alther's_Mill",
		},
		["galardell valley"] = {
			name = "Vallée de Galardell",
			short = "La Vallée de Galardell, dans le nord-est des Carmines, grouille de gnolls sous les ordres du lieutenant Fangore, dont le hurlement fait fondre les meutes sur quiconque l'affronte sans y être préparé.",
			full = "La Vallée de Galardell, dans le nord-est des Carmines, grouille de gnolls sous les ordres du lieutenant Fangore, dont le hurlement fait fondre les meutes sur quiconque l'affronte sans y être préparé.\n\nAu-dessus de la vallée se dresse la Tour d'Ilgalar, demeure du maléfique Morganth, dont le seul nom fait de ce lieu un endroit à craindre.",
			source = "https://warcraft.wiki.gg/wiki/Galardell_Valley",
		},
		["lake everstill"] = {
			name = "Lac placide",
			short = "Le Lac placide s'étend au cœur des Carmines, ses eaux assez vastes et bleues pour donner au paisible bourg de Lakeshire toute sa raison d'être.",
			full = "Le Lac placide s'étend au cœur des Carmines, ses eaux assez vastes et bleues pour donner au paisible bourg de Lakeshire toute sa raison d'être. Le lac se déverse vers l'est, et sa rivière court vers les sombres pierres du Donjon de Guet-de-pierre.\n\nC'était jadis un lac de pêcheurs, calme et fiable, mais cela a changé. Des tribus de murlocs ont envahi les hauts-fonds comme les profondeurs, et quelque part dans les eaux profondes un requin-renard patrouille encore, si vieux et si énorme que même les chasseurs aguerris des tribus murlocs l'évitent soigneusement. Le pont du Lac placide porte toujours les voyageurs au-dessus de l'eau, au-dessus des camps murlocs et de la chose qui guette d'en bas.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Everstill",
		},
		["lakeridge highway"] = {
			name = "Grand-route de la Crête du lac",
			short = "La Grand-route de la Crête du lac voyait jadis passer un trafic régulier le long de la rive sud du Lac placide, avant que les orcs ne s'emparent du Donjon de Guet-de-pierre et que la route ne tombe en désuétude.",
			full = "La Grand-route de la Crête du lac voyait jadis passer un trafic régulier le long de la rive sud du Lac placide, avant que les orcs ne s'emparent du Donjon de Guet-de-pierre et que la route ne tombe en désuétude. Des gnolls parcourent désormais la plus grande partie de son tracé, et des chasseurs Blackrock camouflés sont à l'affût plus loin. Nul ne conseillerait de l'emprunter.",
			source = "https://warcraft.wiki.gg/wiki/Lakeridge_Highway",
		},
		["lakeshire"] = {
			name = "Lakeshire",
			short = "Le Lac placide s'étend, immobile et froid, sous les pics des Carmines, et le bourg sur sa rive a plus d'une fois versé son sang pour cette terre.",
			full = "Le Lac placide s'étend, immobile et froid, sous les pics des Carmines, et le bourg sur sa rive a plus d'une fois versé son sang pour cette terre. Lorsque le chef de guerre Blackhand mena pour la première fois des orcs dans ces montagnes, sire Anduin Lothar et les chevaliers de Stormwind leur tendirent une embuscade sur les pentes et faillirent les briser, jusqu'à ce que deux démonistes du Conseil des ombres renversent le cours de la bataille et forcent Lothar à reculer. Blackhand revint quelques semaines plus tard avec une armée plus nombreuse et prit Lakeshire sans coup férir. Ce n'est qu'après la deuxième guerre que l'Alliance de Lordaeron la reprit, le commandant suprême Turalyon supervisant le retour de ses habitants dispersés.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire",
		},
		["redridge canyons"] = {
			name = "Canyons des Carmines",
			short = "Les canyons entaillent le nord-ouest des Carmines, leurs parois cachant la tanière de Couineur, qui mène les gnolls qui tiennent ce terrain.",
			full = "Les canyons entaillent le nord-ouest des Carmines, leurs parois cachant la tanière de Couineur, qui mène les gnolls qui tiennent ce terrain.",
			source = "https://warcraft.wiki.gg/wiki/Redridge_Canyons",
		},
		["renders camp"] = {
			name = "Camp des Etripeurs",
			short = "Les orcs Blackrock tiennent un camp dans le nord-ouest des Carmines, tout près du chemin qui mène aux Steppes ardentes.",
			full = "Les orcs Blackrock tiennent un camp dans le nord-ouest des Carmines, tout près du chemin qui mène aux Steppes ardentes. D'ici, ils surveillent le col, un point d'appui du clan Blackrock plaqué contre les montagnes qui mènent au domaine de leur maître.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Camp",
		},
		["renders rock"] = {
			name = "Rocher des Etripeurs",
			short = "Le Rocher des Étripeurs est une vaste grotte du nord-ouest des Carmines, près des Steppes ardentes. Les orcs Blackrock la tiennent en force.",
			full = "Le Rocher des Étripeurs est une vaste grotte du nord-ouest des Carmines, près des Steppes ardentes. Les orcs Blackrock la tiennent en force.\n\nC'est ici que le caporal Keeshan gît, blessé et coupé des siens, devant rejoindre Lakeshire vivant.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Rock",
		},
		["renders valley"] = {
			name = "Vallée des Etripeurs",
			short = "La Vallée des Étripeurs s'étend dans le sud-est des Carmines, un avant-poste des orcs Blackrock devenu place forte, ceint de tours et tenu par des guerriers d'élite.",
			full = "La Vallée des Étripeurs s'étend dans le sud-est des Carmines, un avant-poste des orcs Blackrock devenu place forte, ceint de tours et tenu par des guerriers d'élite.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Valley",
		},
		["rethban caverns"] = {
			name = "Cavernes de Rethban",
			short = "Les Cavernes de Rethban s'enfoncent profondément dans le nord-ouest des Carmines. Des gnolls tiennent les tunnels, menés par le rusé Ardo Dirtpaw, et amassent le minerai de Rethban arraché à la pierre.",
			full = "Les Cavernes de Rethban s'enfoncent profondément dans le nord-ouest des Carmines. Des gnolls tiennent les tunnels, menés par le rusé Ardo Dirtpaw, et amassent le minerai de Rethban arraché à la pierre. Les cavernes tiennent peut-être leur nom d'un certain Bart Rethban, bien que l'on ne se souvienne guère d'autre chose de lui.",
			source = "https://warcraft.wiki.gg/wiki/Rethban_Caverns",
		},
		["stonewatch"] = {
			name = "Guet-de-pierre",
			short = "Guet-de-pierre appartenait jadis aux humains de Lakeshire, une place forte adossée aux falaises où les chutes dévalent sous le donjon, veillant sur les Carmines contre la menace orque des Steppes ardentes.",
			full = "Guet-de-pierre appartenait jadis aux humains de Lakeshire, une place forte adossée aux falaises où les chutes dévalent sous le donjon, veillant sur les Carmines contre la menace orque des Steppes ardentes.\n\nCette garde fut brisée par la trahison. Le démoniste Morganth conclut une alliance avec Gath'Ilzogg et ses orcs Blackrock, et leurs forces réunies s'abattirent sur le Donjon de Guet-de-pierre avec une sauvagerie qui brisa la garnison. Les orcs prirent le donjon, mais la confiance ne survécut guère à leur triomphe, car Morganth se retourna contre les alliés qui le lui avaient conquis. Il éleva pour lui-même la Tour d'Ilgalar et plia à ses propres desseins une bande de guerre de gnolls Shadowhide, sous les ordres du lieutenant Fangore. Depuis ce revirement, orcs comme humains qui croisent le chemin des gnolls l'ont payé cher.\n\nAbandonnés par le démoniste qui s'était servi d'eux, les orcs Blackrock tinrent seuls le donjon, Gath'Ilzogg y régnant avec son lieutenant Tharil'zun à ses côtés.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
		},
		["stonewatch falls"] = {
			name = "Chutes de Guet-de-pierre",
			short = "Sous Guet-de-pierre, la rivière orientale du Lac placide dévale la colline en une longue chute, pour se rassembler en un lac profond dans un recoin des Carmines.",
			full = "Sous Guet-de-pierre, la rivière orientale du Lac placide dévale la colline en une longue chute, pour se rassembler en un lac profond dans un recoin des Carmines. Une petite tribu de murlocs s'est installée sur ses rives, pêchant dans ses eaux et dressant de grossiers abris sous les chutes.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Falls",
		},
		["stonewatch keep"] = {
			name = "Donjon de Guet-de-pierre",
			short = "Le Donjon de Guet-de-pierre appartenait jadis aux humains de Lakeshire, chargé de veiller sur les Carmines.",
			full = "Le Donjon de Guet-de-pierre appartenait jadis aux humains de Lakeshire, chargé de veiller sur les Carmines. Il tomba lorsque le démoniste Morganth conclut une alliance avec le seigneur de guerre orc Blackrock Gath'Ilzogg, et leurs forces réunies se jetèrent sur le donjon avec une sauvagerie nourrie par la magie noire de Morganth. Les défenseurs cédèrent, et le donjon fut pris.\n\nL'alliance ne dura pas. À peine Guet-de-pierre était-il tombé que Morganth se retourna contre les orcs qui avaient versé leur sang à ses côtés pour le prendre. Il éleva non loin la Tour d'Ilgalar et la remplit de gnolls Shadowhide sous les ordres du lieutenant Fangore, créatures pliées à sa seule volonté. Orcs comme humains sont depuis tombés sous les coups des brutes qu'il a lâchées.\n\nAbandonnés par leur allié démoniste, les orcs Blackrock tinrent seuls le donjon, Gath'Ilzogg et son lieutenant Tharil'zun régnant sur ce qu'il en restait. Pendant la bataille, ils avaient fait prisonnier le caporal Keeshan, de l'armée de Stormwind, et l'avaient traîné au nord jusqu'à leurs camps. Le magistrat Solomon mit pour cela à prix la tête de Gath'Ilzogg, et le maréchal Marris de Lakeshire jura que Tharil'zun répondrait lui aussi de ses crimes.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "Tour de Guet-de-pierre",
			short = "La Tour de Guet-de-pierre se dressait jadis à côté du Donjon de Guet-de-pierre, tous deux tenus par les humains de Lakeshire, jusqu'à ce que le clan Blackrock s'empare de la place forte.",
			full = "La Tour de Guet-de-pierre se dressait jadis à côté du Donjon de Guet-de-pierre, tous deux tenus par les humains de Lakeshire, jusqu'à ce que le clan Blackrock s'empare de la place forte. La tour sert de poste d'observation aux subalternes de Gath'Ilzogg, des orcs du clan Blackrock qui veillent sur la place forte que les leurs ont prise aux hommes de Lakeshire.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
		},
		["three corners"] = {
			name = "Trois chemins",
			short = "Aux Trois chemins, la route se divise en trois : à l'ouest vers Goldshire, dans la forêt d'Elwynn, à l'est vers Lakeshire, au sud vers Darkshire, dans le Bois de la Pénombre.",
			full = "Aux Trois chemins, la route se divise en trois : à l'ouest vers Goldshire, dans la forêt d'Elwynn, à l'est vers Lakeshire, au sud vers Darkshire, dans le Bois de la Pénombre. Qui se tient ici se tient à la jointure de trois terres, avec pour seul repère du passage de l'une à l'autre ce carrefour. Des gnolls affluent des collines voisines.",
			source = "https://warcraft.wiki.gg/wiki/Three_Corners",
		},
		["tower of ilgalar"] = {
			name = "Tour d'Ilgalar",
			short = "La Tour d'Ilgalar s'élève dans l'est des Carmines.",
			full = "La Tour d'Ilgalar s'élève dans l'est des Carmines. Morganth y règne, un sorcier banni du quartier des mages de Stormwind pour ses sombres études, qui fit de la tour son refuge et plia le clan gnoll Shadowhide à sa volonté.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Ilgalar",
		},
	},
	-- Vallée de Strangleronce: 38 subzones
	[1434] = {
		["baliamah ruins"] = {
			name = "Ruines de Balia'mah",
			short = "Les pierres de Balia'mah sont un ancien ouvrage troll, dressé à l'est de la rivière en contrebas de Mosh'Ogg. Les trolls Skullsplitter les tiennent désormais, ayant fait leur foyer de ce que leurs ancêtres élevèrent.",
			full = "Les pierres de Balia'mah sont un ancien ouvrage troll, dressé à l'est de la rivière en contrebas de Mosh'Ogg. Les trolls Skullsplitter les tiennent désormais, ayant fait leur foyer de ce que leurs ancêtres élevèrent.",
			source = "https://warcraft.wiki.gg/wiki/Balia'mah_Ruins",
		},
		["ballal ruins"] = {
			name = "Ruines de Bal'lal",
			short = "Des colonnes brisées s'élèvent près du Récif infâme, au nord du Campement Grom'gol, tout ce qui reste d'un établissement élevé il y a longtemps par des trolls. Il ne reste guère debout de ce qu'il fut.",
			full = "Des colonnes brisées s'élèvent près du Récif infâme, au nord du Campement Grom'gol, tout ce qui reste d'un établissement élevé il y a longtemps par des trolls. Il ne reste guère debout de ce qu'il fut. Des trolls Scalp-rouge tiennent désormais la ruine, vivant parmi les pierres que leurs ancêtres ont laissées.",
			source = "https://warcraft.wiki.gg/wiki/Bal'lal_Ruins",
		},
		["bloodsail compound"] = {
			name = "Base de la Voile sanglante",
			short = "Les boucaniers de la Voile sanglante tiennent un camp désordonné sur la côte ouest de la vallée de Strangleronce, niché vers le milieu du rivage.",
			full = "Les boucaniers de la Voile sanglante tiennent un camp désordonné sur la côte ouest de la vallée de Strangleronce, niché vers le milieu du rivage. Aucune bannière d'ordre n'y flotte, aucune discipline de véritable port : seulement le rassemblement épars de pirates qui considèrent le lieu comme le leur.",
			source = "https://warcraft.wiki.gg/wiki/Bloodsail_Compound",
		},
		["booty bay"] = {
			name = "Baie-du-Butin",
			short = "Baie-du-Butin se niche dans un lagon bleu à la pointe sud de la vallée de Strangleronce, et l'on y entre à pied par les mâchoires blanchies d'un requin géant.",
			full = "Baie-du-Butin se niche dans un lagon bleu à la pointe sud de la vallée de Strangleronce, et l'on y entre à pied par les mâchoires blanchies d'un requin géant. La vie n'y vaut pas cher, et nul n'est digne de confiance ; c'est un paradis de voleurs, grouillant d'indicateurs et de marchands de tout acabit.\n\nAvant de porter ce nom, la crique s'appelait la Crique des Flots noirs, un petit port humain jusqu'à ce que des trolls de la jungle l'envahissent. Les gobelins du Cartel Gentepression repoussèrent les trolls du rivage et s'approprièrent la crique, avant même que la première guerre ne soit livrée, et y bâtirent leur centre d'opérations dans les Royaumes de l'est.\n\nLes Écumeurs des Flots noirs dirigent aujourd'hui le port, en étroite association avec le Cartel, et ses portes sont ouvertes à tout voyageur, quelle que soit sa bannière. Le baron Revilgaz règne depuis le sommet de l'auberge, aux côtés de l'amiral Seahorn des Écumeurs, et il a dépensé sans compter pour engager des épées contre les boucaniers de la Voile sanglante, des pirates qui ont comploté, sans succès, pour s'emparer de la baie elle-même.",
			source = "https://warcraft.wiki.gg/wiki/Booty_Bay",
		},
		["cape of stranglethorn"] = {
			name = "Le cap Strangleronce",
			short = "Le sud de la vallée de Strangleronce est parsemé de ruines trolls, à demi englouties par la jungle, et de longues étendues de sable où les arbres cèdent la place à la mer.",
			full = "Le sud de la vallée de Strangleronce est parsemé de ruines trolls, à demi englouties par la jungle, et de longues étendues de sable où les arbres cèdent la place à la mer.\n\nSur la côte se trouve Baie-du-Butin, une ville portuaire dirigée par des pirates gobelins, dont les quais et le marché sont ouverts à quiconque a de l'argent, quelle que soit sa bannière.\n\nCette neutralité n'est pas la paix. Les gobelins de Baie-du-Butin tiennent leur port par le commerce et par la force, et leurs rivaux sont les boucaniers de la Voile sanglante, des pirates qui se sont retournés contre eux et se sont mis à piller les eaux et le rivage que les gobelins considèrent comme leurs. Le conflit entre eux n'a fait qu'empirer, navire contre navire et camp contre camp, les gobelins défendant ce qu'ils ont bâti tandis que la Voile sanglante s'acharne à le leur prendre.\n\nAu-delà du port et des ruines, la terre est paisible : du sable, de vieilles pierres, et la mer au-delà.",
			source = "https://warcraft.wiki.gg/wiki/Cape_of_Stranglethorn",
		},
		["crystal shore"] = {
			name = "Le Rivage de cristal",
			short = "Le Rivage de cristal est un littoral sablonneux du sud-est de Strangleronce, où les Mers du sud se brisent contre le continent et contre les plages orientales de l'Île aux jagueros.",
			full = "Le Rivage de cristal est un littoral sablonneux du sud-est de Strangleronce, où les Mers du sud se brisent contre le continent et contre les plages orientales de l'Île aux jagueros. Il s'étend du Rivage cruel jusqu'aux falaises où la terre s'élève vers le nord, coupé de l'intérieur par une crête abrupte que franchissent seulement deux sentiers, dont l'un monte vers Valbrume.\n\nLes Ruines d'Aboraz se trouvent à l'extrémité nord du rivage.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Shore",
		},
		["crystalvein mine"] = {
			name = "Mine aux cristaux",
			short = "Crank Fizzlebub les appelait les cristaux chantants, propres à Strangleronce et valant une fortune.",
			full = "Crank Fizzlebub les appelait les cristaux chantants, propres à Strangleronce et valant une fortune. Ils veinent la roche de la Mine aux cristaux, près de Zul'Mamwe, et les basilics qui y nichent les mangent crus, ce qui durcit leur peau comme de la pierre. La KapitalRisk s'y est introduite dans l'espoir de dépouiller la mine, mais les basilics ont repoussé toutes les tentatives. Devant l'entrée, trolls et humains se dressent, cristallisés là où ils sont tombés.",
			source = "https://warcraft.wiki.gg/wiki/Crystalvein_Mine",
		},
		["gromgol base camp"] = {
			name = "Campement Grom'gol",
			short = "Le Campement Grom'gol se dresse, fortifié, sur la côte sud-ouest de Strangleronce, ses palissades élevées contre les trolls de la jungle de la côte, contre les nagas surgissant du ressac, et contre l'Alliance qui s'avance depuis Baie-du-Butin et le Bois de la Pénombre.",
			full = "Le Campement Grom'gol se dresse, fortifié, sur la côte sud-ouest de Strangleronce, ses palissades élevées contre les trolls de la jungle de la côte, contre les nagas surgissant du ressac, et contre l'Alliance qui s'avance depuis Baie-du-Butin et le Bois de la Pénombre. Le commandant Aggro'gosh tient le camp, en faisant le maillon sûr de la chaîne d'approvisionnement qui mène à Stonard, dans le Marais des Chagrins.",
			source = "https://warcraft.wiki.gg/wiki/Grom'gol_Base_Camp",
		},
		["gurubashi arena"] = {
			name = "Arène des Gurubashi",
			short = "L'Arène des Gurubashi se dresse dans le nord-ouest de Strangleronce, vestige élevé à l'époque où l'empire Gurubashi régnait sur de vastes étendues du sud des Royaumes de l'est.",
			full = "L'Arène des Gurubashi se dresse dans le nord-ouest de Strangleronce, vestige élevé à l'époque où l'empire Gurubashi régnait sur de vastes étendues du sud des Royaumes de l'est.\n\nAutrefois, les combats qui s'y livraient n'étaient pas un sport mais un massacre. Le sable devenait boueux de sang troll tandis que les combattants s'affrontaient jusqu'à la mort. Désormais, Short John Mithril organise des combats d'un genre plus doux, offrant gloire et butin plutôt que la mort. De vieilles histoires avertissent encore que quiconque trouve à minuit une amulette rouge sang sera dévoré par un démon avant l'aube.",
			source = "https://warcraft.wiki.gg/wiki/Gurubashi_Arena",
		},
		["jaguero isle"] = {
			name = "Ile aux jagueros",
			short = "Au large du Rivage cruel se trouve l'Île aux jagueros, une jungle tenue par des panthères et des gorilles qui n'obéissent à personne.",
			full = "Au large du Rivage cruel se trouve l'Île aux jagueros, une jungle tenue par des panthères et des gorilles qui n'obéissent à personne. À leur tête règne le roi Mukla, un singe énorme qui gouverne l'île et retient captive la princesse Poobah, une taurène gardée contre son gré.\n\nÀ demi enfouies le long du rivage se trouvent des bouteilles rejetées par la mer, dont l'une contient un billet plié.",
			source = "https://warcraft.wiki.gg/wiki/Jaguero_Isle",
		},
		["janeiros point"] = {
			name = "Cap Janeiro",
			short = "Le Cap Janeiro est un îlot au large de Baie-du-Butin, marqué par un grand gobelin de pierre aux bras grands ouverts, élevé comme un phare pour accueillir les navires dans le port.",
			full = "Le Cap Janeiro est un îlot au large de Baie-du-Butin, marqué par un grand gobelin de pierre aux bras grands ouverts, élevé comme un phare pour accueillir les navires dans le port. Nul ne se souvient aujourd'hui de qui il représente. Le géant des mers Mok'rash le Fendoir a fait de l'île sa demeure.",
			source = "https://warcraft.wiki.gg/wiki/Janeiro's_Point",
		},
		["kalai ruins"] = {
			name = "Ruines de Kal'ai",
			short = "Les Ruines de Kal'ai gisent, à demi englouties par la mer, dans la vallée de Strangleronce, une antique maçonnerie troll usée par les marées et les âges.",
			full = "Les Ruines de Kal'ai gisent, à demi englouties par la mer, dans la vallée de Strangleronce, une antique maçonnerie troll usée par les marées et les âges. La tribu murloc des Murkgill niche désormais parmi les colonnes effondrées, ayant fait des salles noyées son domaine.",
			source = "https://warcraft.wiki.gg/wiki/Kal'ai_Ruins",
		},
		["kurzens compound"] = {
			name = "Base de Kurzen",
			short = "La Base de Kurzen se trouve à l'est du Camp rebelle, siège de l'expédition de Kurzen. Le colonel Kurzen la dirige, bien que la folie l'ait gagné.",
			full = "La Base de Kurzen se trouve à l'est du Camp rebelle, siège de l'expédition de Kurzen. Le colonel Kurzen la dirige, bien que la folie l'ait gagné. Ce qu'il est devenu, on n'en parle pas, seulement du résultat : ses hommes se sont divisés. Ceux qui refusèrent de le suivre plus loin firent sécession et devinrent les combattants de la jungle du Camp rebelle, et la base est en guerre contre eux depuis lors, des hommes jadis sous un même commandement s'entretuant désormais parmi les arbres.\n\nKurzen lui-même ne se montre plus guère parmi ses hommes ; il se tiendrait dans la Réserve, au fond de la base, où les combattants entreposent leurs armes. Près des écuries, des panthères et des tigres de Strangleronce sont gardés en cage, brisés et dressés pour devenir les bêtes de guerre de l'expédition.",
			source = "https://warcraft.wiki.gg/wiki/Kurzen's_Compound",
		},
		["lake nazferiti"] = {
			name = "Lac Nazfériti",
			short = "Les eaux du lac Nazfériti grouillent de poissons frénétiques et de crocilisques, et une grande base de la KapitalRisk s'entasse sur sa rive.",
			full = "Les eaux du lac Nazfériti grouillent de poissons frénétiques et de crocilisques, et une grande base de la KapitalRisk s'entasse sur sa rive.\n\nLe lac est alimenté par la rivière Nazfériti, que certains tiennent pour la plus longue du sud des Royaumes de l'est, et qui prend sa source à une cascade des Carmines, peut-être même plus loin, dans le défilé de Deuillevent.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Nazferiti",
		},
		["mistvale valley"] = {
			name = "Valbrume",
			short = "Le brouillard s'étend bas sur Valbrume, assez épais pour estomper la lisière des arbres dans le sud de la vallée de Strangleronce.",
			full = "Le brouillard s'étend bas sur Valbrume, assez épais pour estomper la lisière des arbres dans le sud de la vallée de Strangleronce. Les grands gorilles de Valbrume y ont élu domicile, se déplaçant dans la brume entre les arbres, maîtres incontestés de ce creux paisible et humide.",
			source = "https://warcraft.wiki.gg/wiki/Mistvale_Valley",
		},
		["mizjah ruins"] = {
			name = "Ruines de Mizjah",
			short = "Les Ruines de Mizjah s'étendent au sud-est du Campement Grom'gol, tenues par des brutes Mosh'Ogg et leurs sorciers-docteurs.",
			full = "Les Ruines de Mizjah s'étendent au sud-est du Campement Grom'gol, tenues par des brutes Mosh'Ogg et leurs sorciers-docteurs. Depuis ces pierres brisées, les ogres frappent les caravanes à destination de Stonard, prenant en embuscade les lignes d'approvisionnement avant de disparaître dans les ruines sans qu'on puisse riposter.",
			source = "https://warcraft.wiki.gg/wiki/Mizjah_Ruins",
		},
		["moshogg ogre mound"] = {
			name = "Tertre des ogres Mosh'Ogg",
			short = "Le Tertre des ogres Mosh'Ogg se trouve au sud de Zul'Gurub, et ses creux obscurs abritent la tribu d'ogres Mosh'Ogg.",
			full = "Le Tertre des ogres Mosh'Ogg se trouve au sud de Zul'Gurub, et ses creux obscurs abritent la tribu d'ogres Mosh'Ogg. Tout au fond, leur chef, le mage ogre Mai'Zoth, détient une puissante relique appelée l'Œil de l'esprit, et c'est depuis ces profondeurs qu'il règne aujourd'hui sur le tertre.",
			source = "https://warcraft.wiki.gg/wiki/Mosh'Ogg_Ogre_Mound",
		},
		["nekmani wellspring"] = {
			name = "Fontaine des Nek'mani",
			short = "La Fontaine des Nek'mani jaillit dans les falaises qui dominent la Côte sauvage du sud, à la lisière ouest de Strangleronce.",
			full = "La Fontaine des Nek'mani jaillit dans les falaises qui dominent la Côte sauvage du sud, à la lisière ouest de Strangleronce.\n\nLes érudits de toutes les races affirment que ses eaux furent sanctifiées pour leur seul peuple, et nul n'a jamais tranché la question.",
			source = "https://warcraft.wiki.gg/wiki/Nek'mani_Wellspring",
		},
		["nesingwarys expedition"] = {
			name = "Expédition de Nesingwary",
			short = "Hemet Nesingwary, un maître chasseur nain, mena une expédition dans Strangleronce, attiré par le gibier sauvage de la jungle.",
			full = "Hemet Nesingwary, un maître chasseur nain, mena une expédition dans Strangleronce, attiré par le gibier sauvage de la jungle. Il établit son camp juste en contrebas de la rivière, au nord du lac Nazfériti, et ce camp se dresse toujours, point d'appui d'un chasseur taillé dans l'étendue verdoyante de Strangleronce.",
			source = "https://warcraft.wiki.gg/wiki/Nesingwary's_Expedition",
		},
		["rebel camp"] = {
			name = "Camp rebelle",
			short = "Le Camp rebelle se trouve dans le nord de la vallée de Strangleronce, à l'ouest de la route qui descend du Bois de la Pénombre, au nord-ouest de la Base de Kurzen.",
			full = "Le Camp rebelle se trouve dans le nord de la vallée de Strangleronce, à l'ouest de la route qui descend du Bois de la Pénombre, au nord-ouest de la Base de Kurzen.\n\nSes fondateurs servaient dans l'expédition du colonel Kurzen jusqu'à ce que la folie s'empare de lui et de ses hommes, déformant leur esprit au point de les rendre méconnaissables. Une petite troupe menée par le lieutenant Doren se libéra avant que la folie ne la gagne, et s'enfuit de la Base de Kurzen vers l'ouest à travers la jungle.\n\nLà, ils bâtirent le Camp rebelle, un point d'appui d'où défaire ce qu'était devenu Kurzen. Krazek, de Baie-du-Butin, les approvisionne en mines terrestres et autres moyens de défense, assez pour permettre aux rebelles de tenir face à la garnison maudite aux côtés de laquelle ils servaient autrefois.",
			source = "https://warcraft.wiki.gg/wiki/Rebel_Camp",
		},
		["ruins of aboraz"] = {
			name = "Ruines d'Aboraz",
			short = "Aboraz fut élevée par d'antiques trolls, mais elle n'appartient plus à personne.",
			full = "Aboraz fut élevée par d'antiques trolls, mais elle n'appartient plus à personne. Zanzil le Paria, exilé des siens, a fait des ruines son domaine, les peuplant de goules, de nagas et de sbires trolls qui obéissent à son art de sorcier-docteur.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Aboraz",
		},
		["ruins of jubuwal"] = {
			name = "Ruines de Jubuwal",
			short = "Les Ruines de Jubuwal s'étendent à l'est de l'Arène des Gurubashi, un ancien village troll désormais tenu par des goules, des nagas et des trolls au service de Zanzil le Paria.",
			full = "Les Ruines de Jubuwal s'étendent à l'est de l'Arène des Gurubashi, un ancien village troll désormais tenu par des goules, des nagas et des trolls au service de Zanzil le Paria. Parmi eux se cachent Jon-Jon le Corbeau et Maury « Pied-bot » Wilkins, des hommes réfugiés dans cette sinistre compagnie pour échapper aux dettes qu'ils doivent à l'impitoyable MacKinley « Loup des mers ».",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Jubuwal",
		},
		["ruins of zulkunda"] = {
			name = "Ruines de Zul'Kunda",
			short = "Les terrasses de pierre de Zul'Kunda appartiennent désormais aux trolls Scalp-rouge, sous la domination de Nezzliok le Redoutable et de Gan'zulah.",
			full = "Les terrasses de pierre de Zul'Kunda appartiennent désormais aux trolls Scalp-rouge, sous la domination de Nezzliok le Redoutable et de Gan'zulah. Le chemin qui part vers l'est depuis les Ruines de Zuuldaia mène droit sur leur territoire, où une vieille maçonnerie troll est revendiquée par les vivants.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Kunda",
		},
		["ruins of zulmamwe"] = {
			name = "Ruines de Zul'Mamwe",
			short = "Les Ruines de Zul'Mamwe sont cernées de montagnes de tous côtés sauf au nord, au sud du Tertre des ogres Mosh'Ogg.",
			full = "Les Ruines de Zul'Mamwe sont cernées de montagnes de tous côtés sauf au nord, au sud du Tertre des ogres Mosh'Ogg. Elles sont le siège des Skullsplitter, la seconde des tribus trolls de la vallée de Strangleronce, gouvernée par leur chef Ana'thek le Cruel.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Mamwe",
		},
		["savage coast"] = {
			name = "La Côte sauvage",
			short = "La Côte sauvage longe le rivage nord de la vallée de Strangleronce, de la frontière de la Marche de l'Ouest jusqu'à Grom'gol, au-delà du Récif infâme.",
			full = "La Côte sauvage longe le rivage nord de la vallée de Strangleronce, de la frontière de la Marche de l'Ouest jusqu'à Grom'gol, au-delà du Récif infâme.\n\nDes crocilisques hantent ses hauts-fonds et des basilics rôdent sur ses rochers, leur regard changeant en pierre les imprudents. Plusieurs villages trolls veillent sur ces eaux.",
			source = "https://warcraft.wiki.gg/wiki/Savage_Coast",
		},
		["south seas"] = {
			name = "Mers du sud",
			short = "Les Mers du sud emplissent les eaux entre les continents connus, une partie de la Grande mer. Zandalar s'élève de ces eaux, antique berceau de l'empire troll.",
			full = "Les Mers du sud emplissent les eaux entre les continents connus, une partie de la Grande mer. Zandalar s'élève de ces eaux, antique berceau de l'empire troll. Kezan se trouve aussi parmi elles, une île volcanique dont le peuple se tient à l'écart des puissances du continent. Plus près de la vallée de Strangleronce, la mer devient traîtresse, semée de récifs et d'îlots, certains guère plus qu'un banc de sable, d'autres abritant des ruines dont les bâtisseurs ont disparu. Les Mers du sud longent les frontières de Strangleronce, de Tanaris et d'Uldum.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southern savage coast"] = {
			name = "Côte sauvage du sud",
			short = "La Côte sauvage du sud s'étend là où les Mers du sud se brisent contre des plages dégagées et des eaux peu profondes, descendant jusqu'aux eaux proches de Baie-du-Butin et du Cap Janeiro, où le rivage cède la place au Rivage cruel, au-delà.",
			full = "La Côte sauvage du sud s'étend là où les Mers du sud se brisent contre des plages dégagées et des eaux peu profondes, descendant jusqu'aux eaux proches de Baie-du-Butin et du Cap Janeiro, où le rivage cède la place au Rivage cruel, au-delà.\n\nLe Récif infâme marque la limite entre cette côte et son pendant du nord, là où la Grande mer cède la place aux Mers du sud. Baies et anses mettent la côte en contact avec l'Arène des Gurubashi et la Fontaine des Nek'mani.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Savage_Coast",
		},
		["spirit den"] = {
			name = "Antre des esprits",
			short = "L'Antre des esprits se cache dans une grotte à l'extrémité nord de Valbrume. Là, le sorcier-docteur Unbagwa se tient dans l'ombre de l'antre, veillant sur les esprits qui s'attardent dans ce creux paisible et invisible.",
			full = "L'Antre des esprits se cache dans une grotte à l'extrémité nord de Valbrume. Là, le sorcier-docteur Unbagwa se tient dans l'ombre de l'antre, veillant sur les esprits qui s'attardent dans ce creux paisible et invisible.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Den",
		},
		["stockpile"] = {
			name = "La réserve",
			short = "Dans une grotte au fond de la Base de Kurzen, le colonel Kurzen garde l'équipement de sa guerre.",
			full = "Dans une grotte au fond de la Base de Kurzen, le colonel Kurzen garde l'équipement de sa guerre.",
			source = "https://warcraft.wiki.gg/wiki/Stockpile",
		},
		["tkashi ruins"] = {
			name = "Ruines de Tkashi",
			short = "Les Ruines de Tkashi se trouvent dans la vallée de Strangleronce, une vieille maçonnerie troll reprise par la jungle.",
			full = "Les Ruines de Tkashi se trouvent dans la vallée de Strangleronce, une vieille maçonnerie troll reprise par la jungle. La tribu Scalp-rouge les tient désormais, ses chamans accomplissant d'anciens rites parmi les murs brisés, et des artefacts gisent encore épars dans les décombres.",
			source = "https://warcraft.wiki.gg/wiki/Tkashi_Ruins",
		},
		["venture co base camp"] = {
			name = "Campement de la KapitalRisk",
			short = "La KapitalRisk entretient ici un campement voué à la recherche de cristaux roulés. Non loin se dresse son Centre d'opérations, les deux œuvrant de concert vers la même découverte.",
			full = "La KapitalRisk entretient ici un campement voué à la recherche de cristaux roulés. Non loin se dresse son Centre d'opérations, les deux œuvrant de concert vers la même découverte.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Base_Camp",
		},
		["venture co operations center"] = {
			name = "Centre d'opérations de la KapitalRisk",
			short = "La plate-forme pétrolière de la KapitalRisk s'élève d'un lac de la jungle, centre d'opérations de sa poussée dans les terres sauvages.",
			full = "La plate-forme pétrolière de la KapitalRisk s'élève d'un lac de la jungle, centre d'opérations de sa poussée dans les terres sauvages. Mécaniciens, géologues et autres équipes gobelines se pressent sur la plate-forme, faisant tourner les machines d'une entreprise résolue à dépouiller la terre pour le profit.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Operations_Center",
		},
		["vile reef"] = {
			name = "Le Récif infâme",
			short = "Au large de la côte ouest de la vallée de Strangleronce, près de Grom'gol, la mer se brise, étincelante, sur le corail.",
			full = "Au large de la côte ouest de la vallée de Strangleronce, près de Grom'gol, la mer se brise, étincelante, sur le corail. En dessous gisent des ruines trolls englouties, et parmi ces pierres noyées les murlocs ont désormais élu domicile, bancs épais évoluant dans des salles qui appartenaient autrefois à d'autres. L'autel des Marées s'y dresse toujours. Des palourdes géantes jonchent le fond du récif, qui renfermeraient des perles bleues, et les débris de navires qui ne franchirent jamais le récif roulent jusqu'au rivage.",
			source = "https://warcraft.wiki.gg/wiki/Vile_Reef",
		},
		["wild shore"] = {
			name = "Le Rivage cruel",
			short = "Le Rivage cruel est l'endroit où les Royaumes de l'est cèdent la place aux Mers du sud, ses plages tenues par les boucaniers de la Voile sanglante, dont la flotte mouille au large et dont les équipages revendiquent le sable comme le leur.",
			full = "Le Rivage cruel est l'endroit où les Royaumes de l'est cèdent la place aux Mers du sud, ses plages tenues par les boucaniers de la Voile sanglante, dont la flotte mouille au large et dont les équipages revendiquent le sable comme le leur. Quelque part sur le rivage erre Gorlash, un géant solitaire, et entre pirates et géant, la côte n'obéit à aucune couronne.\n\nLa terre se resserre vers l'ouest jusqu'à une pointe rocheuse avant de tourner vers Baie-du-Butin. À l'est, par-delà un détroit peu profond, se trouve l'Île aux jagueros. Au nord, le sable se fond dans le Rivage de cristal.",
			source = "https://warcraft.wiki.gg/wiki/Wild_Shore",
		},
		["yojamba isle"] = {
			name = "Ile de Yojamba",
			short = "Sur ces petites îles au large de la côte nord-ouest de Strangleronce, près de la frontière de la Marche de l'Ouest, la tribu Zandalar se dressa contre un dieu devenu fou.",
			full = "Sur ces petites îles au large de la côte nord-ouest de Strangleronce, près de la frontière de la Marche de l'Ouest, la tribu Zandalar se dressa contre un dieu devenu fou.\n\nHakkar l'Écorcheur d'âmes avait fait de Zul'Gurub un lieu de sang et de folie, et les Zandalari savaient qu'ils ne pourraient l'affronter seuls. Ils vinrent donc sur l'île de Yojamba et appelèrent l'Alliance comme la Horde à mettre leur guerre de côté le temps de les aider à le détruire. C'était une tribu ancienne et fière qui confiait à des étrangers le sort de sa cité touchée par les dieux.",
			source = "https://warcraft.wiki.gg/wiki/Yojamba_Isle",
		},
		["ziatajai ruins"] = {
			name = "Ruines de Ziata'jai",
			short = "Les Ruines de Ziata'jai sont d'antiques pierres élevées il y a longtemps par des trolls, aujourd'hui revendiquées par la tribu Skullsplitter, qui a fait des vieux murs son domaine.",
			full = "Les Ruines de Ziata'jai sont d'antiques pierres élevées il y a longtemps par des trolls, aujourd'hui revendiquées par la tribu Skullsplitter, qui a fait des vieux murs son domaine.",
			source = "https://warcraft.wiki.gg/wiki/Ziata'jai_Ruins",
		},
		["zulgurub"] = {
			name = "Zul'Gurub",
			short = "Zul'Gurub surgit de la jungle dans le nord-est de la vallée de Strangleronce, ses terrasses et ses idoles envahies par la végétation mais toujours debout, une cité-temple qui fut jadis le cœur battant d'un empire.",
			full = "Zul'Gurub surgit de la jungle dans le nord-est de la vallée de Strangleronce, ses terrasses et ses idoles envahies par la végétation mais toujours debout, une cité-temple qui fut jadis le cœur battant d'un empire. Il y a des milliers d'années, c'était la capitale de l'empire Gurubashi, siège de toutes les tribus de trolls de la jungle qui lui étaient liées. Elle n'appartient plus aujourd'hui qu'à la tribu Gurubashi qui subsiste, et la jungle alentour ne paraît pas vide.\n\nL'empire se déchira lorsqu'un cercle de prêtres appelés les Atal'ai invoqua l'avatar d'un antique dieu du sang, Hakkar l'Écorcheur d'âmes, et fut pour cela chassé en exil. Ils apprirent que Hakkar ne pouvait prendre forme physique qu'en un seul lieu : l'ancienne capitale gurubashi elle-même. C'est ici que Jin'do le Maléficieur a asservi plusieurs grands prêtres gurubashi, les pliant à l'œuvre d'appeler Hakkar dans le monde. Les champions envoyés pour l'arrêter, chacun lié à un dieu primordial, sont tombés à leur tour sous l'emprise de Hakkar, et leur puissance nourrit désormais la chose même qu'ils étaient venus détruire.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Gurub",
		},
		["zuuldaia ruins"] = {
			name = "Ruines de Zuuldaia",
			short = "Des pierres usées par le temps s'élèvent au-dessus de la côte ouest de la vallée de Strangleronce, ruines d'un établissement depuis longtemps tombé.",
			full = "Des pierres usées par le temps s'élèvent au-dessus de la côte ouest de la vallée de Strangleronce, ruines d'un établissement depuis longtemps tombé. Les trolls Scalp-rouge tiennent désormais les murs brisés, nombreux parmi les vieilles fondations, revendiquant une terre que leurs ancêtres n'ont jamais bâtie.",
			source = "https://warcraft.wiki.gg/wiki/Zuuldaia_Ruins",
		},
	},
	-- Marais des Chagrins: 14 subzones
	[1435] = {
		["fallow sanctuary"] = {
			name = "Sanctuaire des friches",
			short = "Dans le Marais des Chagrins se dresse le Sanctuaire des friches, foyer d'une tribu d'Égarés connue simplement sous le nom d'Égarés.",
			full = "Dans le Marais des Chagrins se dresse le Sanctuaire des friches, foyer d'une tribu d'Égarés connue simplement sous le nom d'Égarés. Le mal du pays les a tous gagnés, les rendant entièrement sauvages, si bien qu'il ne reste rien de ce qu'ils étaient pour accueillir quiconque s'approche de leur village.",
			source = "https://warcraft.wiki.gg/wiki/Fallow_Sanctuary",
		},
		["harborage"] = {
			name = "Le Havre boueux",
			short = "Dans le nord du Marais des Chagrins se dresse le refuge de ceux qui passèrent de Draenor à Azeroth et qui, contrairement à tant des leurs, gardèrent leur esprit intact.",
			full = "Dans le nord du Marais des Chagrins se dresse le refuge de ceux qui passèrent de Draenor à Azeroth et qui, contrairement à tant des leurs, gardèrent leur esprit intact. Magtoor les dirige ici.",
			source = "https://warcraft.wiki.gg/wiki/Harborage",
		},
		["ithariuss cave"] = {
			name = "Caverne d'Itharius",
			short = "Dans le sud-ouest du Marais des Chagrins, une caverne abrite le haut-elfe Itharius. Au-dehors, de turbulents dragonnets verts se chamaillent et trébuchent, trop jeunes pour maîtriser l'aile ou le feu.",
			full = "Dans le sud-ouest du Marais des Chagrins, une caverne abrite le haut-elfe Itharius. Au-dehors, de turbulents dragonnets verts se chamaillent et trébuchent, trop jeunes pour maîtriser l'aile ou le feu. Itharius s'est donné pour tâche de veiller sur eux pendant leur croissance.",
			source = "https://warcraft.wiki.gg/wiki/Itharius's_Cave",
		},
		["misty reed post"] = {
			name = "Poste de Brumejonc",
			short = "Le Poste de Brumejonc est un petit avant-poste de Stonard, situé entre le Stagalbog et la Grève de Brumejonc, au sud. Tok'Kar le tient, avec Katar, une poignée de chasseurs de Stonard et un chaman de Stonard.",
			full = "Le Poste de Brumejonc est un petit avant-poste de Stonard, situé entre le Stagalbog et la Grève de Brumejonc, au sud. Tok'Kar le tient, avec Katar, une poignée de chasseurs de Stonard et un chaman de Stonard. Ce n'est qu'un camp, sans terrier ni tour, bien que Tok'Kar rêve d'en élever un jour.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Post",
		},
		["misty reed strand"] = {
			name = "Grève de Brumejonc",
			short = "La Grève de Brumejonc longe le Marais des Chagrins, une plage lugubre où ne poussent guère que le bois flotté et la pourriture. Des crocilisques se prélassent dans ses hauts-fonds, et crabes et murlocs occupent le rivage au-delà.",
			full = "La Grève de Brumejonc longe le Marais des Chagrins, une plage lugubre où ne poussent guère que le bois flotté et la pourriture. Des crocilisques se prélassent dans ses hauts-fonds, et crabes et murlocs occupent le rivage au-delà.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Strand",
		},
		["misty valley"] = {
			name = "Vallée des brumes",
			short = "La brume flotte bas sur ce recoin du Marais des Chagrins, assez épaisse pour étouffer les sons. Au fond d'une grotte, au bout de la vallée, demeurait le Seigneur de la fange, une force élémentaire.",
			full = "La brume flotte bas sur ce recoin du Marais des Chagrins, assez épaisse pour étouffer les sons. Au fond d'une grotte, au bout de la vallée, demeurait le Seigneur de la fange, une force élémentaire.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Valley",
		},
		["pool of tears"] = {
			name = "Bassin des larmes",
			short = "Le Bassin des larmes s'étend, large et immobile, à la lisière orientale du Marais des Chagrins. Sous sa surface calme repose le temple d'Atal'Hakkar, englouti là par Ysera après que les trolls l'eurent élevé, caché au monde.",
			full = "Le Bassin des larmes s'étend, large et immobile, à la lisière orientale du Marais des Chagrins. Sous sa surface calme repose le temple d'Atal'Hakkar, englouti là par Ysera après que les trolls l'eurent élevé, caché au monde. Le vol draconique vert veilla longtemps sur ce lieu noyé, pour empêcher que rien ne réveille ce qui dormait en dessous.\n\nDes poissons frénétiques assoiffés de sang parcourent désormais l'eau, et des fragments de maçonnerie atal'ai jonchent la rive.",
			source = "https://warcraft.wiki.gg/wiki/Pool_of_Tears",
		},
		["shifting mire"] = {
			name = "Le Bourbier changeant",
			short = "Le limon de la Fange mouvante n'est jamais immobile. Il s'amasse sur le sol en fines congères et rampe à travers le marais comme si quelque chose d'invisible l'entraînait, s'enroulant et s'accumulant comme une chose vivante.",
			full = "Le limon de la Fange mouvante n'est jamais immobile. Il s'amasse sur le sol en fines congères et rampe à travers le marais comme si quelque chose d'invisible l'entraînait, s'enroulant et s'accumulant comme une chose vivante.\n\nCertains disent que la force derrière ce mouvement n'est pas malveillante, mais qu'il s'agit d'une énergie bienfaisante qui remue le limon sans aucune volonté de nuire.",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
		},
		["sorrowmurk"] = {
			name = "Noirchagrin",
			short = "Noirchagrin s'étend à l'est du Bassin des larmes, près du Temple englouti.",
			full = "Noirchagrin s'étend à l'est du Bassin des larmes, près du Temple englouti. Il appartient aux dragons : des draconides verts rampent dans sa fange sous la surveillance d'un grand drake vert, qui tient à distance tous les voyageurs, hormis les plus téméraires.",
			source = "https://warcraft.wiki.gg/wiki/Sorrowmurk",
		},
		["splinterspear junction"] = {
			name = "Croisement de Lance-brisée",
			short = "Là où la route qui pénètre dans le Marais des Chagrins se divise, une vieille tour de guet orque se dresse toujours, et des patrouilles de la Horde gardent le carrefour à l'œil.",
			full = "Là où la route qui pénètre dans le Marais des Chagrins se divise, une vieille tour de guet orque se dresse toujours, et des patrouilles de la Horde gardent le carrefour à l'œil.\n\nLa tour est ce qui reste de Kyross, un avant-poste orc élevé ici pendant la première guerre. Kyross était plus proche du bourg humain de Grand Hamlet que toute autre position de la Horde dans le marais, et Stormwind ne pouvait le tolérer. Des troupes furent envoyées pour le raser.\n\nLa tour surveille toujours la bifurcation de la route.",
			source = "https://warcraft.wiki.gg/wiki/Splinterspear_Junction",
		},
		["stagalbog"] = {
			name = "Stagalbog",
			short = "Au sud du Bassin des larmes, là où le Marais des Chagrins s'élève vers les montagnes, le marécage s'épaissit pour former le Stagalbog. À l'ouest de cette étendue sauvage et détrempée, au pied de la montagne, une grotte s'ouvre dans la roche.",
			full = "Au sud du Bassin des larmes, là où le Marais des Chagrins s'élève vers les montagnes, le marécage s'épaissit pour former le Stagalbog. À l'ouest de cette étendue sauvage et détrempée, au pied de la montagne, une grotte s'ouvre dans la roche.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog",
		},
		["stagalbog cave"] = {
			name = "Caverne de Stagalbog",
			short = "Dans l'est du Stagalbog, au Marais des Chagrins, une grotte s'ouvre dans la fange.",
			full = "Dans l'est du Stagalbog, au Marais des Chagrins, une grotte s'ouvre dans la fange.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog_Cave",
		},
		["stonard"] = {
			name = "Stonard",
			short = "Stonard surgit de la fange du Marais des Chagrins, sa grande salle toujours debout là où tant d'autres salles orques sont depuis longtemps tombées.",
			full = "Stonard surgit de la fange du Marais des Chagrins, sa grande salle toujours debout là où tant d'autres salles orques sont depuis longtemps tombées. Deux terriers en gardent l'accès, et des patrouilles orques partent tenir les petits campements voisins, autant de revendications plantées contre le marais.\n\nL'avant-poste est ancien, plus ancien que presque tout autre point d'appui orc de ce côté du monde, frère de la forteresse jadis appelée Rockard. Il fut élevé par l'ancienne Horde dans le Noir Marécage, aux jours qui suivirent la première ouverture de la Porte des ténèbres. Lorsque vint la deuxième guerre et que la Horde se brisa, Stonard se tut, probablement abandonné ou détruit comme tant d'autres ouvrages des orcs.\n\nIl ne resta pas vide. Avec l'essor de la nouvelle Horde et une volonté renouvelée de tenir cette terre, Stonard fut rebâti, sa salle restaurée, ses terriers creusés de nouveau. Rockard n'eut pas cette chance : les ogres Cognepeur s'emparèrent de la vieille forteresse et la rebaptisèrent Bastion Cognepeur, laissant Stonard seul avant-poste de la Horde dans le marais, la dernière salle de son espèce encore éclairée dans ces basses terres.",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "Le temple d'Atal'Hakkar",
			short = "Il y a plus de mille ans, l'empire Gurubashi se déchira dans une guerre civile. En son cœur se trouvaient les Atal'ai, des prêtres trolls qui cherchaient à ramener dans le monde le dieu du sang Hakkar l'Écorcheur d'âmes.",
			full = "Il y a plus de mille ans, l'empire Gurubashi se déchira dans une guerre civile. En son cœur se trouvaient les Atal'ai, des prêtres trolls qui cherchaient à ramener dans le monde le dieu du sang Hakkar l'Écorcheur d'âmes. Vaincus et exilés, ils s'enfuirent vers le nord, dans le Marais des Chagrins, et y élevèrent un temple pour préparer son retour.\n\nL'Aspect dragon Ysera eut vent de leur projet et engloutit le temple sous le marais, dans l'intention d'enterrer leur œuvre à jamais. Il n'en alla pas ainsi. Tranquilles dans l'obscurité noyée, à l'abri de tout regard qui aurait pu les arrêter, les Atal'ai poursuivirent leurs rituels en paix. Les dragons verts qu'Ysera chargea de garder les ruines y veillent depuis lors, tenant close une porte qui ne fut jamais vraiment scellée.\n\nLe temple repose toujours englouti et à demi inondé, ses autels à Hakkar intacts, et ceux qui y entrent risquent pire que la mort. Le loa du Sang réclame des âmes autant que de la chair, et chacune de celles qu'on lui donne nourrit le jour où il n'échouera pas.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
	},
	-- Marche de l'Ouest: 17 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "Ferme des Alexston",
			short = "Les champs de la Ferme des Alexston nourrissaient jadis des familles, avant que la Confrérie défias ne s'empare de la terre.",
			full = "Les champs de la Ferme des Alexston nourrissaient jadis des familles, avant que la Confrérie défias ne s'empare de la terre. Désormais, seuls les Gardiens des moissons mécaniques se déplacent entre les sillons, infatigables et sans surveillance, gardant des rangs que plus personne ne sème.\n\nBaros Alexston, devenu architecte au service de la Cité de Stormwind, est né sur cette terre. Il y travailla enfant, dans ces mêmes champs que patrouillent aujourd'hui les Gardiens des moissons, avant que la terre qui l'avait façonné ne passe en d'autres mains.",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
		},
		["dagger hills"] = {
			name = "Les collines de la Dague",
			short = "Les collines de la Dague forment une crête derrière Ruisselune, dans le sud de la Marche de l'Ouest. Peu de choses y bougent aujourd'hui.",
			full = "Les collines de la Dague forment une crête derrière Ruisselune, dans le sud de la Marche de l'Ouest. Peu de choses y bougent aujourd'hui. Grimbooze Thunderbrew se tient parmi les collines, l'une des rares âmes vivantes que l'on puisse trouver dans ce coin tranquille, et l'on sait que la goule Leprithus y surgit aussi de terre.",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Hills",
		},
		["dead acre"] = {
			name = "L'acre mort",
			short = "L'acre mort était jadis une ferme parmi d'autres dans le sud-est de la Marche de l'Ouest, près du pont menant au Bois de la Pénombre. Lorsque la Confrérie défias s'empara de la région, elle prit la ferme qui s'y dressait, ainsi que ses champs.",
			full = "L'acre mort était jadis une ferme parmi d'autres dans le sud-est de la Marche de l'Ouest, près du pont menant au Bois de la Pénombre. Lorsque la Confrérie défias s'empara de la région, elle prit la ferme qui s'y dressait, ainsi que ses champs.\n\nAucun fermier ne la parcourt plus. Ce sont des Gardiens des moissons mécaniques qui arpentent la terre, errant là où poussait autrefois une récolte.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Acre",
		},
		["deadmines"] = {
			name = "Les Mortemines",
			short = "Sous Ruisselune, les tunnels s'enfoncent profondément, et jadis l'or y coulait à flots. Bien avant que les orcs ne pénètrent sur les terres humaines, les Mortemines alimentaient le trésor de Stormwind : selon certains récits, un tiers en provenait de cette roche.",
			full = "Sous Ruisselune, les tunnels s'enfoncent profondément, et jadis l'or y coulait à flots. Bien avant que les orcs ne pénètrent sur les terres humaines, les Mortemines alimentaient le trésor de Stormwind : selon certains récits, un tiers en provenait de cette roche. La première guerre vida les mines de leurs mineurs, et par la suite elles furent laissées à l'abandon, réputées hantées, et restèrent longtemps intactes.\n\nDans ce silence arriva Edwin VanCleef, qui rassembla la Confrérie défias, d'anciens ouvriers devenus brigands, et leur fit construire un mastodonte dans les profondeurs avec l'aide des gobelins.\n\nC'est dans ces profondeurs que demeure VanCleef, gardé par sa Confrérie, tandis que Gryan Stoutmantle rassemble à la Colline des sentinelles des hommes qui ont juré de rapporter sa tête.",
			source = "https://warcraft.wiki.gg/wiki/Deadmines",
		},
		["demonts place"] = {
			name = "Maison de Demont",
			short = "Il ne reste guère de la Maison de Demont que des poutres brisées et des champs envahis par les herbes, à l'ouest de Ruisselune. Jadis une ferme en activité, elle est aujourd'hui occupée par des agents défias, qui la tiennent pour leur.",
			full = "Il ne reste guère de la Maison de Demont que des poutres brisées et des champs envahis par les herbes, à l'ouest de Ruisselune. Jadis une ferme en activité, elle est aujourd'hui occupée par des agents défias, qui la tiennent pour leur.",
			source = "https://warcraft.wiki.gg/wiki/Demont's_Place",
		},
		["dust plains"] = {
			name = "Les Plaines de poussière",
			short = "Les Plaines de poussière s'étendent sur le sud de la Marche de l'Ouest, une terre aride livrée aux gnolls, qui y tiennent quelques camps épars et menacent quiconque traverse leur territoire.",
			full = "Les Plaines de poussière s'étendent sur le sud de la Marche de l'Ouest, une terre aride livrée aux gnolls, qui y tiennent quelques camps épars et menacent quiconque traverse leur territoire.\n\nÀ la lisière orientale se dresse la tour de Mortwake, une ancienne tour de mage dont la vocation première a depuis longtemps cédé la place à de nouveaux maîtres.",
			source = "https://warcraft.wiki.gg/wiki/Dust_Plains",
		},
		["furlbrows pumpkin farm"] = {
			name = "Ferme de potirons de Furlbrow",
			short = "Le champ de potirons de Furlbrow était jadis entretenu par Furlbrow le fermier et sa femme Verna, mais lorsque la Confrérie défias déferla sur la Marche de l'Ouest avec ses golems des moissons mécaniques, la ferme tomba comme tant d'autres dans ce pays.",
			full = "Le champ de potirons de Furlbrow était jadis entretenu par Furlbrow le fermier et sa femme Verna, mais lorsque la Confrérie défias déferla sur la Marche de l'Ouest avec ses golems des moissons mécaniques, la ferme tomba comme tant d'autres dans ce pays. Furlbrow et Verna s'enfuirent, trouvant refuge sur la route près de la ferme des Jansen, au nord, laissant derrière eux leurs potirons et leur nom.",
			source = "https://warcraft.wiki.gg/wiki/Furlbrow's_Pumpkin_Farm",
		},
		["gold coast quarry"] = {
			name = "Carrière de la côte de l'Or",
			short = "La Carrière de la côte de l'Or fournissait jadis or et minerai à Stormwind, avant que la Marche de l'Ouest ne tombe en ruine. La Confrérie défias la tient désormais, exploitant les fosses sous sa propre bannière.",
			full = "La Carrière de la côte de l'Or fournissait jadis or et minerai à Stormwind, avant que la Marche de l'Ouest ne tombe en ruine. La Confrérie défias la tient désormais, exploitant les fosses sous sa propre bannière. La Milice du peuple et ses membres s'y sont heurtés à la Confrérie, pris en embuscade par des Défias parmi les pierres qu'ils continuent de patrouiller.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Coast_Quarry",
		},
		["jangolode mine"] = {
			name = "Mine de Jangolode",
			short = "La Mine de Jangolode fournissait jadis du minerai à Stormwind, l'une des sources les plus régulières de richesses minérales de la Marche de l'Ouest.",
			full = "La Mine de Jangolode fournissait jadis du minerai à Stormwind, l'une des sources les plus régulières de richesses minérales de la Marche de l'Ouest.\n\nCette régularité prit fin lorsque la Confrérie défias s'empara de la mine. Des kobolds se sont depuis glissés dans ses puits et se les sont appropriés.",
			source = "https://warcraft.wiki.gg/wiki/Jangolode_Mine",
		},
		["jansen stead"] = {
			name = "La ferme des Jansen",
			short = "La ferme des Jansen se trouve à la lisière nord de la Marche de l'Ouest, tout près du pont qui mène à la forêt d'Elwynn. Comme les autres fermes de la région, elle fut vidée de ses propriétaires légitimes lorsque la Confrérie défias les chassa.",
			full = "La ferme des Jansen se trouve à la lisière nord de la Marche de l'Ouest, tout près du pont qui mène à la forêt d'Elwynn. Comme les autres fermes de la région, elle fut vidée de ses propriétaires légitimes lorsque la Confrérie défias les chassa.\n\nNon loin se tiennent Furlbrow le fermier et sa femme, qui ont fui leur propre foyer au champ de potirons de Furlbrow et s'abritent désormais à la ferme.",
			source = "https://warcraft.wiki.gg/wiki/Jansen_Stead",
		},
		["longshore"] = {
			name = "Longrivage",
			short = "La côte de la Marche de l'Ouest s'étend, longue et déserte, l'une des plus vastes plages d'Azeroth.",
			full = "La côte de la Marche de l'Ouest s'étend, longue et déserte, l'une des plus vastes plages d'Azeroth. Des murlocs la parcourent en nombre trop grand pour être contenus, et parmi eux nage Old Murk-Eye, une créature que les pêcheurs de la côte ont appris à craindre et à nommer. Au-delà des brisants gisent les carcasses de navires qui n'atteignirent jamais le rivage, parmi lesquels des destroyers elfes, livrés à la marée.\n\nÀ l'extrémité sud-ouest de la plage se trouve la ferme de Daphne Stilwell. La Confrérie défias s'en prit à elle plus d'une fois, dans l'intention de l'incendier comme elle avait incendié tant d'autres choses dans la Marche de l'Ouest. La nouvelle de ses ennuis parvint à Duthorian Rall, qui envoya des aspirants chevaliers de la Main d'argent sur la côte pour veiller sur sa terre, et ils la tinrent.",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "La ferme des Molsen",
			short = "La ferme des Molsen compte parmi les nombreuses fermes de la Marche de l'Ouest tenues par la Confrérie défias.",
			full = "La ferme des Molsen compte parmi les nombreuses fermes de la Marche de l'Ouest tenues par la Confrérie défias. Ses rangs sont livrés à la rouille et aux machines, et des Gardiens des moissons mécaniques errent dans les champs, abattant quiconque s'approche de trop près.",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "Ruisselune",
			short = "Sous les champs de Ruisselune passait jadis un tiers du trésor de Stormwind, l'or tiré des tunnels que l'on appela plus tard les Mortemines.",
			full = "Sous les champs de Ruisselune passait jadis un tiers du trésor de Stormwind, l'or tiré des tunnels que l'on appela plus tard les Mortemines. Le bourg était le grenier du royaume, jusqu'à ce que la dissolution de la guilde des Maçons déclenche des émeutes qui coûtèrent la vie à la reine Tiffin Wrynn. La vengeance du roi Varian pour sa mort s'abattit le plus durement sur la guilde, et les maçons s'enfuirent dans les terres agricoles de la Marche de l'Ouest pour lui échapper. Attisée dans l'ombre, leur colère devint la Confrérie défias. Sous la conduite d'Edwin VanCleef, ils se tournèrent vers le brigandage, chassèrent les fermiers de Ruisselune et firent des tunnels de mine abandonnés sous le bourg leur quartier général, y travaillant en secret à construire une arme destinée à détruire Stormwind depuis la mer.\n\nDepuis des années, aucune armée n'est venue leur répondre. La Confrérie tient toujours Ruisselune, et seule la Milice du peuple de Gryan Stoutmantle leur tient tête, rassemblant ses forces à la Colline des sentinelles en vue d'un règlement de comptes encore à venir.",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["saldeans farm"] = {
			name = "Ferme des Saldean",
			short = "La ferme des Saldean est la seule de la Marche de l'Ouest à n'avoir jamais été envahie par la Confrérie défias. Des golems des moissons défias errent dans ses champs, mais Saldean le fermier et sa femme Salma ont refusé de partir.",
			full = "La ferme des Saldean est la seule de la Marche de l'Ouest à n'avoir jamais été envahie par la Confrérie défias. Des golems des moissons défias errent dans ses champs, mais Saldean le fermier et sa femme Salma ont refusé de partir. Leur ferme sert depuis des années de maison d'accueil, le couple faisant ce qu'il peut pour garder ses hôtes en vie.",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "Colline des sentinelles",
			short = "La Colline des sentinelles se dresse sur les hauteurs dominant les terres agricoles de la Marche de l'Ouest, sa tour veillant sur les chaumières, la forge et le moulin bâtis sur la pente en contrebas.",
			full = "La Colline des sentinelles se dresse sur les hauteurs dominant les terres agricoles de la Marche de l'Ouest, sa tour veillant sur les chaumières, la forge et le moulin bâtis sur la pente en contrebas.\n\nLes gnolls Riverpaw comme la Confrérie défias ont frappé la colline et les terres qu'elle protège.",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["stendels pond"] = {
			name = "Etang de Stendel",
			short = "Un petit étang s'étend au sud-ouest de la Colline des sentinelles, ses eaux devenues immobiles sous la garde d'un cercle de gnolls.",
			full = "Un petit étang s'étend au sud-ouest de la Colline des sentinelles, ses eaux devenues immobiles sous la garde d'un cercle de gnolls. Deux tombes reposent sur sa rive, avec de vieux ossements épars, et quelque chose dans l'eau semble anormal, comme si elle n'était plus jamais destinée à être bue.\n\nLes pêcheurs qui y tentent leur chance remontent surtout des saumons-sauge ordinaires. Mais on dit que quelque chose d'autre nage sous la surface, un poisson appelé le Fléau de Stendel, rarement vu et plus rarement encore pris.",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "Phare de l'Ouest",
			short = "Le phare se dresse à l'extrême sud de la Marche de l'Ouest, son faisceau balayant toujours les eaux la nuit, bien que la main qui l'entretient désormais appartienne à un mort.",
			full = "Le phare se dresse à l'extrême sud de la Marche de l'Ouest, son faisceau balayant toujours les eaux la nuit, bien que la main qui l'entretient désormais appartienne à un mort.\n\nUne famille entretenait jadis la flamme, jusqu'à ce que le murloc Old Murk-Eye surgisse du ressac et la fasse fuir, terrorisée. Elle revint et ralluma le feu, mais Old Murk-Eye revint aussi, et cette fois il amena avec lui les murlocs de la côte pour attaquer le phare. La famille n'y survécut pas. Grayson les vit mourir devant lui, impuissant, et c'est son fantôme qui entretient désormais la lumière, montant la garde devant la tour sans plus personne pour le relever.",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- Les Paluns: 23 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "Campement de Hargnecroc",
			short = "Le Campement de Hargnecroc s'étend dans le centre des Paluns, le plus grand camp que le clan Gueule-de-dragon tienne dans la région, foyer des orcs Hargnecroc.",
			full = "Le Campement de Hargnecroc s'étend dans le centre des Paluns, le plus grand camp que le clan Gueule-de-dragon tienne dans la région, foyer des orcs Hargnecroc.\n\nSous les ordres de Nek'rosh Skullcrusher, fils de Nekros Skullcrusher, le camp est devenu une base d'assaut, où s'amassent des catapultes destinées à attaquer le Port de Menethil. La menace est assez réelle pour que le capitaine Stoutfist ait juré de voir Nek'rosh mort et les bannières de guerre du clan arrachées avant que les catapultes ne se mettent en branle.",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "Baie de Baradin",
			short = "Les eaux de la baie de Baradin baignent la côte où Khaz Modan rejoint Lordaeron, touchant les rivages du Port de Menethil et du Donjon de Stromgarde.",
			full = "Les eaux de la baie de Baradin baignent la côte où Khaz Modan rejoint Lordaeron, touchant les rivages du Port de Menethil et du Donjon de Stromgarde. Murlocs et crocilisques dérivent dans ses hauts-fonds, tandis que requins et crabes occupent les eaux plus profondes.\n\nLa véritable histoire de la baie gît brisée au fond de ses eaux. Pendant la deuxième guerre, l'armada de Kul Tiras patrouillait ces eaux, défendant la côte contre la guerre qui se répandait à travers les Royaumes de l'est. Mais Kul Tiras paya cher cette vigilance : la Troisième flotte du royaume fut détruite dans les combats. Certaines de ses épaves gisent encore fracassées le long de la côte des Paluns, visibles dans les hauts-fonds où elles se brisèrent, tandis que d'autres sombrèrent entièrement, reposant dans l'obscurité en contrebas, où nul ne les a relevées depuis.",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "Marais des eaux-noires",
			short = "La route du Port de Menethil longe le Marais des eaux-noires, dans le sud-ouest des Paluns.",
			full = "La route du Port de Menethil longe le Marais des eaux-noires, dans le sud-ouest des Paluns. Des raptors nichent dans tout le marécage, et les plus affamés s'aventurent près du bord de la route, si bien que les voyageurs qui empruntent ce tronçon ont intérêt à rester sur leurs gardes.",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "Marais des Branchies-bleues",
			short = "Les eaux du Marais des Branchies-bleues, dans l'ouest des Paluns, abritent des camps de murlocs Branchies-bleues, qui ne se déplacent jamais seuls mais par deux ou trois parmi les roseaux.",
			full = "Les eaux du Marais des Branchies-bleues, dans l'ouest des Paluns, abritent des camps de murlocs Branchies-bleues, qui ne se déplacent jamais seuls mais par deux ou trois parmi les roseaux. À leur tête se trouve Gobbler, un murloc plus féroce que les autres, dont la présence fait du marais un lieu où il vaut mieux entrer avec prudence.",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "Taverne de l'Eau-profonde",
			short = "La Taverne de l'Eau-profonde se trouve au Port de Menethil, sa salle commune bruissant des conversations des marins de passage.",
			full = "La Taverne de l'Eau-profonde se trouve au Port de Menethil, sa salle commune bruissant des conversations des marins de passage. C'est un lieu mal famé : on y lance des chaises aussi souvent qu'on y sert de la bière, et les bagarres éclatent souvent à l'instigation de Tapoke « Slim » Jahn.",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "Colline de Morneforge",
			short = "La Colline de Morneforge fut jadis un important campement des nains Sombrefer, menés par le démoniste Balgaras le Crasseux.",
			full = "La Colline de Morneforge fut jadis un important campement des nains Sombrefer, menés par le démoniste Balgaras le Crasseux.",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "Portes des Dragonmaw",
			short = "Les Portes des Dragonmaw sont gardées par le vol draconique rouge sous les ordres du drake Axtroz, qui barre le chemin à ceux qui cherchent à atteindre Grim Batol.",
			full = "Les Portes des Dragonmaw sont gardées par le vol draconique rouge sous les ordres du drake Axtroz, qui barre le chemin à ceux qui cherchent à atteindre Grim Batol.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "Le tunnel de Dun Algaz est plus ancien que la querelle qui divisa les nains. Lorsque la guerre des Trois clans chassa les Marteau-hardi d'Ironforge, c'est par ce col qu'ils battirent en retraite.",
			full = "Le tunnel de Dun Algaz est plus ancien que la querelle qui divisa les nains. Lorsque la guerre des Trois clans chassa les Marteau-hardi d'Ironforge, c'est par ce col qu'ils battirent en retraite.\n\nIl vit aussi passer la retraite de la Horde. Repoussés de Dun Modr, les orcs se replièrent vers le sud à travers la vallée de Thandol et se retranchèrent dans l'avant-poste d'ici, et Anduin Lothar, voulant les chasser entièrement de Khaz Modan, envoya ses forces raser la place forte. L'assaut échoua. Les orcs tinrent bon, et Dun Algaz devint le dernier territoire que la Horde conserva dans la région, un point d'appui dont on ne put la déloger.\n\nLes montagnards nains qui surveillaient ce col se tenaient surtout sur les collines qui le dominent, mais le clan Gueule-de-dragon envahit leur poste et les repoussa jusqu'au tunnel supérieur, où ils tiennent toujours. Le col inférieur perdu, la route entre les terres natales des nains et le Port de Menethil est devenue bien plus dangereuse.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "Dun Modr",
			short = "Dun Modr se dresse au sud du Viaduc de Thandol, une ancienne cité naine depuis longtemps tombée en ruine, dont la forge et l'auberge-brasserie se dressent encore au milieu des décombres que les nains Sombrefer revendiquent désormais comme leurs.",
			full = "Dun Modr se dresse au sud du Viaduc de Thandol, une ancienne cité naine depuis longtemps tombée en ruine, dont la forge et l'auberge-brasserie se dressent encore au milieu des décombres que les nains Sombrefer revendiquent désormais comme leurs.\n\nPendant la deuxième guerre, la Horde orque s'empara des ruines et y bâtit un avant-poste, dont elle se servit pour repousser les troupes de l'Alliance et piller les terres agricoles alentour, une base d'assaut vitale pour ses armées. Des guerriers de Stromgarde partirent de la citadelle insulaire de Tol Barad pour briser cet avant-poste, l'assiégeant et repoussant les orcs vers le sud jusqu'à leur place forte secondaire de Dun Algaz. La Horde contre-attaqua, reprit Dun Modr et tourna ses forces contre Tol Barad elle-même. Ce n'est que lorsque la Horde se brisa devant la Capitale qu'Anduin Lothar la repoussa par le Viaduc de Thandol jusqu'en Khaz Modan, et Dun Modr passa à l'Alliance.\n\nCette paix ne dura pas. Les soldats d'Ironforge épuisés par des guerres menées loin de chez eux, les nains Sombrefer déferlèrent sur le Viaduc de Thandol, et Dun Modr tomba peu après sous le démoniste Balgaras le Crasseux, qui tient désormais la cité que son peuple a revendiquée comme sienne.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["green belt"] = {
			name = "La Ceinture verte",
			short = "La Ceinture verte grouille de crocilisques, de bêtes des tourbières et de limons, et Rethiel le Gardien vert y monte la garde, en colère contre une terre devenue étrange et inquiète.",
			full = "La Ceinture verte grouille de crocilisques, de bêtes des tourbières et de limons, et Rethiel le Gardien vert y monte la garde, en colère contre une terre devenue étrange et inquiète.\n\nÀ l'ouest, des bêtes de la fange sont devenues malveillantes. Au nord-est, des élémentaires de feu surgissent inopinément de la Colline de Morneforge. Ce sont deux blessures infligées à la terre que garde Rethiel, et aucune ne s'est refermée.\n\nAu sein de la Ceinture gît une caravane naufragée du clan Gueule-de-dragon, où des dragonnets rouges ont désormais leur tanière parmi les débris, tout ce qui reste d'une tentative de voler les petits du vol draconique noir, qui connut sa fin ici, engloutie par le marais.",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["grim batol"] = {
			name = "Grim Batol",
			short = "Grim Batol est une forteresse de montagne située dans l'est des Paluns. Elle possède de grands murs et des flèches qui s'élèvent vers un ciel gris acier, mais l'essentiel de la place forte se trouve sous terre.",
			full = "Grim Batol est une forteresse de montagne située dans l'est des Paluns. Elle possède de grands murs et des flèches qui s'élèvent vers un ciel gris acier, mais l'essentiel de la place forte se trouve sous terre. Elle fut fondée par les nains Marteau-hardi, jusqu'à ce qu'elle soit maudite pendant la guerre des Trois clans. Elle fut plus tard prise par les orcs pour servir de prison à l'Aspect dragon Alexstrasza, jusqu'à ce que celle-ci soit libérée lors de la bataille de Grim Batol.",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "Tombe d'Ironbeard",
			short = "La Tombe d'Ironbeard se trouve à l'ouest de la route de Dun Modr, dans le centre-nord des Paluns. Une statue naine domine le cimetière, sans doute sculptée à l'image d'Ironbeard lui-même.",
			full = "La Tombe d'Ironbeard se trouve à l'ouest de la route de Dun Modr, dans le centre-nord des Paluns. Une statue naine domine le cimetière, sans doute sculptée à l'image d'Ironbeard lui-même.\n\nLes morts n'y reposent plus en paix. Des limons noirs, pourpres et de teintes monstrueuses se sont glissés dans la crypte et l'ont profanée, se répandant dans le cimetière au point que plus personne ne souhaitant enterrer les siens ne s'approche désormais du lieu.",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "La flotte perdue",
			short = "Les épaves de la Maîtresse des vagues et de l'Intrépide reposent au fond de la baie de Baradin, au large de la côte nord du Marais des Branchies-bleues.",
			full = "Les épaves de la Maîtresse des vagues et de l'Intrépide reposent au fond de la baie de Baradin, au large de la côte nord du Marais des Branchies-bleues.\n\nIls faisaient partie de la Troisième flotte de Kul Tiras, commandée par Derek Portvaillant, fils aîné du grand amiral Daelin Portvaillant, pendant la deuxième guerre. Lors de la bataille de Crestfall, des dragons rouges asservis par le clan Gueule-de-dragon tombèrent du ciel et mirent le feu à la flotte. Derek grimpa dans le nid-de-pie pour avertir son père du danger. Un dragon l'y tua avant que l'avertissement puisse servir, et son navire sombra peu après avec le reste de la flotte. Un seul homme survécut, le premier officier Fitzsimmons, de la Maîtresse des vagues.\n\nLes morts ne restèrent pas tranquilles. Au fond de la cale de l'Intrépide, son commandant, le capitaine Halyndor, avait caché par cupidité un orbe noirci : l'Œil maudit de Paleth. Sa malédiction atteignit l'équipage englouti des années plus tard, le liant à la non-mort. Seul le premier officier Snellig garda sa raison, et son fantôme erre encore sur le rivage voisin.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["menethil bay"] = {
			name = "Baie de Menethil",
			short = "La baie de Menethil s'étend entre le port et les falaises de Dun Morogh, nichée dans l'anse de la baie de Baradin.",
			full = "La baie de Menethil s'étend entre le port et les falaises de Dun Morogh, nichée dans l'anse de la baie de Baradin.\n\nPrès de l'entrée de la baie reposent les débris du Balbuzard volant, sa coque brisée posée dans l'eau.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "Port de Menethil",
			short = "Le mur est la première chose que l'on remarque, une épaisse muraille de pierre dressée autour d'une ville portuaire assise pour moitié sur la roche, pour moitié sur la mer.",
			full = "Le mur est la première chose que l'on remarque, une épaisse muraille de pierre dressée autour d'une ville portuaire assise pour moitié sur la roche, pour moitié sur la mer. Quatre tours la dominent, surveillant l'eau comme la route, et l'on n'y entre que par le pont, par la marée ou par un passage secret qui court sous terre jusqu'au continent.\n\nCe furent les orcs qui élevèrent ici le premier chantier naval. Après la première guerre, le chef de guerre Orgrim Marteau du Destin choisit ce rivage pour construire la flotte qui devait porter la Horde au-delà des défenses terrestres de Lordaeron, dépouillant pour cela les mines naines de Khaz Modan de leur fer et de leur bois. À la fin de la deuxième guerre, l'Alliance prit le lieu et le rebâtit pour son propre compte, et le grand amiral Daelin Portvaillant le nomma Port de Menethil, en l'honneur de Terenas Menethil II, roi de Lordaeron.\n\nPendant des années, des raptors descendirent des collines pour attaquer la ville, jamais en grand nombre, mais assez souvent.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "Donjon de Menethil",
			short = "Quatre tours s'élèvent au-dessus du Port de Menethil, veillant sur la ville en contrebas tels de sévères gardiens. C'est le Donjon de Menethil.",
			full = "Quatre tours s'élèvent au-dessus du Port de Menethil, veillant sur la ville en contrebas tels de sévères gardiens. C'est le Donjon de Menethil.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
		},
		["mosshide fen"] = {
			name = "Marais des Poils-moussus",
			short = "Le Marais des Poils-moussus est une étendue détrempée de l'est des Paluns, dont le sol est parsemé des camps des gnolls Poils-moussus. La tribu tient le marais, capturant et dévorant quiconque s'aventure trop loin dans les marécages.",
			full = "Le Marais des Poils-moussus est une étendue détrempée de l'est des Paluns, dont le sol est parsemé des camps des gnolls Poils-moussus. La tribu tient le marais, capturant et dévorant quiconque s'aventure trop loin dans les marécages.",
			source = "https://warcraft.wiki.gg/wiki/Mosshide_Fen",
		},
		["raptor ridge"] = {
			name = "Crête des raptors",
			short = "La Crête des raptors s'élève dans l'est des Paluns, au nord-ouest des Portes des Dragonmaw, ses pentes et sa caverne grouillant de raptors. Tout au fond, la matriarche tranchegueules couve sa nichée.",
			full = "La Crête des raptors s'élève dans l'est des Paluns, au nord-ouest des Portes des Dragonmaw, ses pentes et sa caverne grouillant de raptors. Tout au fond, la matriarche tranchegueules couve sa nichée.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Ridge",
		},
		["saltspray glen"] = {
			name = "Vallon des embruns",
			short = "Le Vallon des embruns se trouve là où les Paluns rejoignent la baie de Baradin, entre le Marais des Branchies-bleues et la Tombe d'Ironbeard.",
			full = "Le Vallon des embruns se trouve là où les Paluns rejoignent la baie de Baradin, entre le Marais des Branchies-bleues et la Tombe d'Ironbeard. Son nom lui vient du vent : lorsqu'il souffle fort depuis la baie, l'océan projette ici ses embruns loin à l'intérieur des terres, plus loin que partout ailleurs sur ce rivage, jusqu'à laisser le sol lui-même glissant de sel. Les raptors nichent en nombre dans tout le vallon, comme dans le marais et sur la crête voisins.",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["sundown marsh"] = {
			name = "Marais du couchant",
			short = "Au fin fond du nord-ouest des Paluns s'étend le Marais du couchant, grouillant de crocilisques, de gnolls, de raptors, de bêtes des tourbières et de limons qui tiennent à distance la plupart des voyageurs.",
			full = "Au fin fond du nord-ouest des Paluns s'étend le Marais du couchant, grouillant de crocilisques, de gnolls, de raptors, de bêtes des tourbières et de limons qui tiennent à distance la plupart des voyageurs. En son cœur se dresse la station Swiftgear, une petite demeure de pierre flanquée d'un moulin à vent, où Fradd Swiftgear et Wenna Silkbeard ont élu domicile. Le couple fait commerce de ce que le marais produit, d'objets étranges tirés de la boue, et de recettes rarement trouvées ailleurs.",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["thandol span"] = {
			name = "Viaduc de Thandol",
			short = "Deux grandes arches de pierre enjambent le gouffre entre les Paluns et les Hautes-terres d'Arathi, élevées par des mains naines et gardées depuis trois générations par la lignée des Anvilmar.",
			full = "Deux grandes arches de pierre enjambent le gouffre entre les Paluns et les Hautes-terres d'Arathi, élevées par des mains naines et gardées depuis trois générations par la lignée des Anvilmar. Elles furent construites après la guerre des Trois clans, lorsque Ironforge voulut rester fidèle à ses frères Marteau-hardi du Nid-de-l'Aigle, et les ponts devinrent à la fois une route et un symbole entre les deux royaumes nains, portant un commerce qui les enrichissait tous deux.\n\nLes ponts sont aujourd'hui balafrés. Kam Deepfury et Balgaras le Crasseux menèrent les nains Sombrefer contre le Viaduc, abattant entièrement l'une des deux arches et prenant presque la seconde. Les forces naines se battirent farouchement pour défendre ce qui restait et reprendre la ville voisine de Dun Modr, et beaucoup moururent dans ces combats, parmi lesquels Sully Balloo, Ebenezer Rustlocke et le frère de Longbraid le Macabre. Les Sombrefer tiennent toujours les ruines, et Balgaras le Crasseux vit encore parmi eux.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "Rocher de Thelgen",
			short = "Le Rocher de Thelgen s'élève dans le sud des Paluns, ses cavernes s'enfonçant profondément dans la montagne, grouillantes d'araignées venimeuses qui tissent leur soie dans chaque crevasse.",
			full = "Le Rocher de Thelgen s'élève dans le sud des Paluns, ses cavernes s'enfonçant profondément dans la montagne, grouillantes d'araignées venimeuses qui tissent leur soie dans chaque crevasse. Quelque part dans les tunnels les plus profonds se trouvent des filons de minerai d'incendicite, gardés par le nombre des araignées.",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
		},
		["whelgars excavation site"] = {
			name = "Excavations de Whelgar",
			short = "Le site de fouilles à l'est du Port de Menethil était jadis un paisible chantier pour des nains qui creusaient une terre plus ancienne que la mémoire. Puis des raptors tachetés l'envahirent, acculant les fouilleurs sur une crête au-dessus de leurs propres excavations.",
			full = "Le site de fouilles à l'est du Port de Menethil était jadis un paisible chantier pour des nains qui creusaient une terre plus ancienne que la mémoire. Puis des raptors tachetés l'envahirent, acculant les fouilleurs sur une crête au-dessus de leurs propres excavations. Ils ne tinrent pas, et abandonnèrent le site pour un camp de leur cru à l'écart de la route principale, la Retraite de Whelgar.\n\nCe qu'ils ont laissé derrière eux reste à demi mis au jour. Des fossiles vivants et d'anciens élémentaires arpentent désormais les fosses, sans se soucier des pioches qui y rouillent.",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
	},
	-- Teldrassil: 17 subzones
	[1438] = {
		["aldrassil"] = {
			name = "Aldrassil",
			short = "Aldrassil s'élève au cœur de Sombrevallon, un arbre devenu assez vaste pour abriter un village dans ses ramures.",
			full = "Aldrassil s'élève au cœur de Sombrevallon, un arbre devenu assez vaste pour abriter un village dans ses ramures. Tout à son sommet, hors de portée du village en contrebas, Tenaron Stormgrip a élu domicile, veillant sur le vallon depuis la couronne du grand arbre.",
			source = "https://warcraft.wiki.gg/wiki/Aldrassil",
		},
		["banethil barrow den"] = {
			name = "Refuge des saisons de Ban'ethil",
			short = "Le Refuge des saisons de Ban'ethil fut élevé par les elfes de la nuit comme un tertre sacré, afin que leurs druides de la Serre endormis y reposent en paix.",
			full = "Le Refuge des saisons de Ban'ethil fut élevé par les elfes de la nuit comme un tertre sacré, afin que leurs druides de la Serre endormis y reposent en paix.\n\nCette paix est désormais rompue. Les furbolgs Pins-tordus corrompus ont envahi ses refuges inférieur et supérieur, et ce qui était jadis une terre sanctifiée n'est plus un lieu où un elfe de la nuit peut errer seul.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Barrow_Den",
		},
		["banethil hollow"] = {
			name = "Creux de Ban'ethil",
			short = "Un ravin entaille la terre au sud de la route qui relie Dolanaar à Darnassus, ses pentes tenues par des furbolgs hostiles qui tendent des embuscades aux voyageurs s'approchant de trop près.",
			full = "Un ravin entaille la terre au sud de la route qui relie Dolanaar à Darnassus, ses pentes tenues par des furbolgs hostiles qui tendent des embuscades aux voyageurs s'approchant de trop près. Au fond du creux se trouve le Refuge des saisons de Ban'ethil, enfoncé dans la terre. La prudence s'impose sur la route qui le surplombe.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Hollow",
		},
		["cleft"] = {
			name = "La Faille",
			short = "La Faille se trouve au nord-ouest de Dolanaar, repaire de furbolgs Pins-tordus corrompus menés par Ursal le Mutileur. Ils tendent des embuscades aux voyageurs sur la route de Darnassus et retiennent captif à l'intérieur un groupe de druides endormis.",
			full = "La Faille se trouve au nord-ouest de Dolanaar, repaire de furbolgs Pins-tordus corrompus menés par Ursal le Mutileur. Ils tendent des embuscades aux voyageurs sur la route de Darnassus et retiennent captif à l'intérieur un groupe de druides endormis. La prêtresse de la lune Amara et ses gardes du corps surveillent la route près de l'entrée.",
			source = "https://warcraft.wiki.gg/wiki/Cleft",
		},
		["dolanaar"] = {
			name = "Dolanaar",
			short = "Dolanaar se trouve dans le centre-est de Teldrassil, au sud-ouest de Sombrevallon, ses racines et ses ponts de corde tissés dans le grand arbre lui-même.",
			full = "Dolanaar se trouve dans le centre-est de Teldrassil, au sud-ouest de Sombrevallon, ses racines et ses ponts de corde tissés dans le grand arbre lui-même. Sa place centrale sur les chemins de l'île en a longtemps fait un lieu d'allées et venues, un village qui sentait battre le pouls de tout ce qui se passait alentour.",
			source = "https://warcraft.wiki.gg/wiki/Dolanaar",
		},
		["fel rock"] = {
			name = "Gangreroche",
			short = "Au nord de Dolanaar se trouve une grotte jadis magnifique, désormais corrompue. Des grells infestent ses creux obscurs, et en son sein demeure le satyre Lord Melenas, dont la présence a empoisonné les lieux.",
			full = "Au nord de Dolanaar se trouve une grotte jadis magnifique, désormais corrompue. Des grells infestent ses creux obscurs, et en son sein demeure le satyre Lord Melenas, dont la présence a empoisonné les lieux. Le druide elfe de la nuit Tallonkai Swiftroot observe cette corruption avec effroi, car ce qui était jadis une terre belle est devenu sinistre.",
			source = "https://warcraft.wiki.gg/wiki/Fel_Rock",
		},
		["gnarlpine hold"] = {
			name = "Camp des Pins-tordus",
			short = "À l'extrême sud-ouest de Teldrassil se trouve le Camp des Pins-tordus, foyer des furbolgs Pins-tordus.",
			full = "À l'extrême sud-ouest de Teldrassil se trouve le Camp des Pins-tordus, foyer des furbolgs Pins-tordus.",
			source = "https://warcraft.wiki.gg/wiki/Gnarlpine_Hold",
		},
		["lake alameth"] = {
			name = "Lac Al'Ameth",
			short = "Le lac Al'Ameth s'étend largement au sud de Dolanaar, l'une des grandes étendues d'eau de Teldrassil. Rien ou presque ne marque ses rives, hormis une petite jetée.",
			full = "Le lac Al'Ameth s'étend largement au sud de Dolanaar, l'une des grandes étendues d'eau de Teldrassil. Rien ou presque ne marque ses rives, hormis une petite jetée.\n\nDepuis peu, son calme s'est gâté : des sylvains enragés hantent la rive, et il n'est plus sûr de longer le lac seul.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Al'Ameth",
		},
		["oracle glade"] = {
			name = "La Clairière de l'Oracle",
			short = "La Clairière de l'Oracle s'étend dans le nord-ouest de Teldrassil, abritant le premier et le plus puissant des puits de lune du grand arbre.",
			full = "La Clairière de l'Oracle s'étend dans le nord-ouest de Teldrassil, abritant le premier et le plus puissant des puits de lune du grand arbre. Ici se dresse l'arbre-oracle, dont le large tronc s'élève en ramures qui ont la forme d'un aigle perché sur un ours. Beaucoup murmurent qu'aucune croissance ordinaire ne saurait prendre une telle forme, et que seule la magie de la nature l'a façonnée.\n\nL'arbre a veillé sur la croissance de Teldrassil aux côtés des druides.\n\nDes harpies Plume-de-sang ont niché non loin, menaçant l'arbre, et une petite compagnie de Sentinelles a été envoyée pour les repousser.",
			source = "https://warcraft.wiki.gg/wiki/Oracle_Glade",
		},
		["pools of arlithrien"] = {
			name = "Bassins d'Arlithrien",
			short = "Au sud de Darnassus, dans l'ouest de Teldrassil, les Bassins d'Arlithrien étaient jadis paisibles. Un puits de lune y fut abandonné par les elfes de la nuit lorsque les furbolgs Pins-tordus envahirent les lieux.",
			full = "Au sud de Darnassus, dans l'ouest de Teldrassil, les Bassins d'Arlithrien étaient jadis paisibles. Un puits de lune y fut abandonné par les elfes de la nuit lorsque les furbolgs Pins-tordus envahirent les lieux. Le puits se dresse toujours, laissé à l'abandon parmi les bassins, où vit désormais une faune hostile.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Arlithrien",
		},
		["ruttheran village"] = {
			name = "Rut'theran",
			short = "Rut'theran se trouve au pied de Teldrassil, là où l'Arbre-Monde rencontre l'eau, sous Darnassus qui le domine de très haut.",
			full = "Rut'theran se trouve au pied de Teldrassil, là où l'Arbre-Monde rencontre l'eau, sous Darnassus qui le domine de très haut. Ses bâtiments sont humbles à côté de ceux de la capitale, mais tenus avec un soin extrême, comme si l'on tirait fierté de la simplicité plutôt que de la taille.\n\nIci, les kaldorei s'occupent du perchoir des hippogriffes, rassemblant et soignant les œufs et élevant les petits jusqu'à ce qu'ils sachent voler. C'est un travail discret, accompli par des gens qui, par ailleurs, peinent à faire tourner le village au service de la cité d'en haut, sans guère demander de reconnaissance.\n\nLe village n'est pas fait que de labeur, pourtant. Quand vient la fête du Feu du solstice d'été, ses braseros s'allument, et les mains qui soignent les œufs d'hippogriffes et chargent les bateaux se tournent alors vers la célébration.",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "Sombrevallon",
			short = "Sous les ramures de Teldrassil, niché dans la partie nord-est de l'île, s'étend un vallon qui ne voit jamais tout à fait la pleine lumière du jour. Sombrevallon baigne dans un crépuscule perpétuel, cerné de montagnes de tous côtés sauf un.",
			full = "Sous les ramures de Teldrassil, niché dans la partie nord-est de l'île, s'étend un vallon qui ne voit jamais tout à fait la pleine lumière du jour. Sombrevallon baigne dans un crépuscule perpétuel, cerné de montagnes de tous côtés sauf un. Ce n'est qu'au sud que la pierre s'interrompt, laissant un chemin se faufiler vers Dolanaar.\n\nAu cœur du vallon se dresse Aldrassil, un grand arbre dont la présence domine entièrement la clairière, comme si tout le vallon s'ordonnait autour de lui. Au nord-ouest, le sol s'ouvre sur la Grotte de Sombrefil, une sombre faille creusée dans les collines qui entourent le vallon.",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
			name = "Grotte de Sombrefil",
			short = "La Grotte de Sombrefil se trouve dans l'angle nord-ouest de Sombrevallon, dans les racines de Teldrassil. Elle a toujours appartenu aux grandes araignées de l'île, mais depuis peu elles se sont agitées et la grotte est devenue plus dangereuse.",
			full = "La Grotte de Sombrefil se trouve dans l'angle nord-ouest de Sombrevallon, dans les racines de Teldrassil. Elle a toujours appartenu aux grandes araignées de l'île, mais depuis peu elles se sont agitées et la grotte est devenue plus dangereuse.\n\nTout au fond demeure Githyiss la Vile, la plus grande de la couvée, qui a causé la perte de plus d'un jeune kaldorei aventuré trop loin.",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "Brise-stellaire",
			short = "Brise-stellaire appartenait jadis aux elfes de la nuit, un groupe de petites maisons au sud-est de Sombrevallon. Ils l'ont désertée aujourd'hui, et ses maisons ont été prises par les furbolgs Pins-tordus corrompus.",
			full = "Brise-stellaire appartenait jadis aux elfes de la nuit, un groupe de petites maisons au sud-est de Sombrevallon. Ils l'ont désertée aujourd'hui, et ses maisons ont été prises par les furbolgs Pins-tordus corrompus. Uruson arpente ses chemins, et à ses abords rôde Ferocitas le Mangeur de rêves, une bête dont la seule présence montre combien le village est tombé loin de ce qu'il était.",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
		},
		["wellspring lake"] = {
			name = "Lac d'Aigue-vive",
			short = "Le lac d'Aigue-vive tire ses eaux d'une source jaillie des profondeurs de Teldrassil même, et son trop-plein s'écoule pour former l'Aigue-vive. Les pêcheurs elfes de la nuit appréciaient jadis ces eaux paisibles.",
			full = "Le lac d'Aigue-vive tire ses eaux d'une source jaillie des profondeurs de Teldrassil même, et son trop-plein s'écoule pour former l'Aigue-vive. Les pêcheurs elfes de la nuit appréciaient jadis ces eaux paisibles. Désormais, les sylvains qui y vivent sont corrompus, et sabres-de-nuit et araignées se sont glissés dans les terres alentour, faisant de ce qui était un paisible coin de pêche un lieu dangereux.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "L'Aigue-vive",
			short = "L'Aigue-vive naît d'une source jaillie des profondeurs de Teldrassil, et coule du lac d'Aigue-vive vers le nord jusqu'au bord de l'arbre, où elle tombe en une grande cascade dans la mer en contrebas.",
			full = "L'Aigue-vive naît d'une source jaillie des profondeurs de Teldrassil, et coule du lac d'Aigue-vive vers le nord jusqu'au bord de l'arbre, où elle tombe en une grande cascade dans la mer en contrebas.\n\nDes sylvains devenus fous rôdent désormais sur ses rives, attaquant quiconque s'approche.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
	},
	-- Sombrivage: 15 subzones
	[1439] = {
		["ametharan"] = {
			name = "Ameth'Aran",
			short = "Les ruines d'Ameth'Aran s'étendent au sud-est d'Auberdine, en Sombrivage, et quelque chose de la ville y erre encore.",
			full = "Les ruines d'Ameth'Aran s'étendent au sud-est d'Auberdine, en Sombrivage, et quelque chose de la ville y erre encore.\n\nLa reine Azshara éleva jadis Ameth'Aran en jumelle de Bashal'Aran, y installant ses Bien-nés favoris parmi ses bazars et ses temples dédiés à Elune. Elle plaça à sa tête Athrikus Narassin, un mage d'une grande puissance qui se tenait dans sa tour d'Althalaxx.\n\nLorsque vint la Fracture et que la ville s'écroulait déjà, ses habitants s'accrochaient au sol comme si cela seul pouvait les sauver. Athrikus Narassin apparut parmi eux et leur promit un sort qui leur épargnerait la destruction à venir, leur accordant la vie éternelle dans des gemmes d'âme qu'il portait sur lui. Tandis qu'il le prononçait, les elfes autour de lui moururent. L'éternité qu'il leur offrit fut une prison, non un salut, et ce sont leurs esprits, non leurs vies, qui errent depuis lors à Ameth'Aran.\n\nDeux grandes tablettes de pierre se dressent encore parmi les ruines, gravées du récit de la chute de la ville. Une Sentinelle venue les lire fut assaillie par les Bien-nés tourmentés avant d'avoir pu finir, et s'enfuit.",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["auberdine"] = {
			name = "Auberdine",
			short = "Auberdine se dresse là où la Fracture brisa la terre, sur une côte qui engloutit les grandes cités de l'ancien empire kaldorei. Toutes les colonies tentées depuis en Sombrivage ont échoué, hormis cette seule ville au bord de la mer voilée.",
			full = "Auberdine se dresse là où la Fracture brisa la terre, sur une côte qui engloutit les grandes cités de l'ancien empire kaldorei. Toutes les colonies tentées depuis en Sombrivage ont échoué, hormis cette seule ville au bord de la mer voilée.\n\nElle s'est développée à l'écart du reste de la société des elfes de la nuit. Son port attire navires et marchands des Royaumes de l'est, et ses rues sont remplies de nains, de gnomes, d'humains, voire de hauts-elfes, si bien qu'Auberdine est plus éclairée qu'une ville d'elfes de la nuit n'a de raison de l'être, et ses panneaux sont écrits en deux langues à l'intention des étrangers. Darnassus la regarde de haut pour cette raison. Broll Bearmantle, qui visita jadis la ville, tient ses habitants pour guère mieux que des parias et des marginaux, et les Sentinelles en garnison ici se tiennent à l'écart des gens qu'elles protègent. Pourtant, Shandris Feathermoon, qui y fut autrefois postée, s'en souvient comme d'un lieu qui résonnait de rires.\n\nPrès du phare, l'épave d'un navire jadis commandé par l'elfe Elura marque encore les rochers, sa cargaison de minerai d'élunite perdue lorsqu'il sombra.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["bashalaran"] = {
			name = "Bashal'Aran",
			short = "Avant que la mer ne submerge le monde et ne le brise, la reine Azshara éleva deux villes jumelles dans le nord de Sombrivage pour ses Bien-nés favoris : Ameth'Aran et Bashal'Aran.",
			full = "Avant que la mer ne submerge le monde et ne le brise, la reine Azshara éleva deux villes jumelles dans le nord de Sombrivage pour ses Bien-nés favoris : Ameth'Aran et Bashal'Aran. Elle chargea Athrikus Narassin, un elfe d'une grande puissance magique, de les gouverner, et sous ses ordres servait Asterion, un mage aussi habile dans les arts arcaniques que dans le maniement des armes, qui vivait parmi les habitants de Bashal'Aran et se rendait souvent à Ameth'Aran pour veiller sur ses gens. En ce temps-là, les cités jumelles abritaient des bazars et des temples dédiés à Elune, honorés de la faveur de la reine elle-même.\n\nLorsque le premier Puits d'éternité vola en éclats, les deux cités tombèrent en ruine. Mais à un moment donné, Athrikus Narassin retourna son art contre son propre second, enfermant Asterion dans un sceau de pierre de lune et l'emprisonnant parmi les pierres de Bashal'Aran. Pourquoi le maître se retourna contre son serviteur, nul aujourd'hui vivant ne saurait le dire. Asterion endura la prison au long d'une vie longue et douloureuse, et lorsqu'il mourut enfin, il découvrit que la mort ne l'avait pas libéré. Son esprit resta lié aussi sûrement que l'avait été sa chair.",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["blackwood den"] = {
			name = "Tanière des Noirbois",
			short = "À l'extrême sud de Sombrivage, près de la frontière d'Orneval, un ensemble épars de camps furbolgs et une petite grotte forment le lieu appelé Tanière des Noirbois, parfois nommé Repaire des Noirbois.",
			full = "À l'extrême sud de Sombrivage, près de la frontière d'Orneval, un ensemble épars de camps furbolgs et une petite grotte forment le lieu appelé Tanière des Noirbois, parfois nommé Repaire des Noirbois. Les furbolgs qui le tiennent sont corrompus, déformés par rapport à ce qu'ils étaient jadis.\n\nDans la grotte se trouve un elfe de la nuit solitaire nommé Volcor, retenu captif parmi les furbolgs.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["cliffspring falls"] = {
			name = "Chutes de la Bondissante",
			short = "Les Chutes de la Bondissante sont la source de la Bondissante, jadis ses eaux les plus pures et la source d'eau potable de tout Sombrivage. Cette eau n'est plus pure.",
			full = "Les Chutes de la Bondissante sont la source de la Bondissante, jadis ses eaux les plus pures et la source d'eau potable de tout Sombrivage. Cette eau n'est plus pure. La grotte d'où jaillissent les chutes est devenue infecte, et la corruption se répand avec le courant à travers la région qu'elle nourrissait autrefois.\n\nNul ne s'accorde sur la cause. Certains accusent Gangrebois, disant que la souillure suinte tout simplement de cette forêt ravagée. D'autres désignent ce que l'on a découvert au fond de la grotte elle-même, où des nagas rampent désormais dans l'obscurité à la source des eaux.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring river"] = {
			name = "La Bondissante",
			short = "La Bondissante coule des Chutes de la Bondissante jusqu'à la mer, dans le nord de Sombrivage. Ses eaux sont souillées par les nagas Stormscale, et les animaux qui s'y abreuvent tombent souvent malades.",
			full = "La Bondissante coule des Chutes de la Bondissante jusqu'à la mer, dans le nord de Sombrivage. Ses eaux sont souillées par les nagas Stormscale, et les animaux qui s'y abreuvent tombent souvent malades.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["grove of the ancients"] = {
			name = "Bosquet des Anciens",
			short = "Le Bosquet des Anciens est un ancien temple des elfes de la nuit, dont les pierres entourent le cours tumultueux de la Sinueuse, dans les montagnes de Sombrivage.",
			full = "Le Bosquet des Anciens est un ancien temple des elfes de la nuit, dont les pierres entourent le cours tumultueux de la Sinueuse, dans les montagnes de Sombrivage. Ici demeure Onu, un Ancien du savoir, en compagnie d'un druide endormi et de deux marchands, et c'est ici que le Cercle des Anciens se réunit encore.",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["long wash"] = {
			name = "Le Lent reflux",
			short = "Le Lent reflux s'étend vers le sud depuis Auberdine jusqu'aux eaux à l'ouest d'Ameth'Aran, la plus courte portion de côte de Sombrivage malgré son nom.",
			full = "Le Lent reflux s'étend vers le sud depuis Auberdine jusqu'aux eaux à l'ouest d'Ameth'Aran, la plus courte portion de côte de Sombrivage malgré son nom. Un sable gris s'étend sous un ciel uniformément couvert. La marée ne laisse guère que du bois flotté et des carcasses de créatures marines. On aperçoit des murlocs le long du rivage.",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["masters glaive"] = {
			name = "Le Glaive du Maître",
			short = "Dans le sud-ouest de Sombrivage gît un crâne colossal, à demi englouti par la terre, dans lequel est encore planté un glaive d'adamantite.",
			full = "Dans le sud-ouest de Sombrivage gît un crâne colossal, à demi englouti par la terre, dans lequel est encore planté un glaive d'adamantite. C'était Soggoth le Rampant, un héraut des Dieux très anciens, et la lame est appelée le Glaive du Maître.\n\nDes tablettes mises au jour aux Excavations de Remtravel racontent ce qui s'est passé ici. Les titans avaient envoyé vingt géants de pierre contre Soggoth, et la bataille qui s'ensuivit fut si terrible qu'un seul d'entre eux vécut assez pour en voir la fin : Kronn, le plus grand des vingt. Lorsque les tentacules de Soggoth se refermèrent sur lui, Kronn ne lutta pas pour s'en libérer. Il se laissa entraîner, toujours plus près du crâne de la créature, jusqu'à être assez proche pour frapper. Le coup qui tua Soggoth fut porté depuis sa propre étreinte, et l'épée restée plantée dans son crâne prit le nom de cette victoire.\n\nLe Marteau du crépuscule s'est depuis emparé du site, fouillant les restes de Soggoth, s'efforçant de défaire ce que l'épée de Kronn avait accompli et de rappeler au monde le héraut du Dieu très ancien.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["mists edge"] = {
			name = "La lisière des brumes",
			short = "La côte appelée la lisière des brumes longe tout Sombrivage, le plus long littoral de la région.",
			full = "La côte appelée la lisière des brumes longe tout Sombrivage, le plus long littoral de la région.\n\nC'est une étendue lugubre : plages grises et baies sinistres, jonchées des immenses carcasses d'animaux marins morts et des épaves de navires engloutis.\n\nDes crabes détalent sur toute sa longueur, et des murlocs se tapissent dans les baies peu profondes, menace constante pour quiconque longe le rivage.",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["remtravels excavation"] = {
			name = "Excavations de Remtravel",
			short = "Le prospecteur Remtravel a donné son nom à ce site de fouilles de Sombrivage.",
			full = "Le prospecteur Remtravel a donné son nom à ce site de fouilles de Sombrivage. En creusant, il découvrit un fossile sans pareil, vibrant de propriétés mystiques, mais le prospecteur distrait ne se souvient plus où il l'a rangé.\n\nLes excavations elles-mêmes sont devenues dangereuses : des troggs Gravelflint ont pris possession de ses tunnels, et d'énormes golems, déterrés par les fouilles, s'y agitent désormais.",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of mathystra"] = {
			name = "Ruines de Mathystra",
			short = "Au-delà de la Tour d'Althalaxx, dans le nord de Sombrivage, s'étendent les ruines de Mathystra. Avant la Grande fracture, c'était une cité des elfes de la nuit, élevée à l'époque des Bien-nés.",
			full = "Au-delà de la Tour d'Althalaxx, dans le nord de Sombrivage, s'étendent les ruines de Mathystra. Avant la Grande fracture, c'était une cité des elfes de la nuit, élevée à l'époque des Bien-nés. Lorsque le Puits d'éternité se déchira et que le monde se brisa sous lui, Mathystra fut ruinée comme tant d'autres lieux, et les elfes de la nuit qui survécurent ne revinrent pas la rebâtir. Ils se retirèrent plutôt dans de plus petits villages le long de la côte, plus au sud, laissant les ruines derrière eux.\n\nDes reliques éparses des anciens Bien-nés gisent encore parmi les pierres effondrées, et de jeunes elfes de la nuit viennent parfois fouiller Mathystra à leur recherche, se méfiant des sabres fantômes qui rôdent parmi les ruines de ce que leur peuple bâtit jadis.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["tower of althalaxx"] = {
			name = "Tour d'Althalaxx",
			short = "À l'époque de la Grande fracture, lorsque la reine Azshara élevait les Bien-nés au-dessus de tous les autres, elle chargea un elfe nommé Athrikus Narassin de gouverner les villes jumelles d'Ameth'Aran et de Bashal'Aran.",
			full = "À l'époque de la Grande fracture, lorsque la reine Azshara élevait les Bien-nés au-dessus de tous les autres, elle chargea un elfe nommé Athrikus Narassin de gouverner les villes jumelles d'Ameth'Aran et de Bashal'Aran. Athrikus la servit assez bien au début, mais la tâche l'ennuyait, et il prit l'habitude de passer ses journées loin des villes, dans une tour à lui, appelée Althalaxx.\n\nDix mille ans plus tard, ce que l'on murmurait depuis longtemps de cette tour se révéla vrai. Un culte qui se faisait appeler le culte de la Rive noire s'y était rassemblé, comptant parmi ses membres des démonistes et un satyre, et à sa tête se tenait Athrikus Narassin en personne. Ses desseins restèrent obscurs jusqu'à ce que l'on découvre que le culte obéissait au Conseil des ombres, et qu'Althalaxx était devenue un fil de plus dans la toile de cette vieille conspiration.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight vale"] = {
			name = "Vallée du crépuscule",
			short = "Les forêts au sud d'Ameth'Aran, qui s'étendent jusqu'à la frontière d'Orneval, sont appelées la Vallée du Crépuscule.",
			full = "Les forêts au sud d'Ameth'Aran, qui s'étendent jusqu'à la frontière d'Orneval, sont appelées la Vallée du Crépuscule. Furbolgs corrompus, sabres-de-nuit sauvages et ours enragés hantent ces bois, et l'on conseille aux voyageurs de rester sur les routes plutôt que d'errer sous les arbres.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "La Sinueuse",
			short = "La Sinueuse charrie sa maladie depuis les montagnes, prolongement de la Vénéneuse qui s'écoule de Gangrebois vers le sud de Sombrivage, près du Bosquet des Anciens.",
			full = "La Sinueuse charrie sa maladie depuis les montagnes, prolongement de la Vénéneuse qui s'écoule de Gangrebois vers le sud de Sombrivage, près du Bosquet des Anciens. Ses eaux sont souillées, la corruption de Gangrebois suivant le courant jusque dans ces basses terres.",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
	},
	-- Orneval: 41 subzones
	[1440] = {
		["astranaar"] = {
			name = "Astranaar",
			short = "Astranaar s'élève sur une île au cœur d'Orneval, la plus grande des colonies d'elfes de la nuit de la région, accessible uniquement par deux ponts qui font franchir l'eau à la route.",
			full = "Astranaar s'élève sur une île au cœur d'Orneval, la plus grande des colonies d'elfes de la nuit de la région, accessible uniquement par deux ponts qui font franchir l'eau à la route. Le lac la sépare de la forêt environnante, un lieu paisible et défendable au centre d'une terre disputée.\n\nSon cimetière s'étend au bord de l'eau, abritant les morts de la ville parmi de paisibles rangées de pierres.\n\nAu-delà de la ville, les furbolgs Crins-de-Chardon ont rassemblé leurs forces au nord, et l'on craint à Astranaar qu'ils ne trouvent un jour le courage de retourner leur force contre la ville elle-même.",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "Repaire de Bathran",
			short = "Les piliers du Repaire de Bathran faisaient jadis partie d'une ruine kaldorei, élevée à une époque où les elfes de la nuit parcouraient encore cette partie d'Orneval.",
			full = "Les piliers du Repaire de Bathran faisaient jadis partie d'une ruine kaldorei, élevée à une époque où les elfes de la nuit parcouraient encore cette partie d'Orneval. Cette époque passa, les elfes se retirèrent, et le marbre fut laissé à se fendre et à tomber.\n\nIl n'est pas vide aujourd'hui. Des agents réprouvés se sont installés parmi les colonnes brisées, des herboristes et les brutes qui les gardent, et partout où ils s'établissent la terre répond de même : l'herbe a bruni, les fleurs se sont flétries. Parmi les pierres effondrées, ils ont élevé un laboratoire de fortune, où ils travaillent les herbes locales à des fins qui leur sont propres.\n\nCe qui les attire ici avant tout est une plante que l'on ne trouve nulle part ailleurs aux alentours : les cheveux de Bathran, une herbe médicinale assez rare pour justifier à elle seule de tenir le site.",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom deeps"] = {
			name = "Profondeurs de Brassenoire",
			short = "Sous la grève de Zoram, là où l'antique cité de Zoram sombra dans la mer, s'étendent les salles englouties de Lathar'Lazal, jadis un temple d'Elune.",
			full = "Sous la grève de Zoram, là où l'antique cité de Zoram sombra dans la mer, s'étendent les salles englouties de Lathar'Lazal, jadis un temple d'Elune. On croyait que la Fracture l'avait détruit purement et simplement, et pendant des millénaires l'océan le garda.\n\nPuis vint le Marteau du crépuscule, attiré par des murmures et des rêves immondes vers les cavernes aquatiques qu'était devenu le temple. Le culte sacrifia d'innombrables innocents dans ces profondeurs, et fut récompensé d'une mission : nourrir et protéger une créature chérie des Dieux très anciens, l'hydre monstrueuse Aku'mai la Dévoreuse, jusqu'au jour où elle serait lâchée sur le monde. Le lieu s'appelle désormais Brassenoire, et le nom lui va bien.",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "Camp de Dent-rouge",
			short = "Le Camp de Dent-rouge se trouve à l'ouest du fleuve Falfarren, au sud-ouest du puits de lune méridional d'Orneval. Il tire son nom de Ran Bloodtooth, chef de la tribu furbolg qui le tient.",
			full = "Le Camp de Dent-rouge se trouve à l'ouest du fleuve Falfarren, au sud-ouest du puits de lune méridional d'Orneval. Il tire son nom de Ran Bloodtooth, chef de la tribu furbolg qui le tient.\n\nCes furbolgs étaient jadis semblables à tous ceux de leur espèce, mais la corruption les a tous gagnés, et le camp répond désormais avec hostilité à tout étranger qui s'approche.",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bough shadow"] = {
			name = "L'Ombrage",
			short = "Au-delà du Chant des forêts, là où les arbres d'Orneval poussent denses et anciens, L'Ombrage abrite l'un des portails menant au Rêve d'émeraude.",
			full = "Au-delà du Chant des forêts, là où les arbres d'Orneval poussent denses et anciens, L'Ombrage abrite l'un des portails menant au Rêve d'émeraude.\n\nLe vol draconique vert le garde. Les drakes Phantim et Dreamstalker veillent sur le passage, et des draconides parcourent les bois alentour en patrouilles de trois, un oracle émeraldon flanqué de gardes-ramures et de gardiens des arbres, foulant le même terrain encore et encore au cours de leur longue veille.",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "Canyon de la Malechute",
			short = "Le Canyon de la Malechute porte la cicatrice de l'instant où les orcs se libérèrent de leur ancienne servitude.",
			full = "Le Canyon de la Malechute porte la cicatrice de l'instant où les orcs se libérèrent de leur ancienne servitude.\n\nC'est ici que Mannoroth, le seigneur des Abîmes, affronta Grommash Hurlenfer et Thrall. Le démon terrassa Thrall, mais ne put se détourner assez vite de la hache de Grom, qui s'enfonça dans sa poitrine. La mort de Mannoroth explosa en feu et en lumière, et ce même feu arracha la vie de Grom tout en emportant le démon. Les orcs prirent le lieu de son sacrifice et lui donnèrent son nom, car c'est là que fut brisée la malédiction que la Légion ardente avait jetée sur leur peuple.\n\nDe nombreux orcs s'y rendent encore pour honorer le guerrier qui paya cette liberté, et un monument se dresse à sa mémoire. Mais le sol reste touché par la gangrène, et des démons mineurs hantent désormais le canyon.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "Crête de la Malechute",
			short = "Au-dessus du Canyon de la Malechute, la crête s'élève, déchiquetée, ses pentes et le refuge des saisons creusé dans son flanc envahis par des démons mineurs.",
			full = "Au-dessus du Canyon de la Malechute, la crête s'élève, déchiquetée, ses pentes et le refuge des saisons creusé dans son flanc envahis par des démons mineurs. Plus profond, hors de portée de la lumière du jour, attend Diathorus le Chercheur, un seigneur de l'effroi qui règne sur le conclave démoniaque rassemblé en Orneval, tenant sa cour dans l'obscurité tandis que des démons mineurs gardent la crête au-dessus.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "Le Refuge des saisons de Dor'danil",
			short = "Le Refuge des saisons de Dor'danil est depuis longtemps un lieu de repos pour les druides elfes de la nuit, qui y dorment de corps tandis que leur esprit erre librement.",
			full = "Le Refuge des saisons de Dor'danil est depuis longtemps un lieu de repos pour les druides elfes de la nuit, qui y dorment de corps tandis que leur esprit erre librement. Ce furent les Réprouvés qui s'intéressèrent aux dormeurs, séparant les druides de leur esprit errant. L'expérience ne les tua pas. Elle les rendit fous.\n\nDésormais, le refuge des saisons n'abrite plus de dormeurs paisibles. Des assassins réprouvés s'y déplacent sans être vus, tandis que les âmes furieuses des druides séparés font rage à travers le tertre, sans plus nulle part où retourner. Parmi elles s'attardent trois esprits plus puissants que les autres : Uthil Mooncall, Mavoris Cloudsbreak et Taneel Darkwood.",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "Fleuve Falfarren",
			short = "Le Falfarren coupe Orneval presque en deux. À l'ouest vivent les elfes de la nuit, autour d'Astranaar ; à l'est, les orcs tiennent le Poste de Bois-brisé.",
			full = "Le Falfarren coupe Orneval presque en deux. À l'ouest vivent les elfes de la nuit, autour d'Astranaar ; à l'est, les orcs tiennent le Poste de Bois-brisé. Le fleuve est assez peu profond pour être passé à gué et assez étroit pour être franchi sans grande peine, sauf quand les pluies le font sortir de son lit, mais il marque tout de même une frontière, que les deux peuples comprennent sans avoir besoin d'en parler.\n\nSes eaux prennent leur source sur les pentes du mont Hyjal, descendent en cascades jusqu'au lac de Xavian, puis coulent entre Bois-brisé et le Défilé de la nuit, sous le grand pont qu'empruntent la plupart des voyageurs pour traverser Orneval, et passent devant l'Avant-poste d'Aile-argent et le puits de lune de la Purification, avant de s'enfoncer sous terre, sous les montagnes du nord, en direction des Tarides.\n\nPrès de la Colline Gangrefeu, le fleuve cache un autre danger. Des bêtes des tourbières s'y tapissent sous la surface, frappant tout ce qui s'attarde trop longtemps dans l'eau.",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "Lac Tombeciel",
			short = "Un petit lac s'étend au sud de l'Avant-poste d'Aile-argent, en Orneval, ses eaux rassemblées autour d'une île solitaire.",
			full = "Un petit lac s'étend au sud de l'Avant-poste d'Aile-argent, en Orneval, ses eaux rassemblées autour d'une île solitaire. Sur cette île vit un oracle Ombrefourré, un ancien parmi le peuple des Ombrefourrés qui, moins nombreux, bordent la rive, veillant sur l'eau depuis les roseaux et les fourrés alentour.",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "Colline Gangrefeu",
			short = "La Colline Gangrefeu porte encore les cicatrices de la troisième guerre, lorsque des infernaux tombèrent du ciel en flammes et frappèrent la terre en ce lieu. Des démons s'y sont attardés depuis, créatures immondes tapies parmi les pierres.",
			full = "La Colline Gangrefeu porte encore les cicatrices de la troisième guerre, lorsque des infernaux tombèrent du ciel en flammes et frappèrent la terre en ce lieu. Des démons s'y sont attardés depuis, créatures immondes tapies parmi les pierres.\n\nLa Horde a fortifié les deux ponts qui mènent à la colline, les tenant pour empêcher les démons de se répandre vers les colonies voisines.",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "Sanctuaire de Scarfeu",
			short = "Le Sanctuaire de Scarfeu se dresse dans le sud-ouest d'Orneval, corrompu par l'influence démoniaque du Conseil des ombres au point de devenir un lieu de grand mal.",
			full = "Le Sanctuaire de Scarfeu se dresse dans le sud-ouest d'Orneval, corrompu par l'influence démoniaque du Conseil des ombres au point de devenir un lieu de grand mal. Le démoniste orc Ilkrud Magthrull y résida jadis, au service d'Athrikus Narassin, chef du culte de la Rive noire.\n\nDes démons infestent désormais le sanctuaire, attirés par la souillure laissée dans la pierre. Parmi eux, un garde funeste nommé Akkrilus est connu pour apparaître de temps à autre dans la région, signe rare et dangereux de la profondeur de la corruption.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "Chant des forêts",
			short = "Le Chant des forêts est une ancienne ruine des elfes de la nuit dans les forêts d'Orneval, depuis longtemps livrée à la mousse et au souvenir. Pendant un temps, elle n'abrita presque personne.",
			full = "Le Chant des forêts est une ancienne ruine des elfes de la nuit dans les forêts d'Orneval, depuis longtemps livrée à la mousse et au souvenir. Pendant un temps, elle n'abrita presque personne.\n\nPuis le druide Kayneth Stillwind en fit son domaine, seul habitant de la ruine, dirigeant depuis ses pierres la lutte contre les Réprouvés dans la région. Un lieu oublié devint un poste de sentinelle, tenu non par le nombre mais par le refus d'un druide de l'abandonner.",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "Village des Pattes-vertes",
			short = "Le Village des Pattes-vertes abrite la tribu Foulweald, des furbolgs menés par le chef Murgut et le chaman Oakpaw. Les hommes-ours d'ici sont corrompus.",
			full = "Le Village des Pattes-vertes abrite la tribu Foulweald, des furbolgs menés par le chef Murgut et le chaman Oakpaw. Les hommes-ours d'ici sont corrompus.",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["howling vale"] = {
			name = "Le Val hurlant",
			short = "Une grotte s'ouvre sur le val où se dresse le sanctuaire de Mel'Thandris, dont la pierre porte une antique inscription à la louange d'Elune et, au-dessus, en darnassien : la vérité est une lumière qui guide.",
			full = "Une grotte s'ouvre sur le val où se dresse le sanctuaire de Mel'Thandris, dont la pierre porte une antique inscription à la louange d'Elune et, au-dessus, en darnassien : la vérité est une lumière qui guide.\n\nLe sanctuaire fut élevé par la mère de Velinde Starsong en l'honneur de Mel'Thandris, à qui l'on avait confié la Faux d'Elune. À la mort de Mel'Thandris, la faux fut déposée ici, cachée dans le sanctuaire. Elle resta oubliée jusqu'à ce que Velinde, ayant trouvé à Darnassus un livre qui en contait l'histoire, vienne dans le val et la découvre elle-même.\n\nAvec le temps, le sanctuaire tomba en ruine, et une tribu de worgens appelée les Terrowulf l'envahit, faisant de la grotte son repaire. Leurs hurlements, résonnant dans la pierre, donnèrent au val le nom qu'il porte aujourd'hui.",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "Lac Iris",
			short = "Le lac Iris s'étend dans le centre-nord d'Orneval, à l'est d'Astranaar et à l'ouest du puits de lune de Shael'dryn.",
			full = "Le lac Iris s'étend dans le centre-nord d'Orneval, à l'est d'Astranaar et à l'ouest du puits de lune de Shael'dryn. Autrefois partie intégrante de la forêt intacte des elfes de la nuit, il succomba à la corruption venue de Gangrebois, et son eau prit une teinte vert-jaune maladive. Des bêtes des tourbières difformes hantent désormais ses rives, attaquant quiconque vient chercher les Larmes d'Elune.",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "Donjon de Kargathia",
			short = "Le Donjon de Kargathia se dresse parmi des barricades hérissées de pieux, au Camp de bûcherons Warsong, dans l'est d'Orneval, près du fleuve Furie-du-Sud.",
			full = "Le Donjon de Kargathia se dresse parmi des barricades hérissées de pieux, au Camp de bûcherons Warsong, dans l'est d'Orneval, près du fleuve Furie-du-Sud. Il sert de siège aux officiers du clan Warsong, et son emplacement a été choisi pour que des renforts puissent être appelés depuis Orgrimmar si l'Alliance lançait une attaque en force contre le camp.\n\nLe donjon tire son nom de Kargath Bladefist, le héros orc également honoré à Kargath, dans les Terres ingrates, et à la baie de Bladefist, en Durotar. Le surveillant Gorthak commande le camp depuis ses murs, dirigeant l'abattage du bois d'Orneval.",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["lake falathim"] = {
			name = "Lac Falathim",
			short = "Le lac Falathim s'étend dans l'ouest d'Orneval, là où le clair de lune de la déesse touche toujours l'eau, de jour comme de nuit. Les elfes de la nuit venaient jadis librement y nager et y pêcher, jusqu'à ce que des murlocs envahissent le lac et le rendent sauvage.",
			full = "Le lac Falathim s'étend dans l'ouest d'Orneval, là où le clair de lune de la déesse touche toujours l'eau, de jour comme de nuit. Les elfes de la nuit venaient jadis librement y nager et y pêcher, jusqu'à ce que des murlocs envahissent le lac et le rendent sauvage. Le savant Teronis fut vu pour la dernière fois près de ses rives et ne revint jamais.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "Poste de Maestra",
			short = "Une tour et une unique salle d'elfes de la nuit se dressent ici en silence, abritant une poignée de défenseurs et, chose des plus étranges pour Orneval, deux humains parmi les elfes : Feero Ironhand et Delgren le Purificateur, les seuls de leur espèce à ce poste.",
			full = "Une tour et une unique salle d'elfes de la nuit se dressent ici en silence, abritant une poignée de défenseurs et, chose des plus étranges pour Orneval, deux humains parmi les elfes : Feero Ironhand et Delgren le Purificateur, les seuls de leur espèce à ce poste.\n\nIls sont peu nombreux, car la corruption qui se répand parmi les furbolgs voisins détourne des bras qui pourraient autrement monter la garde ici, laissant les défenseurs du poste en sous-effectif.",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["mystral lake"] = {
			name = "Lac Mystral",
			short = "Les eaux du lac Mystral étaient jadis gardées par des esprits fidèles aux elfes de la nuit, liés au lac en tant que gardiens.",
			full = "Les eaux du lac Mystral étaient jadis gardées par des esprits fidèles aux elfes de la nuit, liés au lac en tant que gardiens. Sarilus Foulborne les retourna, corrompant les élémentaires jusqu'à ce qu'ils lui obéissent à lui plutôt qu'aux elfes qu'ils servaient autrefois. Ce qui attend dans le lac aujourd'hui n'est plus ce qu'il était.",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "Défilé de la nuit",
			short = "Le Défilé de la nuit se trouve sur un promontoire qui s'avance dans les terres, ses falaises trop abruptes pour être escaladées, si bien qu'un voyageur doit suivre le Falfarren presque jusqu'aux eaux de Xavian avant de tourner vers l'ouest, ou bien trouver l'étroite corniche au nord de Raynewood.",
			full = "Le Défilé de la nuit se trouve sur un promontoire qui s'avance dans les terres, ses falaises trop abruptes pour être escaladées, si bien qu'un voyageur doit suivre le Falfarren presque jusqu'aux eaux de Xavian avant de tourner vers l'ouest, ou bien trouver l'étroite corniche au nord de Raynewood. Une fois à l'intérieur, il y a peu à trouver : seulement quelques piliers brisés et une maçonnerie en ruine, la plus petite et la plus pauvre des trois places fortes satyres d'Orneval, éclipsée par Xavian comme par Satyrnaar. Les satyres Felmusk qui s'abritent parmi ces ruines n'ont guère besoin de murs quand la terre elle-même les protège. Parmi les décombres repose l'une des gemmes d'âme du culte de la Rive noire, avec lequel les Felmusk sont alliés.",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "Bois de Chantenuit",
			short = "Le fleuve Falfarren coupe en deux les bois de l'est, et la ligne qu'il trace est celle d'une guerre sans fin.",
			full = "Le fleuve Falfarren coupe en deux les bois de l'est, et la ligne qu'il trace est celle d'une guerre sans fin. À l'ouest de ses rives, les Sentinelles d'Aile-argent tiennent le terrain pour l'Alliance ; à l'est, le clan Warsong a planté ses pieux dans la terre, et c'est ici que les combats entre les deux peuples sont les plus violents et les plus incessants.\n\nPlus à l'est, une seconde rivière, sans nom, marque une autre frontière. D'un côté se dresse le Poste de Bois-brisé, cœur de la puissance de la Horde dans ces bois ; de l'autre, le Bosquet d'Aile-argent répond pour l'Alliance. Au-delà de cette rivière s'étend une terre qui n'appartient longtemps à personne, revendiquée par morceaux par les elfes de la nuit du Chant des forêts, les satyres de Satyrnaar et de Xavian, les orcs Warsong et la Légion ardente elle-même. Jamais une seule bannière n'y a flotté sans être contestée.\n\nAu sud des combats, la forêt a payé le prix de la guerre. Le clan Warsong a dépouillé ces étendues, abattant les vieux arbres pour construire ses colonies, laissant une terre nue et meurtrie là où s'étendait jadis une forêt ancienne et intacte.",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["raynewood retreat"] = {
			name = "Retraite de Raynewood",
			short = "Haut dans les ramures du Grand Arbre qui donne son nom à ce lieu se cache Ordanus, un gardien du bosquet et l'un des fils aînés de Cenarius.",
			full = "Haut dans les ramures du Grand Arbre qui donne son nom à ce lieu se cache Ordanus, un gardien du bosquet et l'un des fils aînés de Cenarius. Il vint ici pour se dissimuler au Conseil des ombres, dont les agents l'avaient marqué pour la mort. À leur tête se trouvait Braelyn Firehand, qui fit de sa mort son unique but et envoya des tueurs contre lui. Ordanus survécut à l'attentat, et reste encore caché dans les hautes branches de l'arbre.\n\nSous lui, des protecteurs cénariens, des dragons clignotants et les sœurs rieuses montent la garde depuis l'avant-poste, surveillant le chemin nord qui mène vers les étendues ravagées de Gangrebois.",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["ruins of ordilaran"] = {
			name = "Les Ruines d'Ordil'Aran",
			short = "Il ne reste aujourd'hui d'Ordil'Aran que des pierres brisées. Le culte de la Rive noire fit jadis des ruines son domaine, prêt à s'abattre sur quiconque s'approchait de trop près.",
			full = "Il ne reste aujourd'hui d'Ordil'Aran que des pierres brisées. Le culte de la Rive noire fit jadis des ruines son domaine, prêt à s'abattre sur quiconque s'approchait de trop près. Cela finit dans le sang : les furbolgs Crins-de-Chardon les chassèrent et s'approprièrent les ruines, et les corps des cultistes gisent encore épars là où ils tombèrent.\n\nAu milieu des décombres se dresse le Cœur-du-bois, enraciné dans ce qui fut jadis une cité de quelque renom et de quelque importance. Rien d'autre n'en subsiste pour dire ce qu'elle fut.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "Les ruines de Chimétoile",
			short = "Les ruines de Chimétoile se trouvent sur une île du lac, jadis plongées dans la sainteté, aujourd'hui plongées dans la pourriture. La souillure démoniaque qui descend de Gangrebois s'est infiltrée dans l'eau comme dans la pierre, teintant l'île d'un vert-jaune maladif.",
			full = "Les ruines de Chimétoile se trouvent sur une île du lac, jadis plongées dans la sainteté, aujourd'hui plongées dans la pourriture. La souillure démoniaque qui descend de Gangrebois s'est infiltrée dans l'eau comme dans la pierre, teintant l'île d'un vert-jaune maladif. Des bêtes des tourbières, déformées par le lac empoisonné, se traînent désormais parmi les décombres.\n\nPourtant, les buissons de chimétoile y poussent encore, épargnés par la corruption qui les entoure. On dit que leurs feuilles recèlent une vertu curative, seule part des ruines qui ressemble encore à ce que le lieu devait être avant la venue de la pourriture.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["satyrnaar"] = {
			name = "Satyrnaar",
			short = "Satyrnaar se dresse, en ruine, parmi les arbres du nord-est d'Orneval, ses bâtiments depuis longtemps effondrés, bien que des tentes se regroupent désormais parmi les décombres, là où les satyres Mornecoeur ont élu domicile.",
			full = "Satyrnaar se dresse, en ruine, parmi les arbres du nord-est d'Orneval, ses bâtiments depuis longtemps effondrés, bien que des tentes se regroupent désormais parmi les décombres, là où les satyres Mornecoeur ont élu domicile. Des trois places fortes satyres de la forêt, Satyrnaar est la seule restée en grande partie intacte, et sa situation au bord de la route qui mène de Bois-brisé vers Azshara en a fait à la fois la plus accessible et la plus disputée des trois.\n\nLes Mornecoeur y détiennent plus qu'un abri. Dans Satyrnaar repose l'une des gemmes d'âme du culte de la Rive noire, gage du pacte qui lie les satyres aux sombres desseins de ce culte.",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "Le creux ombragé",
			short = "Le Recoin ombragé se trouve au sud de la Retraite de Raynewood et à l'est du Village des Pattes-vertes, une petite vallée discrètement nichée en Orneval.",
			full = "Le Recoin ombragé se trouve au sud de la Retraite de Raynewood et à l'est du Village des Pattes-vertes, une petite vallée discrètement nichée en Orneval. Une grotte s'ouvre à flanc de colline, où vit une petite famille d'ours qui reste à l'écart parmi les arbres et l'ombre.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
		},
		["shrine of aessina"] = {
			name = "Le sanctuaire d'Aessina",
			short = "Le sanctuaire d'Aessina se dresse dans le sud-ouest d'Orneval, niché entre le Poste de Maestra et Astranaar.",
			full = "Le sanctuaire d'Aessina se dresse dans le sud-ouest d'Orneval, niché entre le Poste de Maestra et Astranaar.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
		},
		["silverwind refuge"] = {
			name = "Refuge de Vent-argent",
			short = "Le Refuge de Vent-argent appartient aux elfes de la nuit, placé sous la garde des Sentinelles et des élémentaires d'eau qui servent à leurs côtés.",
			full = "Le Refuge de Vent-argent appartient aux elfes de la nuit, placé sous la garde des Sentinelles et des élémentaires d'eau qui servent à leurs côtés. Avec Astranaar, c'est l'un des principaux avant-postes d'Orneval, et son nom est bien mérité : c'est un lieu accueillant, dont l'auberge compte parmi les plus confortables de la région.",
			source = "https://warcraft.wiki.gg/wiki/Silverwind_Refuge",
		},
		["silverwing grove"] = {
			name = "Bosquet d'Aile-argent",
			short = "Le Bosquet d'Aile-argent se trouve dans le centre-sud d'Orneval, un bois tenu par les Sentinelles d'Aile-argent, au sud-ouest de leur avant-poste et à l'ouest du lac Tombeciel.",
			full = "Le Bosquet d'Aile-argent se trouve dans le centre-sud d'Orneval, un bois tenu par les Sentinelles d'Aile-argent, au sud-ouest de leur avant-poste et à l'ouest du lac Tombeciel. La Sentinelle Farsong y monte la garde parmi celles qui ont juré de défendre le bosquet.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Grove",
		},
		["silverwing outpost"] = {
			name = "Avant-poste d'Aile-argent",
			short = "L'Avant-poste d'Aile-argent se dresse du mauvais côté du fleuve Falfarren, au cœur d'un pays que les orcs du Poste de Bois-brisé entendent nettoyer.",
			full = "L'Avant-poste d'Aile-argent se dresse du mauvais côté du fleuve Falfarren, au cœur d'un pays que les orcs du Poste de Bois-brisé entendent nettoyer. Duriel Moonfire le commande, et commander ici signifie une guerre incessante : les orcs ne font pas des raids pour le butin, mais pour effacer l'avant-poste et chasser à jamais toutes les Sentinelles de ces bois.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["southfury river"] = {
			name = "Fleuve Furie-du-Sud",
			short = "Le fleuve Furie-du-Sud prend sa source haut sur le mont Hyjal, jaillissant d'un lac de montagne en une chute qui s'abat avec fracas dans les basses terres.",
			full = "Le fleuve Furie-du-Sud prend sa source haut sur le mont Hyjal, jaillissant d'un lac de montagne en une chute qui s'abat avec fracas dans les basses terres. De là, il coule large et rapide, coupant le pays en deux : il marque l'endroit où Orneval cède la place à Azshara et, plus au sud, celui où finissent les Tarides et où commence Durotar. À son embouchure, le fleuve se jette par une dernière cascade dans la Grande mer, juste au nord-est du port gobelin de Ratchet.\n\nDes ponts le franchissent sur toute sa longueur, l'un reliant Azshara à Orneval, un autre unissant Durotar aux Tarides. Juste au nord du plus occidental d'entre eux, une seule étendue d'eau touche les quatre terres à la fois, le seul endroit où se rejoignent Orneval, Azshara, Durotar et les Tarides.\n\nLe fleuve nourrit toujours les champs le long de ses rives, et verdit toujours la terre là où il coule. Mais on ne peut plus en boire l'eau.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree post"] = {
			name = "Poste de Bois-brisé",
			short = "Les madriers du Poste de Bois-brisé portent encore les marques des haches qui l'ont bâti, car ce furent Grommash Hurlenfer et son clan Warsong qui élevèrent cet avant-poste lorsque les orcs s'enfoncèrent pour la première fois en Orneval pendant la troisième guerre, abattant les arbres anciens pour leur route et leurs camps.",
			full = "Les madriers du Poste de Bois-brisé portent encore les marques des haches qui l'ont bâti, car ce furent Grommash Hurlenfer et son clan Warsong qui élevèrent cet avant-poste lorsque les orcs s'enfoncèrent pour la première fois en Orneval pendant la troisième guerre, abattant les arbres anciens pour leur route et leurs camps.\n\nLes elfes de la nuit n'ont jamais pardonné ce que les Warsong ont fait à leurs forêts, et les vieilles blessures pèsent sur la trêve fragile entre la Horde et l'Alliance. Aussi Bois-brisé attire-t-il les représailles plus que la plupart des avant-postes de ces bois, et les raids sur Astranaar, toute proche, sont fréquents de part et d'autre.\n\nCe qui reste aujourd'hui est une garnison, non un village : des orcs et des taurens qui montent la garde et partent en éclaireurs, surveillant la lisière des arbres dans l'attente des assaillants qu'ils ont appris à attendre.",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["talondeep path"] = {
			name = "La Perce des Serres",
			short = "La Perce des Serres est un tunnel sinueux qui relie Orneval aux Serres-Rocheuses, un passage irrégulier ponctué de petits culs-de-sac et d'étranges creux usés dans la roche.",
			full = "La Perce des Serres est un tunnel sinueux qui relie Orneval aux Serres-Rocheuses, un passage irrégulier ponctué de petits culs-de-sac et d'étranges creux usés dans la roche. Il débouche d'un côté à l'ouest du lac Mystral, et de l'autre dans la partie nord-ouest de la Combe des Cisailles. Rien n'y vit ; ce n'est qu'un chemin à travers les montagnes.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thistlefur village"] = {
			name = "Village des Crins-de-Chardon",
			short = "Le Village des Crins-de-Chardon se trouve dans le centre-ouest d'Orneval, au nord d'Astranaar. C'est le foyer de la tribu Crins-de-Chardon, des furbolgs devenus corrompus et hostiles, qui attaquent quiconque s'aventure à proximité.",
			full = "Le Village des Crins-de-Chardon se trouve dans le centre-ouest d'Orneval, au nord d'Astranaar. C'est le foyer de la tribu Crins-de-Chardon, des furbolgs devenus corrompus et hostiles, qui attaquent quiconque s'aventure à proximité. Deux guerriers féroces, Dal Bloodclaw et Rorgish Jowl, dirigent la tribu et défendent le village contre tous ceux qui l'approchent.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["warsong labor camp"] = {
			name = "Camp de travail Warsong",
			short = "Dans le sud-est d'Orneval, à l'est du lac Tombeciel, le clan Warsong tient un camp de travail où bûcherons et récolteurs travaillent sous la garde des orcs, coupant du bois pour les possessions du clan.",
			full = "Dans le sud-est d'Orneval, à l'est du lac Tombeciel, le clan Warsong tient un camp de travail où bûcherons et récolteurs travaillent sous la garde des orcs, coupant du bois pour les possessions du clan.\n\nLe camp se trouve à l'écart des forces principales des Warsong, et ses gardes y sont isolés, sans espoir de renforts.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "Camp de bûcherons Warsong",
			short = "Les forêts d'Orneval résonnent du bruit des haches au Camp de bûcherons Warsong, où le clan Warsong dépouille les arbres anciens pour leur bois.",
			full = "Les forêts d'Orneval résonnent du bruit des haches au Camp de bûcherons Warsong, où le clan Warsong dépouille les arbres anciens pour leur bois. Le camp s'appuie sur un chenil de bêtes de guerre et sur le Donjon de Kargathia, une place forte élevée pour protéger la coupe.\n\nL'appétit de bois du clan n'est pas resté sans réponse. Illiyana et ses sœurs ont pris le maquis dans ces bois, retournant la magie de la nature contre les déchiqueteuses qui rongent les troncs, et le sol entre les piles de rondins est devenu un champ de bataille entre l'Alliance et la Horde.\n\nMalgré tout, le camp remplit encore son office : un flot régulier de bois part d'ici vers le Poste de Bois-brisé, dont les murs et les habitants dépendent de ce que leur envoie le Camp de bûcherons Warsong.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "Xavian",
			short = "Xavian s'élève là où se dressait jadis un temple des elfes de la nuit, ses pierres aujourd'hui livrées aux satyres.",
			full = "Xavian s'élève là où se dressait jadis un temple des elfes de la nuit, ses pierres aujourd'hui livrées aux satyres. Des trois places fortes satyres d'Orneval, c'est ici que se concentre le pouvoir : le prince Raze et Geltharis y siègent tous deux parmi ces ruines, et c'est ici que les satyres se sont servis de l'huile volée aux Warsong pour leurs rituels.\n\nLe lieu tire son nom de Xavius, qui aida jadis à ouvrir la voie à la Légion ardente par un portail puisé dans le Puits d'éternité, à Zin-Azshari. Sargeras, mécontent de la lenteur de cette œuvre, changea Xavius en tout premier des satyres. Xavian est assez proche d'Azshara pour que le nom ne semble pas dû au hasard.\n\nDes dryades sont venues affronter Xavian ; l'une d'elles, Anilia, y fut retrouvée mortellement blessée après être partie à la recherche d'une branche de Cenarius que les satyres s'étaient appropriée, gisant à terre au milieu des ruines qu'elle n'avait pu purifier.",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "La grève de Zoram",
			short = "Les vagues de la grève de Zoram se brisent sur ce qui fut jadis une cité.",
			full = "Les vagues de la grève de Zoram se brisent sur ce qui fut jadis une cité. Avant que le monde ne soit déchiré par la Grande fracture, Zoram se dressait ici, ville des elfes de la nuit, et lorsque la mer monta pour réclamer sa part du monde brisé, Zoram sombra avec elle. Il ne reste aujourd'hui rien au-dessus des flots, hormis le nom.\n\nCeux qui arpentent la grève aujourd'hui ne sont pas des elfes mais des nagas. Ils ont fait du rivage leur domaine, et les débris éparpillés sur le sable, navires brisés, carcasses de créatures marines échouées, montrent à quel point la côte est passée entre leurs mains. Parmi les rochers et les creux noyés tout proches s'étendent les Profondeurs de Brassenoire, enfoncées dans la terre comme Zoram s'enfonça jadis dans la mer.\n\nLa Horde tient ici un modeste point d'appui, l'Avant-poste de Zoram'gar, par nécessité plus que par choix, et s'est épuisée à combattre les nagas Wrathtail qui lui disputent chaque pouce de la grève. Ces mêmes nagas s'abattirent sur Talen, laissant l'avant-poste face à des ennemis qui le pressent de plus d'un côté. C'est une côte rude, humide et disputée, revendiquée par un empire englouti, et tenue désormais par des créatures nées de la mer qui l'avala.",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "Avant-poste de Zoram'gar",
			short = "L'Avant-poste de Zoram'gar est un port de la Horde sur la grève de Zoram, en Orneval, dont les quais s'avancent dans les eaux en contrebas.",
			full = "L'Avant-poste de Zoram'gar est un port de la Horde sur la grève de Zoram, en Orneval, dont les quais s'avancent dans les eaux en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
	-- Mille pointes: 20 subzones
	[1441] = {
		["camp ethok"] = {
			name = "Camp E'thok",
			short = "Le Camp E'thok est un camp de centaures Galak dans le nord-ouest des Mille pointes.",
			full = "Le Camp E'thok est un camp de centaures Galak dans le nord-ouest des Mille pointes. Ses centaures attaquèrent une caravane qui transportait le gobelin Wizlo Bearingshiner, mais ne purent voler le gadget auquel il tenait le plus, gardé en sûreté au cou de sa féroce panthère apprivoisée.",
			source = "https://warcraft.wiki.gg/wiki/Camp_E'thok",
		},
		["darkcloud pinnacle"] = {
			name = "Cime de Noir-nuage",
			short = "La Cime de Noir-nuage s'élève sur trois petites mesas à l'est de la Grande élévation, leurs sommets reliés par des ponts de corde tendus au-dessus du vide.",
			full = "La Cime de Noir-nuage s'élève sur trois petites mesas à l'est de la Grande élévation, leurs sommets reliés par des ponts de corde tendus au-dessus du vide. Seuls deux chemins y mènent, chacun bien gardé : une pente naturelle à travers une quatrième mesa, ou un pont venant des Souilles de Tranchebauge.\n\nLes taurens Totem sinistre tiennent ces hauteurs, menés par Arnak Grimtotem et Harb Foulmountain. Derrière les ponts gardés, les deux chefs entretiennent une correspondance secrète avec quelque sombre puissance dont l'identité est inconnue. Ce qui passe entre eux n'est pas évoqué ouvertement, mais le soin mis à isoler les mesas montre à quel point ce secret est jalousement gardé.",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["freewind post"] = {
			name = "Poste de Librevent",
			short = "Le Poste de Librevent se dresse au sommet d'une mesa des Mille pointes, hors de portée des centaures qui errent en contrebas.",
			full = "Le Poste de Librevent se dresse au sommet d'une mesa des Mille pointes, hors de portée des centaures qui errent en contrebas. Des monte-charges de bois hissent ses habitants depuis le fond du canyon, et des ponts de corde sont tendus entre les pitons voisins, montant de piton en piton jusqu'au village. En bas, les centaures Galak lancent leurs bandes de guerre, et des harpies tournoient en criant au-dessus des plaines, mais c'est la hauteur elle-même qui constitue la véritable défense du poste.\n\nLe mal plus profond vint du nord-ouest, de la Cime de Noir-nuage, où la tribu Totem sinistre tenait ses propres hauteurs. Le Poste de Librevent se méfia d'eux bien avant que la guerre n'éclate au grand jour : des taurens disparaissaient, des agents d'origine inconnue et sinistre furent vus se rendant à la cime, et des meurtres furent imputés aux Totem sinistre. Le chef Arnak Grimtotem porta le plus lourd de la faute. Lorsque Lakota Windsong, du Poste de Librevent, repoussa ses avances, il la fit enlever de force, et lorsque son frère vint la défendre, les Totem sinistre le tuèrent.",
			source = "https://warcraft.wiki.gg/wiki/Freewind_Post",
		},
		["great lift"] = {
			name = "La Grande élévation",
			short = "La Grande élévation est un ascenseur bâti par les taurens, qui transporte les voyageurs entre les Tarides et les Mille pointes, en contrebas. Grish Longrunner et le brave Moonhorn y montent la garde pour la Horde.",
			full = "La Grande élévation est un ascenseur bâti par les taurens, qui transporte les voyageurs entre les Tarides et les Mille pointes, en contrebas. Grish Longrunner et le brave Moonhorn y montent la garde pour la Horde.",
			source = "https://warcraft.wiki.gg/wiki/Great_Lift",
		},
		["highperch"] = {
			name = "Haut-perchoir",
			short = "Haut-perchoir s'élève au-dessus des Mille pointes, domaine des wyvernes et de leurs nids. Parmi les escarpements, le tauren Pao'ka Swiftmountain est bloqué, espérant se glisser entre les wyvernes pour rentrer chez lui.",
			full = "Haut-perchoir s'élève au-dessus des Mille pointes, domaine des wyvernes et de leurs nids. Parmi les escarpements, le tauren Pao'ka Swiftmountain est bloqué, espérant se glisser entre les wyvernes pour rentrer chez lui.",
			source = "https://warcraft.wiki.gg/wiki/Highperch",
		},
		["ironstone camp"] = {
			name = "Camp Rochefer",
			short = "Le Camp Rochefer se trouve à la lisière des Salines.",
			full = "Le Camp Rochefer se trouve à la lisière des Salines.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Camp",
		},
		["mirage raceway"] = {
			name = "Piste des mirages",
			short = "Un gobelin nommé Pozzik et un gnome nommé Fizzle Brassbolts croyaient chacun que leur peuple comptait les ingénieurs les plus ingénieux, et aucun ne voulait en démordre.",
			full = "Un gobelin nommé Pozzik et un gnome nommé Fizzle Brassbolts croyaient chacun que leur peuple comptait les ingénieurs les plus ingénieux, et aucun ne voulait en démordre. Ils réglèrent donc la question en bons bricoleurs : ils construisirent une piste, et ils construisirent des voitures-fusées pour y courir.\n\nCette rivalité attire des foules bien au-delà d'eux deux. Horde comme Alliance viennent acclamer leurs favoris tandis que les bolides gnomes et gobelins s'affrontent chaque jour, chaque équipe s'empressant ensuite de reconstruire ses moteurs avec quelque nouvel avantage. Le véritable enjeu est toujours le même : quelle race construit la meilleure machine, et la question n'est jamais tranchée.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Raceway",
		},
		["razorfen downs"] = {
			name = "Souilles de Tranchebauge",
			short = "Au plus profond des ronces des Mille pointes s'étend un dédale d'épines et d'ossements, dont l'entrée aurait été façonnée dans la gueule même d'Agamaggan, une ouverture en arche dans le dôme extérieur si bien cachée que seuls ceux qui en connaissent déjà la forme peuvent la trouver.",
			full = "Au plus profond des ronces des Mille pointes s'étend un dédale d'épines et d'ossements, dont l'entrée aurait été façonnée dans la gueule même d'Agamaggan, une ouverture en arche dans le dôme extérieur si bien cachée que seuls ceux qui en connaissent déjà la forme peuvent la trouver. Ce sont les Souilles de Tranchebauge, le lieu de sépulture ancestral et la capitale traditionnelle des hurans, façonnés à partir des mêmes lianes puissantes que le Kraal de Tranchebauge. Charlga Trancheflanc façonna la plus grande partie de l'immense dôme d'épines qui les recouvre.\n\nPendant des générations, les Souilles furent le lieu des morts hurans, veillé par les grands prêtres de la tribu de la Tête de Mort. Mais après la troisième guerre, la liche Amnennar le Porte-froid lança ses agents contre les hurans et s'empara de leur cité sainte, la liant pour en faire un bastion du Fléau. Les hurans se battirent âprement pour reprendre ce qui était à eux avant que la peste d'Amnennar ne se répande plus loin dans les Tarides, et dans cette lutte les vivants furent entraînés et enfermés dans les épines aux côtés des morts.\n\nAmnennar demeure toujours au sein du labyrinthe, régnant sur les hurans qu'il a pliés à sa volonté, son emprise sur les Souilles intacte.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Downs",
		},
		["roguefeather den"] = {
			name = "Tanière des Volplumes",
			short = "Dans une petite caverne du centre-sud des Mille pointes, les harpies de la Tanière des Volplumes ont établi leur nid.",
			full = "Dans une petite caverne du centre-sud des Mille pointes, les harpies de la Tanière des Volplumes ont établi leur nid. Elles poussent des cris stridents contre quiconque s'approche, et au fond de la tanière elles amassent les vivres qu'elles ont rassemblés, gardant leurs réserves aussi farouchement que leurs petits.",
			source = "https://warcraft.wiki.gg/wiki/Roguefeather_Den",
		},
		["rustmaul dig site"] = {
			name = "Site de fouilles de Rustmaul",
			short = "Le Site de fouilles de Rustmaul se trouve dans les Salines, ses tranchées abandonnées en plein travail. La Ligue des explorateurs était venue ici mettre au jour d'anciennes ruines, fouillant le sol à l'ombre d'une grotte qui abritait un nid de silithides.",
			full = "Le Site de fouilles de Rustmaul se trouve dans les Salines, ses tranchées abandonnées en plein travail. La Ligue des explorateurs était venue ici mettre au jour d'anciennes ruines, fouillant le sol à l'ombre d'une grotte qui abritait un nid de silithides.\n\nLes fouilles s'arrêtèrent avant d'être achevées. Les tranchées restent ouvertes et vides, les outils des nains abandonnés là où on les avait laissés, et la grotte sous le site abrite toujours les silithides qui y vivent.",
			source = "https://warcraft.wiki.gg/wiki/Rustmaul_Dig_Site",
		},
		["screeching canyon"] = {
			name = "Canyon des hurlements",
			short = "Le Canyon des hurlements entaille le sud des Mille pointes, ses parois résonnant des cris des harpies Hurleuses qui l'infestent.",
			full = "Le Canyon des hurlements entaille le sud des Mille pointes, ses parois résonnant des cris des harpies Hurleuses qui l'infestent. Au fond du canyon se trouve la Tanière des Volplumes, la place forte des harpies.",
			source = "https://warcraft.wiki.gg/wiki/Screeching_Canyon",
		},
		["shimmering flats"] = {
			name = "Les Salines",
			short = "Les Salines s'étendent à la lisière sud-est des Mille pointes, là où la terre s'étire, plate et nue, jusqu'à la frontière de Tanaris.",
			full = "Les Salines s'étendent à la lisière sud-est des Mille pointes, là où la terre s'étire, plate et nue, jusqu'à la frontière de Tanaris. Rien n'y pousse. Le sol n'est que sel durci par le soleil, où ne vivent que basilics, scorpides, tortues et vautours. C'était jadis le fond d'un lac : la coque naufragée d'un voilier gît encore à demi enfouie dans le nord des Salines, un navire échoué loin de toute eau, preuve de ce qu'était ce lieu avant de se dessécher en sel et en terre craquelée.\n\nCette platitude attira gobelins et gnomes, des deux bords de leur longue rivalité. Ils y élevèrent la Piste des mirages et rivalisèrent pour construire des machines plus rapides les unes que les autres. Les engins tenaient rarement le coup. Des cratères grêlent les Salines là où des moteurs ont mal tourné, et les épaves de bolides ratés gisent éparpillées sur le sel, laissées à cuire là où elles sont tombées.",
			source = "https://warcraft.wiki.gg/wiki/Shimmering_Flats",
		},
		["splithoof crag"] = {
			name = "Combe du Sabot fendu",
			short = "La Combe du Sabot fendu se dresse contre la paroi nord des Mille pointes, à l'est de la Cime de Noir-nuage, foyer des centaures Galak.",
			full = "La Combe du Sabot fendu se dresse contre la paroi nord des Mille pointes, à l'est de la Cime de Noir-nuage, foyer des centaures Galak. En son centre se trouve le Bastion du Sabot fendu, une caverne à flanc de montagne où les Galak gardent le Sabot fendu, un artefact antique protégé par l'Ancien brasero et sa flamme sacrée.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Crag",
		},
		["splithoof hold"] = {
			name = "Bastion du Sabot fendu",
			short = "Les centaures Galak ont fait du Bastion du Sabot fendu leur place forte, dans les grottes de la Combe du Sabot fendu. En son sein brûle la flamme sacrée sur l'Ancien brasero, un feu qui, dit-on, brûle même sous l'eau.",
			full = "Les centaures Galak ont fait du Bastion du Sabot fendu leur place forte, dans les grottes de la Combe du Sabot fendu. En son sein brûle la flamme sacrée sur l'Ancien brasero, un feu qui, dit-on, brûle même sous l'eau.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Hold",
		},
		["tahonda ruins"] = {
			name = "Ruines de Tahonda",
			short = "Un village tauren se dressait jadis là où s'étendent aujourd'hui les Salines, depuis longtemps tombé en ruine et englouti par le sable. Des basilics Pierre-de-sel nichent désormais parmi les pierres, et certains disent que ce sont eux qui chassèrent les taurens.",
			full = "Un village tauren se dressait jadis là où s'étendent aujourd'hui les Salines, depuis longtemps tombé en ruine et englouti par le sable. Des basilics Pierre-de-sel nichent désormais parmi les pierres, et certains disent que ce sont eux qui chassèrent les taurens.\n\nUn indice demeure : sur la paroi de cuir d'un bâtiment, deux séries de trois déchirures parallèles, la marque de griffes, et non du vent ou du temps. Quelque chose s'en est pris à ce village avec détermination.\n\nAucun nom n'a survécu. Seules les ruines demeurent, près du sentier de montagne qui mène à Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Tahonda_Ruins",
		},
		["weathered nook"] = {
			name = "La niche érodée",
			short = "La paroi nord des Mille pointes cache une petite grotte connue sous le nom de Recoin érodé, qu'il est facile de manquer à moins de savoir où chercher.",
			full = "La paroi nord des Mille pointes cache une petite grotte connue sous le nom de Recoin érodé, qu'il est facile de manquer à moins de savoir où chercher. C'est là que le traqueur des plaines Dorn et Prate Cloudseer ont établi leur demeure, à l'abri des vents et de la poussière du canyon en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Weathered_Nook",
		},
		["weazels crater"] = {
			name = "Cratère de Weazel",
			short = "Une grande balafre s'ouvre dans le nord des Salines, assez profonde pour avaler la lumière en plein midi. Nul ne sait comment elle s'est formée, bien que son nom évoque un certain Weazel, qu'il l'ait découverte ou créée.",
			full = "Une grande balafre s'ouvre dans le nord des Salines, assez profonde pour avaler la lumière en plein midi. Nul ne sait comment elle s'est formée, bien que son nom évoque un certain Weazel, qu'il l'ait découverte ou créée. Les décombres épars et les cratères plus petits alentour laissent penser à une bricole gobeline ou gnome qui aurait mal tourné, quelque invention poussée trop loin.\n\nLes basilics Pierre-de-sel ont depuis fait de la fosse leur domaine.",
			source = "https://warcraft.wiki.gg/wiki/Weazel's_Crater",
		},
		["whitereach post"] = {
			name = "Poste de Blanc-relais",
			short = "Le Poste de Blanc-relais est un petit camp de la Horde le long de la route, près du Camp E'thok, dans les Mille pointes.",
			full = "Le Poste de Blanc-relais est un petit camp de la Horde le long de la route, près du Camp E'thok, dans les Mille pointes.",
			source = "https://warcraft.wiki.gg/wiki/Whitereach_Post",
		},
		["windbreak canyon"] = {
			name = "Canyon de Brisevent",
			short = "Le Canyon de Brisevent s'étend entre le Poste de Librevent et les Salines, ses parois criblées de nids. Les serpents des vents en ont fait leur domaine, s'élevant sur les courants qui donnent son nom au canyon.",
			full = "Le Canyon de Brisevent s'étend entre le Poste de Librevent et les Salines, ses parois criblées de nids. Les serpents des vents en ont fait leur domaine, s'élevant sur les courants qui donnent son nom au canyon. Un sentier y mène jusqu'au Recoin érodé.",
			source = "https://warcraft.wiki.gg/wiki/Windbreak_Canyon",
		},
	},
	-- Les Serres-Rocheuses: 18 subzones
	[1442] = {
		["blackwolf river"] = {
			name = "Fleuve Loup-noir",
			short = "Le fleuve Loup-noir s'écoule du lac de la Combe à travers la Combe des Cisailles, dans les Serres-Rocheuses. Ses eaux sont souillées, empoisonnées par le déboisement de la vallée par la KapitalRisk.",
			full = "Le fleuve Loup-noir s'écoule du lac de la Combe à travers la Combe des Cisailles, dans les Serres-Rocheuses. Ses eaux sont souillées, empoisonnées par le déboisement de la vallée par la KapitalRisk.",
			source = "https://warcraft.wiki.gg/wiki/Blackwolf_River",
		},
		["boulderslide cavern"] = {
			name = "Caverne des Eboulis",
			short = "Au bout du Ravin des Éboulis, la Caverne des Éboulis abrite le nid des kobolds des Éboulis. Ils extraient un cristal violet rare appelé résonite, imprégné de magie tellurique, et défendent chacun de ses filons au péril de leur vie.",
			full = "Au bout du Ravin des Éboulis, la Caverne des Éboulis abrite le nid des kobolds des Éboulis. Ils extraient un cristal violet rare appelé résonite, imprégné de magie tellurique, et défendent chacun de ses filons au péril de leur vie.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Cavern",
		},
		["boulderslide ravine"] = {
			name = "Ravin des Eboulis",
			short = "Le Ravin des Éboulis s'étend paisiblement le long du Sentier des Tisseuses, épargné par les guerres qui troublent les terres alentour. Des béliers se fraient un chemin sur ses pentes, et des foudroyeurs des falaises tournoient au-dessus.",
			full = "Le Ravin des Éboulis s'étend paisiblement le long du Sentier des Tisseuses, épargné par les guerres qui troublent les terres alentour. Des béliers se fraient un chemin sur ses pentes, et des foudroyeurs des falaises tournoient au-dessus.\n\nEn face de la caverne du ravin se trouve une grotte abandonnée, ses tonneaux toujours empilés, ses torches grossières toujours dressées bien que personne ne reste pour les allumer. Sur ses parois subsiste un art tribal, tracé dans un style qui semble l'œuvre des taurens.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Ravine",
		},
		["camp aparaje"] = {
			name = "Camp Aparaje",
			short = "Le Camp Aparaje était un village tauren de l'est des Serres-Rocheuses, attaqué par les forces Totem sinistre venues du Poste Totem sinistre sous les ordres de Grundig Darkcloud.",
			full = "Le Camp Aparaje était un village tauren de l'est des Serres-Rocheuses, attaqué par les forces Totem sinistre venues du Poste Totem sinistre sous les ordres de Grundig Darkcloud. Makaba Flathoof y vivait avec sa fille Kaya avant l'attaque.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Aparaje",
		},
		["charred vale"] = {
			name = "Le Val calciné",
			short = "Le Val calciné était jadis verdoyant, une vallée du sud-ouest des Serres-Rocheuses où les harpies Bloodfury faisaient leurs nids et où des tréants parcouraient la forêt en gardiens.",
			full = "Le Val calciné était jadis verdoyant, une vallée du sud-ouest des Serres-Rocheuses où les harpies Bloodfury faisaient leurs nids et où des tréants parcouraient la forêt en gardiens.\n\nPuis les gobelins de la KapitalRisk vinrent dépouiller le val de son bois et de son minerai. Les tréants se dressèrent contre eux et repoussèrent les machines, mais les esprits du val refusèrent de s'apaiser. Les fouilles avaient réveillé quelque chose sous la terre, et le feu et les élémentaires jaillirent du sol éventré là où se dressait la forêt. Les tréants qui avaient repoussé les gobelins n'en revinrent pas intacts ; quoi que les armes des gobelins leur aient infligé, cela demeura, et ils comptent désormais parmi les dangers du val plutôt que parmi ses gardiens.\n\nIl ne reste qu'une vallée de flammes et de lave, où des arbres noirs se dressent dans la cendre là où se dressaient autrefois des arbres verts. Les druides de la Retraite de Roche-Soleil ont repris l'œuvre qu'accomplissaient jadis les tréants, faisant renaître la végétation sur la terre brûlée dans l'espoir que le val redevienne une forêt plutôt qu'une plaie dans les montagnes.",
			source = "https://warcraft.wiki.gg/wiki/Charred_Vale",
		},
		["cragpool lake"] = {
			name = "Lac de la Combe",
			short = "Le lac de la Combe s'étend sous la grande structure de bois que la KapitalRisk a élevée au-dessus de la Combe des Cisailles. Gerenzo Wrenchwhistle surveille l'exploitation depuis cet endroit.",
			full = "Le lac de la Combe s'étend sous la grande structure de bois que la KapitalRisk a élevée au-dessus de la Combe des Cisailles. Gerenzo Wrenchwhistle surveille l'exploitation depuis cet endroit.\n\nLe lac lui-même est interdit, revendiqué par Cragjaw, un poisson devenu monstrueux dans ses eaux immobiles.",
			source = "https://warcraft.wiki.gg/wiki/Cragpool_Lake",
		},
		["greatwood vale"] = {
			name = "Val de Grandbois",
			short = "Le Val de Grandbois s'étend, boisé, sur les contreforts des Serres-Rocheuses ; on y accède par le Sentier des Tisseuses, et Malaka'jin se trouve à son sud.",
			full = "Le Val de Grandbois s'étend, boisé, sur les contreforts des Serres-Rocheuses ; on y accède par le Sentier des Tisseuses, et Malaka'jin se trouve à son sud.\n\nLa quiétude du val se brisa lorsque la tribu Totem sinistre, sous les ordres de Grundig Darkcloud, s'abattit sur le Camp Aparaje et massacra presque tous ses habitants. Makaba Flathoof survécut, et appela en retour à traquer les Totem sinistre du val.",
			source = "https://warcraft.wiki.gg/wiki/Greatwood_Vale",
		},
		["grimtotem post"] = {
			name = "Poste Totem sinistre",
			short = "Le Poste Totem sinistre est le point d'appui de la tribu dans les Serres-Rocheuses, dont les brutes, les voyous, les sorciers et les mercenaires patrouillent les pentes alentour.",
			full = "Le Poste Totem sinistre est le point d'appui de la tribu dans les Serres-Rocheuses, dont les brutes, les voyous, les sorciers et les mercenaires patrouillent les pentes alentour. Grundig Darkcloud les commande ici, tenant le poste pour les desseins propres des Totem sinistre.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Post",
		},
		["malakajin"] = {
			name = "Malaka'jin",
			short = "Malaka'jin se trouve dans les Serres-Rocheuses, au sud du Poste Totem sinistre.",
			full = "Malaka'jin se trouve dans les Serres-Rocheuses, au sud du Poste Totem sinistre. C'est un modeste village, foyer de chasseurs trolls qui gagnent leur vie en vendant leurs prises aux membres de la Horde de passage, un point d'appui en vue du territoire des Totem sinistre.",
			source = "https://warcraft.wiki.gg/wiki/Malaka'jin",
		},
		["mirkfallon lake"] = {
			name = "Lac Mirkfallon",
			short = "Le lac Mirkfallon se trouve au cœur des Serres-Rocheuses, un bassin sauvage peuplé de wyvernes, de limons et de lézards-tonnerre qui évoluent dans ses eaux et sur ses rives.",
			full = "Le lac Mirkfallon se trouve au cœur des Serres-Rocheuses, un bassin sauvage peuplé de wyvernes, de limons et de lézards-tonnerre qui évoluent dans ses eaux et sur ses rives. Une colline s'élève au centre du lac, et au-dessus, sur les hauteurs des Cisailles, les dernières wyvernes de la région nichent encore.",
			source = "https://warcraft.wiki.gg/wiki/Mirkfallon_Lake",
		},
		["sishir canyon"] = {
			name = "Canyon de Sishir",
			short = "Le canyon mène de la route principale des Serres-Rocheuses vers les ruines d'Eldre'thar, mais nul ne le traverse aisément.",
			full = "Le canyon mène de la route principale des Serres-Rocheuses vers les ruines d'Eldre'thar, mais nul ne le traverse aisément. Le Canyon de Sishir est entièrement livré aux araignées Deepmoss, une couvée monstrueuse dont les œufs et les toiles étouffent chaque corniche et chaque creux de la pierre. Tout au fond, la plus grande d'entre elles, Besseleth, attend parmi les siennes.",
			source = "https://warcraft.wiki.gg/wiki/Sishir_Canyon",
		},
		["stonetalon peak"] = {
			name = "Pic des Serres-Rocheuses",
			short = "Le Pic des Serres-Rocheuses se trouve dans une vallée verdoyante, à l'extrême nord-ouest des montagnes qui partagent son nom, veillé par les druides de la Tanière des Serres, toute proche.",
			full = "Le Pic des Serres-Rocheuses se trouve dans une vallée verdoyante, à l'extrême nord-ouest des montagnes qui partagent son nom, veillé par les druides de la Tanière des Serres, toute proche. La montagne est tenue pour sacrée, et la magie imprègne profondément sa pierre.\n\nPendant la troisième guerre, Jaina Proudmoore et son expédition vinrent ici et établirent un camp près de l'entrée des cavernes situées sous le pic. Thrall et sa Horde suivirent, à la recherche de l'Oracle.\n\nIl est depuis devenu un point de ralliement pour les elfes de la nuit et l'Alliance, ses druides veillant sur la vallée.",
			source = "https://warcraft.wiki.gg/wiki/Stonetalon_Peak",
		},
		["sun rock retreat"] = {
			name = "Retraite de Roche-Soleil",
			short = "La Retraite de Roche-Soleil se cache parmi les pics au sud du lac Mirkfallon, dans les Serres-Rocheuses, un lieu où le monde des esprits touche de près celui des vivants.",
			full = "La Retraite de Roche-Soleil se cache parmi les pics au sud du lac Mirkfallon, dans les Serres-Rocheuses, un lieu où le monde des esprits touche de près celui des vivants. Bien avant que la Horde n'y hisse ses bannières, les taurens venaient en pèlerinage sur cette pierre pour accomplir leurs rites de passage vers le royaume des esprits. On dit qu'An'she, le soleil, embrassa jadis la montagne où se dresse aujourd'hui la retraite.\n\nDésormais, orcs et taurens tiennent ensemble la Retraite de Roche-Soleil, le plus grand rassemblement des forces de la Horde dans ces montagnes, un centre de commerce et de labeur, qui répare ce que la KapitalRisk et d'autres forces malfaisantes ont arraché à la terre.",
			source = "https://warcraft.wiki.gg/wiki/Sun_Rock_Retreat",
		},
		["talon den"] = {
			name = "L'antre des Serres",
			short = "Haut sur le Pic des Serres-Rocheuses, la terre s'ouvre sur la Tanière des Serres, un tertre qui abrite les dryades Mirkfallon et les gardiens qui partagent leur nom, sous la surveillance de Gardiens cénariens elfes de la nuit.",
			full = "Haut sur le Pic des Serres-Rocheuses, la terre s'ouvre sur la Tanière des Serres, un tertre qui abrite les dryades Mirkfallon et les gardiens qui partagent leur nom, sous la surveillance de Gardiens cénariens elfes de la nuit.",
			source = "https://warcraft.wiki.gg/wiki/Talon_Den",
		},
		["talondeep path"] = {
			name = "La Perce des Serres",
			short = "La Perce des Serres est un tunnel sinueux qui relie Orneval aux Serres-Rocheuses, un passage irrégulier ponctué de petits culs-de-sac et d'étranges creux usés dans la roche.",
			full = "La Perce des Serres est un tunnel sinueux qui relie Orneval aux Serres-Rocheuses, un passage irrégulier ponctué de petits culs-de-sac et d'étranges creux usés dans la roche. Il débouche d'un côté à l'ouest du lac Mystral, et de l'autre dans la partie nord-ouest de la Combe des Cisailles. Rien n'y vit ; ce n'est qu'un chemin à travers les montagnes.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["webwinder path"] = {
			name = "Sentier des Tisseuses",
			short = "Le Sentier des Tisseuses relie Malaka'jin au lac Mirkfallon, à travers une terre qui s'est affaissée de part et d'autre.",
			full = "Le Sentier des Tisseuses relie Malaka'jin au lac Mirkfallon, à travers une terre qui s'est affaissée de part et d'autre. À l'ouest de Malaka'jin, la Horde a bâti une barricade en travers de la route pour empêcher l'Alliance de pousser plus loin vers l'est.",
			source = "https://warcraft.wiki.gg/wiki/Webwinder_Path",
		},
		["windshear crag"] = {
			name = "Combe des Cisailles",
			short = "La Combe des Cisailles était jadis une forêt primaire, dense et verte dans sa vallée des Serres-Rocheuses. Elle ne l'est plus. On n'y trouve que des souches, des eaux souillées et des machines qui ne cessent jamais tout à fait de grincer.",
			full = "La Combe des Cisailles était jadis une forêt primaire, dense et verte dans sa vallée des Serres-Rocheuses. Elle ne l'est plus. On n'y trouve que des souches, des eaux souillées et des machines qui ne cessent jamais tout à fait de grincer.\n\nCette ruine a un nom : Gerenzo Wrenchwhistle, un gnome lépreux à qui l'on a confié la direction de toute l'expédition forestière sous la bannière de la KapitalRisk. Il construisit la Super Moissonneuse 6000, une machine capable de réduire en sciure les plus vieux arbres de la combe, et il contemple son œuvre depuis une plate-forme élevée au-dessus du lac de la Combe, maître de tout ce que la machine a rasé. Sa mainmise sur le lieu l'a rendu superflu aux yeux de ses supérieurs : le directeur Riddlevox, du syndicat des Bricoleurs d'Undermine, veut sa mort, et le gobelin Ziz Fizziks rôde dans la combe, attendant de voir l'ordre exécuté.\n\nDans l'angle sud-est de la combe, les kobolds des Cisailles se sont approprié la Mine des Cisailles, creusant à la recherche de minerai de fer fumé.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Crag",
		},
		["windshear mine"] = {
			name = "Mine des Cisailles",
			short = "La Mine des Cisailles se trouve au bout du fleuve Loup-noir, dans la Combe des Cisailles. La KapitalRisk y exploitait jadis des filons d'étain, en faisant creuser des kobolds.",
			full = "La Mine des Cisailles se trouve au bout du fleuve Loup-noir, dans la Combe des Cisailles. La KapitalRisk y exploitait jadis des filons d'étain, en faisant creuser des kobolds.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Mine",
		},
	},
	-- Désolace: 20 subzones
	[1443] = {
		["bolgans hole"] = {
			name = "Trou de Bolgan",
			short = "Au Village des Gelkis, la grotte appelée Trou de Bolgan abrite les membres les plus éminents du clan, parmi lesquels son khan, Shaka.",
			full = "Au Village des Gelkis, la grotte appelée Trou de Bolgan abrite les membres les plus éminents du clan, parmi lesquels son khan, Shaka.\n\nTout au fond poussent des cristaux bleus, les larmes de Theradras, amassés par les chamans Gelkis, qui croient que ces pierres portent la protection de la princesse.",
			source = "https://warcraft.wiki.gg/wiki/Bolgan's_Hole",
		},
		["ethel rethor"] = {
			name = "Ethel Rethor",
			short = "Au large de la côte nord-ouest de Désolace, la mer a englouti la plus grande partie d'Ethel Rethor. Seule une tour solitaire perce la surface, reliée au rivage par un étroit pont menant à une porte qui reste close.",
			full = "Au large de la côte nord-ouest de Désolace, la mer a englouti la plus grande partie d'Ethel Rethor. Seule une tour solitaire perce la surface, reliée au rivage par un étroit pont menant à une porte qui reste close. Des nagas ont fait de la ruine engloutie leur domaine.",
			source = "https://warcraft.wiki.gg/wiki/Ethel_Rethor",
		},
		["gelkis village"] = {
			name = "Village des Gelkis",
			short = "Le Village des Gelkis s'étend en cercle autour d'un large ravin dans le sud-ouest de Désolace, siège du clan Gelkis.",
			full = "Le Village des Gelkis s'étend en cercle autour d'un large ravin dans le sud-ouest de Désolace, siège du clan Gelkis. Des ponts tendus entre les falaises et les escarpements du ravin descendent jusqu'au Trou de Bolgan, une grotte taillée dans le flanc sud de la montagne, où réside le khan des Gelkis.\n\nLe village touche la grande route nord-sud de Désolace, si près que la route elle-même est devenue dangereuse pour ceux qui l'empruntent. Les Gelkis ont poussé de nouvelles huttes à l'est de la route qui mène vers Féralas, le long du lac, s'étendant au-delà du ravin qui les abrita d'abord.",
			source = "https://warcraft.wiki.gg/wiki/Gelkis_Village",
		},
		["ghost walker post"] = {
			name = "Poste de Rôdeur-fantôme",
			short = "Le Poste de Rôdeur-fantôme se dresse à côté du Cimetière des kodos, au centre de Désolace, et les morts qui y reposent façonnent tout en ce lieu.",
			full = "Le Poste de Rôdeur-fantôme se dresse à côté du Cimetière des kodos, au centre de Désolace, et les morts qui y reposent façonnent tout en ce lieu. Des chamans taurens veillent sur les ossements, accompagnant les esprits des kodos tombés vers leurs vies suivantes et, lorsque le besoin s'en fait sentir, conversant avec ceux qui sont déjà partis. Gurda Wildmane les dirige, tenant ce poste exposé avec à peine le strict nécessaire pour le faire vivre.\n\nContrairement à Proie-de-l'Ombre, en sécurité ailleurs dans la région, le Poste de Rôdeur-fantôme ne connaît pas une telle sûreté. C'est un camp avancé bâti pour la guerre, non pour le confort, sans auberge ni lieu de repos. Il n'existe que dans un seul but : porter le combat de la Horde contre les cultistes de la Lame ardente et les tribus centaures qui parcourent Désolace.",
			source = "https://warcraft.wiki.gg/wiki/Ghost_Walker_Post",
		},
		["kodo graveyard"] = {
			name = "Cimetière des kodos",
			short = "Les kodos de Désolace viennent ici pour mourir, leurs ossements entassés et blanchis sur la terre craquelée. Qu'on les dérange, et les morts ne restent pas tranquilles : des apparitions de kodos surgissent du sol pour garder ce qui reste des leurs.",
			full = "Les kodos de Désolace viennent ici pour mourir, leurs ossements entassés et blanchis sur la terre craquelée. Qu'on les dérange, et les morts ne restent pas tranquilles : des apparitions de kodos surgissent du sol pour garder ce qui reste des leurs.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Graveyard",
		},
		["kolkar village"] = {
			name = "Village des Kolkar",
			short = "Le village situé à la lisière orientale de Désolace est le siège du clan Kolkar, le plus prolifique des clans centaures de Kalimdor, qui possède des avant-postes jusque dans les Tarides et en Durotar.",
			full = "Le village situé à la lisière orientale de Désolace est le siège du clan Kolkar, le plus prolifique des clans centaures de Kalimdor, qui possède des avant-postes jusque dans les Tarides et en Durotar. Leurs rivaux, les Magram, les harcèlent sans cesse, car la querelle entre les clans ne connaît jamais de répit.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Village",
		},
		["kormeks hut"] = {
			name = "Hutte de Kormek",
			short = "La hutte se dresse, usée par les intempéries, dans le centre-nord de Désolace. À l'intérieur vit Saule, membre du Marteau du crépuscule, qui entretient les lieux avec une chaleur inattendue pour un membre de ce culte.",
			full = "La hutte se dresse, usée par les intempéries, dans le centre-nord de Désolace. À l'intérieur vit Saule, membre du Marteau du crépuscule, qui entretient les lieux avec une chaleur inattendue pour un membre de ce culte. Dehors, dans un enclos jonché d'os de kodos, Bibbly F'utzbuckle danse parmi les restes, ravi du profit que de tels ossements pourraient rapporter.",
			source = "https://warcraft.wiki.gg/wiki/Kormek's_Hut",
		},
		["magram village"] = {
			name = "Village des Magram",
			short = "Le Village des Magram s'élève sur un chapelet d'îlots au milieu de mares jaunes et polluées, dans le sud-est de Désolace, ses huttes reliées par de grossiers ponts jetés au-dessus de l'eau.",
			full = "Le Village des Magram s'élève sur un chapelet d'îlots au milieu de mares jaunes et polluées, dans le sud-est de Désolace, ses huttes reliées par de grossiers ponts jetés au-dessus de l'eau. C'est ici que vit le clan Magram, l'un des peuples centaures en guerre contre le clan Gelkis pour la domination de ces terres stériles.",
			source = "https://warcraft.wiki.gg/wiki/Magram_Village",
		},
		["mannoroc coven"] = {
			name = "Convent de Mannoroc",
			short = "Parmi les ruines des elfes de la nuit qui gisent brisées à travers Désolace, un lieu porte un nom qu'aucun voyageur ne prononce à la légère.",
			full = "Parmi les ruines des elfes de la nuit qui gisent brisées à travers Désolace, un lieu porte un nom qu'aucun voyageur ne prononce à la légère. Le Convent de Mannoroc tire son nom de Mannoroth, le redoutable seigneur des Abîmes, et le sol s'en souvient. La terre était morte bien avant la venue des démons, mais la magie gangrenée l'a dévastée plus encore, au point que l'air même est chargé de corruption et qu'un voile mortel s'abat sur quiconque y pénètre.\n\nLes cultistes de la Lame ardente ouvrirent la voie, déchirant plusieurs portails dans le monde pour invoquer à travers eux les serviteurs de la Légion ardente : infernaux, succubes, chiens corrompus et gangregardes qui rôdent aujourd'hui dans les ruines. Lord Azrethoc commande ces démons, tandis que le démoniste orc Jugkar Grim'rod se tient parmi eux, porte-parole de la Lame ardente au sein du convent. Ensemble, ils ont constitué le plus grand rassemblement de démons de tout le centre de Kalimdor, preuve que le dessein des cultistes a réussi bien au-delà d'un simple avertissement.",
			source = "https://warcraft.wiki.gg/wiki/Mannoroc_Coven",
		},
		["nijels point"] = {
			name = "Combe de Nijel",
			short = "La Combe de Nijel monte la garde dans les montagnes du nord de Désolace, un avant-poste tenu par l'Alliance et le Cercle cénarien.",
			full = "La Combe de Nijel monte la garde dans les montagnes du nord de Désolace, un avant-poste tenu par l'Alliance et le Cercle cénarien.\n\nLe gardien Marandis vint ici avec ses sœurs dryades, faisant de l'avant-poste leur base tandis qu'elles poursuivaient la princesse Theradras. Leur but était de reprendre le corps de Zaetar dans les profondeurs de Maraudon et de le ramener dans les Serres-Rocheuses.\n\nAu même moment, l'armée de Stormwind y posta la garde de la Combe de Nijel sous les ordres du capitaine Pentigast, face à la menace des clans centaures qui tenaient la région. Pentigast observait la rivalité entre les Gelkis et les Magram avec la méfiance d'un soldat, certain que le clan qui l'emporterait deviendrait assez hardi pour se retourner contre les possessions voisines de l'Alliance, et il chercha donc à apprendre comment vaincre les centaures en opposant un clan à l'autre.",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "Ile de Ranazjar",
			short = "L'île de Ranazjar est un petit îlot rocheux au large de la côte nord-ouest de Désolace, repaire des nagas serpentins.",
			full = "L'île de Ranazjar est un petit îlot rocheux au large de la côte nord-ouest de Désolace, repaire des nagas serpentins. Parmi les pierres se dressent des ruines d'elfes de la nuit, vestiges de la même cité antique qu'Ethel Rethor, désormais silencieuses au-dessus des nagas qui y demeurent.",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "Sargeron",
			short = "La cité qui se dressait ici portait jadis un nom elfique, perdu depuis que la guerre des Anciens déchira le monde.",
			full = "La cité qui se dressait ici portait jadis un nom elfique, perdu depuis que la guerre des Anciens déchira le monde. Il n'en reste que des ruines, appelées aujourd'hui Sargeron par les satyres Hatefury qui y demeurent, en l'honneur de leur maître démoniaque Sargeras.\n\nLes ruines abritaient autrefois trois lieux saints d'Elune : sa cathédrale, son temple, son sanctuaire. Des reliques de cette foi plus ancienne gisent encore parmi les pierres : le brasero d'Elune, sa Servante, sa Coupe, et l'antique pierre runique du Vortex.",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "Grève de Sar'theris",
			short = "La côte où Désolace rejoint la mer ne ressemble en rien à la terre qui s'étend derrière elle. Tandis que l'intérieur est gris et désolé, la Grève de Sar'theris est ensoleillée, ses herbes verdoyantes.",
			full = "La côte où Désolace rejoint la mer ne ressemble en rien à la terre qui s'étend derrière elle. Tandis que l'intérieur est gris et désolé, la Grève de Sar'theris est ensoleillée, ses herbes verdoyantes. Des géants des mers pataugent dans ses hauts-fonds, des nagas ondulent dans ses eaux et des makruras détalent sur son sable.\n\nAu pied d'Ethel Rethor, une petite embarcation gît fracassée sur la plage, son bois éclaté, et l'équipage qu'elle portait a disparu.",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "Camp de Scrabblescrew",
			short = "Près du Cimetière des kodos, en Désolace, se trouve un petit camp gobelin.",
			full = "Près du Cimetière des kodos, en Désolace, se trouve un petit camp gobelin. Il appartient à Smeed Scrabblescrew, un gobelin entreprenant qui entretient une caravane de kodos, menant les grandes bêtes à travers les terres désolées pour tout le profit que le pays veut bien offrir.",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "Ravin de Brèche-de-l'Ombre",
			short = "Le Ravin de Brèche-de-l'Ombre se cache dans les montagnes au sud-est de Shok'Thokar, un repli de Désolace sur lequel peu tomberaient par hasard.",
			full = "Le Ravin de Brèche-de-l'Ombre se cache dans les montagnes au sud-est de Shok'Thokar, un repli de Désolace sur lequel peu tomberaient par hasard. Des champignons géants s'élèvent parmi ses rochers, et en son cœur se trouve un cercle d'invocation entravé de chaînes massives, bâti par les cultistes de la Lame ardente qui ont fait du ravin leur refuge.",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "Proie-de-l'Ombre",
			short = "Proie-de-l'Ombre se trouve là où la Grève de Sar'theris rejoint la côte sud de Désolace, un village de pêcheurs trolls.",
			full = "Proie-de-l'Ombre se trouve là où la Grève de Sar'theris rejoint la côte sud de Désolace, un village de pêcheurs trolls. Ses habitants vivent de la mer, et ce sont leurs prises qui nourrissent le Poste de Rôdeur-fantôme, plus à l'intérieur des terres.",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["tethris aran"] = {
			name = "Tethris Aran",
			short = "Des ruines d'elfes de la nuit sont éparpillées dans le nord de Désolace, au nord de la Forteresse de Hache-Tonnerre, vestiges d'une cité que l'on croit détruite lors de la Grande fracture.",
			full = "Des ruines d'elfes de la nuit sont éparpillées dans le nord de Désolace, au nord de la Forteresse de Hache-Tonnerre, vestiges d'une cité que l'on croit détruite lors de la Grande fracture. Rien n'a été reconstruit. Seules les créatures sauvages de Désolace se meuvent désormais parmi les pierres brisées.",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thunder axe fortress"] = {
			name = "Forteresse de Hache-Tonnerre",
			short = "La Forteresse de Hache-Tonnerre se dresse dans le nord-ouest de Désolace, livrée au culte de la Lame ardente.",
			full = "La Forteresse de Hache-Tonnerre se dresse dans le nord-ouest de Désolace, livrée au culte de la Lame ardente. Derrière ses murs, entre donjon, caserne, grotte et tours de guet, les cultistes aux ordres de Kohor s'efforcent d'invoquer le démon Nazargen dans toute sa puissance, se gardant de l'appeler trop tôt, alors qu'il serait assez faible pour être détruit.\n\nLa forteresse abritait jadis le Sceptre de lumière, un artefact d'une terrible puissance que la Lame ardente avait volé aux nagas. Azore Aldamort, au service de l'Aube d'argent, entreprit de le récupérer et, avec de l'aide, parvint à l'arracher à la garde du culte.\n\nEntre ces murs vivait aussi Tyranis Malem, un nom prononcé avec mépris parmi les siens, car il les trahit et se voua à l'étude de la magie démoniaque, faisant de la Forteresse de Hache-Tonnerre le refuge de ces sombres recherches.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["valley of bones"] = {
			name = "Vallée des Ossements",
			short = "La Vallée des Ossements est un escarpement à la lisière sud de Désolace, hanté par des squelettes, des nécromanciens centaures et les fantômes du clan Magram massacré.",
			full = "La Vallée des Ossements est un escarpement à la lisière sud de Désolace, hanté par des squelettes, des nécromanciens centaures et les fantômes du clan Magram massacré. Contre les parois de la falaise reposent deux squelettes gigantesques, les Goliaths morts, dont l'origine est inconnue.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "Vallée des Lances",
			short = "La Vallée des Lances, dans l'ouest de Désolace, abrite le clan centaure des Maraudine, et l'on ne peut y accéder à pied que par d'étroits cols de montagne au sud et à l'est.",
			full = "La Vallée des Lances, dans l'ouest de Désolace, abrite le clan centaure des Maraudine, et l'on ne peut y accéder à pied que par d'étroits cols de montagne au sud et à l'est. À son extrémité sud-ouest se trouve l'entrée de Maraudon. Parmi les centaures est retenue captive Melizza Brimbuzzle.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
	},
	-- Féralas: 28 subzones
	[1444] = {
		["camp mojache"] = {
			name = "Camp Mojache",
			short = "Le Camp Mojache se trouve là où un ruisseau rapide se jette dans le lac des rafales.",
			full = "Le Camp Mojache se trouve là où un ruisseau rapide se jette dans le lac des rafales. Les taurens qui tiennent ce terrain sont connus pour l'épaisseur de leur cuir et le courage de leurs braves, qui protègent les voyageurs des dangers de Féralas.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["dire maul"] = {
			name = "Hache-tripes",
			short = "Il y a douze mille ans, une secte secrète de sorciers elfes de la nuit éleva Eldre'Thalas pour garder les secrets arcaniques les plus précieux de la reine Azshara.",
			full = "Il y a douze mille ans, une secte secrète de sorciers elfes de la nuit éleva Eldre'Thalas pour garder les secrets arcaniques les plus précieux de la reine Azshara. Parmi ses Bien-nés, les arcanistes connus sous le nom de Shen'dralar vivaient dans une splendeur discrète, et l'une d'entre eux, Millicent Serene, créa le Fruit de fertilité, une vigne dont l'aura de croissance et de protection permit à toute la cité de prospérer.\n\nCoupés du Puits d'éternité après la Grande fracture, les Bien-nés lièrent un démon, Immol'thar, et tirèrent leur pouvoir de son emprisonnement. Cela les soutint pendant des milliers d'années, jusqu'à ce que le prix de sa captivité devienne plus lourd que ce qu'il leur donnait. Leur chef, le prince Tortheldrin, y répondit en se retournant contre son propre peuple, massacrant nombre des siens pour libérer assez de puissance afin de maintenir les autres en vie. Les survivants se retirèrent plus profondément dans les ruines sur lesquelles ils régnaient jadis, abandonnant le reste de la cité à tout ce qui viendrait s'y installer.\n\nLa pierre d'Eldre'Thalas se dresse toujours, une énergie arcanique liée en elle par un art dont nul ne se souvient plus, conservant la forme d'une cité qui se nourrit de son propre peuple pour survivre.",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "Bosquet du rêve",
			short = "Un grand arbre s'élève sur un îlot au milieu du lac Jademir, ses racines et ses branches abritant l'un des portails menant au Rêve d'émeraude.",
			full = "Un grand arbre s'élève sur un îlot au milieu du lac Jademir, ses racines et ses branches abritant l'un des portails menant au Rêve d'émeraude. Le vol draconique vert veille sur lui, gardant le seuil contre quiconque voudrait s'en prendre au rêve qui s'étend au-delà.",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["feathermoon stronghold"] = {
			name = "Bastion de Feathermoon",
			short = "Au large de la côte ouest de Féralas, sur l'île de Sardor, se dresse une forteresse élevée dans la mer par le général Shandris Feathermoon, qui depuis dix mille ans se tient aux côtés de Tyrande Whisperwind comme son bras droit parmi les Sentinelles.",
			full = "Au large de la côte ouest de Féralas, sur l'île de Sardor, se dresse une forteresse élevée dans la mer par le général Shandris Feathermoon, qui depuis dix mille ans se tient aux côtés de Tyrande Whisperwind comme son bras droit parmi les Sentinelles. Elle donna son nom au bastion, qui tient encore cette portion de la côte de Kalimdor pour les elfes de la nuit.\n\nSeule la mer le relie au continent, par un bateau qui fait la traversée depuis la Côte oubliée jusqu'au quai de l'île.",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feral scar vale"] = {
			name = "Val des Griffes farouches",
			short = "Dans les plateaux sauvages de l'ouest de Féralas s'étend le Val des Griffes farouches, revendiqué par les yétis Griffes farouches qui lui donnent leur nom.",
			full = "Dans les plateaux sauvages de l'ouest de Féralas s'étend le Val des Griffes farouches, revendiqué par les yétis Griffes farouches qui lui donnent leur nom.",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "La Côte oubliée",
			short = "La Côte oubliée longe toute la lisière ouest de Féralas, là où la terre rencontre la mer voilée. Des élémentaires d'eau surgissent ici du ressac, et des géants des mers arpentent le rivage.",
			full = "La Côte oubliée longe toute la lisière ouest de Féralas, là où la terre rencontre la mer voilée. Des élémentaires d'eau surgissent ici du ressac, et des géants des mers arpentent le rivage.\n\nUn village de pêcheurs murlocs s'accroche à cette côte. On a vu des oiseaux fondre sur lui pour emporter des têtards, et le village a subi tour à tour les raids d'humains et de gnolls. Pires que tous sont les ogres Gordunni, qui s'en prennent à lui depuis des années, entraînant des murlocs en captivité dans les ruines de Hache-tripes. Une douzaine ou plus ont été enlevés ainsi, parmi lesquels deux nommés Murrl et Murrgly.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "Hautes-terres des Aigreplumes",
			short = "Les Hautes-terres des Aigreplumes appartiennent aux hippogriffes Aigreplumes, qui nichent sur les hauteurs et donnent leur nom au pays.",
			full = "Les Hautes-terres des Aigreplumes appartiennent aux hippogriffes Aigreplumes, qui nichent sur les hauteurs et donnent leur nom au pays. Parmi les escarpements, leurs œufs reposent cachés dans des nids épars, gardés par les volées tournoyantes qui ont fait de ces hautes-terres leur foyer.",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordunni outpost"] = {
			name = "Avant-poste des Gordunni",
			short = "Dans les montagnes au nord du Pavillon de Lariss, le sol porte la marque des Gordunni. Alors que Féralas est ailleurs verdoyant, l'avant-poste est flétri et brun sous la présence des ogres.",
			full = "Dans les montagnes au nord du Pavillon de Lariss, le sol porte la marque des Gordunni. Alors que Féralas est ailleurs verdoyant, l'avant-poste est flétri et brun sous la présence des ogres.\n\nDeux grottes marquent les collines, une petite près de l'entrée et un grand monticule au fond, toutes deux tenues par les Gordunni qui revendiquent cette terre ravagée.",
			source = "https://warcraft.wiki.gg/wiki/Gordunni_Outpost",
		},
		["grimtotem compound"] = {
			name = "Base des Totem sinistre",
			short = "La Base des Totem sinistre, à l'est de Hache-tripes, est un foyer que les taurens Totem sinistre se sont bâti. Dans sa partie sud se dresse une grande cage où sont retenus captifs des fées dragons.",
			full = "La Base des Totem sinistre, à l'est de Hache-tripes, est un foyer que les taurens Totem sinistre se sont bâti. Dans sa partie sud se dresse une grande cage où sont retenus captifs des fées dragons. À l'est de la partie nord, des gnolls ont établi leurs propres camps.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Compound",
		},
		["high wilderness"] = {
			name = "Les plateaux sauvages",
			short = "Les plateaux sauvages s'étendent dans l'ouest de Féralas, de la Côte oubliée jusqu'à la Verdantis.",
			full = "Les plateaux sauvages s'étendent dans l'ouest de Féralas, de la Côte oubliée jusqu'à la Verdantis. Ours, loups et hippogriffes errent parmi leurs arbres anciens, des tréants se dressent dans les bosquets les plus profonds, et yétis et ogres revendiquent les étendues plus sauvages au-delà.",
			source = "https://warcraft.wiki.gg/wiki/High_Wilderness",
		},
		["isle of dread"] = {
			name = "lle de l'effroi",
			short = "L'île de l'effroi se trouve au large de la côte de Féralas, au sud de l'île de Sardor, sa vallée centrale enclose de tous côtés par d'inflexibles falaises, hormis un unique accès au sud-est.",
			full = "L'île de l'effroi se trouve au large de la côte de Féralas, au sud de l'île de Sardor, sa vallée centrale enclose de tous côtés par d'inflexibles falaises, hormis un unique accès au sud-est. Dans ce bassin caché vivent les chimaeroks, bêtes imprégnées d'arcanes et dévoreurs tout à la fois, sous la domination de Lord Lakmaeran. Sa chair a été recherchée à des fins plus étranges que la survie : fondue et refaçonnée, elle devint une monstrueuse volaille de deux cent cinquante kilos, dévorée tout entière par le sorcier gnome Narain Soothfancy.\n\nÀ l'extrémité nord de l'île, une grotte s'enfonce dans la roche, différente de tout ce que l'on connaît là-bas, profonde et étrange dans sa facture. Un passage secret sous l'eau mène à une chambre intérieure qui ne sert à rien de connu, sinon à abriter Dame Szallah dans ses profondeurs. La grotte et ses nagas sont commandés par Lord Shalzaru, dont la présence attira l'attention du Bastion de Feathermoon, méfiant envers ces nagas si proches de ses propres rivages.",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "Lac Jademir",
			short = "Le lac Jademir, dans le nord de Féralas, abrite en son centre un îlot, le Bosquet du Rêve. Un portail vers le Rêve d'émeraude s'y dresse, gardé par Lethlas et un certain nombre de draconides verts.",
			full = "Le lac Jademir, dans le nord de Féralas, abrite en son centre un îlot, le Bosquet du Rêve. Un portail vers le Rêve d'émeraude s'y dresse, gardé par Lethlas et un certain nombre de draconides verts. Des dragonnets verts infectés rôdent le long de la rive nord-ouest du lac.",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lariss pavilion"] = {
			name = "Pavillon de Lariss",
			short = "Le Pavillon de Lariss, dont la pierre ouvragée trahit la main des elfes de la nuit, se dresse au nord du Camp Mojache, en Féralas. Ses dryades étaient autrefois paisibles, mais le Cauchemar d'émeraude les a corrompues, et elles attaquent désormais quiconque s'approche.",
			full = "Le Pavillon de Lariss, dont la pierre ouvragée trahit la main des elfes de la nuit, se dresse au nord du Camp Mojache, en Féralas. Ses dryades étaient autrefois paisibles, mais le Cauchemar d'émeraude les a corrompues, et elles attaquent désormais quiconque s'approche.\n\nSous le Pavillon s'ouvre un passage secret vers les profondeurs, connu d'Azj'Tordin, un Bien-né qui rompit avec le prince Tortheldrin et s'enfuit de Hache-tripes par ce chemin. Il s'échappa avec bien peu de choses, car un diablotin nommé Pusillin lui vola son livre d'incantations avant qu'il ne puisse disparaître sous terre, et il se terre dans ce passage depuis lors.",
			source = "https://warcraft.wiki.gg/wiki/Lariss_Pavilion",
		},
		["lower wilds"] = {
			name = "Etendues sauvages",
			short = "Les Étendues sauvages occupent la partie orientale de Féralas, où des tréants se meuvent parmi les arbres et où errent des dryades corrompues, dont les dons sont devenus étranges.",
			full = "Les Étendues sauvages occupent la partie orientale de Féralas, où des tréants se meuvent parmi les arbres et où errent des dryades corrompues, dont les dons sont devenus étranges.",
			source = "https://warcraft.wiki.gg/wiki/Lower_Wilds",
		},
		["oneiros"] = {
			name = "Oneiros",
			short = "Au sud du lac Jademir, dans le nord de Féralas, s'étendent les ruines d'Oneiros.",
			full = "Au sud du lac Jademir, dans le nord de Féralas, s'étendent les ruines d'Oneiros.",
			source = "https://warcraft.wiki.gg/wiki/Oneiros",
		},
		["rage scar hold"] = {
			name = "Repaire des Griffes féroces",
			short = "Le Repaire des Griffes féroces est une grotte creusée en Féralas, qui abrite les yétis les plus féroces de la région.",
			full = "Le Repaire des Griffes féroces est une grotte creusée en Féralas, qui abrite les yétis les plus féroces de la région. À l'intérieur sont éparpillés des livres et d'étranges symboles, indices d'études arcaniques, ou peut-être restes de quelque malheureux magus qui y trouva la mort.",
			source = "https://warcraft.wiki.gg/wiki/Rage_Scar_Hold",
		},
		["ruins of isildien"] = {
			name = "Ruines d'Isildien",
			short = "Les Ruines d'Isildien sont ce qui reste d'une grande cité des elfes de la nuit, brisée il y a dix mille ans. Les ogres Gordunni nichent désormais parmi ses colonnades effondrées, régnant sur des pierres élevées par des mains bien plus anciennes que les leurs.",
			full = "Les Ruines d'Isildien sont ce qui reste d'une grande cité des elfes de la nuit, brisée il y a dix mille ans. Les ogres Gordunni nichent désormais parmi ses colonnades effondrées, régnant sur des pierres élevées par des mains bien plus anciennes que les leurs.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Isildien",
		},
		["ruins of ravenwind"] = {
			name = "Ruines de Vent-du-Corbeau",
			short = "Le nord de Féralas abrite les pierres brisées de Ravenwind, élevées il y a longtemps par les Bien-nés kaldorei, tout comme Hache-tripes le fut ailleurs.",
			full = "Le nord de Féralas abrite les pierres brisées de Ravenwind, élevées il y a longtemps par les Bien-nés kaldorei, tout comme Hache-tripes le fut ailleurs. Il reste bien peu de cette gloire debout aujourd'hui. Les harpies de Northspring ont fait des ruines leur domaine, nichant parmi les colonnes effondrées et les salles vides.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ravenwind",
		},
		["ruins of solarsal"] = {
			name = "Ruines de Solarsal",
			short = "Au sud-ouest du Bastion de Feathermoon, sur l'île de Sardor, les vieilles pierres de Solarsal se dressent encore parmi les arbres, ouvrage des elfes de la nuit depuis longtemps abandonné à la nature sauvage.",
			full = "Au sud-ouest du Bastion de Feathermoon, sur l'île de Sardor, les vieilles pierres de Solarsal se dressent encore parmi les arbres, ouvrage des elfes de la nuit depuis longtemps abandonné à la nature sauvage. Les nagas Hatecrest tiennent désormais les ruines, ondulant entre les colonnes brisées où marchaient jadis les elfes.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Solarsal",
		},
		["sardor isle"] = {
			name = "Ile de Sardor",
			short = "L'île de Sardor s'élève au large de la côte de Féralas, un petit refuge tenu par les elfes de la nuit sous les ordres de Shandris Feathermoon.",
			full = "L'île de Sardor s'élève au large de la côte de Féralas, un petit refuge tenu par les elfes de la nuit sous les ordres de Shandris Feathermoon. Des nagas se sont glissés sur ses rivages, et des loups parcourent ce qui reste de lieux sauvages, si bien que la garde du bastion n'est jamais oisive.",
			source = "https://warcraft.wiki.gg/wiki/Sardor_Isle",
		},
		["shalzarus lair"] = {
			name = "Antre de Shalzaru",
			short = "Au sud de l'île du Bastion de Feathermoon, à l'extrémité nord de l'île de l'effroi, une grotte sinueuse abrite deux chambres reliées par une voie d'eau.",
			full = "Au sud de l'île du Bastion de Feathermoon, à l'extrémité nord de l'île de l'effroi, une grotte sinueuse abrite deux chambres reliées par une voie d'eau. Des ensorceleuses et des gardes serpents Hatecrest l'occupent sur toute sa longueur. Au plus profond demeure Shalzaru, maître des Hatecrest.",
			source = "https://warcraft.wiki.gg/wiki/Shalzaru's_Lair",
		},
		["thalanaar"] = {
			name = "Thalanaar",
			short = "Thalanaar est un lieu paisible, un petit avant-poste qui n'a guère d'attrait pour les voyageurs au-delà de sa fonction.",
			full = "Thalanaar est un lieu paisible, un petit avant-poste qui n'a guère d'attrait pour les voyageurs au-delà de sa fonction. Caryssia Moonhunter y exerce son métier, travaillant peaux et cuir selon l'ancienne manière tribale, l'une des rares raisons qu'ait quiconque de s'y attarder.",
			source = "https://warcraft.wiki.gg/wiki/Thalanaar",
		},
		["twin colossals"] = {
			name = "Les Colosses jumeaux",
			short = "Les Colosses jumeaux se dressent à la lisière ouest de Féralas, deux montagnes verticales si hautes qu'elles forment le point culminant de la région, la route de Désolace se faufilant dans la brèche qui les sépare.",
			full = "Les Colosses jumeaux se dressent à la lisière ouest de Féralas, deux montagnes verticales si hautes qu'elles forment le point culminant de la région, la route de Désolace se faufilant dans la brèche qui les sépare.\n\nAu sommet du pic oriental se trouve un petit étang profond, aux eaux assez calmes pour y pêcher, où l'on peut trouver Gregan Brewspewer. Depuis le sommet, toute la région s'offre au regard en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Twin_Colossals",
		},
		["verdantis river"] = {
			name = "La Verdantis",
			short = "La Verdantis serpente à travers le centre de Féralas, au sud-est des ruines de Hache-tripes, traçant un paisible fil vert à travers la forêt enchevêtrée.",
			full = "La Verdantis serpente à travers le centre de Féralas, au sud-est des ruines de Hache-tripes, traçant un paisible fil vert à travers la forêt enchevêtrée. Ses eaux abritent l'ahi de Féralas, que l'on ne trouve nulle part ailleurs au monde.",
			source = "https://warcraft.wiki.gg/wiki/Verdantis_River",
		},
		["wildwind lake"] = {
			name = "Lac des rafales",
			short = "Le lac des rafales s'étend près du Camp Mojache, en Féralas, ses eaux tranquilles au milieu des terres sauvages environnantes, abritant rien de plus remarquable que ce qui nage sous sa surface et le calme qui plane sur le camp voisin.",
			full = "Le lac des rafales s'étend près du Camp Mojache, en Féralas, ses eaux tranquilles au milieu des terres sauvages environnantes, abritant rien de plus remarquable que ce qui nage sous sa surface et le calme qui plane sur le camp voisin.",
			source = "https://warcraft.wiki.gg/wiki/Wildwind_Lake",
		},
		["woodpaw den"] = {
			name = "Tanière des Griffebois",
			short = "Au cœur de Féralas se trouve la Tanière des Griffebois, terrier des gnolls Griffebois. Ici, les mâles alpha Griffebois règnent sur leurs congénères, si nombreux sur le terrain que peu d'étrangers se risquent à les défier.",
			full = "Au cœur de Féralas se trouve la Tanière des Griffebois, terrier des gnolls Griffebois. Ici, les mâles alpha Griffebois règnent sur leurs congénères, si nombreux sur le terrain que peu d'étrangers se risquent à les défier. Au sud de la tanière se dressent les ruines de Sombrebrume, voisines silencieuses du vacarme des gnolls.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "Collines des Griffebois",
			short = "Les Collines des Griffebois sont couvertes d'une épaisse forêt, domaine des gnolls du clan Griffebois.",
			full = "Les Collines des Griffebois sont couvertes d'une épaisse forêt, domaine des gnolls du clan Griffebois. Leur emprise sur ces terres s'effrite, car dans les confins les plus au sud-est, le sol s'est ouvert sur ce que l'on appelle désormais le Gouffre grouillant, et les créatures grouillantes qui ont jailli des profondeurs de la terre chassent les gnolls de leur propre territoire. Là où les mâles alpha Griffebois menaient jadis leur tribu depuis les camps, ils ne tiennent plus que la Tanière des Griffebois.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "Gouffre grouillant",
			short = "Le Gouffre grouillant, dans le sud-est de Féralas, est livré à la ruche Zukk'ash. Les silithides y ont empoisonné le sol alentour, poussant les gnolls voisins à la frénésie et vers le nord, contre le Camp Mojache.",
			full = "Le Gouffre grouillant, dans le sud-est de Féralas, est livré à la ruche Zukk'ash. Les silithides y ont empoisonné le sol alentour, poussant les gnolls voisins à la frénésie et vers le nord, contre le Camp Mojache.\n\nLes guerriers du camp abattirent les silithides à la surface, mais le cœur de la ruche, sous terre, rempli d'œufs, ne fut jamais atteint. Rexxar avertit que ce n'est qu'une question de temps avant l'éclosion de la génération suivante.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
		},
	},
	-- Marécage d'Âprefange: 24 subzones
	[1445] = {
		["alcaz island"] = {
			name = "Ile d'Alcaz",
			short = "L'île d'Alcaz surgit de la mer au large du marécage d'Âprefange, couverte d'une verdure tropicale qui n'a rien à faire si près de la boue grise du marais, comme si quelque puissance plus ancienne et plus chaude avait jadis revendiqué cette terre sans jamais la lâcher.",
			full = "L'île d'Alcaz surgit de la mer au large du marécage d'Âprefange, couverte d'une verdure tropicale qui n'a rien à faire si près de la boue grise du marais, comme si quelque puissance plus ancienne et plus chaude avait jadis revendiqué cette terre sans jamais la lâcher. Les nagas Strashaz la tiennent, et myrmidons et sirènes abondent sur ses rivages.\n\nPourtant, pendant la guerre contre Ahn'Qiraj, le docteur Weavil vint sur l'île à bord d'une machine volante et installa ses sbires au sommet de la colline, transformant une portion du rivage en atelier d'inventions technologiques.",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "Epave de Beezil",
			short = "Un zeppelin gobelin qui faisait route vers le sud, chargé de provisions, s'écrasa dans les confins les plus reculés du marécage d'Âprefange, à l'est de la ferme de Tabetha.",
			full = "Un zeppelin gobelin qui faisait route vers le sud, chargé de provisions, s'écrasa dans les confins les plus reculés du marécage d'Âprefange, à l'est de la ferme de Tabetha. Sa coque gît brisée dans la boue, sa cargaison éparpillée parmi les débris, et des propulseurs au seaforium reposent encore là où ils sont tombés.",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["bloodfen burrow"] = {
			name = "Terrier des Rougefanges",
			short = "Une grotte du sud-ouest du marécage d'Âprefange abrite un nombre inhabituel de raptors Rougefange. Devant l'entrée gisent les restes d'un hameau, mis en pièces par les créatures, dont les habitants ont désormais disparu dans la boue du marais.",
			full = "Une grotte du sud-ouest du marécage d'Âprefange abrite un nombre inhabituel de raptors Rougefange. Devant l'entrée gisent les restes d'un hameau, mis en pièces par les créatures, dont les habitants ont désormais disparu dans la boue du marais. Quelque part à l'intérieur, une partie de la Devinette de Cortello attend parmi les décombres.",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "Marais bleu",
			short = "Le Marais bleu s'étend dans le nord du marécage d'Âprefange, ses terres basses couvertes de roseaux et d'eaux stagnantes.",
			full = "Le Marais bleu s'étend dans le nord du marécage d'Âprefange, ses terres basses couvertes de roseaux et d'eaux stagnantes. Araignées, crocilisques, raptors et oiseaux des marais y circulent librement, et des infiltrateurs de Theramore le traversent sans être vus parmi les roseaux.",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "Mur-de-Fougères",
			short = "Mur-de-Fougères se dresse parmi les huttes et les tertres ogres dans le nord-ouest du marécage d'Âprefange, foyer des ogres Cognepierres, fidèles à la Horde.",
			full = "Mur-de-Fougères se dresse parmi les huttes et les tertres ogres dans le nord-ouest du marécage d'Âprefange, foyer des ogres Cognepierres, fidèles à la Horde. Ce ne fut pas toujours leur foyer. Les Cognepierres tenaient autrefois un village plus au sud, jusqu'à ce que le vol draconique noir s'abatte sur lui et le réduise en cendres. Le suzerain Mok'Morokk, qui avait pris la tête du clan après Rexxar, conduisit les survivants vers le nord et éleva Mur-de-Fougères à sa place.\n\nMok'Morokk fonda son règne sur l'immobilité. Lorsque l'ogre Draz'Zilb apprit que les assaillants étaient la progéniture d'Onyxia et lui en apporta la vérité, Mok'Morokk refusa d'agir. Mur-de-Fougères était en sécurité, aucun dragon noir n'y vivait, et cela lui suffisait. Draz'Zilb ne compte pas en rester là, et pèse en silence ce qu'il faudrait pour voir tomber le suzerain et ramener les Cognepierres vers ce qu'ils ont perdu.",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "Caverne de Sombrebrume",
			short = "Une petite mine se trouve dans le nord-ouest du marécage d'Âprefange, depuis longtemps livrée à des araignées devenues terriblement grandes dans l'obscurité.",
			full = "Une petite mine se trouve dans le nord-ouest du marécage d'Âprefange, depuis longtemps livrée à des araignées devenues terriblement grandes dans l'obscurité. Les gens du marais les appellent les araignées Sombrebrume, et la caverne Sombrebrume à son tour, bien que nul ne puisse dire quel nom vint en premier, celui du lieu ou celui des créatures qui s'en emparèrent.\n\nDevant l'entrée de la mine se dressent les ruines de petites maisons, à demi enfoncées dans le sol détrempé, tout ce qui reste d'un hameau depuis longtemps oublié.",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "L'Antre des flammes",
			short = "L'Antre des flammes fut élevé par les ogres Cognepierres pour leur servir de tertre, et sa maçonnerie porte encore la marque de leur savoir-faire. Il se trouve à l'ouest des ruines Cognepierres, dans un marais revendiqué par Onyxia.",
			full = "L'Antre des flammes fut élevé par les ogres Cognepierres pour leur servir de tertre, et sa maçonnerie porte encore la marque de leur savoir-faire. Il se trouve à l'ouest des ruines Cognepierres, dans un marais revendiqué par Onyxia.\n\nLes ogres l'ont désormais quitté. Des dragons noirs ont envahi l'antre et en ont fait un nid du vol draconique noir. Seules la vieille maçonnerie et la bannière des Cognepierres, restée dressée à l'intérieur, rappellent ses premiers bâtisseurs.",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["dragonmurk"] = {
			name = "Le cloaque aux dragons",
			short = "Dans le sud du marécage d'Âprefange s'étend une étendue de terre fétide appelée le Dragonmurk, grouillante de dragonnets et de rejetons du vol draconique noir.",
			full = "Dans le sud du marécage d'Âprefange s'étend une étendue de terre fétide appelée le Dragonmurk, grouillante de dragonnets et de rejetons du vol draconique noir. Non loin se dressent l'Antre des flammes et les Ruines Cognepierres, tous deux envahis eux aussi par des draconides noirs.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
		},
		["dreadmurk shore"] = {
			name = "Rivage de Troubleffroi",
			short = "Le rivage entre l'île de Theramore et le Fort du Nord grouille de murlocs de la tribu Aileron boueux, qui revendiquent le littoral et ses îlots épars comme leur domaine.",
			full = "Le rivage entre l'île de Theramore et le Fort du Nord grouille de murlocs de la tribu Aileron boueux, qui revendiquent le littoral et ses îlots épars comme leur domaine. Des tortues de mer et d'autres créatures partagent les eaux qui les entourent.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmurk_Shore",
		},
		["dustwallow bay"] = {
			name = "Baie d'Âprefange",
			short = "La baie d'Âprefange fait partie de la Grande mer et pénètre dans la côte orientale du marécage d'Âprefange, à l'ouest de l'île de Theramore.",
			full = "La baie d'Âprefange fait partie de la Grande mer et pénètre dans la côte orientale du marécage d'Âprefange, à l'ouest de l'île de Theramore. Sur un îlot au large de la baie, dans la crique du Mascaret, le pêcheur Nat Pagle veille en solitaire sur les eaux.",
			source = "https://warcraft.wiki.gg/wiki/Dustwallow_Bay",
		},
		["emberstrifes den"] = {
			name = "Tanière de Brandeguerre",
			short = "Une vaste grotte s'ouvre sur la Tourbière du Ver et sa puanteur, repaire du drake noir Brandeguerre.",
			full = "Une vaste grotte s'ouvre sur la Tourbière du Ver et sa puanteur, repaire du drake noir Brandeguerre. Il y met à l'épreuve les jeunes dragonnets noirs par des épreuves d'endurance et de cruauté, car seuls ceux qui s'en montrent dignes peuvent ensuite pénétrer dans le Repaire d'Onyxia.",
			source = "https://warcraft.wiki.gg/wiki/Emberstrife's_Den",
		},
		["foothold citadel"] = {
			name = "Citadelle de Theramore",
			short = "La Citadelle de Theramore se dresse au cœur de l'île de Theramore, quartier général de la garde de Theramore.",
			full = "La Citadelle de Theramore se dresse au cœur de l'île de Theramore, quartier général de la garde de Theramore.\n\nC'est ici que Daelin Portvaillant trouva la mort, lorsque les forces de Thrall prirent Theramore d'assaut, menées dans le donjon par Rexxar et ses compagnons. L'amiral qui avait défié la paix conclue par sa fille Jaina avec les orcs tomba entre ces murs.",
			source = "https://warcraft.wiki.gg/wiki/Foothold_Citadel",
		},
		["lost point"] = {
			name = "Halte perdue",
			short = "La Halte perdue, une tour d'éclaireurs délabrée élevée jadis par Theramore dans l'ouest du marécage d'Âprefange, ne sert plus ses bâtisseurs.",
			full = "La Halte perdue, une tour d'éclaireurs délabrée élevée jadis par Theramore dans l'ouest du marécage d'Âprefange, ne sert plus ses bâtisseurs. Des déserteurs de Theramore la tiennent désormais, menés par Balos Jacken, qui connaît le rôle du soldat Hendel dans l'enlèvement d'une personne de grande importance.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
		},
		["north point tower"] = {
			name = "Tour de la halte nord",
			short = "La Tour de la halte nord veille sur le nord du marécage d'Âprefange, au bord d'une route très fréquentée, tenue par un important contingent de gardes de Theramore.",
			full = "La Tour de la halte nord veille sur le nord du marécage d'Âprefange, au bord d'une route très fréquentée, tenue par un important contingent de gardes de Theramore. Depuis que des déserteurs se sont emparés de la Halte perdue, cette tour est l'avant-poste le plus éloigné de Theramore.",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "Repaire d'Onyxia",
			short = "Le passage qui mène au repaire d'Onyxia a la forme de la gueule béante de la mère des couvées elle-même. Au-delà, le chemin est bordé de magma, le sol fissuré et rougeoyant du feu qui monte d'en dessous.",
			full = "Le passage qui mène au repaire d'Onyxia a la forme de la gueule béante de la mère des couvées elle-même. Au-delà, le chemin est bordé de magma, le sol fissuré et rougeoyant du feu qui monte d'en dessous. Le plafond de pierre gémit et bouge au-dessus, laissant sans cesse tomber des éboulis, et les murs eux-mêmes suintent de lave là où la chaleur ne peut être contenue. Onyxia creusa elle-même ce lieu, loin sous le Dragonmurk, le lugubre marais au sein du marécage d'Âprefange.\n\nElle ne ressemble pas aux siens. Là où son père règne par la force brute et où son frère façonne des abominations difformes pour exécuter ses volontés, Onyxia agit par murmures et par charme, se délectant des intrigues embrouillées des mortels et les pliant discrètement à ses propres desseins. Un temps, elle porta un nom volé, se faisant appeler Katrana Prestor, et sous ce déguisement s'insinua au cœur de la cour de Stormwind, s'employant à la défaire de l'intérieur. Ce fut le maréchal Windsor qui perça le masque à jour et la nomma pour ce qu'elle était. Démasquée, elle s'enfuit de la ville et regagna sa salle ardente sous le marais, où elle demeure, toujours gardée par les siens, le vol draconique noir.",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "Le Bourbier",
			short = "Le Bourbier est le cœur détrempé du marécage d'Âprefange, qui s'étend entre la Halte perdue et la baie d'Âprefange, encadré par Mur-de-Fougères au nord et le Dragonmurk au sud.",
			full = "Le Bourbier est le cœur détrempé du marécage d'Âprefange, qui s'étend entre la Halte perdue et la baie d'Âprefange, encadré par Mur-de-Fougères au nord et le Dragonmurk au sud.\n\nDes crocilisques se tapissent dans ses eaux noires, des limons et des araignées rampent dans ses roseaux, et des taurens Totem sinistre y tiennent le terrain, loin de tout parent qui voudrait les réclamer. Mieux vaut le traverser que s'y attarder.",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "Halte de la Vigie",
			short = "La Halte de la Vigie s'élève juste de l'autre côté du pont qui part de Theramore, une tour d'éclaireurs bâtie par la citadelle pour surveiller la route en contrebas. Elle se dresse intacte, montant sa garde silencieuse sur tous ceux qui passent en direction de la ville.",
			full = "La Halte de la Vigie s'élève juste de l'autre côté du pont qui part de Theramore, une tour d'éclaireurs bâtie par la citadelle pour surveiller la route en contrebas. Elle se dresse intacte, montant sa garde silencieuse sur tous ceux qui passent en direction de la ville.",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "Auberge du Repos ombragé",
			short = "L'Auberge du Repos ombragé se dressait autrefois près de la frontière entre le marécage d'Âprefange et les Tarides du sud, une halte bâtie par les humains.",
			full = "L'Auberge du Repos ombragé se dressait autrefois près de la frontière entre le marécage d'Âprefange et les Tarides du sud, une halte bâtie par les humains.\n\nElle brûla entièrement sans prévenir. Deux hommes auraient pu nommer les coupables, Paval Reethe et le lieutenant Caldwell, mais tous deux furent tués avant que l'un ou l'autre ne puisse dire la vérité, et l'incendie resta inexpliqué.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "Ruines Cognepierres",
			short = "Le village des Cognepierres se dressait autrefois dans le marécage d'Âprefange, foyer des ogres du clan Cognepierre, jusqu'à ce que le seigneur de guerre Kor'gall, s'étant emparé de l'antique hache orque Serathil, prenne le clan en main et le gouverne par la brutalité.",
			full = "Le village des Cognepierres se dressait autrefois dans le marécage d'Âprefange, foyer des ogres du clan Cognepierre, jusqu'à ce que le seigneur de guerre Kor'gall, s'étant emparé de l'antique hache orque Serathil, prenne le clan en main et le gouverne par la brutalité. C'est ici que Rexxar vint et se vit refuser l'entrée, qu'il força les armes à la main. Kor'gall lui offrit une place dans le clan s'il survivait à l'Épreuve, une vallée infestée de bêtes mortelles. Rexxar l'endura et revint, et fut fait Cognepierre. Lorsque Kor'gall refusa de prêter le clan à la guerre de la Horde contre Kul Tiras, Rexxar le défia pour le commandement et le tua, puis mena lui-même les Cognepierres à la guerre. Ensuite, il désigna Mok'Morokk pour régner à sa place et s'en alla.\n\nMok'Morokk ne régna pas comme Rexxar. Il prit à son peuple au lieu de le servir, et lorsque la progéniture d'Onyxia s'abattit sur le village et s'en empara, il mena les survivants en lieu sûr et se contenta d'y rester, loin des dragons, plutôt que de se battre pour reprendre l'ancien foyer.\n\nLes ruines se trouvent désormais dans le Dragonmurk, infestées de draconides Firemane.",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
		},
		["swamplight manor"] = {
			name = "Manoir des Flammeroles",
			short = "Le Manoir des Flammeroles est une modeste maison sur la Colline des sorcières, dans le marécage d'Âprefange, demeure du cuisinier Jarl « Œil-des-marais ».",
			full = "Le Manoir des Flammeroles est une modeste maison sur la Colline des sorcières, dans le marécage d'Âprefange, demeure du cuisinier Jarl « Œil-des-marais ».\n\nDans le jardin, un tas de terre retournée cache quelque chose que la cuisine de Jarl n'explique jamais : un rapport enterré par un espion orc, laissé sous la terre pour garder son secret à l'abri des regards indiscrets.",
			source = "https://warcraft.wiki.gg/wiki/Swamplight_Manor",
		},
		["theramore isle"] = {
			name = "Ile de Theramore",
			short = "Après la troisième guerre, Jaina Proudmoore conduisit les survivants de Lordaeron par-delà la mer jusqu'à Kalimdor.",
			full = "Après la troisième guerre, Jaina Proudmoore conduisit les survivants de Lordaeron par-delà la mer jusqu'à Kalimdor. Sur une île rocheuse au large du marécage d'Âprefange, ils élevèrent Theramore, une cité fortifiée destinée à abriter ce qui restait de l'Alliance sur une terre étrangère.\n\nLa cité est entourée d'un mur rectangulaire hérissé de tours à canons, interrompu seulement au port, que gardent à la place deux tours d'éclaireurs. En son cœur s'élève la tour de Jaina, la Citadelle, le plus haut bâtiment de Theramore, dont les nombreux étages aux planchers de bois sont reliés par des escaliers en colimaçon et protégés contre les attaques ; elle abrite les appartements privés de Jaina, sa bibliothèque et la petite salle du trône de la cité. Non loin se dresse la Citadelle de Theramore, le quartier des gardes, où les soldats s'exercent sur des mannequins d'entraînement et où les recrues s'affrontent sous l'œil de prêtres prêts à invoquer la Lumière dès que quelqu'un est blessé.\n\nLe marais offre un sol pauvre et un bois médiocre, et les marins de Theramore grommellent que les chênes que les orcs abattent au-dessus d'Orgrimmar valent bien mieux que tout ce qu'offre Âprefange. Malgré tout, humains et orcs échangent du poisson contre les surplus de récoltes de Durotar, et pour l'heure la criminalité de la cité est faible et ses habitants, pour la plupart, en paix.",
			source = "https://warcraft.wiki.gg/wiki/Theramore_Isle",
		},
		["tidefury cove"] = {
			name = "Crique du Mascaret",
			short = "La crique du Mascaret se trouve au bout de la baie d'Âprefange, au sud de l'île de Theramore, ses eaux parsemées d'îlots et de récifs cachés. Ce sont des eaux traîtresses pour la navigation.",
			full = "La crique du Mascaret se trouve au bout de la baie d'Âprefange, au sud de l'île de Theramore, ses eaux parsemées d'îlots et de récifs cachés. Ce sont des eaux traîtresses pour la navigation. Deux navires gisent brisés sur ses hauts-fonds, livrés désormais aux makruras qui y rôdent.\n\nParmi ses îlots se trouve le Débarcadère de Nat, demeure du pêcheur Nat Pagle.",
			source = "https://warcraft.wiki.gg/wiki/Tidefury_Cove",
		},
		["witch hill"] = {
			name = "Colline des sorcières",
			short = "Le Manoir des Flammeroles se dresse au centre de la Colline des sorcières, demeure de Jarl « Œil-des-marais ». Les murlocs Aileron boueux ont leurs camps non loin, dans la fange.",
			full = "Le Manoir des Flammeroles se dresse au centre de la Colline des sorcières, demeure de Jarl « Œil-des-marais ». Les murlocs Aileron boueux ont leurs camps non loin, dans la fange.",
			source = "https://warcraft.wiki.gg/wiki/Witch_Hill",
		},
		["wyrmbog"] = {
			name = "Tourbière du Ver",
			short = "Au sud du Dragonmurk, dans le marécage d'Âprefange, la fange s'épaissit pour former la Tourbière du Ver.",
			full = "Au sud du Dragonmurk, dans le marécage d'Âprefange, la fange s'épaissit pour former la Tourbière du Ver. Des dragons noirs y ont élu domicile, et la terre s'ouvre sur deux lieux cachés : l'entrée de la Tanière de Brandeguerre, et le repaire d'Onyxia elle-même.",
			source = "https://warcraft.wiki.gg/wiki/Wyrmbog",
		},
	},
	-- Tanaris: 23 subzones
	[1446] = {
		["abyssal sands"] = {
			name = "Désert Abysséen",
			short = "Ces sables s'étendent en Tanaris, un désert qui se déploie dans toutes les directions.",
			full = "Ces sables s'étendent en Tanaris, un désert qui se déploie dans toutes les directions.",
			source = "https://warcraft.wiki.gg/wiki/Abyssal_Sands",
		},
		["broken pillar"] = {
			name = "Pilier brisé",
			short = "Au sud de Gadgetzan, près du Désert Abysséen, se dresse un petit amas de ruines trolls connu sous le nom de Pilier brisé.",
			full = "Au sud de Gadgetzan, près du Désert Abysséen, se dresse un petit amas de ruines trolls connu sous le nom de Pilier brisé. Le savant gobelin Marvon Rivetseeker y a établi son camp, cherchant parmi les pierres effondrées des réponses qui lui sont propres.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Pillar",
		},
		["caverns of time"] = {
			name = "Grottes du temps",
			short = "Les Grottes du temps s'étendent sous les sables orientaux de Tanaris, un labyrinthe sinueux fermé au monde d'en haut. Ici, le vol draconique bronze veille sur les chemins ramifiés du temps lui-même.",
			full = "Les Grottes du temps s'étendent sous les sables orientaux de Tanaris, un labyrinthe sinueux fermé au monde d'en haut. Ici, le vol draconique bronze veille sur les chemins ramifiés du temps lui-même. Depuis la jeunesse du monde, c'est la charge sacrée que les titans lui ont confiée : garder les grottes contre toute intrusion mortelle, car l'ingérence de mains inférieures pourrait défaire le cours de l'histoire. Au cœur des grottes se dresse un grand sablier.\n\nNozdormu, l'Aspect du temps, demeure ici parmi son vol, et s'adonne à un passe-temps personnel : la collection d'objets rares. Au lendemain de la deuxième guerre, le mage Krasus pénétra dans l'antre de Nozdormu au moyen d'une rose des éons, un artefact qui lui permit de franchir la distance en un instant. Nozdormu fut mécontent de cette intrusion, qui le dérangeait au beau milieu de ses collections, et il fit savoir son mécontentement.",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
		},
		["dunemaul compound"] = {
			name = "Base des Cognedunes",
			short = "La Base des Cognedunes est le fief des ogres Cognedunes, étalé sur les sables de Tanaris, où le clan se rassemble dans ses abris de terre sous le soleil.",
			full = "La Base des Cognedunes est le fief des ogres Cognedunes, étalé sur les sables de Tanaris, où le clan se rassemble dans ses abris de terre sous le soleil.",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Compound",
		},
		["eastmoon ruins"] = {
			name = "Ruines d'Estelune",
			short = "Des terrasses de pierre et des piliers fendus marquent les Ruines d'Estelune, à l'ouest du Gouffre béant en Tanaris, tout ce qui reste d'un village troll depuis longtemps abandonné.",
			full = "Des terrasses de pierre et des piliers fendus marquent les Ruines d'Estelune, à l'ouest du Gouffre béant en Tanaris, tout ce qui reste d'un village troll depuis longtemps abandonné. Les ogres Cognedunes se sont approprié la maçonnerie en ruine après les trolls, et la tiennent toujours.",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
		},
		["gadgetzan"] = {
			name = "Gadgetzan",
			short = "Gadgetzan s'élève dans le désert du nord de Tanaris sous un voile permanent de fumées noires, capitale du Cartel Gentepression, le plus grand des cartels gobelins.",
			full = "Gadgetzan s'élève dans le désert du nord de Tanaris sous un voile permanent de fumées noires, capitale du Cartel Gentepression, le plus grand des cartels gobelins. Ici, le credo des gobelins régit tout : le profit avant la loyauté. La Horde comme l'Alliance reconnaissent officiellement la ville comme terrain neutre, et des cogneurs gobelins patrouillent dans ses rues, prêts à réduire en bouillie quiconque serait assez fou pour porter la guerre dans un lieu bâti sur le commerce. Ce sont les bourses, et non les bannières, qui décident qui est le bienvenu.\n\nCette neutralité n'a jamais plu à tout le monde. Les bandits Bat-le-désert s'emparèrent des Ruines d'Ombre-du-Zénith et du Champ des puisatiers, au nord-est. Les gobelins se souciaient peu des vieilles ruines, mais le Champ des puisatiers était une autre affaire : les châteaux d'eau qu'y avait élevés et qu'y entretenait la Compagnie des Eaux de Gadgetzan, sous le soleil ardent du désert, étaient l'or liquide qui faisait vivre la ville. Les gobelins n'avaient aucune intention de céder des tours pour lesquelles ils avaient sué sang et eau, et c'est ainsi que des mercenaires venus des quatre coins du monde furent entraînés à défendre l'eau de Gadgetzan contre les bandits qui voulaient la voir tomber.",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "Le Gouffre béant",
			short = "Le Gouffre béant grouille de silithides Hazzali, dont les ruches criblent la roche dans le sud-est de Tanaris.",
			full = "Le Gouffre béant grouille de silithides Hazzali, dont les ruches criblent la roche dans le sud-est de Tanaris.\n\nLe Grand Géomètre Fizzledowser envoya jadis son subordonné, Scrimshank, étudier le fond du gouffre. Scrimshank n'en ressortit jamais. Il mourut parmi les ruches, et seul son équipement fut plus tard retrouvé et rapporté à Fizzledowser, qui l'avait envoyé à la mort sans jamais le savoir.",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "Plage du Bout-du-Monde",
			short = "La Plage du Bout-du-Monde s'étend à la pointe la plus méridionale de Tanaris, là où l'angle sud-est de Kalimdor rencontre la mer. Le rivage est paisible, marqué surtout par les créatures qui le parcourent.",
			full = "La Plage du Bout-du-Monde s'étend à la pointe la plus méridionale de Tanaris, là où l'angle sud-est de Kalimdor rencontre la mer. Le rivage est paisible, marqué surtout par les créatures qui le parcourent. Des planeurs des vagues et des crabes des dunes se fraient un chemin le long de la partie orientale de la plage, sans être dérangés.",
			source = "https://warcraft.wiki.gg/wiki/Land's_End_Beach",
		},
		["lost rigger cove"] = {
			name = "Crique des Gréements",
			short = "Abritée par des montagnes sur trois côtés, la Crique des Gréements cache le port des pirates des Mers du sud sur la côte de Tanaris, dont le chantier naval s'affaire à la construction d'un nouveau navire.",
			full = "Abritée par des montagnes sur trois côtés, la Crique des Gréements cache le port des pirates des Mers du sud sur la côte de Tanaris, dont le chantier naval s'affaire à la construction d'un nouveau navire.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Rigger_Cove",
		},
		["noonshade ruins"] = {
			name = "Ruines d'Ombre-du-Zénith",
			short = "Les Ruines d'Ombre-du-Zénith s'étendent à l'est de Gadgetzan, pierres usées laissées par des trolls depuis longtemps disparus. Quel usage avaient autrefois ces ruines, ou ce qu'il advint de ceux qui les élevèrent, les sables du désert ne le disent plus.",
			full = "Les Ruines d'Ombre-du-Zénith s'étendent à l'est de Gadgetzan, pierres usées laissées par des trolls depuis longtemps disparus. Quel usage avaient autrefois ces ruines, ou ce qu'il advint de ceux qui les élevèrent, les sables du désert ne le disent plus.",
			source = "https://warcraft.wiki.gg/wiki/Noonshade_Ruins",
		},
		["noxious lair"] = {
			name = "Le Repaire nuisible",
			short = "Le sud-ouest de Tanaris porte une plaie dans le sable, là où l'eau se trouvait jadis. Quelque chose de large et peu profond, une rivière ou un lac, s'étendait sur cette terre avant l'arrivée des silithides, et ce que l'essaim Centipaar y trouva, il le vida.",
			full = "Le sud-ouest de Tanaris porte une plaie dans le sable, là où l'eau se trouvait jadis. Quelque chose de large et peu profond, une rivière ou un lac, s'étendait sur cette terre avant l'arrivée des silithides, et ce que l'essaim Centipaar y trouva, il le vida. L'ouest de Tanaris en fut asséché.\n\nLa surface garde encore la forme de ce qui a été perdu. Le terrain s'affaisse, creusé et évidé, et regarde vers le cratère d'Un'Goro comme s'il se souvenait d'avoir été un rivage. Çà et là, de grandes pinces se dressent hors du sable, agitées de soubresauts, comme si des créatures enfouies s'étaient figées en pleine attaque. Autour de chaque pince, le sol est noir et humide de glu silithide, la seule humidité qui reste en un lieu qui abritait autrefois un lac.\n\nSous la surface, le Repaire nuisible est une ruche semblable à toutes celles que les Centipaar ont creusées dans Tanaris : humide, chaude, d'une immobilité inquiétante, ses tunnels enduits d'acide silithide.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["sandsorrow watch"] = {
			name = "Guet de Tristesable",
			short = "Le Guet de Tristesable s'étend à l'ouest de Gadgetzan, à travers le bassin aride de Tanaris, tenu par les trolls Farraki et les zombies qu'ils ont relevés parmi leurs propres morts.",
			full = "Le Guet de Tristesable s'étend à l'ouest de Gadgetzan, à travers le bassin aride de Tanaris, tenu par les trolls Farraki et les zombies qu'ils ont relevés parmi leurs propres morts.",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
		},
		["south seas"] = {
			name = "Mers du sud",
			short = "Les eaux au sud des continents connus s'ouvrent sur une vaste étendue de la Grande mer, dont les courants passent devant des îles dont seuls les marins connaissent vraiment les noms.",
			full = "Les eaux au sud des continents connus s'ouvrent sur une vaste étendue de la Grande mer, dont les courants passent devant des îles dont seuls les marins connaissent vraiment les noms. Zandalar s'élève de ces eaux, antique berceau de l'empire troll. Kezan se trouve aussi parmi elles, une île volcanique dont le peuple se tient à l'écart des puissances du continent.\n\nPlus près de la vallée de Strangleronce, la mer devient traîtresse, semée de récifs et de criques cachées, le genre d'eaux où un capitaine connaît chaque rocher par son nom ou perd son navire. De petites îles parsèment cette étendue, certaines guère plus qu'un banc de sable, d'autres abritant des ruines dont les bâtisseurs ont depuis longtemps disparu sous les flots.\n\nCe qui rend cette mer digne d'être nommée, c'est moins une bataille qui s'y serait livrée que tout ce qu'elle a englouti puis à demi révélé de nouveau : temples engloutis, côtes noyées, ruines entrevues à travers l'eau claire à marée basse. C'est une mer de lisières et d'entre-deux, qui longe les frontières de Strangleronce, de Tanaris et d'Uldum, portant ce que les marées choisissent d'apporter aux rivages qu'elle sépare.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "Rivage de Brisesud",
			short = "Le Rivage de Brisesud s'étend paisiblement le long de la lisière sud de Tanaris, une plage plate presque dépourvue de vie. Des tortues et des géants des mers errent dans le ressac.",
			full = "Le Rivage de Brisesud s'étend paisiblement le long de la lisière sud de Tanaris, une plage plate presque dépourvue de vie. Des tortues et des géants des mers errent dans le ressac.",
			source = "https://warcraft.wiki.gg/wiki/Southbreak_Shore",
		},
		["southmoon ruins"] = {
			name = "Ruines de Sudelune",
			short = "Les Ruines de Sudelune sont les vestiges d'un ancien village troll du sud de Tanaris, leurs pierres érodées et à demi ensevelies dans le sable du désert.",
			full = "Les Ruines de Sudelune sont les vestiges d'un ancien village troll du sud de Tanaris, leurs pierres érodées et à demi ensevelies dans le sable du désert.",
			source = "https://warcraft.wiki.gg/wiki/Southmoon_Ruins",
		},
		["steamwheedle port"] = {
			name = "Port Gentepression",
			short = "Port Gentepression se trouve sur la côte orientale de Tanaris, avec une route filant vers l'ouest jusqu'à sa ville mère, Gadgetzan, et un quai tendu vers Kezan.",
			full = "Port Gentepression se trouve sur la côte orientale de Tanaris, avec une route filant vers l'ouest jusqu'à sa ville mère, Gadgetzan, et un quai tendu vers Kezan. Il appartient au Cartel Gentepression, des gobelins qui traitent avec tous les venus tant que l'or est bon.\n\nParmi les résidents du port se trouve Yeh'kinya, dont les manigances contribuèrent au retour de Hakkar l'Écorcheur d'âmes.",
			source = "https://warcraft.wiki.gg/wiki/Steamwheedle_Port",
		},
		["thistleshrub valley"] = {
			name = "Vallée des Chardonniers",
			short = "La Vallée des Chardonniers est couverte de cactus géants, chose étrange pour un désert si aride capable d'entretenir une végétation vivante.",
			full = "La Vallée des Chardonniers est couverte de cactus géants, chose étrange pour un désert si aride capable d'entretenir une végétation vivante. Les chardonniers qui poussaient ici en abondance se sont raréfiés ces derniers temps, et l'on peut désormais trouver des fleurs du désert parmi eux, bien que peu nombreuses.",
			source = "https://warcraft.wiki.gg/wiki/Thistleshrub_Valley",
		},
		["uldum"] = {
			name = "Uldum",
			short = "Uldum se trouve sur la côte sud de Kalimdor, enclavée par le cratère d'Un'Goro au nord, Tanaris à l'est et Silithus au nord-ouest.",
			full = "Uldum se trouve sur la côte sud de Kalimdor, enclavée par le cratère d'Un'Goro au nord, Tanaris à l'est et Silithus au nord-ouest. C'est un lieu riche du savoir des titans, dont les cols montagneux sont voilés afin qu'aucun œil mortel ne puisse trouver le chemin qui y mène.",
			source = "https://warcraft.wiki.gg/wiki/Uldum",
		},
		["valley of the watchers"] = {
			name = "Vallée des guetteurs",
			short = "La Vallée des guetteurs garde le sud de Tanaris, là où une grande porte impénétrable se dresse face à Uldum. Des géants des montagnes, les Écrase-dunes, y errent en guise de guetteurs.",
			full = "La Vallée des guetteurs garde le sud de Tanaris, là où une grande porte impénétrable se dresse face à Uldum. Des géants des montagnes, les Écrase-dunes, y errent en guise de guetteurs.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_the_Watchers",
		},
		["waterspring field"] = {
			name = "Champ des puisatiers",
			short = "Le Champ des puisatiers tire son nom des châteaux d'eau qui s'y dressent, puisant l'eau de réserves profondément enfouies sous terre.",
			full = "Le Champ des puisatiers tire son nom des châteaux d'eau qui s'y dressent, puisant l'eau de réserves profondément enfouies sous terre. Ce sont les gobelins de Gadgetzan qui les construisirent, afin d'assurer l'approvisionnement en eau de leurs activités dans le désert de Tanaris.\n\nCe projet ne survécut pas aux Bat-le-désert. Ces bandits nomades déferlèrent sur le champ et s'en emparèrent tout simplement, prenant les tours pour eux-mêmes sans un regard pour les gobelins qui les avaient élevées. Ils y campent encore, bien contents de cette terre après ce qu'ils ont fui auparavant : ils ne tiennent pas à parler du camp ogre qu'ils ont connu avant, seulement à dire que c'est mieux ici.",
			source = "https://warcraft.wiki.gg/wiki/Waterspring_Field",
		},
		["wavestrider beach"] = {
			name = "Plage des Déferlantes",
			short = "La Plage des Déferlantes longe la côte orientale de Tanaris, l'étendue de sable qui sépare Port Gentepression de la Crique des Gréements.",
			full = "La Plage des Déferlantes longe la côte orientale de Tanaris, l'étendue de sable qui sépare Port Gentepression de la Crique des Gréements. Des rampants du désert détalent sur la plage, aux côtés des claque-mâchoires qui partagent le même rivage.",
			source = "https://warcraft.wiki.gg/wiki/Wavestrider_Beach",
		},
		["zalashjis den"] = {
			name = "La tanière de Zalashji",
			short = "La tanière de Zalashji porte encore le nom de celui qui y eut jadis son repaire. Rien dans les récits qui nous sont parvenus ne dit qui était Zalashji, ni ce que devint ce lieu par la suite.",
			full = "La tanière de Zalashji porte encore le nom de celui qui y eut jadis son repaire. Rien dans les récits qui nous sont parvenus ne dit qui était Zalashji, ni ce que devint ce lieu par la suite. Zalashji vit-il encore, est-il mort ici ou ailleurs, nul ne peut le dire avec certitude.",
			source = "https://warcraft.wiki.gg/wiki/Zalashji's_Den",
		},
		["zulfarrak"] = {
			name = "Zul'Farrak",
			short = "Zul'Farrak fut jadis une cité de la jungle, lorsque Tanaris était encore une forêt sous l'empire Gurubashi.",
			full = "Zul'Farrak fut jadis une cité de la jungle, lorsque Tanaris était encore une forêt sous l'empire Gurubashi. Quand la Grande fracture déchira le monde ancien, la jungle brûla et céda la place au désert, et les trolls Farraki qui avaient bâti ici leur cité se retrouvèrent échoués au milieu du sable. Ils endurèrent, s'endurcissant pour devenir les Sandfury, une tribu connue, même parmi les trolls, pour sa cruauté et son sombre mysticisme.\n\nEntre les murs brûlés par le soleil, la légende troll parle de Sul'thraze le Fouetteur, une lame qui, dit-on, instillait la peur et la faiblesse chez tout ennemi qu'elle touchait. Il y a longtemps, l'épée fut brisée en deux, et l'on murmure que les deux moitiés se trouvent toujours quelque part dans la cité, perdues parmi ses cours et ses temples.\n\nAu cœur de Zul'Farrak se trouve un bassin sacré, et sous ses eaux immobiles les Sandfury garderaient endormi quelque chose de bien plus ancien qu'eux : un demi-dieu dont le réveil ferait s'abattre la ruine sur la cité et sur tous ceux qui s'y trouvent.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Farrak",
		},
	},
	-- Azshara: 26 subzones
	[1447] = {
		["bay of storms"] = {
			name = "Baie des tempêtes",
			short = "La Baie des tempêtes s'étend au large de la côte orientale d'Azshara, ses eaux connues des voyageurs pour les tempêtes qui s'y forment. Sur ses rives se trouvent la Caverne de Barbe-d'écailles, le Frai d'Hetaera et le Temple d'Arkkoran.",
			full = "La Baie des tempêtes s'étend au large de la côte orientale d'Azshara, ses eaux connues des voyageurs pour les tempêtes qui s'y forment. Sur ses rives se trouvent la Caverne de Barbe-d'écailles, le Frai d'Hetaera et le Temple d'Arkkoran.",
			source = "https://warcraft.wiki.gg/wiki/Bay_of_Storms",
		},
		["bears head"] = {
			name = "Tête d'ours",
			short = "Tête d'ours tire son nom des villages furbolgs disséminés sur ces terres, petits avant-postes qui surveillent les abords du Repaire des Grumegueules et d'Ursolan, plus au nord.",
			full = "Tête d'ours tire son nom des villages furbolgs disséminés sur ces terres, petits avant-postes qui surveillent les abords du Repaire des Grumegueules et d'Ursolan, plus au nord.\n\nSur une falaise dominant les villages se dresse la tour de Xylem, demeure de l'archimage Xylem, qui y vit en compagnie de plusieurs apprentis et associés qui étudient et travaillent entre ses murs.",
			source = "https://warcraft.wiki.gg/wiki/Bear's_Head",
		},
		["bitter reaches"] = {
			name = "Confins amers",
			short = "Les Confins amers s'étendent au nord-est d'Azshara, peuplés d'hippogriffes, de limons et de chimères. Le long de la lisière nord, des géants des montagnes ont chassé la faune plus modeste et se sont approprié le terrain.",
			full = "Les Confins amers s'étendent au nord-est d'Azshara, peuplés d'hippogriffes, de limons et de chimères. Le long de la lisière nord, des géants des montagnes ont chassé la faune plus modeste et se sont approprié le terrain.",
			source = "https://warcraft.wiki.gg/wiki/Bitter_Reaches",
		},
		["forlorn ridge"] = {
			name = "La crête lugubre",
			short = "La crête lugubre se dresse sur l'ouest d'Azshara, dominant le pays sur des lieues à la ronde.",
			full = "La crête lugubre se dresse sur l'ouest d'Azshara, dominant le pays sur des lieues à la ronde. Des fortifications se dressent sur ses pentes par paires, ouvrages de l'Alliance et de la Horde élevés à portée de vue les uns des autres : bâtis pour une bataille qui n'est jamais venue, ils restent vides.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Ridge",
		},
		["haldarr encampment"] = {
			name = "Campement des Haldarr",
			short = "Le Campement des Haldarr grouille de satyres dans l'ouest d'Azshara, une horde corrompue de démons aux pattes de bouc, dont les feux brûlent au nord-est du Sanctuaire de Shadowsong et au sud-ouest du vieux Valormok.",
			full = "Le Campement des Haldarr grouille de satyres dans l'ouest d'Azshara, une horde corrompue de démons aux pattes de bouc, dont les feux brûlent au nord-est du Sanctuaire de Shadowsong et au sud-ouest du vieux Valormok.",
			source = "https://warcraft.wiki.gg/wiki/Haldarr_Encampment",
		},
		["hetaeras clutch"] = {
			name = "Frai d'Hetaera",
			short = "Sous la Baie des tempêtes, au large d'Azshara, se trouve le Frai d'Hetaera, un temple désormais peuplé d'hydres.",
			full = "Sous la Baie des tempêtes, au large d'Azshara, se trouve le Frai d'Hetaera, un temple désormais peuplé d'hydres.",
			source = "https://warcraft.wiki.gg/wiki/Hetaera's_Clutch",
		},
		["jagged reef"] = {
			name = "Récif déchiqueté",
			short = "Le Récif déchiqueté est la côte nord d'Azshara, une plage de sable sans cesse entrecoupée d'éperons rocheux et de petites anses marines. Rochers et hauts-fonds se cachent sous la surface, rendant le rivage dangereux à parcourir.",
			full = "Le Récif déchiqueté est la côte nord d'Azshara, une plage de sable sans cesse entrecoupée d'éperons rocheux et de petites anses marines. Rochers et hauts-fonds se cachent sous la surface, rendant le rivage dangereux à parcourir. Murlocs, hydres et makruras tiennent cette côte, nageant dans les hauts-fonds ou arpentant le sable en quête de nourriture.",
			source = "https://warcraft.wiki.gg/wiki/Jagged_Reef",
		},
		["lake mennar"] = {
			name = "Lac Mennar",
			short = "Les eaux du lac Mennar reposent, immobiles, en leur centre, bien que la terre de tous côtés appartienne aux draconides.",
			full = "Les eaux du lac Mennar reposent, immobiles, en leur centre, bien que la terre de tous côtés appartienne aux draconides. Quiconque franchit ce périmètre découvre que le lac lui-même est sans danger, un lieu de calme et de fraîcheur au milieu de rives bien gardées.\n\nC'est l'un des rares endroits du monde, hors du Norfendre, où le vol draconique bleu s'est manifesté. Seul Mazthoril, au Berceau-de-l'Hiver, lui est comparable. Les jeunes dragonnets azur sont une vision courante près de ces eaux.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mennar",
		},
		["legash encampment"] = {
			name = "Campement Legashi",
			short = "Les satyres Legashi tiennent leur campement dans le nord d'Azshara, à l'est d'Ursolan.",
			full = "Les satyres Legashi tiennent leur campement dans le nord d'Azshara, à l'est d'Ursolan.\n\nC'est ici que l'archimage Xylem trouva jadis un grimoire, découverte qui attira l'attention sur ce camp par ailleurs insignifiant de créatures touchées par la gangrène.",
			source = "https://warcraft.wiki.gg/wiki/Legash_Encampment",
		},
		["ravencrest monument"] = {
			name = "Colosse de Ravencrest",
			short = "Les falaises de la pointe sud d'Azshara portent les restes d'un colosse, bien qu'il en reste aujourd'hui peu de chose pour justifier ce mot.",
			full = "Les falaises de la pointe sud d'Azshara portent les restes d'un colosse, bien qu'il en reste aujourd'hui peu de chose pour justifier ce mot. Seules les jambes brisées se dressent encore, plantées au-dessus de la mer, tandis que le reste de la grande statue gît éparpillé sur la pierre alentour, ou a glissé sous les flots en contrebas.\n\nLes nagas Fouette-bile tiennent désormais les ruines. On ne peut y accéder par la mer ; quiconque le cherche doit venir par la terre et franchir le pont qui mène au-delà des Ruines d'Eldarath, pour se tenir sous les jambes renversées de ce qui fut jadis, sans aucun doute, un spectacle impressionnant.",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "Sanctuaire de Rethress",
			short = "Le Sanctuaire de Rethress se dresse en ruine sur la côte dévastée, au sud-ouest du Colosse de Ravencrest. Nul ne l'entretient plus. Murlocs et makruras errent parmi ses pierres effondrées, les seuls à s'y rendre encore.",
			full = "Le Sanctuaire de Rethress se dresse en ruine sur la côte dévastée, au sud-ouest du Colosse de Ravencrest. Nul ne l'entretient plus. Murlocs et makruras errent parmi ses pierres effondrées, les seuls à s'y rendre encore.",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "Les Confins dévastés",
			short = "La côte sud d'Azshara porte ouvertement sa ruine. Falaises et plages se brisent en anses, et l'eau cache des hauts-fonds qui ont piégé plus de coques qu'aucun marin ne se soucie d'en compter.",
			full = "La côte sud d'Azshara porte ouvertement sa ruine. Falaises et plages se brisent en anses, et l'eau cache des hauts-fonds qui ont piégé plus de coques qu'aucun marin ne se soucie d'en compter. Des navires naufragés gisent à demi enfouis dans le sable, aux côtés de ruines plus anciennes et plus étranges dont les bâtisseurs ont disparu. Murlocs, hydres et makruras hantent le rivage, et même ceux qui connaissent la côte y avancent avec prudence.\n\nSur les rives occidentales, au-dessus de la plage, un bâtiment gnome se dresse sur une colline, que l'on n'atteint que par un sentier escarpé venant de l'intérieur des terres. Blimo et Jubie Gadgetspring y ont établi leur foyer et leur commerce. À l'étage, dans leurs appartements privés, se trouve un troisième lit. Nul ne sait à qui il appartient, ni si quelqu'un y dort seulement.",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of eldarath"] = {
			name = "Ruines d'Eldarath",
			short = "Avant que le monde ne soit brisé, Eldarath était l'un des grands bastions des Bien-nés, une cité du savoir arcanique où les mages les plus puissants gravaient des runes et des tablettes dans la pierre et les laissaient dressées dans les lieux publics, afin que tout passant puisse méditer leurs réflexions sur les arcanes.",
			full = "Avant que le monde ne soit brisé, Eldarath était l'un des grands bastions des Bien-nés, une cité du savoir arcanique où les mages les plus puissants gravaient des runes et des tablettes dans la pierre et les laissaient dressées dans les lieux publics, afin que tout passant puisse méditer leurs réflexions sur les arcanes.\n\nLa cité ne tomba pas sans bruit. Pendant la guerre des Anciens, la résistance kaldorei y tint tête à la Légion ardente. Lorsque la Grande fracture déchira le monde, Eldarath ne put y résister : la plus grande partie de la cité s'effondra et sombra dans les eaux de la Baie des tempêtes, en contrebas.\n\nCe qu'il en reste s'accroche aux falaises orientales, un groupe de tours brisées que fuient depuis longtemps les elfes de la nuit qui y vivaient autrefois. Les nagas ont désormais pris possession des ruines, et le seigneur de guerre Krellian règne sur ce qu'il en reste depuis le Temple de Zin-Malor. Parmi les décombres, les tablettes runiques des anciens Bien-nés se dressent toujours, leur sagesse arcanique intacte malgré les âges écoulés.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["scalebeards cave"] = {
			name = "Caverne de Barbe-d'écailles",
			short = "Une grotte sur un îlot de la Baie des tempêtes porte le nom de Barbe-d'écailles, une vieille tortue rare. C'est sa demeure, mais rarement son lieu de repos, car il préfère chasser au loin dans la Grande mer, laissant la tanière vide.",
			full = "Une grotte sur un îlot de la Baie des tempêtes porte le nom de Barbe-d'écailles, une vieille tortue rare. C'est sa demeure, mais rarement son lieu de repos, car il préfère chasser au loin dans la Grande mer, laissant la tanière vide.",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["shadowsong shrine"] = {
			name = "Sanctuaire de Shadowsong",
			short = "Colline couverte de ruines dans l'ouest d'Azshara, le Sanctuaire de Shadowsong ne garde aucune trace claire de la raison pour laquelle il porte ce nom.",
			full = "Colline couverte de ruines dans l'ouest d'Azshara, le Sanctuaire de Shadowsong ne garde aucune trace claire de la raison pour laquelle il porte ce nom. Il partage son nom avec Jarod Shadowsong, qui mena la résistance pendant la guerre des Anciens, et avec sa sœur Maiev, la gardienne dont on se souvient pour avoir tenu Illidan Hurlorage captif après sa trahison au mont Hyjal. Ce que l'un ou l'autre a à voir avec cette colline, nul ne saurait le dire.\n\nCe que l'on peut dire, c'est ce qui y rôde. Des fantômes de Bien-nés s'attardent parmi les pierres, avides de toute créature vivante qui s'approche.",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "La Grève fracassée",
			short = "La Grève fracassée longe la rive nord de la Baie des tempêtes, en Azshara, peuplée d'hydres, de géants des mers, de makruras et de murlocs, chacun tenant sa propre portion de sable.",
			full = "La Grève fracassée longe la rive nord de la Baie des tempêtes, en Azshara, peuplée d'hydres, de géants des mers, de makruras et de murlocs, chacun tenant sa propre portion de sable. Le Temple d'Arkkoran et la Tour d'Eldara se dressent sur le rivage malgré la cohue de pinces et de tentacules.\n\nDes gobelins, eux aussi, ont jalonné des concessions le long de cette côte, spéculant sur les terrains en bord de mer au milieu des crocs et des marées.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
		},
		["southfury river"] = {
			name = "Fleuve Furie-du-Sud",
			short = "Le fleuve Furie-du-Sud prend sa source haut sur le mont Hyjal, jaillissant d'un lac de montagne en une chute qui s'abat avec fracas dans les basses terres.",
			full = "Le fleuve Furie-du-Sud prend sa source haut sur le mont Hyjal, jaillissant d'un lac de montagne en une chute qui s'abat avec fracas dans les basses terres. De là, il coule large et rapide, coupant le pays en deux : il marque l'endroit où Orneval cède la place à Azshara et, plus au sud, celui où finissent les Tarides et où commence Durotar. À son embouchure, le fleuve se jette par une dernière cascade dans la Grande mer, juste au nord-est du port gobelin de Ratchet.\n\nDes ponts le franchissent sur toute sa longueur, l'un reliant Azshara à Orneval, un autre unissant Durotar aux Tarides.\n\nLe fleuve nourrit toujours les champs le long de ses rives, et verdit toujours la terre là où il coule.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southridge beach"] = {
			name = "Plage des Crêtes du sud",
			short = "La Plage des Crêtes du sud borde la rive sud de la Baie des tempêtes, son sable jonché des ruines de la cité autrefois grandiose d'Eldarath.",
			full = "La Plage des Crêtes du sud borde la rive sud de la Baie des tempêtes, son sable jonché des ruines de la cité autrefois grandiose d'Eldarath. Les nagas tiennent désormais le rivage, qu'ils partagent avec des makruras, des hydres, des murlocs et, à l'occasion, un géant des mers surgi des eaux profondes.",
			source = "https://warcraft.wiki.gg/wiki/Southridge_Beach",
		},
		["storm cliffs"] = {
			name = "Falaises de la Tempête",
			short = "Les Falaises de la Tempête se dressent en Azshara, revendiquées par les nagas Fouette-bile qui vivent parmi les rochers. À l'extrémité orientale des falaises se dresse le Colosse de Ravencrest, un repère solitaire qui domine la pierre tenue par les nagas.",
			full = "Les Falaises de la Tempête se dressent en Azshara, revendiquées par les nagas Fouette-bile qui vivent parmi les rochers. À l'extrémité orientale des falaises se dresse le Colosse de Ravencrest, un repère solitaire qui domine la pierre tenue par les nagas.",
			source = "https://warcraft.wiki.gg/wiki/Storm_Cliffs",
		},
		["talrendis point"] = {
			name = "Halte de Talrendis",
			short = "La Halte de Talrendis se dresse dans le sud-ouest d'Azshara, ses deux tours de garde surveillant la frontière d'Orneval, tandis qu'un puits de lune arrose encore la terre au sud.",
			full = "La Halte de Talrendis se dresse dans le sud-ouest d'Azshara, ses deux tours de garde surveillant la frontière d'Orneval, tandis qu'un puits de lune arrose encore la terre au sud.\n\nLa Halte ne fut d'abord qu'un petit campement d'elfes de la nuit, un poste de guet à la lisière de la forêt.",
			source = "https://warcraft.wiki.gg/wiki/Talrendis_Point",
		},
		["temple of arkkoran"] = {
			name = "Temple d'Arkkoran",
			short = "Le Temple d'Arkkoran fut jadis voué au culte d'Elune, ses pierres élevées sur les rives nord-est d'Azshara. Ce caractère sacré a depuis longtemps disparu.",
			full = "Le Temple d'Arkkoran fut jadis voué au culte d'Elune, ses pierres élevées sur les rives nord-est d'Azshara. Ce caractère sacré a depuis longtemps disparu. Le géant des mers Arkkoroc demeure désormais à son sommet, gardé par des murlocs et des makruras qui se jettent sur quiconque s'approche. Le rivage alentour, la Grève fracassée, n'offre pas de passage plus sûr, surveillé par des hydres et des géants des mers aussi agressifs qu'Arkkoroc lui-même.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "Temple de Zin-Malor",
			short = "Le Temple de Zin-Malor se dresse parmi les Ruines d'Eldarath, ses pierres façonnées à l'image du Temple d'Arkkoran voisin, et du temple de la Lune élevé plus tard à Darnassus.",
			full = "Le Temple de Zin-Malor se dresse parmi les Ruines d'Eldarath, ses pierres façonnées à l'image du Temple d'Arkkoran voisin, et du temple de la Lune élevé plus tard à Darnassus. Il fut bâti par dévotion envers Elune, à l'époque où les elfes de la nuit ne s'étaient pas encore tournés vers la magie des arcanes.\n\nEn son sein reposait jadis le cristal de Zin-Malor, un présent destiné à porter un message aux Bien-nés : qu'ils n'avaient en vérité nul besoin de la magie des arcanes. Le cristal a disparu aujourd'hui, emporté il y a bien longtemps.\n\nLe temple est depuis tombé aux mains de la tribu naga des Fouette-bile. Le seigneur de guerre Krellian y règne désormais, s'arrogeant la place d'honneur autrefois réservée au culte de la déesse.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
		},
		["thalassian base camp"] = {
			name = "Camp de base thalassien",
			short = "La colline qui domine les camps Legashi appartient aux elfes de sang, ses pentes découpées en petits postes fortifiés sous les ordres de la magus Rimtori.",
			full = "La colline qui domine les camps Legashi appartient aux elfes de sang, ses pentes découpées en petits postes fortifiés sous les ordres de la magus Rimtori. Elle conclut un marché avec la Horde, promettant une part de tout ce que son expédition mettrait au jour en échange d'or et d'acier pour la protéger. Le marché ne tint pas. Rimtori prit l'argent et ne rendit rien, et la nouvelle de sa trahison s'est répandue au point que l'on dit qu'une vengeance lui est due, à elle comme à ses partisans.\n\nRimtori elle-même est rarement au camp, occupée à explorer Azshara sous une escorte de son choix, laissant au magistère Hawkhelm le soin de tenir la colline en son absence. Ce que tous deux recherchent vraiment, ce n'est pas l'or. Sur l'une des crêtes du camp repose un Tome d'invocation kaldorei, un objet capable d'appeler des démons dans le monde, et sa présence révèle l'expédition pour ce qu'elle est : non pas une chasse au trésor, mais quelque chose de plus sombre qui en a pris l'apparence.",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Base_Camp",
		},
		["tower of eldara"] = {
			name = "Tour d'Eldara",
			short = "La Tour d'Eldara se dresse à l'extrême pointe nord-est des terres, au-dessus de la Baie des tempêtes, son rivage de sable patrouillé par des murlocs, des makruras et des hydres.",
			full = "La Tour d'Eldara se dresse à l'extrême pointe nord-est des terres, au-dessus de la Baie des tempêtes, son rivage de sable patrouillé par des murlocs, des makruras et des hydres. Elle appartenait jadis à la civilisation des elfes de la nuit qui s'étendait sur cette côte, mais la tour est désormais close et abandonnée.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Eldara",
		},
		["ursolan"] = {
			name = "Ursolan",
			short = "Ursolan tire son nom d'Ursol, le demi-dieu ours vénéré par la race des furbolgs. C'est aujourd'hui le site d'un vaste village furbolg des Grumegueules, qui s'étend vers le sud à travers le Repaire jusqu'à Tête d'ours.",
			full = "Ursolan tire son nom d'Ursol, le demi-dieu ours vénéré par la race des furbolgs. C'est aujourd'hui le site d'un vaste village furbolg des Grumegueules, qui s'étend vers le sud à travers le Repaire jusqu'à Tête d'ours.",
			source = "https://warcraft.wiki.gg/wiki/Ursolan",
		},
		["valormok"] = {
			name = "Valormok",
			short = "Valormok est un avant-poste de la Horde en Azshara, situé au nord-ouest, au nord du Campement des Haldarr. Les guerriers qui y sont stationnés traversent des temps difficiles mais gardent espoir.",
			full = "Valormok est un avant-poste de la Horde en Azshara, situé au nord-ouest, au nord du Campement des Haldarr. Les guerriers qui y sont stationnés traversent des temps difficiles mais gardent espoir.\n\nCet espoir fut trahi de l'intérieur. Belgrom Rockmaul avait envoyé la magus Rimtori, une elfe de sang, avec une compagnie de guerriers orcs, trouver des richesses et de puissants artefacts dans la région. Rimtori trouva ce qu'elle cherchait et, plutôt que de partager sa découverte, se retourna contre les guerriers qui l'avaient escortée, les tua et garda le butin pour elle. Ag'tor Bloodfist, qui commande le camp, ne laissera pas ce massacre sans réponse. Il cherche des guerriers pour venger ses morts et l'orgueil blessé de Rockmaul, et pour voir la magus Rimtori périr dans son camp tout proche.",
			source = "https://warcraft.wiki.gg/wiki/Valormok",
		},
	},
	-- Gangrebois: 18 subzones
	[1448] = {
		["bloodvenom falls"] = {
			name = "Chutes de la Vénéneuse",
			short = "Les Chutes de la Vénéneuse dévalent des hauteurs de Gangrebois, leurs eaux souillées dès la source.",
			full = "Les Chutes de la Vénéneuse dévalent des hauteurs de Gangrebois, leurs eaux souillées dès la source. C'est ici que naît la Vénéneuse, qui charrie la souillure vers l'aval jusqu'à se déverser en Sombrivage sous la forme de la Sinueuse, rivière malade.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Falls",
		},
		["bloodvenom post"] = {
			name = "Poste de la Vénéneuse",
			short = "Le Poste de la Vénéneuse se dresse sur les hautes falaises dominant Sombrivage, là où la Vénéneuse traverse Gangrebois.",
			full = "Le Poste de la Vénéneuse se dresse sur les hautes falaises dominant Sombrivage, là où la Vénéneuse traverse Gangrebois. Son architecture et les taurens qui le gardent en font une fondation taurène, un petit point d'appui de la Horde qui veille sur la côte en contrebas.\n\nOn y accède par un sentier sombre qui suit la rive sud du fleuve vers l'ouest depuis le chemin de pierre qui traverse Gangrebois, et contourne la colline jusqu'au poste lui-même.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Post",
		},
		["bloodvenom river"] = {
			name = "La Vénéneuse",
			short = "La Vénéneuse coule, noire, à travers Gangrebois, et sa corruption se répand au-delà de la région jusqu'à resurgir sous la forme de la Sinueuse, en Sombrivage.",
			full = "La Vénéneuse coule, noire, à travers Gangrebois, et sa corruption se répand au-delà de la région jusqu'à resurgir sous la forme de la Sinueuse, en Sombrivage. Des limons nocifs rampent sur ses berges, et la faune alentour est devenue venimeuse. Nul n'y boit, et nul n'y nage.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_River",
		},
		["deadwood village"] = {
			name = "Village des Mort-bois",
			short = "Les furbolgs Mort-bois bâtirent leur village dans le sud de Gangrebois, derrière des murs de lourds madriers, et élevèrent à l'intérieur des constructions plus solides.",
			full = "Les furbolgs Mort-bois bâtirent leur village dans le sud de Gangrebois, derrière des murs de lourds madriers, et élevèrent à l'intérieur des constructions plus solides. Comme leurs frères à travers la forêt corrompue, ils succombèrent à la souillure de Gangrebois, devenant hostiles et difformes.",
			source = "https://warcraft.wiki.gg/wiki/Deadwood_Village",
		},
		["emerald sanctuary"] = {
			name = "Sanctuaire d'émeraude",
			short = "Le Sanctuaire d'émeraude se trouve dans le sud-est de Gangrebois, un camp des druides du Cercle d'émeraude. De là, ils surveillent Jaedenar et s'efforcent d'étouffer la corruption démoniaque qui s'en répand avant qu'elle ne dévore davantage de terres.",
			full = "Le Sanctuaire d'émeraude se trouve dans le sud-est de Gangrebois, un camp des druides du Cercle d'émeraude. De là, ils surveillent Jaedenar et s'efforcent d'étouffer la corruption démoniaque qui s'en répand avant qu'elle ne dévore davantage de terres.",
			source = "https://warcraft.wiki.gg/wiki/Emerald_Sanctuary",
		},
		["felpaw village"] = {
			name = "Village de Gangrepatte",
			short = "Le Village de Gangrepatte se trouve à la lisière nord de Gangrebois, près de l'entrée du Repaire des Grumegueules.",
			full = "Le Village de Gangrepatte se trouve à la lisière nord de Gangrebois, près de l'entrée du Repaire des Grumegueules. Il appartient aux Mort-bois, des furbolgs que leur corruption a détournés des leurs, et leur souillure marque encore la terre qu'ils tiennent.",
			source = "https://warcraft.wiki.gg/wiki/Felpaw_Village",
		},
		["irontree cavern"] = {
			name = "Caverne d'Arbrefer",
			short = "Au fond de la grotte, le bois tordu des Warpwoods a pris racine, donnant naissance à des déchiqueteurs et à des écorcheurs de mousse qui rôdent dans l'obscurité en lieu et place de tout gardien vivant.",
			full = "Au fond de la grotte, le bois tordu des Warpwoods a pris racine, donnant naissance à des déchiqueteurs et à des écorcheurs de mousse qui rôdent dans l'obscurité en lieu et place de tout gardien vivant.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Cavern",
		},
		["irontree woods"] = {
			name = "Bois d'Arbrefer",
			short = "Le Bois d'Arbrefer était jadis une paisible clairière du nord de Gangrebois, avant que la corruption de la Légion ardente n'en fasse tout autre chose.",
			full = "Le Bois d'Arbrefer était jadis une paisible clairière du nord de Gangrebois, avant que la corruption de la Légion ardente n'en fasse tout autre chose. Trois grands Anciens des elfes de la nuit vivaient ici, des arbres vivants nommés Hastat, Stoma et Vartrus. La corruption ne les épargna pas : tous trois furent pétrifiés sur place et restent encore ensevelis dans le bois, morts au milieu du fléau qui les a tués.\n\nPourtant, quelque chose a refusé de rester mort. L'eau d'un puits de lune versée au cœur du bois fit naître une jeune pousse. Soignée et grandie, elle fleurit, puis retourna à la terre où elle était née, enracinée parmi les morts pétrifiés, attendant de se dresser en Ancien à leur place.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Woods",
		},
		["jadefire glen"] = {
			name = "Vallon des Jadefeu",
			short = "Dans les bois corrompus du sud de Gangrebois, le Vallon des Jadefeu abrite un camp de satyres, créatures démoniaques qui ont fait de ce creux souillé leur domaine, prospérant dans sa pourriture et répandant la corruption plus loin parmi les arbres alentour.",
			full = "Dans les bois corrompus du sud de Gangrebois, le Vallon des Jadefeu abrite un camp de satyres, créatures démoniaques qui ont fait de ce creux souillé leur domaine, prospérant dans sa pourriture et répandant la corruption plus loin parmi les arbres alentour.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Glen",
		},
		["jadefire run"] = {
			name = "Défilé des Jadefeu",
			short = "Dans le nord de Gangrebois se trouve le Défilé des Jadefeu, repaire des satyres les plus puissants de la région. La prudence s'impose à quiconque s'en approche.",
			full = "Dans le nord de Gangrebois se trouve le Défilé des Jadefeu, repaire des satyres les plus puissants de la région. La prudence s'impose à quiconque s'en approche. Ses constructions suivent des plans démoniaques plutôt que mortels.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Run",
		},
		["jaedenar"] = {
			name = "Jaedenar",
			short = "Jaedenar s'élève sur une terre qui appartint jadis aux elfes de la nuit, ses pierres plus anciennes que la corruption qui s'en empare aujourd'hui.",
			full = "Jaedenar s'élève sur une terre qui appartint jadis aux elfes de la nuit, ses pierres plus anciennes que la corruption qui s'en empare aujourd'hui. Sous ses ruines s'étendent deux refuges des saisons druidiques, autrefois sacrés, et c'est sur ces fondations profanées que le Conseil des ombres bâtit sa domination, donnant au lieu lui-même son nom en hommage à Kil'jaeden le Trompeur.\n\nAprès la troisième guerre, les ruines passèrent aux mains de Lord Banehollow et du Conseil des ombres qu'il dirigeait. Des démonistes orcs et réprouvés emplirent ses salles, et ils ne vinrent pas seuls : succubes, chasseurs corrompus, gangregardes et satyres évoluaient parmi eux. En son cœur se dresse le Fort des ombres, siège du pouvoir du Conseil sur Azeroth, et à côté le Sanctuaire du Trompeur, élevé au nom de Kil'jaeden.",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "Morlos'Aran",
			short = "Morlos'Aran fut jadis une grande cité des elfes de la nuit, élevée avant que la Grande fracture ne déchire le monde.",
			full = "Morlos'Aran fut jadis une grande cité des elfes de la nuit, élevée avant que la Grande fracture ne déchire le monde. Elle gît aujourd'hui en ruine à la lisière sud de Gangrebois, un lieu parmi d'autres semblables, comme Ameth'Aran, Bashal'Aran, Ordil'Aran et Tethris'Aran, autrefois des cités florissantes, désormais réduites à des pierres et au souvenir d'un âge d'or depuis longtemps perdu.",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "Ruines de Constellas",
			short = "Les colonnes brisées de ce lieu appartenaient jadis à une cité des elfes de la nuit proche du mont Hyjal. Un puits de lune repose encore en son cœur, mais sa lumière n'est plus pure.",
			full = "Les colonnes brisées de ce lieu appartenaient jadis à une cité des elfes de la nuit proche du mont Hyjal. Un puits de lune repose encore en son cœur, mais sa lumière n'est plus pure. La corruption gangrenée s'est infiltrée dans ses eaux, et le satyre Xavathras l'entretient désormais pour le compte de Xavaric, cultivant la corruption comme un jardin destiné à empoisonner. Plus loin dans les ruines, un mur de flammes barre le chemin jusqu'à lui.\n\nLes druides n'ont pas laissé les démons agir sans riposte, et les harcèlent pour tenter d'arracher le lieu à la gangrène qui y a pris racine.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "Fort des ombres",
			short = "Sous Jaedenar, dans l'ouest de Gangrebois, s'étend un labyrinthe qui fut jadis un refuge des saisons des elfes de la nuit. Le Conseil des ombres s'en empara il y a longtemps, et des démonistes et leurs familiers démoniaques arpentent désormais ses tunnels.",
			full = "Sous Jaedenar, dans l'ouest de Gangrebois, s'étend un labyrinthe qui fut jadis un refuge des saisons des elfes de la nuit. Le Conseil des ombres s'en empara il y a longtemps, et des démonistes et leurs familiers démoniaques arpentent désormais ses tunnels. Le prince satyre Xavalis et le seigneur de l'effroi Lord Banehollow y demeurent tous deux.\n\nLe paladin Trey Lightforge et l'elfe de la nuit Arko'narin Starshade s'aventurèrent en Gangrebois à la recherche des traces de l'œuvre du Conseil des ombres. Les cultistes les capturèrent tous deux et les enfermèrent dans des cages au Fort des ombres. Trey y fut torturé à mort, son esprit tordu et corrompu par ses geôliers. Arko'narin reste enfermée dans les profondeurs, surveillée par ses tourmenteurs, attendant un secours qui n'est pas encore venu.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shatter scar vale"] = {
			name = "Val Grêlé",
			short = "Le Val Grêlé est l'endroit où s'abattirent les infernaux lorsque la Légion ardente déferla sur Gangrebois pendant la troisième guerre. Les cratères qu'ils laissèrent fument encore, balafrant la terre, et des démons errent toujours parmi eux.",
			full = "Le Val Grêlé est l'endroit où s'abattirent les infernaux lorsque la Légion ardente déferla sur Gangrebois pendant la troisième guerre. Les cratères qu'ils laissèrent fument encore, balafrant la terre, et des démons errent toujours parmi eux.",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
		},
		["shrine of the deceiver"] = {
			name = "Sanctuaire du Trompeur",
			short = "Le Sanctuaire du Trompeur, un refuge des saisons corrompu situé à Jaedenar, en Gangrebois, tire son nom de Kil'jaeden, le Trompeur, seigneur de la Légion ardente.",
			full = "Le Sanctuaire du Trompeur, un refuge des saisons corrompu situé à Jaedenar, en Gangrebois, tire son nom de Kil'jaeden, le Trompeur, seigneur de la Légion ardente. Les démonistes du Conseil des ombres en peuplent les profondeurs, ce qui en fait un lieu dangereux pour qui n'y est pas préparé.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Deceiver",
		},
		["talonbranch glade"] = {
			name = "Clairière de Griffebranche",
			short = "La Clairière de Griffebranche se trouve dans le nord de Gangrebois, au sud du Repaire des Grumegueules, sur le chemin qui mène à Reflet-de-Lune et au Berceau-de-l'Hiver.",
			full = "La Clairière de Griffebranche se trouve dans le nord de Gangrebois, au sud du Repaire des Grumegueules, sur le chemin qui mène à Reflet-de-Lune et au Berceau-de-l'Hiver.",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
		},
		["timbermaw hold"] = {
			name = "Repaire des Grumegueules",
			short = "Le Repaire des Grumegueules, au nord-est de Gangrebois, est la capitale de la tribu furbolg des Grumegueules. Ses tunnels ouvrent un passage vers Reflet-de-Lune et le Berceau-de-l'Hiver.",
			full = "Le Repaire des Grumegueules, au nord-est de Gangrebois, est la capitale de la tribu furbolg des Grumegueules. Ses tunnels ouvrent un passage vers Reflet-de-Lune et le Berceau-de-l'Hiver.\n\nLorsque la corruption de la Légion ardente s'insinua dans les forêts sacrées de Kalimdor, les furbolgs tombèrent sous son emprise et sombrèrent dans la folie. Seule la tribu des Grumegueules échappa à ces ténèbres, se réfugiant dans son repaire tandis que la forêt qu'elle aimait se muait en une parodie purulente d'elle-même. Longtemps encore après la chute du chef des démons, la souillure demeura sur les bois.\n\nLes furbolgs du Repaire des Grumegueules se méfient de tous les étrangers, craignant d'être confondus avec leurs frères corrompus et attaqués à vue. Ils savent pourtant qu'ils ne peuvent survivre seuls, et ceux qui gagnent leur confiance découvrent que les Grumegueules placent l'amitié au-dessus de tout. Plus que tout, ils ne souhaitent que mettre fin aux souffrances de leurs frères corrompus et trouver un remède à la plaie qu'est devenu Gangrebois.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Cratère d'Un'Goro: 9 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "Crête de la Fournaise",
			short = "La Crête de la Fournaise s'élève au cœur du cratère d'Un'Goro, une montagne de roche calcinée où la lave coule lentement le long des pentes et où des élémentaires de feu s'agitent dans la chaleur.",
			full = "La Crête de la Fournaise s'élève au cœur du cratère d'Un'Goro, une montagne de roche calcinée où la lave coule lentement le long des pentes et où des élémentaires de feu s'agitent dans la chaleur. Des veines de magma peu profondes courent sous le sol du cratère, alimentant les bassins de vapeur et les geysers qui sifflent dans tout Un'Goro, si bien que le bassin tout entier semble respirer au rythme du feu de la montagne.\n\nDans une grotte au sommet demeure Blazerunner, le plus puissant des élémentaires de feu qui hantent la crête, maître du cœur brûlant de la montagne. Les esprits de feu qui vacillent et dansent ici parlent de siècles passés à brûler, à s'éteindre jusqu'aux braises, puis à se rallumer, encore et encore, sans fin.\n\nTous ceux qui viennent sur la crête n'en triomphent pas. Un voyageur du nom de Ringo vint explorer ses pentes, s'égara, et fut terrassé par la chaleur. On peut encore le trouver dans la grotte du sud, dont il n'est jamais ressorti.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
		},
		["fungal rock"] = {
			name = "Rocher fongique",
			short = "Le Rocher fongique s'ouvre dans la paroi nord-est du cratère d'Un'Goro, une caverne où vivent des gorilles parmi les champignons fantômes qui poussent dans son obscurité.",
			full = "Le Rocher fongique s'ouvre dans la paroi nord-est du cratère d'Un'Goro, une caverne où vivent des gorilles parmi les champignons fantômes qui poussent dans son obscurité. Au-dehors, un petit bassin se forme sous une cascade, et là se tient le singe mécanique de Karna Remtravel, A-Me 01.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Rock",
		},
		["golakka hot springs"] = {
			name = "Sources de Golakka",
			short = "La vapeur s'élève sans cesse des Sources de Golakka, où le cœur volcanique du cratère d'Un'Goro déverse sa chaleur dans des bassins et des geysers, à l'ouest du cratère.",
			full = "La vapeur s'élève sans cesse des Sources de Golakka, où le cœur volcanique du cratère d'Un'Goro déverse sa chaleur dans des bassins et des geysers, à l'ouest du cratère. Des élémentaires de fureur nés de cette vapeur et de ce feu arpentent les rives, arrachés à la terre par les mêmes forces qui font bouillir les sources.\n\nKrakle vint jadis ici pour découvrir ce qui liait les sources chaudes aux feux de la Crête de la Fournaise toute proche, avant que ses recherches ne l'entraînent ailleurs.",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
		},
		["ironstone plateau"] = {
			name = "Plateau de Rochefer",
			short = "La roche nue perce la verdure d'Un'Goro le long de sa paroi nord-est. Le Plateau de Rochefer est paisible comparé au reste du cratère, presque dépourvu de prédateurs.",
			full = "La roche nue perce la verdure d'Un'Goro le long de sa paroi nord-est. Le Plateau de Rochefer est paisible comparé au reste du cratère, presque dépourvu de prédateurs. De jeunes pterrordax y nichent, et le calme du plateau le distingue de la végétation fébrile d'Un'Goro.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Plateau",
		},
		["lakkari tar pits"] = {
			name = "Fosses de goudron de Lakkari",
			short = "Les lacs noirs au nord du Refuge des Marshal s'étendent, épais et nauséabonds, au milieu de la verdure d'Un'Goro. Des ossements en saillent par centaines, restes de bêtes qui s'y sont aventurées en croyant trouver un sol ferme et n'en ont trouvé aucun.",
			full = "Les lacs noirs au nord du Refuge des Marshal s'étendent, épais et nauséabonds, au milieu de la verdure d'Un'Goro. Des ossements en saillent par centaines, restes de bêtes qui s'y sont aventurées en croyant trouver un sol ferme et n'en ont trouvé aucun. Des charognards rôdent sur les bords, attendant que le goudron achève ce qu'il a commencé, tandis que des bêtes de goudron ont surgi des fosses elles-mêmes.",
			source = "https://warcraft.wiki.gg/wiki/Lakkari_Tar_Pits",
		},
		["marshals refuge"] = {
			name = "Refuge des Marshal",
			short = "Le Refuge des Marshal se trouve à la lisière nord du cratère d'Un'Goro, établi par les Expéditions Marshal sous la conduite de Williden et Hol'anyee Marshal.",
			full = "Le Refuge des Marshal se trouve à la lisière nord du cratère d'Un'Goro, établi par les Expéditions Marshal sous la conduite de Williden et Hol'anyee Marshal. Leur entreprise dans le cratère n'était pas préparée à ce qu'elle allait y trouver : les bêtes d'Un'Goro se révélèrent trop féroces, et les camps de base de l'expédition furent submergés l'un après l'autre. Ce qui restait de la troupe s'enfuit vers les hauteurs et trouva son salut ici, au bord du cratère.\n\nLe refuge est le fruit de cette retraite, une position à peine tenue plutôt que conquise.",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshlands"] = {
			name = "La Fondrière",
			short = "Le marais s'étend sur la partie sud-est du cratère d'Un'Goro, une vaste étendue basse d'eaux stagnantes et de végétation fétide qui accueille la plupart de ceux qui descendent pour la première fois dans le cratère depuis Tanaris, car tout autre accès est périlleux.",
			full = "Le marais s'étend sur la partie sud-est du cratère d'Un'Goro, une vaste étendue basse d'eaux stagnantes et de végétation fétide qui accueille la plupart de ceux qui descendent pour la première fois dans le cratère depuis Tanaris, car tout autre accès est périlleux. Des raptors s'y déplacent en grand nombre parmi les roseaux, certains portant du poison dans leur morsure.\n\nOn trouve ici des cristaux de puissance bleus, et leur présence a imprégné le marais lui-même, s'infiltrant dans les raptors qui chassent sur le sol détrempé et les marquant de son empreinte.\n\nSur un monticule émergeant de l'eau, Torwa Pathfinder monte la garde, venu jusque-là en canoë depuis une autre partie du cratère.",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["slithering scar"] = {
			name = "La Balafre sinueuse",
			short = "La Balafre sinueuse s'étend sur la partie sud du cratère d'Un'Goro, une ruche de la secte Gorishi.",
			full = "La Balafre sinueuse s'étend sur la partie sud du cratère d'Un'Goro, une ruche de la secte Gorishi.\n\nLa ruche eut autrefois une reine, invoquée en perturbant le cristal silithide Gorishi qui s'y trouve.",
			source = "https://warcraft.wiki.gg/wiki/Slithering_Scar",
		},
		["terror run"] = {
			name = "Coteaux de la terreur",
			short = "Dans les Coteaux de la terreur, à l'ouest de la Balafre sinueuse, des cristaux rouges surgissent du sol comme nulle part ailleurs dans le cratère d'Un'Goro. Les bêtes des coteaux se sont abreuvées de leur puissance, et cela se voit.",
			full = "Dans les Coteaux de la terreur, à l'ouest de la Balafre sinueuse, des cristaux rouges surgissent du sol comme nulle part ailleurs dans le cratère d'Un'Goro. Les bêtes des coteaux se sont abreuvées de leur puissance, et cela se voit.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Run",
		},
	},
	-- Reflet-de-Lune: 5 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "Lac Elune'ara",
			short = "Une eau cristalline emplit le cœur de Reflet-de-Lune, immobile comme du verre sous les arbres. Sous sa surface gît Omen, le demi-dieu fou, vaincu il y a de longs siècles et jamais tout à fait parti de ces profondeurs.",
			full = "Une eau cristalline emplit le cœur de Reflet-de-Lune, immobile comme du verre sous les arbres. Sous sa surface gît Omen, le demi-dieu fou, vaincu il y a de longs siècles et jamais tout à fait parti de ces profondeurs. Le lac le maintient immobile, un poids silencieux sous l'eau calme.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "Havrenuit",
			short = "Sur les rives du lac Elune'ara se dresse Havrenuit, un village de pierre ouvragée par les elfes de la nuit et de puits de lune, où vivent les druides du Cercle cénarien.",
			full = "Sur les rives du lac Elune'ara se dresse Havrenuit, un village de pierre ouvragée par les elfes de la nuit et de puits de lune, où vivent les druides du Cercle cénarien. C'est un lieu paisible et retiré, fermé à la plupart des étrangers, dont les habitants se consacrent au druidisme et au soin de la nature sauvage.\n\nUne seule fois par an, Havrenuit ouvre ses portes, lorsque l'on célèbre la Fête lunaire et que des feux d'artifice s'allument au-dessus du lac en hommage à la puissance d'Elune, accueillant des étrangers qui, sinon, ne trouveraient jamais bon accueil ici.\n\nMais le village a connu des nuits plus sombres qu'aucune fête. C'est ici que le gardien Remulos affronta Eranikus, le dragon du Cauchemar, corrompu et retourné contre le village. Des créatures du Cauchemar s'abattirent sur Havrenuit, menaçant de l'anéantir entièrement, jusqu'à ce que Tyrande Whisperwind vienne enfin et fasse descendre la lumière d'Elune pour purifier le dragon de la corruption qui l'avait saisi. Les puits de lune brûlent encore de cette même lumière.",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["shrine of remulos"] = {
			name = "Sanctuaire de Remulos",
			short = "Dans l'ouest de Reflet-de-Lune se dresse le Sanctuaire de Remulos, élevé en l'honneur du gardien qui veille sur ce lieu. En son sein demeure l'elfe de la nuit Tajarri, qui guide les jeunes druides désireux d'apprendre la forme aquatique.",
			full = "Dans l'ouest de Reflet-de-Lune se dresse le Sanctuaire de Remulos, élevé en l'honneur du gardien qui veille sur ce lieu. En son sein demeure l'elfe de la nuit Tajarri, qui guide les jeunes druides désireux d'apprendre la forme aquatique.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "Refuge des saisons de Malfurion",
			short = "Sous le gazon paisible de Reflet-de-Lune s'étendent les refuges des saisons, creusés dans une terre que de nombreux druides elfes de la nuit ne quittent jamais vraiment, leur corps reposant tandis que leur esprit parcourt le Rêve d'émeraude.",
			full = "Sous le gazon paisible de Reflet-de-Lune s'étendent les refuges des saisons, creusés dans une terre que de nombreux druides elfes de la nuit ne quittent jamais vraiment, leur corps reposant tandis que leur esprit parcourt le Rêve d'émeraude.\n\nC'est ici que dormit jadis Malfurion Hurlorage, et c'est pourquoi ces refuges portent son nom. Lorsque Tichondrius et ses seigneurs de l'effroi vinrent pendant la troisième guerre, ils frappèrent Malfurion là où il reposait, déchirant presque son refuge. Ce fut Tyrande Whisperwind qui le réveilla, le rappelant au monde pour se dresser contre Archimonde et la Légion ardente.\n\nPlus tard, lorsque le Cercle cénarien parla de faire pousser un second Arbre-Monde, Malfurion retourna aux refuges des saisons pour méditer. Tyrande vint ensuite le chercher et trouva son corps immobile, comme endormi, sans qu'on puisse l'éveiller. Le Cercle jugea plus sage de ne pas le déplacer : si son esprit errait encore dans le Rêve en cherchant le chemin du retour, il lui faudrait retrouver le corps là où il l'avait laissé. Il resta donc là, veillé par le Cercle cénarien et la Sororité d'Elune, son corps gisant immobile dans le refuge qui porte son nom.",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "Repaire des Grumegueules",
			short = "Le Repaire des Grumegueules se trouve au nord-est de Gangrebois, là où un tunnel perce jusqu'à Reflet-de-Lune et au Berceau-de-l'Hiver. C'est la capitale de la tribu furbolg des Grumegueules.",
			full = "Le Repaire des Grumegueules se trouve au nord-est de Gangrebois, là où un tunnel perce jusqu'à Reflet-de-Lune et au Berceau-de-l'Hiver. C'est la capitale de la tribu furbolg des Grumegueules.\n\nLorsque la corruption de la Légion ardente s'insinua dans les forêts sacrées de Kalimdor, les furbolgs tombèrent sous son emprise. Seule la tribu des Grumegueules échappa à ces ténèbres, se réfugiant dans son repaire et assistant, impuissante, à la transformation de la forêt qu'elle aimait en une parodie purulente d'elle-même. Même après la destruction de la source de cette corruption, la souillure demeura sur les bois.\n\nLes Grumegueules se méfient désormais de tous les étrangers, craignant d'être confondus avec leurs frères corrompus et attaqués à vue. Ils savent pourtant qu'ils ne peuvent survivre seuls, et ceux qui gagnent leur confiance découvrent que les Grumegueules placent l'amitié au-dessus de tout. Leur tradition chamanique perdure, riche en savoir-faire dans la confection d'armures de peau et en connaissances anciennes de la guérison. Plus que tout, la tribu aspire à mettre fin aux souffrances de ses frères corrompus, afin que l'antique forêt résonne un jour de nouveau des chants et des rires qu'elle a perdus.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Silithus: 19 subzones
	[1451] = {
		["bones of grakkarond"] = {
			name = "Restes de Grakkarond",
			short = "Au centre de Silithus gisent les immenses ossements du dragon Grakkarond, tombé là pendant la guerre des Sables changeants.",
			full = "Au centre de Silithus gisent les immenses ossements du dragon Grakkarond, tombé là pendant la guerre des Sables changeants.",
			source = "https://warcraft.wiki.gg/wiki/Bones_of_Grakkarond",
		},
		["bronzebeard encampment"] = {
			name = "Campement de Bronzebeard",
			short = "Le Campement de Bronzebeard se trouve dans le sud de Silithus, à l'est du Mur du scarabée.",
			full = "Le Campement de Bronzebeard se trouve dans le sud de Silithus, à l'est du Mur du scarabée.",
			source = "https://warcraft.wiki.gg/wiki/Bronzebeard_Encampment",
		},
		["cenarion hold"] = {
			name = "Fort cénarien",
			short = "Le Fort cénarien fut érigé à Silithus après la guerre des Sables changeants, bâti par le Cercle cénarien sur une ancienne cité des elfes de la nuit.",
			full = "Le Fort cénarien fut érigé à Silithus après la guerre des Sables changeants, bâti par le Cercle cénarien sur une ancienne cité des elfes de la nuit. C'est l'une des grandes places fortes druidiques de Kalimdor, que seul Reflet-de-Lune égale en taille, et sa mission est unique : tenir la ligne face aux essaims silithides et veiller sur la chose enfouie sous les sables, le Dieu très ancien emprisonné C'Thun, de peur que ses armées ne se relèvent.\n\nC'est un lieu de vie rude et assiégé. Les silithides pressent sans relâche contre ses murs, et la région alentour devient toujours plus hostile. Malgré tout, les marchands du fort gardent leurs étals ouverts, commerçant avec quiconque fait la longue ascension depuis le cratère d'Un'Goro, car le commerce est rare si loin de tout, et chaque pièce compte.\n\nLe chemin qui y mène serpente vers le nord-ouest depuis Un'Goro, passe le Tas moussu et gravit une falaise abrupte en lacets avant de déboucher sur les étendues brûlantes de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Hold",
		},
		["crystal vale"] = {
			name = "La Vallée des cristaux",
			short = "Dans l'extrême nord-ouest de Silithus s'étend le Val de cristal, une vallée livrée aux élémentaires de terre et d'air.",
			full = "Dans l'extrême nord-ouest de Silithus s'étend le Val de cristal, une vallée livrée aux élémentaires de terre et d'air. Le thorium abonde sous sa pierre, mais le sol appartient d'abord aux esprits qui s'y agitent, anciens et inquiets. Le généralissime Demetrian tient un camp dans le val.\n\nC'est ici que Thunderaan, le Cherchevent, peut être appelé et lié de nouveau à la lame qui porte sa fureur, une œuvre de tempête et de volonté que peu osent tenter et que moins encore mènent à bien.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Vale",
		},
		["hiveashi"] = {
			name = "Ruche'Ashi",
			short = "Ruche'Ashi se trouve dans le nord de Silithus, et sa couvée silithide se répand pour infester le pilier grouillant, au-delà de ses limites.",
			full = "Ruche'Ashi se trouve dans le nord de Silithus, et sa couvée silithide se répand pour infester le pilier grouillant, au-delà de ses limites.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Ashi",
		},
		["hiveregal"] = {
			name = "Ruche'Regal",
			short = "Dans le sud de Silithus, les monticules de Ruche'Regal s'élèvent du sable, repaire des silithides, où tunnels et chitine abondent dans la poussière.",
			full = "Dans le sud de Silithus, les monticules de Ruche'Regal s'élèvent du sable, repaire des silithides, où tunnels et chitine abondent dans la poussière.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Regal",
		},
		["hivezora"] = {
			name = "Ruche'Zora",
			short = "Ruche'Zora est un nid silithide creusé dans les sables de l'ouest de Silithus.",
			full = "Ruche'Zora est un nid silithide creusé dans les sables de l'ouest de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Zora",
		},
		["ortells hideout"] = {
			name = "La planque d'Ortell",
			short = "Dans le sud-est de Silithus, une petite grotte s'ouvre sur les pentes, demeure d'un ermite du nom d'Ortell.",
			full = "Dans le sud-est de Silithus, une petite grotte s'ouvre sur les pentes, demeure d'un ermite du nom d'Ortell.",
			source = "https://warcraft.wiki.gg/wiki/Ortell's_Hideout",
		},
		["ravaged twilight camp"] = {
			name = "Camp du Crépuscule ravagé",
			short = "Dans le Val de cristal, au nord-ouest de Silithus, se dresse un camp du Marteau du crépuscule, dont s'est emparé le généralissime Demetrian.",
			full = "Dans le Val de cristal, au nord-ouest de Silithus, se dresse un camp du Marteau du crépuscule, dont s'est emparé le généralissime Demetrian.\n\nDemetrian y demeure, tenant ce terrain pour le culte.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Twilight_Camp",
		},
		["scarab dais"] = {
			name = "L'Estrade du scarabée",
			short = "Le gong du Scarabée se dresse sur l'estrade du Scarabée, au nord-ouest du Mur du scarabée, aux portes d'Ahn'Qiraj, dans le sud de Silithus.",
			full = "Le gong du Scarabée se dresse sur l'estrade du Scarabée, au nord-ouest du Mur du scarabée, aux portes d'Ahn'Qiraj, dans le sud de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Dais",
		},
		["scarab wall"] = {
			name = "Le Mur du scarabée",
			short = "Le Mur du scarabée court le long de la lisière sud de Silithus, séparant le désert de la cité en ruine d'Ahn'Qiraj qui s'étend au-delà.",
			full = "Le Mur du scarabée court le long de la lisière sud de Silithus, séparant le désert de la cité en ruine d'Ahn'Qiraj qui s'étend au-delà. Il fut élevé à partir du sable même à la fin de la guerre des Sables changeants, sa masse de grès s'élevant à au moins trente mètres dans le ciel. Au-dessus de cette hauteur, là où la pierre ne pouvait monter davantage, le vol draconique bronze tissa sa magie en une barrière bien plus haute encore.\n\nCeux qui le bâtirent, elfes de la nuit et dragons bronze ensemble, le nommèrent Irana'ethil, le Bouclier contre l'ombre. Le nom dit clairement à quoi il servait : C'Thun et ses couvées silithides étaient scellés dans Ahn'Qiraj, et le mur se dressait entre cette horreur et le reste du monde.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["southwind village"] = {
			name = "Village de Sudevent",
			short = "Le Village de Sudevent fut jadis un avant-poste des elfes de la nuit à Silithus. Il ne survécut pas à la guerre des Sables changeants.",
			full = "Le Village de Sudevent fut jadis un avant-poste des elfes de la nuit à Silithus. Il ne survécut pas à la guerre des Sables changeants.\n\nLorsque les qiraji se levèrent en multitudes grouillantes, Valstann Staghelm, fils de Fandral Staghelm, mena un détachement de l'armée des elfes de la nuit pour tenir le village. Ses troupes furent massacrées sur place, et Valstann lui-même fut capturé vivant par le général Rajaxx tandis que le village qu'il avait été chargé de défendre était mis en pièces derrière lui.\n\nCe que les qiraji laissèrent derrière eux n'est pas resté vide. Les esprits des druides et des Sentinelles tombés dans le massacre s'attardent parmi les décombres, errant sans but, liés au lieu de leur mort, à la suite de l'Ombre d'Ambermoon. Le Village de Sudevent subsiste non comme une ruine paisible mais comme une terre hantée, dont les morts n'en ont pas encore fini avec elle.",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "Halte de Staghelm",
			short = "Une tour des elfes de la nuit couronnait jadis un pic du nord-est de Silithus. Ici, Ralo'shan, la Gardienne éternelle, tient son poste, tandis qu'un drake bronze de la lignée de Nozdormu tournoie dans le ciel au-dessus d'elle.",
			full = "Une tour des elfes de la nuit couronnait jadis un pic du nord-est de Silithus. Ici, Ralo'shan, la Gardienne éternelle, tient son poste, tandis qu'un drake bronze de la lignée de Nozdormu tournoie dans le ciel au-dessus d'elle. En contrebas de la tour, le long de la route, se trouve le Défilé du Crépuscule, une grotte qui abrite des sectateurs du Crépuscule, avec un petit camp à son entrée, une menace à laquelle la gardienne doit faire face.",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "Le pilier grouillant",
			short = "Le pilier grouillant s'élève au sud du Fort cénarien, un pic criblé de tunnels silithides, dont les pentes ne sont jamais immobiles.",
			full = "Le pilier grouillant s'élève au sud du Fort cénarien, un pic criblé de tunnels silithides, dont les pentes ne sont jamais immobiles. Une nuée de petits silithides tourne autour de la pierre à toute heure, un nuage vivant qui a donné son nom au pilier, et sous le sable, à son pied, se trouve l'une des chambres de la ruche, le plus grand des nombreux nids qui criblent le sol de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
		},
		["twilight base camp"] = {
			name = "Campement du crépuscule",
			short = "Le Campement du crépuscule est l'un des quatre camps que le culte du Marteau du crépuscule a établis à travers les étendues désolées de Silithus, un point d'appui pour ceux qui servent la venue des Dieux très anciens, au milieu de la poussière et des ruines de cette terre dévastée.",
			full = "Le Campement du crépuscule est l'un des quatre camps que le culte du Marteau du crépuscule a établis à travers les étendues désolées de Silithus, un point d'appui pour ceux qui servent la venue des Dieux très anciens, au milieu de la poussière et des ruines de cette terre dévastée.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Base_Camp",
		},
		["twilight outpost"] = {
			name = "Avant-poste du Crépuscule",
			short = "L'Avant-poste du Crépuscule se trouve dans l'extrême sud-ouest de Silithus, près du Mur du scarabée, à l'ouest du Campement de Bronzebeard. Il est tenu par le culte du Marteau du crépuscule.",
			full = "L'Avant-poste du Crépuscule se trouve dans l'extrême sud-ouest de Silithus, près du Mur du scarabée, à l'ouest du Campement de Bronzebeard. Il est tenu par le culte du Marteau du crépuscule.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Outpost",
		},
		["twilight post"] = {
			name = "Poste du Crépuscule",
			short = "Le Poste du Crépuscule se trouve dans le nord-ouest de Silithus, à l'ouest du Fort cénarien et au nord-ouest du Campement du crépuscule, un point d'appui revendiqué par le Marteau du crépuscule sur cette terre dévastée, balayée par le limon.",
			full = "Le Poste du Crépuscule se trouve dans le nord-ouest de Silithus, à l'ouest du Fort cénarien et au nord-ouest du Campement du crépuscule, un point d'appui revendiqué par le Marteau du crépuscule sur cette terre dévastée, balayée par le limon.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Post",
		},
		["twilights run"] = {
			name = "Défilé du Crépuscule",
			short = "Le Défilé du Crépuscule se cache dans la roche au pied de la Halte de Staghelm, dans le nord de Silithus.",
			full = "Le Défilé du Crépuscule se cache dans la roche au pied de la Halte de Staghelm, dans le nord de Silithus. L'entrée de sa grotte ne laisse rien deviner de ce qui emplit l'obscurité au-delà : salle après salle livrée au culte du Marteau du crépuscule, qui a fait de ce creux dans la montagne son domaine, profond et invisible, tandis que le vent du désert balaie la pierre au-dessus.",
			source = "https://warcraft.wiki.gg/wiki/Twilight's_Run",
		},
		["valors rest"] = {
			name = "Le repos des vaillants",
			short = "Le repos des vaillants est un petit camp à la lisière de Silithus, auquel on accède par le chemin qui monte depuis l'angle nord-ouest du cratère d'Un'Goro : c'est le premier terrain que foule le voyageur en montant vers les sables.",
			full = "Le repos des vaillants est un petit camp à la lisière de Silithus, auquel on accède par le chemin qui monte depuis l'angle nord-ouest du cratère d'Un'Goro : c'est le premier terrain que foule le voyageur en montant vers les sables.\n\nLe camp est tenu par des membres du Cercle cénarien, qui partagent le terrain avec une infestation d'insectes d'une familiarité troublante. Alliance et Horde s'y abritent de passage, et des tombes reposent en silence à sa lisière.",
			source = "https://warcraft.wiki.gg/wiki/Valor's_Rest",
		},
	},
	-- Berceau-de-l'Hiver: 18 subzones
	[1452] = {
		["banthallow barrow den"] = {
			name = "Refuge des saisons de Ban'Thallow",
			short = "Derrière Pluie-d'Étoiles, au Berceau-de-l'Hiver, se trouve le Refuge des saisons de Ban'Thallow, un dédale de tunnels qui renferme des reliques bénies, chères au village.",
			full = "Derrière Pluie-d'Étoiles, au Berceau-de-l'Hiver, se trouve le Refuge des saisons de Ban'Thallow, un dédale de tunnels qui renferme des reliques bénies, chères au village.",
			source = "https://warcraft.wiki.gg/wiki/Ban'Thallow_Barrow_Den",
		},
		["darkwhisper gorge"] = {
			name = "Gorge du Sombre murmure",
			short = "La Gorge du Sombre murmure se trouve dans le sud du Berceau-de-l'Hiver.",
			full = "La Gorge du Sombre murmure se trouve dans le sud du Berceau-de-l'Hiver.\n\nLorsque l'armée de la Légion ardente se brisa sur le mont Hyjal pendant la troisième guerre et qu'Archimonde tomba, les démons survivants ne disparurent pas du monde. Ils s'enfuirent dans la Gorge du Sombre murmure et y trouvèrent refuge, vestiges d'une armée qui avait failli anéantir le monde, laissés à pourrir dans l'obscurité.",
			source = "https://warcraft.wiki.gg/wiki/Darkwhisper_Gorge",
		},
		["dun mandarr"] = {
			name = "Dun Mandarr",
			short = "Dun Mandarr se trouve près d'une caverne glacée, dans le sud-est du Berceau-de-l'Hiver, et son nom trahit des mains naines. De féroces séléniens envahissent aujourd'hui le camp, et il ne reste guère d'autre trace de ceux qui l'élevèrent.",
			full = "Dun Mandarr se trouve près d'une caverne glacée, dans le sud-est du Berceau-de-l'Hiver, et son nom trahit des mains naines. De féroces séléniens envahissent aujourd'hui le camp, et il ne reste guère d'autre trace de ceux qui l'élevèrent.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Mandarr",
		},
		["everlook"] = {
			name = "Long-guet",
			short = "Long-guet se dresse au croisement des routes commerciales du Berceau-de-l'Hiver, un comptoir gobelin du Cartel Gentepression, dont le laboratoire se niche parmi les bâtiments.",
			full = "Long-guet se dresse au croisement des routes commerciales du Berceau-de-l'Hiver, un comptoir gobelin du Cartel Gentepression, dont le laboratoire se niche parmi les bâtiments.\n\nL'Aube d'argent envoya ici Gregor Greystone pour défendre ses intérêts auprès de l'administration locale du Cartel.",
			source = "https://warcraft.wiki.gg/wiki/Everlook",
		},
		["frostfire hot springs"] = {
			name = "Sources de Givrefeu",
			short = "La vapeur s'élève d'une chaîne de bassins à l'extrême ouest du Berceau-de-l'Hiver, une eau trop chaude pour la terre gelée qui l'entoure. Nul n'a pu expliquer pourquoi les sources brûlent sous la neige et la glace.",
			full = "La vapeur s'élève d'une chaîne de bassins à l'extrême ouest du Berceau-de-l'Hiver, une eau trop chaude pour la terre gelée qui l'entoure. Nul n'a pu expliquer pourquoi les sources brûlent sous la neige et la glace. Donova Snowden, qui campe non loin, se demande si quelque souillure démoniaque, remontant vers le nord depuis la Gorge du Sombre murmure, n'aurait pas trouvé son chemin jusqu'ici pour réchauffer la pierre.\n\nLe bassin le plus proche du Repaire des Grumegueules n'a jamais échappé à l'emprise de la tribu Tombe-hiver. Elle le tient toujours, et les furbolgs ne sont guère enclins à partager la chaleur qu'ils se sont appropriée.",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
		},
		["frostsaber rock"] = {
			name = "Roc des Sabres-de-Givre",
			short = "Au sommet du Roc des Sabres-de-Givre se tient Rivern Frostwind, gardien du lien entre les sabres-de-givre et ceux qui voudraient les monter.",
			full = "Au sommet du Roc des Sabres-de-Givre se tient Rivern Frostwind, gardien du lien entre les sabres-de-givre et ceux qui voudraient les monter. Il enseigne aux amis de l'Alliance qui l'ont mérité comment apprivoiser et monter les grands félins blancs qui rôdent sur la pierre glacée en contrebas.",
			source = "https://warcraft.wiki.gg/wiki/Frostsaber_Rock",
		},
		["frostwhisper gorge"] = {
			name = "Gorge du Blanc murmure",
			short = "La Gorge du Blanc murmure entaille le sud du Berceau-de-l'Hiver, son fond et ses crêtes jonchés de ruines des elfes de la nuit. Parmi ces vieilles pierres demeurent les géants Frostmaul et leurs immenses Préservateurs.",
			full = "La Gorge du Blanc murmure entaille le sud du Berceau-de-l'Hiver, son fond et ses crêtes jonchés de ruines des elfes de la nuit. Parmi ces vieilles pierres demeurent les géants Frostmaul et leurs immenses Préservateurs.",
			source = "https://warcraft.wiki.gg/wiki/Frostwhisper_Gorge",
		},
		["hidden grove"] = {
			name = "Le Bosquet caché",
			short = "Le Bosquet caché repose au fond d'un cratère du Berceau-de-l'Hiver, enfermé de tous côtés par des falaises à pic.",
			full = "Le Bosquet caché repose au fond d'un cratère du Berceau-de-l'Hiver, enfermé de tous côtés par des falaises à pic. Seule une grotte, creusée dans la crête sud-est, permet de le traverser, et se laisser tomber depuis les hauteurs est une voie que peu oseraient emprunter.\n\nAutrefois, ce creux n'abritait rien de plus redoutable que des lièvres blancs, prospérant sans être dérangés dans son refuge. Cela a changé depuis. Le bosquet est désormais revendiqué par des séléniens, hostiles à quiconque y pénètre, et leur présence a scellé le lieu aussi sûrement que ses falaises l'avaient jamais fait.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Grove",
		},
		["ice thistle hills"] = {
			name = "Collines des Chardons de glace",
			short = "Les Collines des Chardons de glace s'élèvent au sud-est de Long-guet, domaine des yétis Chardon de glace, qui ont leur tanière dans une grotte montant à flanc de colline et parcourent les pentes alentour.",
			full = "Les Collines des Chardons de glace s'élèvent au sud-est de Long-guet, domaine des yétis Chardon de glace, qui ont leur tanière dans une grotte montant à flanc de colline et parcourent les pentes alentour. Leur épaisse fourrure et leurs cornes pâles sont prisées par ceux qui bravent le froid pour s'en emparer.\n\nDes calots de glace poussent sur les pentes dégagées, et à l'intérieur de la grotte des veines de thorium parcourent la roche. Plus rare que tout, tout au bord de la grotte, un lotus noir fleurirait parfois, fragile et étrange sur le territoire des yétis.",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "Lac Kel'Theril",
			short = "Les eaux gelées du lac Kel'Theril reposent, immobiles, au cœur du Berceau-de-l'Hiver, entourées des ruines qui partagent son nom.",
			full = "Les eaux gelées du lac Kel'Theril reposent, immobiles, au cœur du Berceau-de-l'Hiver, entourées des ruines qui partagent son nom. Ces ruines sont l'œuvre ancienne des Bien-nés, et ceux qui y vivaient autrefois ne partirent pas lorsque leurs salles tombèrent. Leurs esprits s'y attardent encore, tourmentés, dérivant sur la glace et les pierres brisées.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["mazthoril"] = {
			name = "Mazthoril",
			short = "Au plus profond des glaces du Berceau-de-l'Hiver, près du lac Kel'Theril, la caverne de Mazthoril s'ouvre sous la terre, froide, immense et chargée de magie.",
			full = "Au plus profond des glaces du Berceau-de-l'Hiver, près du lac Kel'Theril, la caverne de Mazthoril s'ouvre sous la terre, froide, immense et chargée de magie. Ici demeure une couvée de dragons bleus, liés par serment à Malygos, et ici leur matriarche monte sa garde solitaire.\n\nHaleh prend rarement une forme que le monde qualifierait de véritable, ne se montrant que sous l'apparence d'une haute-elfe, debout au point le plus élevé de la caverne, que l'on atteint par une rune de passage gravée dans le sol, loin en contrebas. Rares sont ceux qui, n'étant pas de son espèce, voient jamais son visage.\n\nAutour d'elle, elle a placé une garde digne de son goût pour la solitude. Quatre puissants drakes n'obéissent qu'à elle. Spellmaw parcourt un circuit lent et ininterrompu à travers un tiers des basses terres du Berceau-de-l'Hiver, tandis que Manaclaw et Scryer veillent sur les runes au fond de la caverne, telles des sentinelles devant une porte verrouillée.",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "Antre de l'Horreur lunaire",
			short = "À quelques pas au nord-est des portes de Long-guet, le sol monte vers une petite grotte connue sous le nom d'Antre de l'Horreur lunaire, repaire de féroces chouettards enragés.",
			full = "À quelques pas au nord-est des portes de Long-guet, le sol monte vers une petite grotte connue sous le nom d'Antre de l'Horreur lunaire, repaire de féroces chouettards enragés. Une montagne se dresse entre l'antre et le Village Tombe-hiver, au sud, aussi proches que ces deux lieux paraissent, si bien qu'aucun chemin direct ne les relie, seulement une longue chevauchée autour des hauteurs.",
			source = "https://warcraft.wiki.gg/wiki/Moon_Horror_Den",
		},
		["owl wing thicket"] = {
			name = "Fourré de l'Aile de la chouette",
			short = "Les grottes du Fourré de l'Aile de la chouette entaillent le sud du Berceau-de-l'Hiver, repaire de chouettards devenus furieux, frappés par la lune et fous.",
			full = "Les grottes du Fourré de l'Aile de la chouette entaillent le sud du Berceau-de-l'Hiver, repaire de chouettards devenus furieux, frappés par la lune et fous. On dit que les anciens Gardiens d'Elune y racontent comment les séléniens vinrent au monde, un récit préservé par Ranshalla.",
			source = "https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",
		},
		["ruins of keltheril"] = {
			name = "Les ruines de Kel'Theril",
			short = "Les ruines de Kel'Theril gisent, brisées, sur les rives du lac qui porte leur nom, tout ce qui reste d'une grande cité des elfes de la nuit.",
			full = "Les ruines de Kel'Theril gisent, brisées, sur les rives du lac qui porte leur nom, tout ce qui reste d'une grande cité des elfes de la nuit. Elle tomba lors de la Grande fracture, quand le monde lui-même fut déchiré, et ne s'est jamais relevée.\n\nCe qui s'y attarde aujourd'hui est un chagrin devenu inquiet. Les Bien-nés qui périrent à la chute de Kel'Theril ne trouvèrent pas le repos ; leurs esprits demeurent parmi les colonnes effondrées des ruines du nord, tourmentés, incapables de renoncer à ce qu'ils ont perdu. Des fantômes de hauts-elfes hantent la partie orientale, parmi lesquels des forestiers trahis et un archimage.\n\nUn cristal nommé Zin-Malor est lié à la chute de ce lieu, attaché à une destruction qui engloutit ici des générations d'elfes. Cette histoire appartient à Kel'Theril même, aux pierres effondrées et aux fantômes qui y errent encore.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["starfall village"] = {
			name = "Pluie-d'Etoiles",
			short = "Pluie-d'Étoiles se dresse le long de la route qui traverse le Berceau-de-l'Hiver, le seul lieu de ce pays froid où l'Alliance tient une position.",
			full = "Pluie-d'Étoiles se dresse le long de la route qui traverse le Berceau-de-l'Hiver, le seul lieu de ce pays froid où l'Alliance tient une position. Un pavillon des elfes de la nuit et une maison plus petite composent le hameau, et non loin se trouve le Refuge des saisons de Ban'Thallow, enfoncé dans la terre comme les tertres funéraires dont il tire son nom.",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "Repaire des Grumegueules",
			short = "Le Repaire des Grumegueules se trouve dans les tunnels du nord de Gangrebois, le passage qui s'ouvre sur Reflet-de-Lune et le Berceau-de-l'Hiver, et c'est le dernier bastion de la tribu furbolg des Grumegueules.",
			full = "Le Repaire des Grumegueules se trouve dans les tunnels du nord de Gangrebois, le passage qui s'ouvre sur Reflet-de-Lune et le Berceau-de-l'Hiver, et c'est le dernier bastion de la tribu furbolg des Grumegueules.\n\nLorsque la corruption de la Légion ardente s'insinua dans les forêts sacrées de Kalimdor, les furbolgs de cette terre y succombèrent, changés en créatures sauvages et cruelles. Seule la tribu des Grumegueules échappa à ce sort, se retranchant dans ses tunnels tandis que la forêt qu'elle aimait se muait autour d'elle en une parodie purulente d'elle-même. Même après la destruction de la source de la corruption, la souillure ne quitta pas les bois.\n\nLes Grumegueules restent méfiants envers tous les étrangers, craignant d'être confondus avec leurs frères corrompus et abattus avant de pouvoir prouver le contraire. Ils savent pourtant qu'ils ne peuvent survivre seuls, et se montrent généreux envers ceux qui gagnent leur confiance : ils restent fidèles aux anciennes voies chamaniques et partagent librement le savoir de guérison qu'ils détiennent. Ce qu'ils désirent le plus, c'est la fin des souffrances de leurs frères corrompus, et un remède aux blessures qu'a subies Gangrebois.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "Poste des Grumegueules",
			short = "Le Poste des Grumegueules porte un nom qui ne lui convient plus.",
			full = "Le Poste des Grumegueules porte un nom qui ne lui convient plus. Le camp appartenait autrefois à la tribu des Grumegueules, mais il obéit désormais aux furbolgs corrompus Tombe-hiver, qui le tiennent entièrement, au sud-est des Sources de Givrefeu et à l'ouest du lac Kel'Theril.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "Village Tombe-hiver",
			short = "Le Village Tombe-hiver s'étage sur les pentes orientales du Berceau-de-l'Hiver, près de Long-guet, et ses furbolgs sont corrompus depuis longtemps. À son sommet se trouve une petite grotte, siège du grand chef Tombe-hiver, qui gouverne le village depuis ce lieu.",
			full = "Le Village Tombe-hiver s'étage sur les pentes orientales du Berceau-de-l'Hiver, près de Long-guet, et ses furbolgs sont corrompus depuis longtemps. À son sommet se trouve une petite grotte, siège du grand chef Tombe-hiver, qui gouverne le village depuis ce lieu.",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
	-- Cité de Stormwind: 3 subzones
	[1453] = {
		["champions hall"] = {
			name = "Hall des Champions",
			short = "Dans le sud de la Vieille ville, à la Cité de Stormwind, se dresse le Hall des Champions, où logent les officiers de l'Alliance, à l'écart au sein de la vieille cité, comme il sied à leur rang.",
			full = "Dans le sud de la Vieille ville, à la Cité de Stormwind, se dresse le Hall des Champions, où logent les officiers de l'Alliance, à l'écart au sein de la vieille cité, comme il sied à leur rang.",
			source = "https://warcraft.wiki.gg/wiki/Champions'_Hall",
		},
		["deeprun tram"] = {
			name = "Tram des profondeurs",
			short = "Ce n'est pas par goût du confort que le roi Magni Bronzebeard fit construire le Tram des profondeurs.",
			full = "Ce n'est pas par goût du confort que le roi Magni Bronzebeard fit construire le Tram des profondeurs. Dans les années qui suivirent la deuxième guerre, tandis que Stormwind peinait à se relever de ses ruines, Magni s'impatienta de la lenteur avec laquelle l'aide d'Ironforge parvenait à ses alliés humains, et s'inquiéta du temps qu'il faudrait aux soldats nains pour les rejoindre si la guerre revenait. Il s'adressa au Grand Bricoleur Gelbin Mekkatorque, l'ingénieur le plus estimé d'Azeroth, et lui confia le problème. La réponse de Mekkatorque fut une voie ferrée creusée sous la terre même, reliant directement les deux capitales.\n\nLes bâtisseurs rencontrèrent un lac souterrain sur le tracé du tunnel, et ne le contournèrent pas. Le tram le traverse encore aujourd'hui, ses voies couvertes passant sous l'eau plutôt qu'à côté.\n\nDes gnomes entretiennent le tram chaque jour, veillant à ce que ses deux rames de trois wagons filent vite et sans heurt entre Ironforge et Stormwind, gratuitement pour tous ceux qui empruntent les quais souterrains.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["valley of heroes"] = {
			name = "Vallée des héros",
			short = "Un pont de pierre pâle mène chaque voyageur par-dessus les douves, devant la porte sud de Stormwind, jusqu'à une vallée verdoyante bordée de statues élevées autant par chagrin que par gloire.",
			full = "Un pont de pierre pâle mène chaque voyageur par-dessus les douves, devant la porte sud de Stormwind, jusqu'à une vallée verdoyante bordée de statues élevées autant par chagrin que par gloire.\n\nAprès la deuxième guerre, lorsque Stormwind fut rebâtie sur ses ruines, la cité rendit hommage à ceux qui menèrent l'expédition de l'Alliance à travers la Porte des ténèbres pour la sceller depuis l'autre côté. Kurdran Marteau-hardi et l'archimage Khadgar se dressent à gauche de la route ; le commandant des forces Danath Trollemort et la capitaine des forestiers Alleria Windrunner à droite ; et au bout de la route, là où elle se divise pour entrer dans la cité proprement dite, se tient le général Turalyon, qui les commandait tous. Aucun des cinq ne revint jamais.\n\nDes années plus tard, Arator, le fils d'Alleria et de Turalyon, fut conduit à une cérémonie dans la vallée, porté sur les épaules d'un chevalier de la Main d'argent. Il leva les yeux vers l'effigie de pierre de sa mère, un visage dont il n'avait aucun souvenir. Quelque chose d'elle l'atteignit pourtant, car l'enfant sourit et tendit la main vers la statue. Il reviendrait encore et encore en grandissant, pour se tenir devant son visage et savoir, sans se souvenir d'elle, qu'elle l'avait aimé.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Heroes",
		},
	},
	-- Orgrimmar: 2 subzones
	[1454] = {
		["hall of legends"] = {
			name = "Hall des Légendes",
			short = "Le Hall des Légendes se dresse dans la vallée de la Force, à Orgrimmar : ce sont les casernes où les officiers de la Horde tiennent conseil.",
			full = "Le Hall des Légendes se dresse dans la vallée de la Force, à Orgrimmar : ce sont les casernes où les officiers de la Horde tiennent conseil.\n\nEn son centre, une table est couverte de cartes d'Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Legends",
		},
		["ragefire chasm"] = {
			name = "Gouffre de Ragefeu",
			short = "Sous Orgrimmar, la terre s'ouvre sur un gouffre ardent, aux tunnels encombrés de lave et de fumée. Des troggs ont commencé à remonter des profondeurs en ce lieu, un clan que la Horde finit par appeler les troggs de Ragefeu.",
			full = "Sous Orgrimmar, la terre s'ouvre sur un gouffre ardent, aux tunnels encombrés de lave et de fumée. Des troggs ont commencé à remonter des profondeurs en ce lieu, un clan que la Horde finit par appeler les troggs de Ragefeu. Magatha la Voyante, des taurens, tenta de faire la paix avec eux, dans l'espoir de les détourner de la cité qui les surplombe. Elle ne rencontra que de l'hostilité. Il devint évident que ces créatures n'avaient que faire de la diplomatie, et que, si on les laissait faire, elles pourraient submerger la Horde tout entière.\n\nPire encore, le complot s'étendait jusque dans Orgrimmar. Neeru Lamefeu, qui dissimulait sa véritable allégeance de chef de la Lame ardente, attira les fidèles de Thrall lui-même au fond du gouffre, les livrant à une secte de sombres cultistes qui s'y abritaient, à la fois pour se débarrasser d'eux et pour éprouver la loyauté des cultistes. Thrall en sait plus sur cette trahison qu'il ne le laisse paraître, mais les chefs cultistes tiennent toujours les cavernes qu'ils se sont appropriées.",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm",
		},
	},
	-- Ironforge: 2 subzones
	[1455] = {
		["deeprun tram"] = {
			name = "Tram des profondeurs",
			short = "Ce n'est pas par goût du confort que le roi Magni Bronzebeard fit construire le Tram des profondeurs.",
			full = "Ce n'est pas par goût du confort que le roi Magni Bronzebeard fit construire le Tram des profondeurs. Dans les années qui suivirent la deuxième guerre, tandis que Stormwind peinait à se relever de ses ruines, Magni s'impatienta de la lenteur avec laquelle l'aide d'Ironforge parvenait à ses alliés humains, et s'inquiéta du temps qu'il faudrait aux soldats nains pour les rejoindre si la guerre revenait. Il s'adressa au Grand Bricoleur Gelbin Mekkatorque, l'ingénieur le plus estimé d'Azeroth, et lui confia le problème. La réponse de Mekkatorque fut une voie ferrée creusée sous la terre même, reliant directement les deux capitales.\n\nLes bâtisseurs rencontrèrent un lac souterrain sur le tracé du tunnel, et ne le contournèrent pas. Le tram le traverse encore aujourd'hui, ses voies couvertes passant sous l'eau plutôt qu'à côté.\n\nDes gnomes entretiennent le tram chaque jour, veillant à ce que ses deux rames de trois wagons filent vite et sans heurt entre Ironforge et Stormwind, gratuitement pour tous ceux qui empruntent les quais souterrains.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["gates of ironforge"] = {
			name = "Portes d'Ironforge",
			short = "Les Portes d'Ironforge s'élèvent là où la grande rampe de Dun Morogh monte à la rencontre de la montagne, visibles à des lieues à travers les neiges bien avant qu'un voyageur ne les atteigne.",
			full = "Les Portes d'Ironforge s'élèvent là où la grande rampe de Dun Morogh monte à la rencontre de la montagne, visibles à des lieues à travers les neiges bien avant qu'un voyageur ne les atteigne. Elles marquent le seuil entre les terres naines à ciel ouvert et Ironforge proprement dite.\n\nUne fois passé, on se trouve sous le regard d'une immense statue élevée au haut-roi Modimus Anvilmar, placée juste après l'entrée pour monter la garde, afin que nul n'entre dans la cité sans passer d'abord sous ses yeux.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
	},
	-- Thunder Bluff: 4 subzones
	[1456] = {
		["elder rise"] = {
			name = "Cime des Anciens",
			short = "La Cime des Anciens se dresse à l'est du plateau central, et l'on y accède par des ponts de corde depuis la cime haute et la cime du milieu.",
			full = "La Cime des Anciens se dresse à l'est du plateau central, et l'on y accède par des ponts de corde depuis la cime haute et la cime du milieu. C'est ici que le Cercle cénarien a élu domicile, là où se réunissent les druides et les prêtres taurens, et où réside l'archidruide Hamuul Runetotem. Le conseil des Anciens y exerce aussi son autorité.\n\nEntre les deux ponts se dresse une hutte que s'est appropriée Magatha Grimtotem, cheffe de la tribu Totem sinistre.",
			source = "https://warcraft.wiki.gg/wiki/Elder_Rise",
		},
		["hunter rise"] = {
			name = "Cime des chasseurs",
			short = "La cime sud de Thunder Bluff appartient à ceux qui combattent et à ceux qui chassent.",
			full = "La cime sud de Thunder Bluff appartient à ceux qui combattent et à ceux qui chassent. Là se dresse le Hall des chasseurs, où les taurens forment leurs guerriers et leurs chasseurs, et où trappeurs, pisteurs et tanneurs s'adonnent à leur métier. Des ponts de corde relient la cime aux sentiers qui passent au-dessus et en dessous, l'unissant au reste du plateau.",
			source = "https://warcraft.wiki.gg/wiki/Hunter_Rise",
		},
		["pools of vision"] = {
			name = "Les Bassins de la Vision",
			short = "Sous le sommet de la Cime des Esprits, un tunnel débouche sur une eau sombre et immobile, connue sous le nom de Bassins de la vision.",
			full = "Sous le sommet de la Cime des Esprits, un tunnel débouche sur une eau sombre et immobile, connue sous le nom de Bassins de la vision. Les Réprouvés y tiennent un point d'appui, au cœur du pays tauren, un lieu de rassemblement pour leurs mages et leurs prêtres, où un émissaire des Profanateurs réprouvés recrute des combattants parmi les bassins.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Vision",
		},
		["spirit rise"] = {
			name = "Cime des Esprits",
			short = "La Cime des Esprits se dresse au nord-ouest du plateau central, vouée à l'étude chamanique chez les taurens. La tribu Skychaser y fait autorité.",
			full = "La Cime des Esprits se dresse au nord-ouest du plateau central, vouée à l'étude chamanique chez les taurens. La tribu Skychaser y fait autorité. Sous la surface de la mesa s'étendent les Bassins de la vision, dont les eaux sont réchauffées par une vapeur cachée. Des ponts de corde descendent vers la cime basse et la cime du milieu, unissant les hauteurs entre elles.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Rise",
		},
	},
	-- Darnassus: 5 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "Enclave cénarienne",
			short = "L'Enclave cénarienne s'étend au nord-ouest de Darnassus, un bosquet circulaire où chênes et frênes s'élèvent plus haut que les salles de pierre du reste de la cité.",
			full = "L'Enclave cénarienne s'étend au nord-ouest de Darnassus, un bosquet circulaire où chênes et frênes s'élèvent plus haut que les salles de pierre du reste de la cité. Chaque arbre porte ici des runes qui n'ont pas été gravées mais qui ont poussé dans l'écorce vivante, et les lieux de rassemblement du bosquet sont eux-mêmes faits de bois et de pierre travaillés ensemble, comme s'ils avaient été élevés plutôt que construits.\n\nCe fut toujours le siège des druides de la cité, tout comme le temple de la Lune est celui de ses prêtresses. L'archidruide Fandral Staghelm les dirige depuis les ramures de l'Enclave, et la plus grande de ses structures vivantes, au cœur du bosquet, est sa propre demeure.\n\nLe bosquet sert encore l'ordre qui se rassemble sous ses branches : les druides y viennent apprendre les anciennes voies, les chasseurs s'entraînent dans son arbre le plus à l'est, et au pied du grand arbre de l'Enclave, on peut apprendre à monter les sabres-de-nuit qui portent les cavaliers de Darnassus à travers les terres sauvages. Sous terre, cachée dans la ramure la plus à l'ouest, une guilde secrète de voleurs a ses quartiers, connue seulement de ceux qui savent déjà où chercher.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "Terrasse des Artisans",
			short = "La Terrasse des Artisans s'étend au nord de Darnassus, vouée au commerce plutôt qu'à la guerre ou au culte. Les artisans de la cité y tiennent boutique, et les voyageurs las peuvent trouver refuge dans l'une des auberges de Darnassus.",
			full = "La Terrasse des Artisans s'étend au nord de Darnassus, vouée au commerce plutôt qu'à la guerre ou au culte. Les artisans de la cité y tiennent boutique, et les voyageurs las peuvent trouver refuge dans l'une des auberges de Darnassus. Une ambassade de l'Aube d'argent s'y dresse également, présence étrangère à qui l'on a accordé une place dans la cité elfique.\n\nLa terrasse est bordée par la Terrasse des Guerriers au sud, et par l'Enclave cénarienne à l'ouest.",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["temple gardens"] = {
			name = "Les Jardins du temple",
			short = "Au cœur de Darnassus s'étendent les Jardins du temple, une vaste étendue d'eau, de passerelles et de petites îles, qui tirent leur nom du grand temple de la Lune qui s'élève juste au sud.",
			full = "Au cœur de Darnassus s'étendent les Jardins du temple, une vaste étendue d'eau, de passerelles et de petites îles, qui tirent leur nom du grand temple de la Lune qui s'élève juste au sud. Des ponts rayonnent dans toutes les directions, reliant l'Enclave cénarienne au nord, les Terrasses des Artisans, des Guerriers et des Marchands à l'est, et le temple de la Lune au sud, si bien que toutes les routes de la cité semblent converger ici.\n\nLa plus grande île abrite la banque de la cité, et un portail, à la lisière ouest des jardins, permet de descendre jusqu'à Rut'theran, au pied de l'Arbre-Monde : ce paisible centre d'eau et de pierre est ainsi aussi le seuil entre Darnassus et le monde au-delà.",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["tradesmens terrace"] = {
			name = "Terrasse des Marchands",
			short = "La Terrasse des Marchands se trouve dans la partie sud de Darnassus, où les boutiquiers tiennent leurs étals et où les négociants se retrouvent pour marchander, ce qui en fait le cœur commerçant de toute la cité.",
			full = "La Terrasse des Marchands se trouve dans la partie sud de Darnassus, où les boutiquiers tiennent leurs étals et où les négociants se retrouvent pour marchander, ce qui en fait le cœur commerçant de toute la cité. Au nord, elle s'ouvre sur la Terrasse des Guerriers, et à l'ouest les chemins mènent vers le temple de la Lune et les Jardins du temple.\n\nSes bâtiments sont faits de bois poussé, à la manière des elfes de la nuit, légers et gracieux.",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
		},
		["warriors terrace"] = {
			name = "Terrasse des Guerriers",
			short = "La Terrasse des Guerriers abrite la porte orientale de Darnassus, là où la cité s'ouvre sur les terres sauvages de Teldrassil.",
			full = "La Terrasse des Guerriers abrite la porte orientale de Darnassus, là où la cité s'ouvre sur les terres sauvages de Teldrassil. Les Sentinelles y tiennent leurs quartiers, et tout elfe de la nuit qui souhaite prendre les armes au service de la cité vient ici le faire, s'exerçant sur les pas de tir et les terrains de duel jusqu'à ce que son habileté soit digne de la guerre.\n\nDes cavaliers montés sur des sabres-de-nuit veillent le long des portes, et la terrasse se dresse comme le bouclier de la cité contre toute violence qui pourrait monter de la forêt par la route.\n\nElle est bordée par la Terrasse des Artisans au nord, la Terrasse des Marchands au sud et les Jardins du temple à l'ouest, si bien qu'un guerrier qui s'entraîne ici se trouve à portée de voix des artisans, des marchands et des prêtresses de la cité.",
			source = "https://warcraft.wiki.gg/wiki/Warrior's_Terrace",
		},
