	[1458] = {
		["ruins of lordaeron"] = {
			name = "Ruines de Lordaeron",
			short = "Au-dessus de la cité ensevelie, le palais de Lordaeron se dresse toujours, ses salles ouvertes au ciel, ses jardins retournés à l'abandon. C'est ici que mourut le grand royaume de l'Alliance, et ses fantômes ne l'ont jamais tout à fait quitté.",
			full = "Au-dessus de la cité ensevelie, le palais de Lordaeron se dresse toujours, ses salles ouvertes au ciel, ses jardins retournés à l'abandon. C'est ici que mourut le grand royaume de l'Alliance, et ses fantômes ne l'ont jamais tout à fait quitté.\n\nCe fut Arthas Menethil qui y mit fin. Le prince rentra chez lui à la tête d'une armée levée contre son propre peuple, accueilli à ces portes par les cloches et les acclamations avant que quiconque ne comprenne ce qu'il était devenu. Il trouva son père, le roi Terenas, qui l'attendait dans la salle du trône, et l'y tua. Debout au-dessus du corps, il prononça des paroles qui résonnent encore dans cette salle pour quiconque s'y attarde : le royaume tomberait, et de ses cendres s'élèverait un ordre nouveau qui ébranlerait le monde. Ce n'était pas une vaine fanfaronnade. En quelques jours, la cité et ses habitants furent massacrés, et Lordaeron appartint au Fléau.\n\nOn dit qu'en arpentant encore la cour, on peut entendre ce dont la pierre se souvient : des voix étouffées, le tintement des cloches de bienvenue, un murmure venu de la salle du trône qui ne s'éteint jamais tout à fait. Ceux qui voient au-delà du voile affirment que les citoyens de Lordaeron y marchent toujours, ignorant que leur royaume n'est plus.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
	},
}

